				{
					int num3 = num2;
					int num4 = num;
					if (num3 <= num4)
					{
						if (Operators.ConditionalCompareObjectEqual((object)check, datas.Tables[0].Rows[num2][0], false))
						{
							combo.Items.Add(RuntimeHelpers.GetObjectValue(datas.Tables[0].Rows[num2][1]));
							combo.SelectedItem = datas.Tables[0].Rows[num2][1].ToString();
						}
						num2++;
						continue;
					}
					break;
				}
			}
		}

