		public string num_to_word(double num, string rupee, string paisa)
		{
			Assembly assembly = Assembly.Load("NumberToWord");
			object objectValue = RuntimeHelpers.GetObjectValue(assembly.CreateInstance("NumberToWord.NumeriCon"));
			object[] array = new object[3] { num, rupee, paisa };
			bool[] array2 = new bool[3] { true, true, true };
			object obj = NewLateBinding.LateGet(objectValue, (Type)null, "ConvertNum", array, (string[])null, (Type[])null, array2);
			if (array2[0])
			{
				num = (double)Conversions.ChangeType(RuntimeHelpers.GetObjectValue(array[0]), typeof(double));
			}
			if (array2[1])
			{
				rupee = (string)Conversions.ChangeType(RuntimeHelpers.GetObjectValue(array[1]), typeof(string));
			}
			if (array2[2])
			{
				paisa = (string)Conversions.ChangeType(RuntimeHelpers.GetObjectValue(array[2]), typeof(string));
			}
			return Conversions.ToString(obj);
		}
