		private void GetNewIndexId()
		{
			s = "SELECT TOP (1) IndexId FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (restaurantCode = '" + TempResturantCode + "') ORDER BY IndexId DESC";
			IndexId = Conversions.ToDouble(ob_dataAccess.singleValueReturn(s));
			IndexId += 1.0;
		}

		private void GetNewTrnNo()
		{
			s = "SELECT TOP (1) TrnNo FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (TrnType = '" + TrnType + "') AND (restaurantCode = '" + TempResturantCode + "') ORDER BY TrnNo DESC";
			TrnNo = Conversions.ToInteger(ob_dataAccess.singleValueReturn(s));
			checked
			{
				TrnNo++;
			}
