		public void GetVchMinMaxDates(bool NewVch, string VchType)
		{
			string text = "";
			TempResturantCode = "NOTREQ";
			DataSet dataSet;
			if (NewVch)
			{
				s = "SELECT TOP (1) VchDate FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (restaurantCode = '" + TempResturantCode + "') AND (TrnType = '" + VchType + "') ORDER BY VchDate DESC";
				dataSet = masterFunction.editMaster(s);
				if (dataSet.Tables[0].Rows.Count != 0)
				{
					VchMinDate = Conversions.ToDate(dataSet.Tables[0].Rows[0][0]);
				}
				else
				{
					VchMinDate = mdl_public_variables.comstdate;
				}
				VchMaxDate = mdl_public_variables.comenddate;
				return;
			}
			s = "SELECT TOP (1) VchDate FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (restaurantCode = 'NOTREQ') AND (TrnType = '" + VchType + "') AND (TrnNo < " + Conversions.ToString(TrnNo) + ") ORDER BY VchDate DESC";
			dataSet = masterFunction.editMaster(s);
			if (dataSet.Tables[0].Rows.Count != 0)
			{
				VchMinDate = Conversions.ToDate(dataSet.Tables[0].Rows[0][0]);
			}
			else
			{
				VchMinDate = mdl_public_variables.comstdate;
			}
			s = "SELECT TOP (1) VchDate FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (restaurantCode = 'NOTREQ') AND (TrnType = '" + VchType + "') AND (TrnNo > " + Conversions.ToString(TrnNo) + ") ORDER BY VchDate";
			DataSet dataSet2 = masterFunction.editMaster(s);
			if (dataSet2.Tables[0].Rows.Count != 0)
			{
				VchMaxDate = Conversions.ToDate(dataSet2.Tables[0].Rows[0][0]);
			}
			else
			{
				VchMaxDate = mdl_public_variables.comenddate;
			}
		}

