		{
			s = "SELECT TOP (1) TrnNo FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (TrnType = '" + TrnType + "') AND (restaurantCode = '" + TempResturantCode + "') AND (TrnNo = " + Conversions.ToString(TrnNo) + ") ORDER BY TrnNo DESC";
