		public void insertTransaction(string InsertTrnNo = "")
		{
			checked
			{
				if (Operators.CompareString(InsertTrnNo, "", false) == 0)
				{
					GetNewIndexId();
					GetNewTrnNo();
					s = "";
					s = "INSERT INTO TransactionMain (companycode, yearcode, restaurantCode, IndexId, VchDate, TrnType, TrnNo, ReceiptType, ChequeNo, CardNo, TransactionIDDetails, Narration, TrnId ) VALUES ( '" + mdl_public_variables.companycode + "', '" + mdl_public_variables.yearcode + "', '" + TempResturantCode + "', '" + Conversions.ToString(IndexId) + "', '" + Conversions.ToString(VchDate) + "', '" + TrnType + "', '" + Conversions.ToString(TrnNo) + "', '" + ReceiptType + "', '" + ChequeNo + "', '" + CardNo + "', '" + TransactionIDDetails + "', '" + Narration + "', '" + Conversions.ToString(TrnId) + "' )";
					ob_dataAccess.insert(s);
					s = "";
					s = "INSERT INTO TransactionDetail (companycode, yearcode, restaurantCode, IndexId, SerialId, TrnAccount, TrnAmount, TrnEffect, LookupSerialId, LookupTrnAccount) VALUES ('" + mdl_public_variables.companycode + "', '" + mdl_public_variables.yearcode + "', '" + TempResturantCode + "', '" + Conversions.ToString(IndexId) + "', '1', '" + TrnAccount_Party + "', '" + Conversions.ToString(TrnAmount_Party) + "', " + Conversions.ToString(TrnEffect_Party) + ", '2', '" + TrnAccount_CashBank + "')";
					ob_dataAccess.insert(s);
					s = "";
					s = "INSERT INTO TransactionDetail (companycode, yearcode, restaurantCode, IndexId, SerialId, TrnAccount, TrnAmount, TrnEffect, LookupSerialId, LookupTrnAccount) VALUES ('" + mdl_public_variables.companycode + "', '" + mdl_public_variables.yearcode + "', '" + TempResturantCode + "', '" + Conversions.ToString(IndexId) + "', '2', '" + TrnAccount_CashBank + "', '" + Conversions.ToString(TrnAmount_Party) + "', " + Conversions.ToString(-TrnEffect_Party) + ", '1', '" + TrnAccount_Party + "')";
					ob_dataAccess.insert(s);
				}
				else
				{
					string text = "";
					text = Conversions.ToString(CheckNewTrnNo(Conversions.ToInteger(InsertTrnNo)));
					if ((double)CheckNewTrnNo(Conversions.ToInteger(InsertTrnNo)) != Conversion.Val(InsertTrnNo))
					{
						GetNewIndexId();
						TrnNo = (int)Math.Round(Conversion.Val(InsertTrnNo));
						s = "";
						s = "INSERT INTO TransactionMain (companycode, yearcode, restaurantCode, IndexId, VchDate, TrnType, TrnNo, ReceiptType, ChequeNo, CardNo, TransactionIDDetails, Narration, TrnId ) VALUES ( '" + mdl_public_variables.companycode + "', '" + mdl_public_variables.yearcode + "', '" + TempResturantCode + "', '" + Conversions.ToString(IndexId) + "', '" + Conversions.ToString(VchDate) + "', '" + TrnType + "', '" + Conversions.ToString(TrnNo) + "', '" + ReceiptType + "', '" + ChequeNo + "', '" + CardNo + "', '" + TransactionIDDetails + "', '" + Narration + "', '" + Conversions.ToString(TrnId) + "' )";
						ob_dataAccess.insert(s);
						s = "";
						s = "INSERT INTO TransactionDetail (companycode, yearcode, restaurantCode, IndexId, SerialId, TrnAccount, TrnAmount, TrnEffect, LookupSerialId, LookupTrnAccount) VALUES ('" + mdl_public_variables.companycode + "', '" + mdl_public_variables.yearcode + "', '" + TempResturantCode + "', '" + Conversions.ToString(IndexId) + "', '1', '" + TrnAccount_Party + "', '" + Conversions.ToString(TrnAmount_Party) + "', " + Conversions.ToString(TrnEffect_Party) + ", '2', '" + TrnAccount_CashBank + "')";
						ob_dataAccess.insert(s);
						s = "";
						s = "INSERT INTO TransactionDetail (companycode, yearcode, restaurantCode, IndexId, SerialId, TrnAccount, TrnAmount, TrnEffect, LookupSerialId, LookupTrnAccount) VALUES ('" + mdl_public_variables.companycode + "', '" + mdl_public_variables.yearcode + "', '" + TempResturantCode + "', '" + Conversions.ToString(IndexId) + "', '2', '" + TrnAccount_CashBank + "', '" + Conversions.ToString(TrnAmount_Party) + "', " + Conversions.ToString(-TrnEffect_Party) + ", '1', '" + TrnAccount_Party + "')";
						ob_dataAccess.insert(s);
					}
				}
				SetIndexId(IndexId);
			}
		}

		public void updateTransaction()
		{
			string text = "";
			text = Conversions.ToString(CheckNewTrnNo(TrnNo));
			if (CheckNewTrnNo(TrnNo) != 0)
			{
				s = "";
				s = "UPDATE TransactionMain SET VchDate  = '" + Conversions.ToString(VchDate) + "', TrnType  = '" + TrnType + "', TrnNo  = '" + Conversions.ToString(TrnNo) + "', ReceiptType  = '" + ReceiptType + "', ChequeNo  = '" + ChequeNo + "', CardNo  = '" + CardNo + "', TransactionIDDetails  = '" + TransactionIDDetails + "', Narration  = '" + Narration + "', TrnId  = '" + Conversions.ToString(TrnId) + "' WHERE companycode  = '" + mdl_public_variables.companycode + "' AND yearcode  = '" + mdl_public_variables.yearcode + "' AND restaurantCode  = '" + TempResturantCode + "' AND IndexId  = '" + Conversions.ToString(IndexId) + "'";
				ob_dataAccess.insert(s);
				s = "";
				s = "UPDATE TransactionDetail SET TrnAccount = '" + TrnAccount_Party + "', TrnAmount = " + Conversions.ToString(TrnAmount_Party) + ", TrnEffect = " + Conversions.ToString(TrnEffect_Party) + ", LookupSerialId = 2, LookupTrnAccount = '" + TrnAccount_CashBank + "'WHERE companycode = '" + mdl_public_variables.companycode + "' AND yearcode = '" + mdl_public_variables.yearcode + "' AND restaurantCode = '" + TempResturantCode + "' AND IndexId = '" + Conversions.ToString(IndexId) + "' AND SerialId = 1";
				ob_dataAccess.insert(s);
				s = "";
				s = "UPDATE TransactionDetail SET TrnAccount = '" + TrnAccount_CashBank + "', TrnAmount = " + Conversions.ToString(TrnAmount_Party) + ", TrnEffect = " + Conversions.ToString(checked(-TrnEffect_Party)) + ", LookupSerialId = 1, LookupTrnAccount = '" + TrnAccount_Party + "'WHERE companycode = '" + mdl_public_variables.companycode + "' AND yearcode = '" + mdl_public_variables.yearcode + "' AND restaurantCode = '" + TempResturantCode + "' AND IndexId = '" + Conversions.ToString(IndexId) + "' AND SerialId = 2";
				ob_dataAccess.insert(s);
			}
		}

		public void selectTransactionMain()
		{
			string text = "SELECT VchDate, TrnType, TrnNo, ReceiptType, ChequeNo, CardNo, TransactionIDDetails, Narration, TrnId FROM TransactionMain WHERE (IndexId = " + Conversions.ToString(IndexId) + ") AND (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (restaurantCode = '" + TempResturantCode + "')";
			DataSet dataSet = masterFunction.editMaster(text);
			VchDate = Conversions.ToDate(dataSet.Tables[0].Rows[0][0]);
			TrnType = dataSet.Tables[0].Rows[0][1].ToString();
			TrnNo = Conversions.ToInteger(dataSet.Tables[0].Rows[0][2].ToString());
			ReceiptType = dataSet.Tables[0].Rows[0][3].ToString();
			ChequeNo = dataSet.Tables[0].Rows[0][4].ToString();
			CardNo = dataSet.Tables[0].Rows[0][5].ToString();
			TransactionIDDetails = dataSet.Tables[0].Rows[0][6].ToString();
			Narration = dataSet.Tables[0].Rows[0][7].ToString();
			if (!Information.IsDBNull(RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[0][8])))
			{
				TrnId = Conversions.ToInteger(dataSet.Tables[0].Rows[0][8]);
			}
			text = "SELECT TrnAccount, TrnAmount, TrnEffect FROM TransactionDetail WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (restaurantCode = '" + TempResturantCode + "') AND (IndexId = " + Conversions.ToString(IndexId) + ") AND (SerialId = 1)";
			dataSet = masterFunction.editMaster(text);
			TrnAccount_Party = dataSet.Tables[0].Rows[0][0].ToString();
			TrnAmount_Party = Conversions.ToDouble(dataSet.Tables[0].Rows[0][1]);
			TrnEffect_Party = Conversions.ToInteger(dataSet.Tables[0].Rows[0][2]);
			text = "SELECT TrnAccount FROM TransactionDetail WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (restaurantCode = '" + TempResturantCode + "') AND (IndexId = " + Conversions.ToString(IndexId) + ") AND (SerialId = 2)";
			dataSet = masterFunction.editMaster(text);
			TrnAccount_CashBank = dataSet.Tables[0].Rows[0][0].ToString();
		}

