		private void ReleaseComObject(object obj)
		{
			try
			{
				Marshal.ReleaseComObject(RuntimeHelpers.GetObjectValue(obj));
				obj = null;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				obj = null;
				ProjectData.ClearProjectError();
			}
			finally
			{
				GC.Collect();
			}
		}
	}
	public class cls_floor
	{
		private cls_Master masterFunction;

		private string restaurantName;

		private string restaurantCode;

		private string floor;

		private int floorCode;

		private int tableCount;

		public cls_floor()
		{
			masterFunction = new cls_Master();
		}

		public cls_floor(int floor)
		{
			masterFunction = new cls_Master();
			this.floor = Conversions.ToString(floor);
		}

		public void setRestaurantName(string restaurantName)
		{
			this.restaurantName = restaurantName;
		}

		public void setRestaurantCode(string restaurantCode)
		{
			this.restaurantCode = restaurantCode;
		}

		public void setFloor(string floor)
		{
			this.floor = floor;
		}

		public void setTableCount(int tableCount)
		{
			this.tableCount = tableCount;
		}

		public void SetFloorCode(int floorCode)
		{
			this.floorCode = floorCode;
		}

		public string getRestaurantName()
		{
			return restaurantName;
		}

		public string getRestaurantCode()
		{
			return restaurantCode;
		}

		public string getFloor()
		{
			return floor;
		}

		public int getTableCount()
		{
			return tableCount;
		}

		public int GetFloorCode()
		{
			return floorCode;
		}

		public void insertFloorDetails()
		{
			string s = "INSERT INTO floorMaster(companyCode, restaurentCode, floor, tableCount,floorCode) VALUES ('" + mdl_public_variables.companycode + "','" + restaurantCode + "','" + floor + "','" + Conversions.ToString(tableCount) + "'," + Conversions.ToString(floorCode) + ")";
			masterFunction.insertIntoDatabase(s);
		}

		public void deleteFloorDetails()
		{
			string s = "delete from floorMaster where companyCode='" + mdl_public_variables.companycode + "' and restaurentCode = '" + restaurantCode + "' and floor ='" + floor + "' and floorCode=" + Conversions.ToString(floorCode) + "";
			masterFunction.deleteMaster(s);
		}

		public void editFloorDetails(string restaurentCode, string floor)
		{
			string s = "UPDATE floorMaster SET restaurentCode ='" + restaurentCode + "', floor ='" + floor + "', tableCount ='" + Conversions.ToString(tableCount) + "' WHERE companyCode = '" + mdl_public_variables.companycode + "' AND restaurentCode = '" + restaurantCode + "' AND floor = '" + this.floor + "' and floorCode=" + Conversions.ToString(floorCode) + "";
			masterFunction.insertIntoDatabase(s);
		}

		public void initilisedFloorMaster()
		{
			string s = "SELECT floorMaster.companyCode, floorMaster.restaurentCode, floor, tableCount, totalPax,restaurantName,floorCode FROM floorMaster INNER JOIN restaurantMaster ON floorMaster.companyCode = restaurantMaster.companyCode AND floorMaster.restaurentCode = restaurantMaster.restaurantCode  where floorMaster.companyCode='" + mdl_public_variables.companycode + "' and floorMaster.restaurentCode='" + restaurantCode + "' and floor = '" + floor + "'";
			DataSet dataSet = masterFunction.editMaster(s);
			restaurantName = Conversions.ToString(dataSet.Tables[0].Rows[0][5]);
			restaurantCode = Conversions.ToString(dataSet.Tables[0].Rows[0][1]);
			floor = Conversions.ToString(dataSet.Tables[0].Rows[0][2]);
			tableCount = Conversions.ToInteger(dataSet.Tables[0].Rows[0][3]);
			floorCode = Conversions.ToInteger(dataSet.Tables[0].Rows[0][6]);
		}

		public bool checkFloorPresent(int type, string floorName)
		{
			string s = ((type != 1) ? ("select * from floorMaster where companyCode= '" + mdl_public_variables.companycode + "' and restaurentCode='" + restaurantCode + "' and floor='" + floorName + "' and floorCode<>" + Conversions.ToString(floorCode)) : ("select * from floorMaster where companyCode= '" + mdl_public_variables.companycode + "' and restaurentCode='" + restaurantCode + "' and floor='" + floor + "' "));
			DataSet dataSet = masterFunction.editMaster(s);
			if (dataSet.Tables[0].Rows.Count > 0)
			{
				return true;
			}
			return false;
		}

		public void getNewFloorCode()
		{
			cls_DataAccess cls_DataAccess2 = new cls_DataAccess();
			string s = "select top 1 floorCode from floorMaster where companyCode = '" + mdl_public_variables.companycode + "' and restaurentCode = '" + restaurantCode + "' order by floorCode desc ";
			floorCode = checked((int)Math.Round(Conversions.ToDouble(cls_DataAccess2.singleValueReturn(s)) + 1.0));
		}
	}
