		public bool compareItemName(int i)
		{
			string s = null;
			switch (i)
			{
			case 0:
				s = "select count(*) from itemMaster where companyCode='" + mdl_public_variables.companycode + "' and itemName = '" + itemName + "' ";
				break;
			case 1:
				s = "Select count(*) from itemMaster where companyCode ='" + mdl_public_variables.companycode + "' and itemName ='" + itemName + "' and itemCode<>'" + itemCode + "'";
				break;
			}
			return masterFunction.compareTwoValue(s);
		}

