		private void GetNewIndexId()
		{
			s = "SELECT TOP (1) IndexId FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "')  ORDER BY IndexId DESC";
			indexId = Conversions.ToDouble(ob_dataAccess.singleValueReturn(s));
			indexId += 1.0;
		}

		private void GetNewTrnNo()
		{
			s = "SELECT TOP (1) TrnNo FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (TrnType = '" + trnType + "') AND (restaurantCode = '" + tempRestaurantCode + "') ORDER BY TrnNo DESC";
			checked
			{
				trnNo = (int)Math.Round(Conversion.Val(ob_dataAccess.singleValueReturn(s)));
				trnNo++;
			}
		}

		public void InitilisedArray()
		{
			checked
			{
				trnAccountCode = (string[])Utils.CopyArray((Array)trnAccountCode, (Array)new string[totalField + 1]);
				trnAmount = (string[])Utils.CopyArray((Array)trnAmount, (Array)new string[totalField + 1]);
				trnEffect = (int[])Utils.CopyArray((Array)trnEffect, (Array)new int[totalField + 1]);
				lookUpAccount = (string[])Utils.CopyArray((Array)lookUpAccount, (Array)new string[totalField + 1]);
				lookUpSerialId = (int[])Utils.CopyArray((Array)lookUpSerialId, (Array)new int[totalField + 1]);
				serialId = (int[])Utils.CopyArray((Array)serialId, (Array)new int[totalField + 1]);
			}
		}

		public bool InsertJournalDetails(ref string result, string trnNo = "", bool isDueAmountPost = false)
		{
			if (indexId < 1.0)
			{
				GetNewIndexId();
			}
			if (Operators.CompareString(trnNo, "", false) == 0)
			{
				GetNewTrnNo();
			}
			else if ((Operators.CompareString(receiptType, "FL", false) == 0) | (Operators.CompareString(receiptType, "CS", false) == 0))
			{
				if (CheckNewTrnNo(receiptType))
				{
					result = "This voucher no already exist please change this voucher no.";
					return false;
				}
			}
			else if (CheckNewTrnNo())
			{
				result = "This voucher no already exist please change this voucher no.";
				return false;
			}
			s = "INSERT INTO TransactionMain (companycode,                                      yearcode,                                       restaurantCode,             IndexId,            VchDate,           TrnType,                TrnNo,             ReceiptType,  ChequeNo, CardNo,TransactionIDDetails,  Narration,    TrnId ) VALUES ( '" + mdl_public_variables.companycode + "',            '" + mdl_public_variables.yearcode + "',                '" + tempRestaurantCode + "',   '" + Conversions.ToString(indexId) + "', '" + Conversions.ToString(vchDate) + "', '" + trnType + "',     '" + Conversions.ToString(this.trnNo) + "', '" + receiptType + "', '',     '',         '',         '" + Narration + "', '' )";
			ob_dataAccess.insert(s);
			checked
			{
				int num = totalField - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					s = "INSERT INTO TransactionDetail(companycode,                                 yearcode,                                       restaurantCode,             IndexId,        SerialId,              TrnAccount,              TrnAmount,           TrnEffect,           LookupSerialId,            LookupTrnAccount) VALUES ('" + mdl_public_variables.companycode + "',          '" + mdl_public_variables.yearcode + "',                '" + tempRestaurantCode + "',   " + Conversions.ToString(indexId) + "," + Conversions.ToString(serialId[num2]) + ",'" + trnAccountCode[num2] + "'," + trnAmount[num2] + "," + Conversions.ToString(trnEffect[num2]) + "," + Conversions.ToString(lookUpSerialId[num2]) + ",'" + lookUpAccount[num2] + "') ";
					ob_dataAccess.insert(s);
					num2++;
				}
			}
			if (Operators.CompareString(trnType, "PURCHASE", false) == 0 || isDueAmountPost)
			{
				s = "INSERT INTO TransactionMatch (                            companyCode,                                            yearCode,                   restaurantCode,     indexId,    serialId,  MatchId,      vchDate,            trnType,        trnNo,              TrnAccount,             trnAmount,              trnEffect,      ReferenceText,    ReferenceId,         ReferenceSl, ReferenceMatchId, Matched) VALUES ('" + mdl_public_variables.companycode + "',                  '" + mdl_public_variables.yearcode + "',        'NOTREQ',   " + Conversions.ToString(indexId) + "," + Conversions.ToString(1) + "," + Conversions.ToString(1) + ",'" + Conversions.ToString(vchDate) + "',  '" + trnType + "'," + Conversions.ToString(this.trnNo) + ",'" + trnAccountCode[0] + "'," + trnAmount[0] + "," + Conversions.ToString(trnEffect[0]) + ",     '',         " + Conversions.ToString(indexId) + ",          0,              0,              0) ";
				ob_dataAccess.insert(s);
			}
			else if (Operators.CompareString(receiptType, "EXPENCE", false) == 0)
			{
				s = "INSERT INTO TransactionMatch (                            companyCode,                                            yearCode,                   restaurantCode,     indexId,    serialId,  MatchId,      vchDate,            trnType,        trnNo,              TrnAccount,             trnAmount,              trnEffect,      ReferenceText,    ReferenceId,         ReferenceSl, ReferenceMatchId, Matched) VALUES ('" + mdl_public_variables.companycode + "',                  '" + mdl_public_variables.yearcode + "',        'NOTREQ',   " + Conversions.ToString(indexId) + "," + Conversions.ToString(1) + "," + Conversions.ToString(1) + ",'" + Conversions.ToString(vchDate) + "',  '" + trnType + "'," + Conversions.ToString(this.trnNo) + ",'" + trnAccountCode[1] + "'," + trnAmount[1] + "," + Conversions.ToString(trnEffect[1]) + ",     '',         " + Conversions.ToString(indexId) + ",          0,              0,              0) ";
				ob_dataAccess.insert(s);
			}
			return true;
		}

		public void SelectJournalDetails()
		{
			//IL_02aa: Unknown result type (might be due to invalid IL or missing references)
			s = " SELECT TransactionMain.ReceiptType, TransactionMain.ChequeNo, TransactionMain.CardNo, TransactionMain.TransactionIDDetails, TransactionMain.Narration, TransactionMain.TrnId, TransactionDetail.SerialId, TransactionDetail.TrnAccount, TransactionDetail.TrnAmount, TransactionDetail.TrnEffect, TransactionDetail.LookupSerialId, TransactionDetail.LookupTrnAccount,MasterAccountsLedger.ledgerName FROM TransactionMain INNER JOIN TransactionDetail ON TransactionMain.companycode = TransactionDetail.companycode AND TransactionMain.yearcode = TransactionDetail.yearcode AND TransactionMain.restaurantCode = TransactionDetail.restaurantCode AND TransactionMain.IndexId = TransactionDetail.IndexId INNER JOIN MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode where TransactionMain.companyCode='" + mdl_public_variables.companycode + "' and TransactionMain.yearCode='" + mdl_public_variables.yearcode + "' AND TransactionMain.VchDate = '" + Conversions.ToString(vchDate) + "' and trnType='" + trnType + "' and TransactionMain.trnNo = '" + Conversions.ToString(trnNo) + "' order by serialId ";
			DataSet dataSet = ob_dataAccess.populate(s);
			checked
			{
				if (dataSet.Tables[0].Rows.Count > 0)
				{
					receiptType = Conversions.ToString(dataSet.Tables[0].Rows[0][0]);
					Narration = Conversions.ToString(dataSet.Tables[0].Rows[0][4]);
					totalField = dataSet.Tables[0].Rows.Count;
					InitilisedArray();
					trnAccountName = new string[totalField + 1];
					int num = dataSet.Tables[0].Rows.Count - 1;
					int num2 = 0;
					while (true)
					{
						int num3 = num2;
						int num4 = num;
						if (num3 <= num4)
						{
							serialId[num2] = Conversions.ToInteger(dataSet.Tables[0].Rows[num2][6]);
							trnAccountCode[num2] = Conversions.ToString(dataSet.Tables[0].Rows[num2][7]);
							trnAmount[num2] = Conversions.ToString(dataSet.Tables[0].Rows[num2][8]);
							trnEffect[num2] = Conversions.ToInteger(dataSet.Tables[0].Rows[num2][9]);
							lookUpSerialId[num2] = Conversions.ToInteger(dataSet.Tables[0].Rows[num2][10]);
							lookUpAccount[num2] = Conversions.ToString(dataSet.Tables[0].Rows[num2][11]);
							trnAccountName[num2] = Conversions.ToString(dataSet.Tables[0].Rows[num2][12]);
							num2++;
							continue;
						}
						break;
					}
				}
				else
				{
					Interaction.MsgBox((object)"Sorry Some error occured to edit this bill", (MsgBoxStyle)16, (object)null);
				}
			}
		}

		public void DeleteJournalDetails()
		{
			s = "DELETE FROM TransactionDetail WHERE companycode = '" + mdl_public_variables.companycode + "' AND yearcode = '" + mdl_public_variables.yearcode + "' AND restaurantCode = '" + tempRestaurantCode + "' AND IndexId = " + Conversions.ToString(indexId);
			ob_dataAccess.insert(s);
			s = "DELETE FROM TransactionMain WHERE companycode = '" + mdl_public_variables.companycode + "' AND yearcode = '" + mdl_public_variables.yearcode + "' AND restaurantCode = '" + tempRestaurantCode + "' AND IndexId = " + Conversions.ToString(indexId);
			ob_dataAccess.insert(s);
		}

		private bool CheckNewTrnNo(string receiptType = "")
		{
			if (Operators.CompareString(receiptType, "", false) == 0)
			{
				s = "SELECT TOP (1) TrnNo FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (TrnType = '" + trnType + "') AND (restaurantCode = '" + tempRestaurantCode + "') AND (TrnNo = " + Conversions.ToString(trnNo) + ") ORDER BY TrnNo DESC";
			}
			else
			{
				s = "SELECT TOP (1) TrnNo FROM TransactionMain WHERE (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "') AND (TrnType = '" + trnType + "') AND (restaurantCode = '" + tempRestaurantCode + "') AND (TrnNo = " + Conversions.ToString(trnNo) + ") AND (receiptType = '" + receiptType + "')  ORDER BY TrnNo DESC";
			}
			if (Conversion.Val(ob_dataAccess.singleValueReturn(s)) > 0.0)
			{
				return true;
			}
			return false;
		}

		public bool updateTransaction(int newTrnNo, ref string result)
		{
			if (newTrnNo == trnNo)
			{
				DeleteJournalDetails();
				if (InsertJournalDetails(ref result, Conversions.ToString(trnNo)))
				{
					return true;
				}
				return false;
			}
			int num = trnNo;
			trnNo = newTrnNo;
			if (CheckNewTrnNo())
			{
				result = "Sorry voucher no already exist in database please change voucher no.";
				return false;
			}
			trnNo = num;
			DeleteJournalDetails();
			trnNo = newTrnNo;
			if (InsertJournalDetails(ref result, Conversions.ToString(trnNo)))
			{
				return true;
			}
			return false;
		}

