	public class cls_kflMaster
	{
		private cls_Master masterFunction;

		private string kflName;

		private string kflCode;

		public cls_kflMaster()
		{
			masterFunction = new cls_Master();
		}

		public cls_kflMaster(string kflName)
		{
			masterFunction = new cls_Master();
			this.kflName = kflName;
		}

		public void setKflCode(string kflCode)
		{
			this.kflCode = kflCode;
		}

		public void setKflName(string kflName)
		{
			this.kflName = kflName;
		}

		public string getKflCode()
		{
			return kflCode;
		}

		public string getKflName()
		{
			return kflName;
		}

		public void getNewKflCode()
		{
			string s = "select top 1 kflCode from KflMaster where kflcode like '" + Conversions.ToString(kflName[0]) + "%' order by kflCode desc";
			kflCode = masterFunction.returnCode(s, kflName);
		}

		public void selectKflDetails()
		{
			string s = "SELECT companyCode, kflCode, kflName FROM kflMaster where companyCode='" + mdl_public_variables.companycode + "' and kflCode='" + kflCode + "'";
			DataSet dataSet = masterFunction.editMaster(s);
			kflName = Conversions.ToString(dataSet.Tables[0].Rows[0][2]);
		}

		public void insertKflMaster()
		{
			string s = "INSERT INTO kflMaster(companyCode, kflCode, kflName) VALUES ('" + mdl_public_variables.companycode + "','" + kflCode + "','" + kflName + "')";
			masterFunction.insertIntoDatabase(s);
		}

		public void updateKflMaster()
		{
			string s = "UPDATE kflMaster SET kflName = '" + kflName + "' where companyCode='" + mdl_public_variables.companycode + "' and kflCode = '" + kflCode + "'";
			masterFunction.insertIntoDatabase(s);
		}

		public void DeleteKflMaster()
		{
			string s = "delete from kflMaster where companyCode = '" + mdl_public_variables.companycode + "' and kflCode = '" + kflCode + "'";
			masterFunction.deleteMaster(s);
		}

		public bool checkKflName(int type)
		{
			string s = ((type != 1) ? ("select * from kflMaster where companyCode = '" + mdl_public_variables.companycode + "' and kflName = '" + kflName + "' and kflCode <> '" + kflCode + "' ") : ("select * from kflMaster where companyCode = '" + mdl_public_variables.companycode + "' and kflName = '" + kflName + "' "));
			DataSet dataSet = masterFunction.editMaster(s);
			if (dataSet.Tables[0].Rows.Count > 0)
			{
				return true;
			}
			return false;
		}
	}
