		public void selectLedgerDetails()
		{
			string s = "SELECT     MasterAccountsLedger.companyCode, MasterAccountsLedger.AccGroupCode, MasterAccountsLedger.ledgerCode, MasterAccountsLedger.ledgerName as LedgerName,                        MasterAccountsLedger.contactPerson as ContractPerson, MasterAccountsLedger.contactNo as ContractNo, MasterAccountsLedger.address1, MasterAccountsLedger.address2,                       MasterAccountsLedger.city, MasterAccountsLedger.district, MasterAccountsLedger.state, MasterAccountsLedger.pin, MasterAccountsLedger.phn,                        MasterAccountsLedger.faxNo, MasterAccountsLedger.email, MasterAccountsLedger.webSite, MasterAccountsLedger.vat, MasterAccountsLedger.pan,  \t\t\t\t\t  MasterAccountsOpening.TrnAmount as OpenAmount,                       CASE WHEN MasterAccountsOpening.TrnEffect = - 1 THEN 'Debit' ELSE CASE WHEN MasterAccountsOpening.TrnEffect = 1 THEN 'Credit' ELSE '' END END AS 'OpenType',   CASE WHEN MasterAccountsLedger.CreditEffects = - 1 THEN 'Debit' ELSE CASE WHEN MasterAccountsLedger.CreditEffects = 1 THEN 'Credit' ELSE '' END END AS 'LedgerCreditType',   MasterAccountsLedger.CreditEffects,  MasterAccountsGroups.AccGroupName as AccountsGroup, MasterAccountsGroups.ShortCode,  CASE WHEN MasterAccountsGroups.CreditEffects = - 1 THEN 'Debit' ELSE CASE WHEN MasterAccountsGroups.CreditEffects = 1 THEN 'Credit' ELSE '' END END AS 'GroupCreditType',  MasterAccountsGroups.CreditEffects AS CreditEffectsGroup, MasterAccountsLedger.LockAmount, MasterAccountsLedger.LockEffect  , MasterAccountsLedger.BankName,MasterAccountsLedger.BranchName,MasterAccountsLedger.AccountNo,MasterAccountsLedger.IfcCode FROM         MasterAccountsLedger LEFT OUTER JOIN                       MasterAccountsOpening ON MasterAccountsLedger.companyCode = MasterAccountsOpening.companyCode AND                         MasterAccountsLedger.ledgerCode = MasterAccountsOpening.ledgerCode INNER JOIN                        MasterAccountsGroups ON MasterAccountsLedger.companyCode = MasterAccountsGroups.companyCode AND                         MasterAccountsLedger.AccGroupCode = MasterAccountsGroups.AccGroupCode  WHERE     (MasterAccountsLedger.companyCode = '" + mdl_public_variables.companycode + "' AND MasterAccountsLedger.ledgerCode = '" + ledgerCode + "')  ORDER BY MasterAccountsLedger.ledgerName";
			DataSet dataSet = masterFunction.editMaster(s);
			ledgerName = Conversions.ToString(dataSet.Tables[0].Rows[0][3]);
			groupName = dataSet.Tables[0].Rows[0][22].ToString();
			groupCode = dataSet.Tables[0].Rows[0][1].ToString();
			contactPerson = dataSet.Tables[0].Rows[0][4].ToString();
			contactNo = dataSet.Tables[0].Rows[0][5].ToString();
			addr1 = dataSet.Tables[0].Rows[0][6].ToString();
			addr2 = dataSet.Tables[0].Rows[0][7].ToString();
			city = dataSet.Tables[0].Rows[0][8].ToString();
			Pin = dataSet.Tables[0].Rows[0][11].ToString();
			district = dataSet.Tables[0].Rows[0][9].ToString();
			state = dataSet.Tables[0].Rows[0][10].ToString();
			phn = dataSet.Tables[0].Rows[0][12].ToString();
			maild = dataSet.Tables[0].Rows[0][14].ToString();
			webSite = dataSet.Tables[0].Rows[0][15].ToString();
			pan = dataSet.Tables[0].Rows[0][17].ToString();
			vat = dataSet.Tables[0].Rows[0][16].ToString();
			if (!Information.IsDBNull(RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[0][18])))
			{
				balance = Conversions.ToDouble(dataSet.Tables[0].Rows[0][18].ToString());
			}
			else
			{
				balance = 0.0;
			}
			if (Operators.CompareString(dataSet.Tables[0].Rows[0][19].ToString(), "Debit", false) == 0)
			{
				TrnEffect = -1;
			}
			else
			{
				TrnEffect = 1;
			}
			faxNo = dataSet.Tables[0].Rows[0][13].ToString();
			CreditEffectsGroup = Conversions.ToInteger(dataSet.Tables[0].Rows[0][25].ToString());
			if (!Information.IsDBNull(RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[0][21])))
			{
				creditEffect = Conversions.ToInteger(dataSet.Tables[0].Rows[0][21].ToString());
			}
			else
			{
				creditEffect = CreditEffectsGroup;
			}
			ShortCode = dataSet.Tables[0].Rows[0][23].ToString();
			LockAmount = Conversions.ToDouble(dataSet.Tables[0].Rows[0][26].ToString());
			LockEffect = Conversions.ToInteger(dataSet.Tables[0].Rows[0][27].ToString());
			bankName = dataSet.Tables[0].Rows[0][28].ToString();
			branchName = dataSet.Tables[0].Rows[0][29].ToString();
			accountNo = dataSet.Tables[0].Rows[0][30].ToString();
			IfcCode = dataSet.Tables[0].Rows[0][31].ToString();
		}

