	public class cls_Master
	{
		public cls_DataAccess dataAccess;

		public cls_conn ob;

		private string s;

		private DataSet ds;

		public cls_Master()
		{
			dataAccess = new cls_DataAccess();
			ob = new cls_conn();
			s = null;
			ds = null;
		}

		public void insertIntoDatabase(string s)
		{
			this.s = s;
			dataAccess.insert(s);
		}

		public DataSet editMaster(string s)
		{
			this.s = s;
			ds = ob.populate(s);
			return ds;
		}

		public void deleteMaster(string s)
		{
			this.s = s;
			dataAccess.insert(s);
		}

		public string returnCode(string s, string name)
		{
			string text = null;
			return dataAccess.getcode(s, name);
		}

		public string returnLedgerCode(string s, string name)
		{
			string text = null;
			return dataAccess.getLedgercode(s, name);
		}

		public bool compareTwoValue(string s)
		{
			bool result = false;
			if (Conversions.ToDouble(dataAccess.singleValueReturn(s)) > 0.0)
			{
				result = true;
			}
			return result;
		}

		public object returnCode(string s)
		{
			string text = null;
			text = Conversion.Val(dataAccess.singleValueReturn(s)).ToString();
			return checked(int.Parse(text) + 1).ToString();
		}
	}
