		public void insertMenuMaster(string transactionType)
		{
			string s = "";
			if (Operators.CompareString(transactionType, "Outlet Menu Master", false) == 0)
			{
				s = "INSERT INTO menuMaster(companyCode,                                     subMenuCode,             menuCode,          menuName,           storeKitchenCode,           unitCode,           taxSchemeCode,          menuRate,            isInventoryItem,           shortName,          estimatedCost,          calculateBillDiscount,         preparationTime,         restaurantCode,          restaurantMenuCode,          allowRateChange,          mainMenuCode,           imagePath,         menuPrinter) VALUES ('" + mdl_public_variables.companycode + "','" + SubGroupCode + "' , '" + menuCode + "','" + menuName + "' ,'" + storeKitchenCode + "' ,'" + unitCode + "' ,'" + taxSchemeCode + "' ," + Conversions.ToString(menuRate) + " ,  '" + Conversions.ToString(isInventoryItem) + "' ,'" + shortName + "' ," + Conversions.ToString(estimatedCost) + " ,'" + Conversions.ToString(calculateBillDiscount) + "' ," + Conversions.ToString(preprationTime) + ",'" + restaurantCode + "','" + restaurantMenuCode + "','" + Conversions.ToString(allowRateChange) + "','" + mainGroupCode + "','" + imagePath + "','" + printer + "' ) ";
			}
