	public class cls_Print
	{
		[DebuggerNonUserCode]
		public cls_Print()
		{
		}

		public string space_cal(string str_num, int count_space)
		{
			string text = "";
			checked
			{
				count_space -= Strings.Len(str_num);
				int num = count_space - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					text += " ";
					num2++;
				}
				return text;
			}
		}

		public string centre_alignment(string str_num, int count_space)
		{
			string text = "";
			checked
			{
				count_space = (int)Math.Round((double)(count_space - Strings.Len(str_num)) / 2.0);
				int num = count_space - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					text += " ";
					num2++;
				}
				return text;
			}
		}

