		public DataSet selectReconciliationDetails()
		{
			string s = "SELECT ROW_NUMBER() Over (Order By TransactionMain.TrnNo) as RowIndex,CONVERT(VARCHAR,TransactionMain.IndexId) as IndexId ,TransactionMain.TrnNo AS VchNo,  \r\n  MasterAccountsLedger.ledgerName AS ACName,CASE WHEN TransactionDetail.TrnEffect=-1   \r\n  THEN TransactionDetail.TrnAmount ELSE '' END AS Debit,  \r\n  CASE WHEN TransactionDetail.TrnEffect=-1 THEN '' ELSE TransactionDetail.TrnAmount END AS Credit,  \r\n  ISNULL(CONVERT(varchar,TransactionReconciliation.VchDate,103),CONVERT(varchar,TransactionMain.VchDate,103)) as VchDate,    \r\n  TransactionMain.TrnType,ISNULL(CONVERT(varchar,TransactionReconciliation.ReconciliationDate,103),'') as ReconciliationDate , \r\n  CASE WHEN  ISNULL(convert(varchar,TransactionReconciliation.VchDate,103),'') = '' THEN 'INSERT' ELSE 'UPDATE' END AS [Status], \r\n  TransactionMain.ReceiptType,TransactionMain.ChequeNo \r\n  FROM TransactionDetail   \r\n  LEFT OUTER JOIN  MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode   \r\n  AND TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode  \r\n  LEFT OUTER JOIN  TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode   \r\n  AND TransactionDetail.yearcode = TransactionMain.yearcode AND TransactionDetail.restaurantCode = TransactionMain.restaurantCode   \r\n  AND TransactionDetail.IndexId = TransactionMain.IndexId    \r\n  LEFT OUTER JOIN TransactionReconciliation ON TransactionMain.companycode=TransactionReconciliation.companycode   \r\n  AND TransactionMain.yearcode=TransactionReconciliation.yearcode   \r\n  AND TransactionMain.restaurantCode=TransactionReconciliation.restaurantCode AND TransactionMain.IndexId=TransactionReconciliation.IndexId   \r\n  AND TransactionMain.TrnType=TransactionReconciliation.TrnType   \r\n  AND TransactionMain.TrnNo=TransactionReconciliation.TrnNo   \r\n WHERE (TransactionDetail.IndexId IN  (SELECT IndexId  FROM TransactionDetail AS TransactionDetail_1   \r\n WHERE (TrnAccount = '" + TrnAccount + "') AND (companycode = '" + mdl_public_variables.companycode + "') AND (yearcode = '" + mdl_public_variables.yearcode + "'))) AND (TransactionDetail.companycode = '" + mdl_public_variables.companycode + "') AND    \r\n (TransactionDetail.yearcode = '" + mdl_public_variables.yearcode + "') AND (TransactionDetail.TrnAccount <> '" + TrnAccount + "') AND    \r\n (TransactionMain.VchDate BETWEEN CONVERT(varchar, '" + Conversions.ToString(fromeDate) + "', 103) AND CONVERT(VARCHAR, '" + Conversions.ToString(toDate) + "', 103)) ";
			return ob.populate(s);
		}

