			bool flag = false;
			return flag;
		}

		public void setNewStoreCode()
		{
			string s = "select top 1 storeKitchenCode from storeKitchenMaster where storeKitchenName like '" + Conversions.ToString(storeName[0]) + "%' and companyCode like '" + mdl_public_variables.companycode + "' order by storeKitchenCode desc";
			storeCode = masterFunction.returnCode(s, storeName);
		}

		public void insertInDatabase()
		{
			string s = "INSERT INTO storeKitchenMaster (companyCode, storeKitchenCode, storeKitchenName,type) VALUES ('" + mdl_public_variables.companycode + "','" + storeCode + "','" + storeName + "','" + storeKitchenType + "')";
			masterFunction.insertIntoDatabase(s);
		}

		public void selectFromDatabase()
		{
			string s = "SELECT companyCode, storeKitchenCode, storeKitchenName,type FROM storeKitchenMaster where companyCode = '" + mdl_public_variables.companycode + "' and storeKitchenCode='" + storeCode + "'";
			DataSet dataSet = masterFunction.editMaster(s);
			storeName = Conversions.ToString(dataSet.Tables[0].Rows[0][2]);
			storeKitchenType = Conversions.ToString(dataSet.Tables[0].Rows[0][3]);
		}

		public void updateStoreKitchen()
		{
			string s = "UPDATE storeKitchenMaster SET storeKitchenName ='" + storeName + "',type = '" + storeKitchenType + "' where companyCode='" + mdl_public_variables.companycode + "' and storeKitchenCode='" + storeCode + "' ";
			masterFunction.insertIntoDatabase(s);
		}

		public void deleteStoreKitchen()
		{
			string s = "delete from storeKitchenMaster where companyCode='" + mdl_public_variables.companycode + "' and storeKitchenCode='" + storeCode + "'";
			masterFunction.deleteMaster(s);
		}

		public bool checkStoreKitchenName(int type)
		{
			string s = ((type != 1) ? ("select * from storeKitchenMaster where companyCode = '" + mdl_public_variables.companycode + "' and storeKitchenName = '" + storeName + "' and StoreKitchenCode<>'" + storeCode + "' ") : ("select * from storeKitchenMaster where companyCode = '" + mdl_public_variables.companycode + "' and storeKitchenName = '" + storeName + "' "));
			DataSet dataSet = masterFunction.editMaster(s);
			if (dataSet.Tables[0].Rows.Count > 0)
			{
				return true;
			}
			return false;
		}
	}
