			masterFunction.insertIntoDatabase(s);
		}

		public bool checkStrengthName(int type, string strengthName)
		{
			string s;
			if (type == 1)
			{
				s = "select * from strengthMaster where companyCode='" + mdl_public_variables.companycode + "' and strengthName = '" + this.strengthName + "'";
			}
			else
			{
				if (Operators.CompareString(this.strengthName, strengthName, false) == 0)
				{
					return false;
				}
				s = "select * from strengthMaster where companyCode='" + mdl_public_variables.companycode + "' and strengthName = '" + strengthName + "'";
			}
			DataSet dataSet = masterFunction.editMaster(s);
			if (dataSet.Tables[0].Rows.Count > 0)
			{
				return true;
			}
			return false;
		}
	}
