		private void frm_ask4help_Load(object sender, EventArgs e)
		{
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Expected O, but got Unknown
			//IL_0058: Unknown result type (might be due to invalid IL or missing references)
			//IL_005e: Expected O, but got Unknown
			((Form)this).Icon = Icon.FromHandle(Resources.Help.GetHicon());
			PictureBox1.Image = (Image)mdl_public_variables.clear_back(Resources.ABM_logo);
			string text = Application.StartupPath.ToString();
			ManagementObject val = new ManagementObject("win32_logicaldisk.deviceid=\"" + Conversions.ToString(text[0]) + ":\"");
			val.Get();
			txt_id.Text = ((ManagementBaseObject)val)["VolumeSerialNumber"].ToString();
			if (!MyProject.Forms.frm_main.flgout)
			{
				txt_companyname.Text = mdl_public_variables.companyname;
				txt_address1.Text = mdl_public_variables.comaddress1;
				txt_address2.Text = mdl_public_variables.comaddress2;
				txt_city.Text = mdl_public_variables.comcity;
				txt_state.Text = mdl_public_variables.comstate;
				txt_pin.Text = mdl_public_variables.compin;
				txt_phone.Text = mdl_public_variables.comphone;
			}
			txt_abmrepresent.Text = "Self";
			if (File.Exists(Application.StartupPath.ToString() + "\\ABM.dll"))
			{
				Assembly assembly = Assembly.Load("ABM");
				object objectValue = RuntimeHelpers.GetObjectValue(assembly.CreateInstance("ABM.Cls_abm"));
				NewLateBinding.LateCall(objectValue, (Type)null, "status", new object[0], (string[])null, (Type[])null, (bool[])null, true);
				dc = Conversions.ToString(NewLateBinding.LateGet(objectValue, (Type)null, "code", new object[0], (string[])null, (Type[])null, (bool[])null));
			}
			NetworkInterface[] allNetworkInterfaces = NetworkInterface.GetAllNetworkInterfaces();
			mac = allNetworkInterfaces[0].GetPhysicalAddress().ToString();
			((Control)txt_companyname).Select();
		}

		public string getMacAddress()
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Expected O, but got Unknown
