			//IL_0032: Expected O, but got Unknown
			string text = string.Empty;
			ManagementClass val = new ManagementClass("Win32_NetworkAdapterConfiguration");
			ManagementObjectCollection instances = val.GetInstances();
			ManagementObjectEnumerator enumerator = default(ManagementObjectEnumerator);
			try
			{
				enumerator = instances.GetEnumerator();
				while (enumerator.MoveNext())
				{
					ManagementObject val2 = (ManagementObject)enumerator.Current;
					if ((Operators.CompareString(text, string.Empty, false) == 0) & Conversions.ToBoolean(((ManagementBaseObject)val2).Properties["IPEnabled"].Value))
					{
						text = ((ManagementBaseObject)val2).Properties["MacAddress"].Value.ToString();
					}
				}
			}
			finally
			{
				((IDisposable)enumerator)?.Dispose();
			}
			return text;
		}

