		private void Button1_Click_1(object sender, EventArgs e)
		{
			//IL_0480: Unknown result type (might be due to invalid IL or missing references)
			//IL_0314: Unknown result type (might be due to invalid IL or missing references)
			//IL_044e: Unknown result type (might be due to invalid IL or missing references)
			string text = "";
			text = "Customer Id: " + txt_id.Text + "\r\nCode: " + dc + "\r\n1st ID: " + mac + "\r\n2nd ID Confirm: " + getMacAddress() + "\r\n3rd: " + getMB_ID() + "\r\n4th: " + getCPU_ID() + "\r\nSoftware: " + Application.ProductName.ToString() + "\r\nType: Full\r\nVersion: " + Application.ProductVersion + "\r\nCompany Name: " + txt_companyname.Text + "\r\nAddress: " + txt_address1.Text + "\r\n" + txt_address2.Text + "\r\nCity: " + txt_city.Text + "\r\nState: " + txt_state.Text + "\r\nPIN: " + txt_pin.Text + "\r\nPhone: " + txt_phone.Text + "\r\nFax: " + mdl_public_variables.fax + "\r\nE-Mail: " + txt_mail.Text + "\r\nWebsite: " + txt_www.Text + "\r\nContact Person: " + txt_person.Text + "\r\nContact No: " + txt_phone.Text + "\r\nABM Representative: " + txt_abmrepresent.Text + "\r\nProblem: " + txt_problem.Text;
			if ((Operators.CompareString(txt_id.Text, "", false) == 0) | (Operators.CompareString(txt_companyname.Text, "", false) == 0) | (Operators.CompareString(txt_address1.Text, "", false) == 0) | (Operators.CompareString(txt_person.Text, "", false) == 0) | (Operators.CompareString(txt_phone.Text, "", false) == 0) | (Operators.CompareString(txt_abmrepresent.Text, "", false) == 0) | (Operators.CompareString(txt_problem.Text, "", false) == 0))
			{
				Interaction.MsgBox((object)"PLease fill all the information", (MsgBoxStyle)64, (object)null);
				return;
			}
			if (!File.Exists(Application.StartupPath.ToString() + "\\Help.msi"))
			{
				File.Create(Application.StartupPath.ToString() + "\\Help.msi").Close();
			}
			File.WriteAllText(Application.StartupPath.ToString() + "\\Help.msi", text);
			string[] array = txt_problem.Text.Split(new char[1] { Conversions.ToChar(Environment.NewLine) });
			try
			{
				SmtpClient smtpClient = new SmtpClient();
				MailMessage mailMessage = new MailMessage();
				smtpClient.Credentials = new NetworkCredential("madhushala.report@gmail.com", "abmtech1330");
				smtpClient.Port = 587;
				smtpClient.Host = "smtp.gmail.com";
				smtpClient.EnableSsl = true;
				mailMessage.To.Add("info@abmtechno.com");
				mailMessage.From = new MailAddress("madhushala.report@gmail.com");
				mailMessage.Subject = array[0];
				mailMessage.Body = text;
				mailMessage.Attachments.Add(new Attachment(Application.StartupPath + "\\Help.msi"));
				smtpClient.Send(mailMessage);
				Interaction.MsgBox((object)"Help message sent successfully.", (MsgBoxStyle)64, (object)null);
				((Control)MyProject.Forms.frm_main).Enabled = true;
				((Form)this).Close();
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				Interaction.MsgBox((object)ex2.ToString(), (MsgBoxStyle)0, (object)null);
				ProjectData.ClearProjectError();
			}
		}

