		private void gettrn()
		{
			s = "select top 1 trnno from breakagemain where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "' order by cast ( trnno As Integer)   desc";
			TextBox2.Text = ob.executereader(s);
			if (Operators.CompareString(TextBox2.Text, (string)null, false) == 0)
			{
				TextBox2.Text = "1";
			}
			else
			{
				TextBox2.Text = Conversions.ToString(Conversion.Val(TextBox2.Text) + 1.0);
			}
		}

