		private void cmb_strore_SelectedIndexChanged(object sender, EventArgs e)
		{
			EnumerableRowCollection<object> source = from p in ds1.Tables[0].AsEnumerable()
				where Operators.ConditionalCompareObjectEqual(p[1], (object)cmb_strore.Text, false)
				select p[0];
			breakage_store_code = source.ElementAtOrDefault(0).ToString();
			itemload();
		}

