		private void ComboBox2_SelectedIndexChanged(object sender, EventArgs e)
		{
			cmb_billno.Items.Clear();
			cmb_tppass.Items.Clear();
			if (!rad_open.Checked)
			{
				EnumerableRowCollection<object> source = from p in ds2.Tables[0].AsEnumerable()
					where Operators.ConditionalCompareObjectEqual(p[1], (object)cmb_party.Text, false)
					select p[0];
				breakage_ledgercode = source.ElementAtOrDefault(0).ToString();
			}
			else
			{
				breakage_ledgercode = ob.executereader("select ledgerCode from MasterAccountsLedger where ledgerName='" + mdl_public_variables.breakage_party_name + "' and companyCode='" + mdl_public_variables.companycode + "'  ");
			}
			if (dset_bill_no.Tables.Count > 0)
			{
				dset_bill_no.Tables.Clear();
			}
			s = "select '0',docno from purchasemain where companycode='" + mdl_public_variables.companycode + "' and yearcode ='" + mdl_public_variables.yearcode + "' and suppliercode='" + breakage_ledgercode + "' and ptype<>'RETURN'";
			dset_bill_no = ob.populate(s);
			if (dset_tppass_no.Tables.Count > 0)
			{
				dset_tppass_no.Tables.Clear();
			}
			s = "select '0',tppassno from purchasemain where companycode='" + mdl_public_variables.companycode + "' and yearcode ='" + mdl_public_variables.yearcode + "' and suppliercode='" + breakage_ledgercode + "' and ptype<>'RETURN'";
			dset_tppass_no = ob.populate(s);
			ob.combofill(dset_bill_no.Tables[0], cmb_billno);
			ob.combofill(dset_tppass_no.Tables[0], cmb_tppass);
			if (dset_bill_no.Tables[0].Rows.Count > 0)
			{
				cmb_billno.SelectedIndex = 0;
			}
			else if (dset_tppass_no.Tables[0].Rows.Count > 0)
			{
				cmb_tppass.SelectedItem = RuntimeHelpers.GetObjectValue(dset_tppass_no.Tables[0].Rows[0][1]);
			}
			itemload();
		}

