		private void cmb_billno_SelectedIndexChanged(object sender, EventArgs e)
		{
			if (rad_supplierwise.Checked)
			{
				billno = Conversions.ToString(cmb_billno.SelectedItem);
				s = "select tppassno from purchasemain where yearcode='" + mdl_public_variables.yearcode + "' and companycode ='" + mdl_public_variables.companycode + "' and docno='" + cmb_billno.Text + "' and suppliercode='" + breakage_ledgercode + "' and ptype<>'RETURN'";
				s = ob.executereader(s);
				if (Operators.CompareString(cmb_tppass.Text, s, false) != 0)
				{
					cmb_tppass.Text = s;
				}
				if (!Conversions.ToBoolean(Operators.AndObject(Operators.CompareObjectEqual(flag, (object)1, false), (object)rad_supplierwise.Checked)))
				{
				}
			}
			itemload();
		}

