		private void ComboBox4_SelectedIndexChanged(object sender, EventArgs e)
		{
			if (rad_supplierwise.Checked)
			{
				pass_no = cmb_tppass.Text;
				s = "select docno from purchasemain where yearcode='" + mdl_public_variables.yearcode + "' and companycode ='" + mdl_public_variables.companycode + "' and tppassno='" + cmb_tppass.Text + "' and suppliercode='" + breakage_ledgercode + "' and ptype<>'RETURN'";
				s = ob.executereader(s);
				if (Conversions.ToBoolean(Operators.NotObject(Operators.CompareObjectEqual(cmb_billno.SelectedItem, (object)s, false))))
				{
					cmb_billno.SelectedItem = s;
				}
			}
			itemload();
		}

		private void breakageentry_Load(object sender, EventArgs e)
		{
			((Form)this).Icon = Icon.FromHandle(Resources.Broken_Bofftle.GetHicon());
			flag = mdl_public_variables.flag;
			((Control)MyProject.Forms.frm_Form1).Enabled = false;
			((TextBoxBase)TextBox2).ReadOnly = true;
			s = "select shopcode,shopname from storage where companycode='" + mdl_public_variables.companycode + "'";
			ds1 = ob.populate(s);
			s = "select ledgerCode,ledgerName  \r\n from MasterAccountsLedger join MasterAccountsGroups on MasterAccountsGroups.AccGroupCode=MasterAccountsLedger.AccGroupCode \r\n and MasterAccountsLedger.companyCode=MasterAccountsGroups.companyCode \r\n where MasterAccountsLedger.companyCode='" + mdl_public_variables.companycode + "'  \r\n and MasterAccountsGroups.AccGroupName like '%SUPPLIERS' or MasterAccountsLedger.companyCode='" + mdl_public_variables.companycode + "' \r\n and MasterAccountsGroups.AccGroupName like '%CREDITORS' order by ledgerName ";
			ds2 = ob.populate(s);
			ob.combofill(ds1.Tables[0], cmb_strore);
			ob.combofill(ds2.Tables[0], cmb_party);
			refresh_breakage_grid();
			((Control)dtp1).Select();
		}

		private void breakageentry_FormClosing(object sender, FormClosingEventArgs e)
		{
			((Control)MyProject.Forms.frm_Form1).Enabled = true;
		}

		private void itemload()
		{
			if (rad_supplierwise.Checked)
			{
				s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)string.Concat(string.Concat(string.Concat("select itemcode, itemname, sum(itemquantity) as qnty,packing,ml,ItemType \r\n from \r\n (  \r\n \tSELECT itemmst.itemcode, itemmst.itemname, itemquantity,itemmst.packing,itemmst.ml,itemmst.kflname as ItemType  \r\n \tFROM purchasedetail  \r\n \tJOIN vw_itemCodebarCode as  itemmst ON itemmst.itemcode = purchasedetail.itemcode  \r\n \tAND itemmst.companycode = purchasedetail.companycode  \r\n \tJOIN purchasemain ON purchasedetail.companycode = purchasemain.companycode  \r\n \tAND purchasedetail.yearcode = purchasemain.yearcode AND purchasedetail.trnno = purchasemain.trnno  \r\n \tWHERE purchasedetail.yearcode = '" + mdl_public_variables.yearcode, "' AND purchasedetail.companycode = '"), mdl_public_variables.companycode), "' and purchasemain.shopcode='"), ds1.Tables[0].Rows[cmb_strore.SelectedIndex][0]), (object)"' \r\n"), (object)" \tAND purchasemain.docno = '"), cmb_billno.SelectedItem), (object)"' and purchasemain.ptype<>'RETURN'and purchasemain.ptype<>'RETURN'  \r\n"), (object)" \tunion all  \r\n"), (object)" \tSELECT itemmst.itemcode, itemmst.itemname, (quantity*(-1)) as itemquantity,itemmst.packing,itemmst.ml,itemmst.kflname as ItemType   \r\n"), (object)" \tFROM breakagedetail  \r\n"), (object)" \tJOIN vw_itemCodebarCode as itemmst ON itemmst.itemcode = breakagedetail.itemcode  \r\n"), (object)" \tAND itemmst.companycode = breakagedetail.companycode  \r\n"), (object)" \tJOIN breakagemain ON breakagedetail.companycode = breakagemain.companycode  \r\n"), (object)" \tAND breakagedetail.yearcode = breakagemain.yearcode And breakagedetail.trnno = breakagemain.trnno  \r\n"), (object)" \tWHERE breakagedetail.yearcode = '"), (object)mdl_public_variables.yearcode), (object)"' AND breakagedetail.companycode = '"), (object)mdl_public_variables.companycode), (object)"' and breakagemain.shopcode='"), ds1.Tables[0].Rows[cmb_strore.SelectedIndex][0]), (object)"'  \r\n"), (object)" \tAND breakagemain.billno = '"), cmb_billno.SelectedItem), (object)"'  \r\n"), (object)" )as x group by x.itemcode, x.itemname,x.packing,x.ml,x.ItemType "));
			}
			else
			{
				s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)string.Concat(string.Concat(string.Concat(string.Concat(string.Concat(string.Concat(string.Concat(string.Concat(string.Concat("SELECT itemmst.itemcode,itemmst.itemname, isnull(opening_closing_stock.stock,0) AS qnty,itemmst.packing,itemmst.ml, \r\n itemmst.kflname as ItemType    \r\n FROM vw_itemCodebarCode as  itemmst  \r\n left JOIN dbo.opening_closing_stock('" + Conversions.ToString(mdl_public_variables.comstdate), "','"), Conversions.ToString(dtp1.Value.Date)), "','"), Conversions.ToString(dtp1.Value.Date)), "')  \r\n"), " ON itemmst.companycode = opening_closing_stock.companycode and itemmst.itemcode = opening_closing_stock.itemcode  \r\n"), " WHERE itemmst.companycode = '"), mdl_public_variables.companycode), "' and storecode='"), ds1.Tables[0].Rows[cmb_strore.SelectedIndex][0]), (object)"' \r\n"), (object)" order by itemmst.itemname "));
			}
			dsitems = ob.populate(s);
			cmb_item.Items.Clear();
			dgv_item.Columns.Clear();
			cmb_item.Items.Add((object)"SELECT ITEM");
			if (dsitems.Tables[0].Rows.Count > 0)
			{
				ob.combofill(dsitems.Tables[0], cmb_item);
				cmb_item.SelectedIndex = 0;
				dgv_item.Columns[1].HeaderText = "ITEM NAME";
				dgv_item.Columns[2].HeaderText = "QNTY";
				dgv_item.Columns[5].HeaderText = "ITEM TYPE";
