		private void frmcompanyload()
		{
			if (mdl_public_variables.flag == 1)
			{
				s = "select companycode,companyname from companymast order by companyname";
				dscom = ob.populate(s);
				if (dscom.Tables[0].Rows.Count > 0)
				{
					((Control)chk_copymast).Visible = true;
					cmb_comname.Items.Clear();
					ob.combofill(dscom.Tables[0], cmb_comname);
					cmb_comname.SelectedIndex = 0;
				}
			}
			txt_cname.Text = null;
			txt_address.Text = null;
			txt_adress2.Text = null;
			txt_city.Text = null;
			txt_district.Text = null;
			txt_state.Text = null;
			txt_pin.Text = null;
			txt_phone.Text = null;
			txt_faxno.Text = null;
			txt_email.Text = null;
			txt_website.Text = null;
			dtp_startdate.Text = null;
			dtp_end_date.Text = null;
			txt_pan.Text = null;
			txt_vat.Text = null;
			txt_lst.Text = null;
			txt_cst.Text = null;
			txt_st.Text = null;
			check = false;
			((Control)MyProject.Forms.frm_Form1).Enabled = false;
		}

