		private void comexist()
		{
			//IL_0065: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b3: Unknown result type (might be due to invalid IL or missing references)
			s = "select count(*) from companymast where companyname='" + txt_cname.Text + "'";
			s = ob.executereader(s);
			if (Convert.ToInt32(s) > 0)
			{
				if (mdl_public_variables.flag == 1)
				{
					Interaction.MsgBox((object)"Company already exist, Please enter new Company", (MsgBoxStyle)64, (object)"Company Exist");
					check = true;
				}
				else if ((mdl_public_variables.flag == 2) & (Operators.CompareString(txt_cname.Text.ToUpper(), mdl_public_variables.comname.ToUpper(), false) != 0))
				{
					Interaction.MsgBox((object)"Company already exist, Please enter new Company", (MsgBoxStyle)64, (object)"Company Exist");
					check = true;
				}
				((Control)txt_cname).Select();
			}
		}

		private void get_company_code()
		{
			s = "select top 1 companycode from companymast order by companycode desc";
			s = ob.executereader(s);
			if (Operators.CompareString(s, (string)null, false) != 0)
			{
				ccode = Conversions.ToString(checked(Convert.ToInt32(s) + 1));
			}
			else
			{
				ccode = Conversions.ToString(1);
			}
		}

		private void get_yearcode()
		{
			s = "select top 1 yearcode from yearmst where companycode='" + ccode + "' order by yearcode desc";
			s = ob.executereader(s);
			if (Operators.CompareString(s, (string)null, false) != 0)
			{
				ycode = Conversions.ToString(checked(Convert.ToInt32(s) + 1));
			}
			else
			{
				ycode = Conversions.ToString(1);
			}
		}

		private void Button1_Click(object sender, EventArgs e)
		{
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0696: Unknown result type (might be due to invalid IL or missing references)
			//IL_06b4: Unknown result type (might be due to invalid IL or missing references)
			check = false;
			comexist();
			if (Operators.CompareString(Strings.Trim(txt_cname.Text), "", false) == 0)
			{
				Interaction.MsgBox((object)"Blank company Name, please enter company name.", (MsgBoxStyle)64, (object)null);
				return;
			}
			if (!check)
			{
				if ((mdl_public_variables.flag == 1) & (Operators.CompareString(dtp_startdate.Text, (string)null, false) != 0) & (Operators.CompareString(dtp_end_date.Text, (string)null, false) != 0))
				{
					get_company_code();
					s = "insert into companymast (companycode,companyname,address1,city,pin,stat,phn,email,website,address2,district,faxno,lstno,cstno,panno,vatno,stno ) values('" + ccode + "','" + txt_cname.Text.ToUpper() + "','" + txt_address.Text.ToUpper() + "','" + txt_city.Text.ToUpper() + "','" + txt_pin.Text + "','" + txt_state.Text.ToUpper() + "','" + txt_phone.Text + "','" + txt_email.Text + "','" + txt_website.Text + "','" + txt_adress2.Text.ToUpper() + "','" + txt_district.Text.ToUpper() + "','" + txt_faxno.Text.ToUpper() + "', '" + txt_lst.Text.ToUpper() + "', '" + txt_cst.Text.ToUpper() + "', '" + txt_pan.Text.ToUpper() + "', '" + txt_vat.Text.ToUpper() + "', '" + txt_st.Text.ToUpper() + "')";
					ob.insert(s);
					get_yearcode();
					s = "insert into yearmst(yearcode,yearrange,stdate,enddate,companycode) values('" + ycode + "','" + dtp_startdate.Text + "-" + dtp_end_date.Text + "','" + dtp_startdate.Text + "-04-01','" + dtp_end_date.Text + "-03-31','" + ccode + "')";
					ob.insert(s);
					s = "insert into itemrateinfo(ratecode,ratename,companycode) values('G00001','GENERAL','" + ccode + "')";
					ob.insert(s);
					s = "insert into itemratemst(companycode,ratecode,itemcode,salesrate) (select('" + ccode + "') as companycode,'G00001' as ratecode,itemcode,salesrate from itemratemst where companycode='" + mdl_public_variables.companycode + "' and ratecode='G00001')";
					ob.insert(s);
					if (chk_copymast.Checked)
					{
						copymast();
					}
				}
				else if (mdl_public_variables.flag == 2)
				{
					s = "update companymast  set companyname='" + txt_cname.Text.ToUpper() + "',  address1='" + txt_address.Text.ToUpper() + "',city='" + txt_city.Text.ToUpper() + "',pin='" + txt_pin.Text + "',stat='" + txt_state.Text.ToUpper() + "',phn='" + txt_phone.Text + "',email='" + txt_email.Text + "',website='" + txt_website.Text + "',address2='" + txt_adress2.Text.ToUpper() + "',district='" + txt_district.Text.ToUpper() + "',faxno='" + txt_faxno.Text + "',lstno='" + txt_lst.Text.ToUpper() + "',cstno='" + txt_cst.Text.ToUpper() + "',panno='" + txt_pan.Text.ToUpper() + "',vatno='" + txt_vat.Text.ToUpper() + "',stno ='" + txt_st.Text.ToUpper() + "' where companycode ='" + mdl_public_variables.comcode + "'";
					ob.insert(s);
					if (Operators.CompareString(mdl_public_variables.companycode, mdl_public_variables.comcode, false) == 0)
					{
						((ToolStripItem)MyProject.Forms.frm_main.tsl_company_name).Text = txt_cname.Text.ToUpper();
					}
				}
			}
			else if (mdl_public_variables.flag == 1)
			{
				Interaction.MsgBox((object)"company with this name is already exists or you hav'nt entered the starting and the ending year", (MsgBoxStyle)16, (object)null);
			}
			else if (mdl_public_variables.flag == 2)
			{
				Interaction.MsgBox((object)"company already exists", (MsgBoxStyle)16, (object)null);
			}
			if (mdl_public_variables.flag1 == 1)
			{
				frm_login frm_login2 = new frm_login();
				((Form)frm_login2).MdiParent = (Form)(object)MyProject.Forms.frm_main;
				((Control)frm_login2).Show();
				mdl_public_variables.flag1 = 0;
				((Form)this).Close();
			}
			else if (mdl_public_variables.flag == 1)
			{
				try
				{
					Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
				}
				frmcompanyload();
			}
			else if (mdl_public_variables.flag == 2)
			{
				if (Operators.CompareString(mdl_public_variables.companycode, mdl_public_variables.comcode, false) == 0)
				{
					mdl_public_variables.companyname = txt_cname.Text.ToUpper();
				}
				try
				{
					Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
				}
				catch (Exception ex3)
				{
					ProjectData.SetProjectError(ex3);
					Exception ex4 = ex3;
					ProjectData.ClearProjectError();
				}
				((Form)this).Close();
			}
		}

		private void copymast()
		{
			s = "insert into   ManufacturerMaster (Companycode, ManufacturerCode, ManufacturerName, ManufacturerDescription, column1, column2)(select('" + ccode + "') as companycode,ManufacturerCode,ManufacturerName,ManufacturerDescription, column1, column2 from ManufacturerMaster where companycode='" + mdl_public_variables.companycode + "')";
			ob.insert(s);
			s = "insert into categorymst( companycode, categorycode, categoryname, ManufacturerCode)(select('" + ccode + "') as companycode,categorycode,categoryname,ManufacturerCode from categorymst where companycode='" + mdl_public_variables.companycode + "')";
			ob.insert(s);
			s = "insert into groupmst(companycode,groupcode,groupname) (select('" + ccode + "') as companycode,groupcode,groupname from groupmst where companycode='" + mdl_public_variables.companycode + "')";
			ob.insert(s);
			s = "insert into kflmst(companycode,kflcode,kflname) (select('" + ccode + "') as companycode,kflcode,kflname from kflmst where companycode='" + mdl_public_variables.companycode + "') ";
			ob.insert(s);
			s = "insert into  MasterAccountsGroups( companyCode, AccMainCode, AccGroupCode, AccGroupName, ShortCode, PrimaryGroup, UnderAccGroupCode, PLEffect, CreditEffects, AccGroupAlias, Sequence, Hidden) \r\n ( \r\n SELECT\t('" + ccode + "') as companycode, AccMainCode, AccGroupCode, AccGroupName, ShortCode, PrimaryGroup, UnderAccGroupCode, PLEffect, CreditEffects, AccGroupAlias, Sequence, Hidden \r\n FROM  MasterAccountsGroups \r\n where MasterAccountsGroups.companycode='" + mdl_public_variables.companycode + "'\r\n  )  ";
			ob.insert(s);
			s = "insert into    MasterAccountsLedger  (companyCode, AccGroupCode, ledgerCode, ledgerName, contactPerson, contactNo, address1, address2, city, district, state, pin, phn, faxNo, email, webSite, vat, pan, ledgerNameAlias, CreditEffects,  \r\n \t\t\t\t\t\t\t\t\tLockAmount, LockEffect, Sequence, Hidden, rateCode, BankName, BranchName, AccountNo, IfcCode) \r\n ( \r\n SELECT\t\t\t\t\t\t\t\t('" + ccode + "') as companycode, AccGroupCode, ledgerCode, ledgerName, contactPerson, contactNo, address1, address2, city, district, state, pin, phn, faxNo, email, webSite, vat, pan, ledgerNameAlias, CreditEffects,  \r\n \t\t\t\t\t\t\t\t\tLockAmount, LockEffect, Sequence, Hidden, rateCode, BankName, BranchName, AccountNo, IfcCode \r\n FROM         MasterAccountsLedger \r\n where MasterAccountsLedger.companycode='" + mdl_public_variables.companycode + "'\r\n ) ";
			ob.insert(s);
			s = "INSERT INTO [taxdetail]([companycode],[SchemeCode] ,[schemename],[SrNo],[TaxCode],[taxname] \r\n ,[ledcode],[sig],[TaxRate],[taxamount],[calc_on],[base],[after_discount],[after_saletax]) \r\n (select '" + ccode + "' as[companycode],[SchemeCode] ,[schemename],[SrNo],[TaxCode],[taxname] \r\n ,[ledcode],[sig],[TaxRate],[taxamount],[calc_on],[base],[after_discount],[after_saletax] from [taxdetail] where [companycode]='" + mdl_public_variables.companycode + "'  ) \r\n";
			ob.insert(s);
			s = "insert into Itemgroupml(companycode,ml,packing) (select ('" + ccode + "') as companycode,ml,packing from Itemgroupml where companycode='" + mdl_public_variables.companycode + "') ";
			ob.insert(s);
			s = "insert into strength(companycode,strengthname) (select ('" + ccode + "') as companycode,strengthname from strength where companycode='" + mdl_public_variables.companycode + "') ";
			ob.insert(s);
			s = "insert into itemmst(companycode,groupcode,itemcode,itemname,categorycode,kflcode,packing,strengthname,ml,barcode,salesrate,purchaseRate) (select ('" + ccode + "') as companycode,groupcode,itemcode,itemname,categorycode,kflcode,packing,strengthname,ml,barcode,salesrate,purchaseRate from itemmst where companycode='" + mdl_public_variables.companycode + "') ";
			ob.insert(s);
			s = "insert into storage(companycode,shopcode,shopname,address) (select ('" + ccode + "') as companycode,shopcode,shopname,address from storage where companycode='" + mdl_public_variables.companycode + "')";
			ob.insert(s);
			s = "insert into companyparamtr(companycode,csalebillno, SaleAccount_Head, cashparty, bankacc, crcashparty, breakacc, saleretrnacc, csalelmt, printbill, printer, purchaseacchd, cashhd, discntacc, ratecode,  defshpgdn, expenceacc, rndoffacc, autorefcurrsal, actposmode, bill_footer, bill_footer2, bill_footer3, bill_footer4, on_off_shop_type, back_up_restore_path,  print_mode, surcharge_account_head, Trade_discount_head, surcharge_percent, phone_number1, email_id, sender_id, password, zone, screen_time, status_show, language, message, sales_taxon_mrp, sales_taxon_mrp_rate, mrp_change, sms_password) (select ('" + ccode + "') as companycode,csalebillno, SaleAccount_Head, cashparty, bankacc, crcashparty, breakacc, saleretrnacc, csalelmt, printbill, printer, purchaseacchd, cashhd, discntacc, ratecode,  defshpgdn, expenceacc, rndoffacc, autorefcurrsal, actposmode, bill_footer, bill_footer2, bill_footer3, bill_footer4, on_off_shop_type, back_up_restore_path,  print_mode, surcharge_account_head, Trade_discount_head, surcharge_percent, phone_number1, email_id, sender_id, password, zone, screen_time, status_show,  language, message, sales_taxon_mrp, sales_taxon_mrp_rate, mrp_change, sms_password from companyparamtr where companycode='" + mdl_public_variables.companycode + "') ";
			ob.insert(s);
			s = "insert into userrights (usercode,companycode,accaccess,modulename,perv,pera,perd) (select usercode,('" + ccode + "') as companycode,accaccess,modulename,perv,pera,perd from userrights where companycode='" + mdl_public_variables.companycode + "') ";
			ob.insert(s);
			s = "INSERT INTO [reportTaggingMain]([reportName],[reportCategory],[companycode]) \r\n (select [reportName],[reportCategory], '" + ccode + "' as [companycode] from [reportTaggingMain] where [companycode]='" + mdl_public_variables.companycode + "' ) ";
			ob.insert(s);
			s = "INSERT INTO [reportTaggingDetail]([reportName],[reportCategory],[groupname],[companycode]) \r\n (select [reportName],[reportCategory],[groupname],'" + ccode + "' as [companycode] from [reportTaggingDetail] where [companycode]='" + mdl_public_variables.companycode + "' ) ";
			ob.insert(s);
			s = "INSERT INTO [naiUnitMaster]([companyCode],[unitCode],[basicUnitName],[basicQnty],[bulkUnitName],[bulkQnty],[type],[userCode]) \r\n (select '" + ccode + "' as [companyCode],[unitCode],[basicUnitName],[basicQnty],[bulkUnitName],[bulkQnty],[type],[userCode] from [naiUnitMaster] where [companyCode]='" + mdl_public_variables.companycode + "') \r\n";
			ob.insert(s);
			s = "INSERT INTO [naiItemMainGroup]([companyCode],[mainGroupCode],[mainGroupName],[isRawMeterial],[isBarItem],[userCode]) \r\n (select '" + ccode + "' [companyCode],[mainGroupCode],[mainGroupName],[isRawMeterial],[isBarItem],[userCode] from [naiItemMainGroup] where [companyCode]='" + mdl_public_variables.companycode + "') \r\n";
			ob.insert(s);
			s = "INSERT INTO [naiItemSubGroup]([companyCode],[mainGroupCode],[subGroupCode],[subGroupName],[ManufacturerCode],[userCode]) \r\n (select '" + ccode + "' as [companyCode],[mainGroupCode],[subGroupCode],[subGroupName],[ManufacturerCode],[userCode] from [naiItemSubGroup] where [companyCode]='" + mdl_public_variables.companycode + "' ) \r\n";
			ob.insert(s);
			s = "INSERT INTO [naiItemMaster]([companyCode],[mainGroupCode] ,[subGroupCode] ,[itemCode],[itemName],[itemType] ,[unitCode],[kflCode],[strengthName] \r\n ,[salesRate],[purchaseRate],[purchaseBulkRate],[barCode],[shortCode],[allowBillDiscountTax],[taxSchemeCode],[isBarItem],[minQnty],[isCommonItem],[userCode]) \r\n (select '" + ccode + "' as [companyCode],[mainGroupCode] ,[subGroupCode] ,[itemCode],[itemName],[itemType] ,[unitCode],[kflCode],[strengthName] \r\n ,[salesRate],[purchaseRate],[purchaseBulkRate],[barCode],[shortCode],[allowBillDiscountTax],[taxSchemeCode],[isBarItem],[minQnty],[isCommonItem],[userCode] from [naiItemMaster] where [companyCode]='" + mdl_public_variables.companycode + "') \r\n";
			ob.insert(s);
		}

