		private void companyparameter_Load(object sender, EventArgs e)
		{
			cmb_MaxDigitForQty.SelectedIndex = 0;
			cmb_PortNo.DataSource = SerialPort.GetPortNames();
			if (!mdl_public_variables.FLCS)
			{
				((Control)lbl_CsBillLimit).Visible = false;
				((Control)lbl_csBillNO).Visible = false;
				((Control)txt_CsBillNO).Visible = false;
				((Control)txt_csLimit).Visible = false;
				((Control)lbl_naiBillNO).Visible = false;
				((Control)txt_naiBillNO).Visible = false;
			}
			((Form)this).Icon = Icon.FromHandle(Resources.Work.GetHicon());
			s = "SELECT ledgerCode, ledgerName FROM MasterAccountsLedger WHERE (companyCode = '" + mdl_public_variables.companycode + "') AND (Hidden = 0) ORDER BY ledgerName";
			data_set = ob.populate(s);
			ob.combofill(data_set.Tables[0], cmb_salacc_hd);
			ob.combofill(data_set.Tables[0], cmb_bankacc);
			ob.combofill(data_set.Tables[0], cmb_cashhd);
			ob.combofill(data_set.Tables[0], cmb_breakacc);
			ob.combofill(data_set.Tables[0], cmb_cash_discount);
			ob.combofill(data_set.Tables[0], cmb_trade_discount);
			ob.combofill(data_set.Tables[0], cmb_expenceacc);
			ob.combofill(data_set.Tables[0], cmb_rndoffacc);
			ob.combofill(data_set.Tables[0], cmb_saleretrnacc);
			ob.combofill(data_set.Tables[0], cmb_purchaseacc_hd);
			ob.combofill(data_set.Tables[0], cmb_surcharge_acc);
			ob.combofill(data_set.Tables[0], cmb_salestaxonmrp);
			s = "select shopcode,shopname from storage where companycode='" + mdl_public_variables.companycode + "'order by shopname";
			ds1 = ob.populate(s);
			ob.combofill(ds1.Tables[0], cmb_defshpgdn);
			s = "select ratecode,ratename from itemrateinfo where companycode='" + mdl_public_variables.companycode + "'";
			ds2 = ob.populate(s);
			ob.combofill(ds2.Tables[0], cmb_defrate);
			foreach (object installedPrinter in PrinterSettings.InstalledPrinters)
			{
				string text = Conversions.ToString(installedPrinter);
				cmb_printer.Items.Add((object)text);
			}
			s = "select companycode,isnull(csalebillno,0),saleAccount_head,bankacc,cashparty,crcashparty,breakacc,saleretrnacc,csalelmt,isnull(printbill,0) as printbill,printer,purchaseacchd,cashhd,discntacc,defshpgdn,ratecode,expenceacc,rndoffacc,isnull(autorefcurrsal,0),isnull(actposmode,0),bill_footer,bill_footer2,bill_footer3,bill_footer4,on_off_shop_type,back_up_restore_path,print_mode,surcharge_account_head,Trade_discount_head,surcharge_percent,phone_number1,email_id,sender_id,password,zone,screen_time,status_show,sales_taxon_mrp,isnull(sales_taxon_mrp_rate,0) as sales_taxon_mrp_rate,isnull(mrp_change,0),isnull(batchsale,0) as batchsale,isnull(negativeSale,0) as negativeSale,isnull(batchEdit,0) as batchEdit,isNull(manualBatchSale,0) as manualBatchSale,csLimit ,isnull( UserWiseSaleStatement,convert(bit,0)) as UserWiseSaleStatement,isnull(savebill,0) as savebill, maxdegitFrQty,billLeftMargin from companyparamtr where companycode= '" + mdl_public_variables.companycode + "'";
			ds = ob.populate(s);
			checked
			{
				if (ds.Tables[0].Rows.Count > 0)
				{
					txt_salebillno.Text = ds.Tables[0].Rows[0][1].ToString();
					txt_salelmt.Text = ds.Tables[0].Rows[0][8].ToString();
					txt_csLimit.Text = Conversions.ToString(ds.Tables[0].Rows[0][44]);
					txt_billfooter.Text = ds.Tables[0].Rows[0][20].ToString();
					txt_billfooter2.Text = ds.Tables[0].Rows[0][21].ToString();
					txt_billfooter3.Text = ds.Tables[0].Rows[0][22].ToString();
					txt_billfooter4.Text = ds.Tables[0].Rows[0][23].ToString();
					txt_zone.Text = ds.Tables[0].Rows[0][34].ToString();
					txt_salestaxrate.Text = ds.Tables[0].Rows[0][38].ToString();
					cmb_printer.Text = mdl_public_variables.comprinter;
					txt_backup.Text = mdl_public_variables.back_up_path;
					print_bill_on_save.Checked = Conversion.Val(ds.Tables[0].Rows[0][9].ToString()) != 0.0;
					save_bill_on_print.Checked = Conversion.Val(ds.Tables[0].Rows[0]["savebill"].ToString()) != 0.0;
					chk_salerefresh.Checked = Conversions.ToBoolean(ds.Tables[0].Rows[0][18].ToString());
					chk_pos_mode.Checked = Conversion.Val(ds.Tables[0].Rows[0][19].ToString()) != 0.0;
					cmb_MaxDigitForQty.SelectedItem = ds.Tables[0].Rows[0]["maxdegitFrQty"].ToString();
					txt_BillLeftMargin.Text = Conversions.ToString(ds.Tables[0].Rows[0]["billLeftMargin"]);
					if (Operators.CompareString(ds.Tables[0].Rows[0][2].ToString(), (string)null, false) != 0)
					{
						EnumerableRowCollection<object> source = from p in data_set.Tables[0].AsEnumerable()
							where Operators.ConditionalCompareObjectEqual(p[0], ds.Tables[0].Rows[0][2], false)
							select p[1];
						if (source.Count() > 0)
						{
							cmb_salacc_hd.Text = source.ElementAtOrDefault(0).ToString();
						}
					}
					if (Operators.CompareString(ds.Tables[0].Rows[0][3].ToString(), (string)null, false) != 0)
					{
						EnumerableRowCollection<object> source2 = from p in data_set.Tables[0].AsEnumerable()
							where Operators.ConditionalCompareObjectEqual(p[0], ds.Tables[0].Rows[0][3], false)
							select p[1];
						if (source2.Count() > 0)
						{
							cmb_bankacc.Text = source2.ElementAtOrDefault(0).ToString();
						}
					}
					if (Operators.CompareString(ds.Tables[0].Rows[0][6].ToString(), (string)null, false) != 0)
					{
						EnumerableRowCollection<object> source3 = from p in data_set.Tables[0].AsEnumerable()
							where Operators.ConditionalCompareObjectEqual(p[0], ds.Tables[0].Rows[0][6], false)
							select p[1];
						if (source3.Count() > 0)
						{
							cmb_breakacc.Text = source3.ElementAtOrDefault(0).ToString();
						}
					}
					if (Operators.CompareString(ds.Tables[0].Rows[0][7].ToString(), (string)null, false) != 0)
					{
						EnumerableRowCollection<object> source4 = from p in data_set.Tables[0].AsEnumerable()
							where Operators.ConditionalCompareObjectEqual(p[0], ds.Tables[0].Rows[0][7], false)
							select p[1];
						if (source4.Count() > 0)
						{
							cmb_saleretrnacc.Text = source4.ElementAtOrDefault(0).ToString();
						}
					}
					if (Operators.CompareString(ds.Tables[0].Rows[0][11].ToString(), (string)null, false) != 0)
