		private void cmb_bill_from_SelectedIndexChanged(object sender, EventArgs e)
		{
			cmb_bill_to.Items.Clear();
			checked
			{
				if (cmb_bill_from.SelectedIndex > 0)
				{
					((Control)lbl_to).Visible = true;
					((Control)cmb_bill_to).Visible = true;
					int num = cmb_bill_from.SelectedIndex - 1;
					int num2 = cmb_bill_from.Items.Count - 2;
					int num3 = num;
					while (true)
					{
						int num4 = num3;
						int num5 = num2;
						if (num4 > num5)
						{
							break;
						}
						ObjectCollection items = cmb_bill_to.Items;
						object obj = NewLateBinding.LateGet(ds_disc, (Type)null, "Tables", new object[1] { 0 }, (string[])null, (Type[])null, (bool[])null);
						object[] array = new object[1] { num3 };
						bool[] array2 = new bool[1] { true };
						object obj2 = NewLateBinding.LateGet(obj, (Type)null, "Rows", array, (string[])null, (Type[])null, array2);
						if (array2[0])
						{
							num3 = (int)Conversions.ChangeType(RuntimeHelpers.GetObjectValue(array[0]), typeof(int));
						}
						items.Add(RuntimeHelpers.GetObjectValue(NewLateBinding.LateGet(obj2, (Type)null, "Item", new object[1] { 0 }, (string[])null, (Type[])null, (bool[])null)));
						num3++;
					}
					cmb_bill_to.SelectedIndex = 0;
					strbills = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)"and trnno>= '", cmb_bill_from.SelectedItem), (object)"'"));
				}
				else
				{
					((Control)lbl_to).Visible = false;
					((Control)cmb_bill_to).Visible = false;
					strbills = "";
				}
			}
		}

