		private void billload()
		{
			s = "select distinct cast(trnno as integer) from salesbillmain where salesbillmain.companycode='" + mdl_public_variables.companycode + "'  and yearcode='" + mdl_public_variables.yearcode + "' and trndate>='" + Conversions.ToString(dtp1.Value.Date) + "' and trndate<= '" + Conversions.ToString(dtp2.Value.Date) + "'order by cast(trnno as integer)";
			ds_disc = ob.populate(s);
			cmb_bill_from.Items.Clear();
			cmb_bill_to.Items.Clear();
			cmb_bill_from.Items.Add((object)"--------- All ---------");
			object objectValue = default(object);
			object obj = default(object);
			if (Operators.ConditionalCompareObjectGreater(NewLateBinding.LateGet(NewLateBinding.LateGet(NewLateBinding.LateGet(ds_disc, (Type)null, "Tables", new object[1] { 0 }, (string[])null, (Type[])null, (bool[])null), (Type)null, "Rows", new object[0], (string[])null, (Type[])null, (bool[])null), (Type)null, "Count", new object[0], (string[])null, (Type[])null, (bool[])null), (object)0, false) && ForLoopControl.ForLoopInitObj(objectValue, (object)0, Operators.SubtractObject(NewLateBinding.LateGet(NewLateBinding.LateGet(NewLateBinding.LateGet(ds_disc, (Type)null, "Tables", new object[1] { 0 }, (string[])null, (Type[])null, (bool[])null), (Type)null, "Rows", new object[0], (string[])null, (Type[])null, (bool[])null), (Type)null, "Count", new object[0], (string[])null, (Type[])null, (bool[])null), (object)1), (object)1, ref obj, ref objectValue))
			{
				do
				{
					ObjectCollection items = cmb_bill_from.Items;
					object obj2 = NewLateBinding.LateGet(ds_disc, (Type)null, "Tables", new object[1] { 0 }, (string[])null, (Type[])null, (bool[])null);
					object[] array = new object[1] { RuntimeHelpers.GetObjectValue(objectValue) };
					bool[] array2 = new bool[1] { true };
					object obj3 = NewLateBinding.LateGet(obj2, (Type)null, "Rows", array, (string[])null, (Type[])null, array2);
					if (array2[0])
					{
						objectValue = RuntimeHelpers.GetObjectValue(array[0]);
					}
					items.Add(RuntimeHelpers.GetObjectValue(NewLateBinding.LateGet(obj3, (Type)null, "Item", new object[1] { 0 }, (string[])null, (Type[])null, (bool[])null)));
				}
				while (ForLoopControl.ForNextCheckObj(objectValue, obj, ref objectValue));
			}
			cmb_bill_from.SelectedIndex = 0;
		}

