		private void frm_payreceive_vch_Load(object sender, EventArgs e)
		{
			NewAdd = false;
			if (Operators.CompareString(transactionType, "Payment Voucher", false) == 0)
			{
				TrnType = "PAYMENT";
			}
			else if (Operators.CompareString(transactionType, "Receipt Voucher", false) == 0)
			{
				TrnType = "RECEIPT";
			}
			else if (Operators.CompareString(transactionType, "Credit Note", false) == 0)
			{
				TrnType = "CREDIT NOTE";
			}
			else if (Operators.CompareString(transactionType, "Debit Note", false) == 0)
			{
				TrnType = "DEBIT NOTE";
			}
			else if (Operators.CompareString(transactionType, "Contra Entry", false) == 0)
			{
				Label3.Text = "By A/c";
				Label4.Text = "To A/c";
				TrnType = "CONTRA";
				((Control)dgv1).Visible = false;
				Newcontrascreen();
			}
			refreshForm();
			if (Operators.CompareString(loadType, "Edit", false) == 0)
			{
				((Control)CheckBoxEdit).Visible = true;
				VoucharEditLoadMain();
			}
			else
			{
				date_vouchar_new = DateAndTime.Today.Date;
			}
			dgv1.BackgroundColor = Color.White;
			dgv1.DefaultCellStyle.BackColor = Color.White;
			dgv1.RowHeadersVisible = false;
			dgv1.ColumnHeadersVisible = true;
			((ToolStripItem)tsl_Title).Text = ((Form)this).Text;
		}

