		private void btn_Save_Click(object sender, EventArgs e)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c6: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Unknown result type (might be due to invalid IL or missing references)
			//IL_0070: Unknown result type (might be due to invalid IL or missing references)
			//IL_0174: Unknown result type (might be due to invalid IL or missing references)
			if (cmb_cashbank.SelectedIndex < 0)
			{
				Interaction.MsgBox((object)"Please select Cash / Bank", (MsgBoxStyle)64, (object)null);
				((Control)cmb_cashbank).Focus();
				return;
			}
			if (cmb_party.SelectedIndex < 0)
			{
				if (Operators.CompareString(transactionType, "Contra Entry", false) == 0)
				{
					Interaction.MsgBox((object)"Please select Cash / Bank", (MsgBoxStyle)64, (object)null);
				}
				else
				{
					Interaction.MsgBox((object)"Please select Ledger Account", (MsgBoxStyle)64, (object)null);
				}
				((Control)cmb_party).Focus();
				return;
			}
			if (Operators.CompareString(txt_paidamt.Text, "", false) == 0)
			{
				Interaction.MsgBox((object)"Please type Amount", (MsgBoxStyle)64, (object)null);
				((Control)txt_paidamt).Focus();
				return;
			}
			checked
			{
				if (Operators.CompareString(transactionType, "Contra Entry", false) != 0)
				{
					double num = 0.0;
					int num2 = dgv1.Rows.Count - 1;
					int num3 = 0;
					while (true)
					{
						int num4 = num3;
						int num5 = num2;
						if (num4 > num5)
						{
							break;
						}
						num += Conversion.Val(RuntimeHelpers.GetObjectValue(dgv1[3, num3].Value));
						num3++;
					}
					if (Conversion.Val(txt_paidamt.Text) != num)
					{
						Interaction.MsgBox((object)"Please check Amount in details", (MsgBoxStyle)64, (object)null);
						((Control)txt_paidamt).Focus();
						return;
					}
				}
				if (Operators.CompareString(loadType, "Add", false) == 0)
				{
					VoucharAddSaveMain();
				}
				else if (Operators.CompareString(loadType, "Edit", false) == 0)
				{
					VoucharEditSaveMain();
				}
				try
				{
					Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
				}
			}
		}

