		private void cmb_cashbank_SelectedIndexChanged(object sender, EventArgs e)
		{
			if (!Operators.ConditionalCompareObjectNotEqual(cmb_cashbank.SelectedItem, (object)null, false))
			{
				return;
			}
			if (ds1.Tables[0].Rows[cmb_cashbank.SelectedIndex][1].ToString().Contains("BANK"))
			{
				txt_chq.Text = LastChequeNo;
				txt_CardNo.Text = LastCardNo;
				cmb_CardType.Text = LastCardType;
				txt_TransactionID.Text = LastTransactionID;
				((Control)lbl_chk).Enabled = true;
				((Control)txt_chq).Enabled = true;
				((Control)lbl_CardNo).Enabled = true;
				((Control)txt_CardNo).Enabled = true;
				((Control)lbl_CardType).Enabled = true;
				((Control)cmb_CardType).Enabled = true;
				((Control)lbl_TransactionID).Enabled = true;
				((Control)txt_TransactionID).Enabled = true;
			}
			else
			{
				txt_chq.Text = "";
				txt_CardNo.Text = "";
				cmb_CardType.Text = "";
				txt_TransactionID.Text = "";
				((Control)lbl_chk).Enabled = false;
				((Control)txt_chq).Enabled = false;
				((Control)lbl_CardNo).Enabled = false;
				((Control)txt_CardNo).Enabled = false;
				((Control)lbl_CardType).Enabled = false;
				((Control)cmb_CardType).Enabled = false;
				((Control)lbl_TransactionID).Enabled = false;
				((Control)txt_TransactionID).Enabled = false;
			}
			if (mdl_public_variables.flag == 1)
			{
				dgv1.Rows.Clear();
				refresh_grid();
			}
			double num = 0.0;
			num = Conversions.ToDouble(ds1.Tables[0].Rows[cmb_cashbank.SelectedIndex][2].ToString());
			Lbl_cash_bank_Lmt.Text = ds1.Tables[0].Rows[cmb_cashbank.SelectedIndex][3].ToString();
			if ((Operators.CompareString(transactionType, "Payment Voucher", false) == 0) | (Operators.CompareString(transactionType, "Debit Note", false) == 0))
			{
				if (num < 0.0)
				{
					Label_cash_bank.Text = Math.Abs(num) + " Dr";
					((Control)Label_cash_bank).ForeColor = Color.DarkBlue;
					if (Operators.CompareString(last_cas_bank_name, "", false) == 0)
					{
						if (Conversion.Val(txt_paidamt.Text) > Math.Abs(num))
						{
							((Control)Label_cash_bank).ForeColor = Color.Red;
						}
					}
					else if (Operators.CompareString(last_cas_bank_name, cmb_cashbank.Text, false) != 0 && Conversion.Val(txt_paidamt.Text) > Math.Abs(num))
					{
						((Control)Label_cash_bank).ForeColor = Color.Red;
					}
				}
				else
