		private void cmb_party_SelectedIndexChanged(object sender, EventArgs e)
		{
			if (Operators.CompareString(loadType, "Add", false) == 0)
			{
				dgv1.Rows.Clear();
				refresh_grid();
			}
			if (!Operators.ConditionalCompareObjectNotEqual(cmb_party.SelectedItem, (object)null, false))
			{
				return;
			}
			Lbl_Party_Lmt.Text = ds2.Tables[0].Rows[cmb_party.SelectedIndex][3].ToString();
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			num2 = Conversions.ToDouble(ds2.Tables[0].Rows[cmb_party.SelectedIndex][2].ToString());
			if (num2 < 0.0)
			{
				Label_close.Text = Math.Abs(num2).ToString();
				lbl_close.Text = "Dr";
			}
			else
			{
				Label_close.Text = num2.ToString();
				lbl_close.Text = "Cr";
			}
			int num5 = default(int);
			if ((Operators.CompareString(transactionType, "Payment Voucher", false) == 0) | (Operators.CompareString(transactionType, "Contra Entry", false) == 0) | (Operators.CompareString(transactionType, "Credit Note", false) == 0))
			{
				num5 = -1;
			}
			else if ((Operators.CompareString(transactionType, "Receipt Voucher", false) == 0) | (Operators.CompareString(transactionType, "Debit Note", false) == 0))
			{
				num5 = 1;
			}
			num3 = Conversion.Val(txt_paidamt.Text) * (double)num5;
			num = num2 - num3;
			if (num < 0.0)
			{
				Label_open.Text = Math.Abs(num).ToString();
				lbl_open.Text = "Dr";
			}
			else
			{
				Label_open.Text = num.ToString();
				lbl_open.Text = "Cr";
			}
			Lbl_Party_Lmt.Text = ds2.Tables[0].Rows[cmb_party.SelectedIndex][3].ToString();
			num4 = Conversion.Val(Lbl_Party_Lmt.Text);
			if (num4 != 0.0)
			{
				if (num4 < 0.0)
				{
					if (num4 < num2)
					{
						((Control)Label_close).ForeColor = Color.Black;
						((Control)lbl_close).ForeColor = Color.Black;
					}
					else
					{
						((Control)Label_close).ForeColor = Color.Red;
						((Control)lbl_close).ForeColor = Color.Red;
					}
					if (num4 < num)
					{
						((Control)Label_open).ForeColor = Color.Black;
						((Control)lbl_open).ForeColor = Color.Black;
					}
					else
					{
						((Control)Label_open).ForeColor = Color.Red;
						((Control)lbl_open).ForeColor = Color.Red;
					}
				}
				else
				{
					if (num4 > num2)
					{
						((Control)Label_close).ForeColor = Color.Black;
						((Control)lbl_close).ForeColor = Color.Black;
					}
					else
					{
						((Control)Label_close).ForeColor = Color.Red;
						((Control)lbl_close).ForeColor = Color.Red;
					}
					if (num4 > num)
					{
						((Control)Label_open).ForeColor = Color.Black;
						((Control)lbl_open).ForeColor = Color.Black;
					}
					else
					{
						((Control)Label_open).ForeColor = Color.Red;
						((Control)lbl_open).ForeColor = Color.Red;
					}
				}
			}
			else if ((Operators.CompareString(transactionType, "Payment Voucher", false) == 0) | (Operators.CompareString(transactionType, "Contra Entry", false) == 0) | (Operators.CompareString(transactionType, "Debit Note", false) == 0))
			{
				if (num2 < 0.0)
				{
					((Control)Label_close).ForeColor = Color.DarkBlue;
					((Control)lbl_close).ForeColor = Color.DarkBlue;
				}
				else
				{
					((Control)Label_close).ForeColor = Color.Red;
					((Control)lbl_close).ForeColor = Color.Red;
				}
				if (num < 0.0)
				{
					((Control)Label_open).ForeColor = Color.DarkBlue;
					((Control)lbl_open).ForeColor = Color.DarkBlue;
				}
				else
				{
					((Control)Label_open).ForeColor = Color.Red;
					((Control)lbl_open).ForeColor = Color.Red;
				}
			}
			else if ((Operators.CompareString(transactionType, "Receipt Voucher", false) == 0) | (Operators.CompareString(transactionType, "Credit Note", false) == 0))
			{
				if (num2 < 0.0)
