							{
								RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[num2][0]),
								RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[num2][1]),
								RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[num2][2]),
								RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[num2][3]),
								RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[num2][4])
							});
						}
						num2++;
					}
					DataGridView val = dgv1;
					val.Columns[3].DefaultCellStyle.Format = "0.00";
					val = null;
					totpaid = 0;
					int num5 = dgv1.Rows.Count - 1;
					int num6 = 0;
					while (true)
					{
						int num7 = num6;
						int num4 = num5;
