		private void RefreshCombo()
		{
			//IL_01bb: Unknown result type (might be due to invalid IL or missing references)
			//IL_01a5: Unknown result type (might be due to invalid IL or missing references)
			//IL_03ac: Unknown result type (might be due to invalid IL or missing references)
			ds1.Clear();
			string s;
			if (Operators.CompareString(transactionType, "Debit Note", false) == 0)
			{
				Label3.Text = "Account";
				Label4.Text = "Supp. A/C";
				s = "EXEC LedgerOthers @ComCode = N'" + mdl_public_variables.companycode + "', @YearCode = N'" + mdl_public_variables.yearcode + "'";
			}
			else if (Operators.CompareString(transactionType, "Credit Note", false) == 0)
			{
				Label3.Text = "Account";
				Label4.Text = "Party A/C";
				s = "EXEC LedgerOthers @ComCode = N'" + mdl_public_variables.companycode + "', @YearCode = N'" + mdl_public_variables.yearcode + "'";
			}
			else
			{
				s = "EXEC LedgerCashBank @ComCode = N'" + mdl_public_variables.companycode + "', @YearCode = N'" + mdl_public_variables.yearcode + "'";
			}
			ds1 = ob_dataAccess.populate(s);
			if (ds1.Tables[0].Rows.Count < 1)
			{
				if ((Operators.CompareString(transactionType, "Debit Note", false) == 0) | (Operators.CompareString(transactionType, "Credit Note", false) == 0))
				{
					Interaction.MsgBox((object)"System Can not find any ledger with out 'Cash' or 'Bank' Sub Group, please check 'Ledger' in 'Master' menu", (MsgBoxStyle)0, (object)null);
				}
				else
				{
					Interaction.MsgBox((object)"System Can not find any ledger with 'Cash' or 'Bank' Sub Group, please check 'Ledger' in 'Master' menu", (MsgBoxStyle)0, (object)null);
				}
				return;
			}
			cmb_cashbank.Items.Clear();
			int count = cmb_cashbank.Items.Count;
			ob_dataAccess.combofill(ds1.Tables[0], cmb_cashbank);
			cmb_cashbank.SelectedIndex = 0;
			if (Operators.CompareString(last_cas_bank_name, "", false) != 0)
			{
				cmb_cashbank.SelectedItem = last_cas_bank_name;
				last_cas_bank_name = "";
			}
			if (Operators.CompareString(transactionType, "Contra Entry", false) != 0)
			{
				s = ((Operators.CompareString(transactionType, "Debit Note", false) == 0) ? ("EXEC LedgerCreditor @ComCode = N'" + mdl_public_variables.companycode + "', @YearCode = N'" + mdl_public_variables.yearcode + "'") : ((Operators.CompareString(transactionType, "Credit Note", false) != 0) ? ("EXEC LedgerOthers @ComCode = N'" + mdl_public_variables.companycode + "', @YearCode = N'" + mdl_public_variables.yearcode + "'") : ("EXEC LedgerDebtor @ComCode = N'" + mdl_public_variables.companycode + "', @YearCode = N'" + mdl_public_variables.yearcode + "'")));
			}
			ds2.Clear();
			ds2 = ob_dataAccess.populate(s);
			if (ds2.Tables[0].Rows.Count < 1)
			{
				Interaction.MsgBox((object)"System Can not find any ledger, please check 'Ledger' in 'Master' menu", (MsgBoxStyle)0, (object)null);
				return;
			}
			cmb_party.Items.Clear();
			ob_dataAccess.combofill(ds2.Tables[0], cmb_party);
			cmb_party.SelectedIndex = 0;
			if (Operators.CompareString(LasttransactionType, "", false) != 0)
			{
				transactionType = LasttransactionType;
				LasttransactionType = "";
			}
		}

