				{
					dgv1.ClearSelection();
					dgv1.CurrentCell = dgv1[3, 0];
					dgv1.CurrentCell.Selected = true;
					((Control)dgv1).Select();
				}
				paymenttype();
			}
			else
			{
				((Control)txt_nar).Focus();
			}
		}

		private void txt_paidamt_KeyPress(object sender, KeyPressEventArgs e)
		{
			switch (e.KeyChar)
			{
			case '\b':
			case '\r':
			case '.':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				e.Handled = false;
				break;
			default:
				e.Handled = true;
				break;
			}
		}

		private void txt_paidamt_TextChanged(object sender, EventArgs e)
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			if (Operators.CompareString(lbl_open.Text, "Dr", false) == 0)
			{
				num = Conversion.Val(Label_open.Text) * -1.0;
			}
			else if (Operators.CompareString(lbl_open.Text, "Cr", false) == 0)
			{
				num = Conversion.Val(Label_open.Text);
			}
			int num5 = default(int);
			if ((Operators.CompareString(transactionType, "Payment Voucher", false) == 0) | (Operators.CompareString(transactionType, "Contra Entry", false) == 0) | (Operators.CompareString(transactionType, "Debit Note", false) == 0))
			{
				num5 = -1;
			}
			else if ((Operators.CompareString(transactionType, "Receipt Voucher", false) == 0) | (Operators.CompareString(transactionType, "Credit Note", false) == 0))
			{
				num5 = 1;
			}
			num3 = Conversion.Val(txt_paidamt.Text) * (double)num5;
			num2 = num + num3;
			num4 = Conversion.Val(Lbl_Party_Lmt.Text);
			if (num2 < 0.0)
			{
				Label_close.Text = Math.Abs(num2).ToString();
				lbl_close.Text = "Dr";
			}
			else
			{
				Label_close.Text = num2.ToString();
				lbl_close.Text = "Cr";
			}
			double value = 0.0;
			if (Operators.CompareString(cmb_cashbank.Text, "", false) != 0)
			{
				value = Conversions.ToDouble(ds1.Tables[0].Rows[cmb_cashbank.SelectedIndex][2].ToString());
			}
			if ((Operators.CompareString(transactionType, "Payment Voucher", false) == 0) | (Operators.CompareString(transactionType, "Contra Entry", false) == 0) | (Operators.CompareString(transactionType, "Debit Note", false) == 0))
			{
				if (Conversion.Val(txt_paidamt.Text) > Math.Abs(value))
				{
					((TextBoxBase)txt_paidamt).ForeColor = Color.Red;
				}
				else
				{
					((TextBoxBase)txt_paidamt).ForeColor = Color.DarkBlue;
				}
			}
			else if ((Operators.CompareString(transactionType, "Receipt Voucher", false) == 0) | (Operators.CompareString(transactionType, "Credit Note", false) == 0))
			{
				if (Conversion.Val(txt_paidamt.Text) > Math.Abs(value))
				{
					((TextBoxBase)txt_paidamt).ForeColor = Color.DarkBlue;
				}
				else
				{
					((TextBoxBase)txt_paidamt).ForeColor = Color.Red;
				}
			}
			if (num4 != 0.0)
			{
				if (num4 < 0.0)
				{
					if (num4 < num2)
					{
						((Control)Label_close).ForeColor = Color.DarkBlue;
						((Control)lbl_close).ForeColor = Color.DarkBlue;
					}
					else
					{
						((Control)Label_close).ForeColor = Color.Red;
						((Control)lbl_close).ForeColor = Color.Red;
					}
				}
				else if (num4 > num2)
				{
					((Control)Label_close).ForeColor = Color.DarkBlue;
					((Control)lbl_close).ForeColor = Color.DarkBlue;
				}
				else
				{
					((Control)Label_close).ForeColor = Color.Red;
					((Control)lbl_close).ForeColor = Color.Red;
				}
			}
