		private void VoucherPrint()
		{
			//IL_0456: Unknown result type (might be due to invalid IL or missing references)
			//IL_045c: Expected O, but got Unknown
			//IL_046b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0471: Expected O, but got Unknown
			if (dgv1.Rows.Count < 1)
			{
				return;
			}
			ds_voucher_print ds_voucher_print2 = new ds_voucher_print();
			rep_NewVoucher_print rep_NewVoucher_print2 = new rep_NewVoucher_print();
			string text = "";
			DataRow dataRow = ds_voucher_print2.Tables["vch_detail"].NewRow();
			dataRow["account"] = cmb_party.Text;
			dataRow["amount"] = txt_paidamt.Text;
			bool flag = true;
			checked
			{
				int num = dgv1.Rows.Count - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					if (Operators.CompareString(dgv1[1, num2].Value.ToString(), "", false) != 0)
					{
						if (flag)
						{
							text = "Against Bill No: " + text + dgv1[1, num2].Value.ToString() + ", ";
							flag = false;
						}
						else
						{
							text = text + dgv1[1, num2].Value.ToString() + ", ";
						}
					}
					num2++;
				}
				if (Operators.CompareString(text, "", false) != 0)
				{
					text = text.Substring(0, Strings.Len(text) - 2);
				}
				dataRow["bill_detail"] = text;
				if (LikeOperator.LikeString(ds1.Tables[0].Rows[cmb_cashbank.SelectedIndex][2].ToString(), "*BANK", (CompareMethod)0) | LikeOperator.LikeString(ds1.Tables[0].Rows[cmb_cashbank.SelectedIndex][2].ToString(), "BANK*", (CompareMethod)0))
				{
					dataRow["trough"] = cmb_cashbank.Text + " Chq No " + txt_chq.Text;
				}
				else
				{
					dataRow["trough"] = cmb_cashbank.Text;
				}
				ds_voucher_print2.Tables["vch_detail"].Rows.Add(dataRow);
				DataRow dataRow2 = ds_voucher_print2.Tables["company_info"].NewRow();
				dataRow2["companyname"] = mdl_public_variables.companyname;
				dataRow2["add1"] = mdl_public_variables.address1;
				dataRow2["add2"] = mdl_public_variables.address2;
				if ((Operators.CompareString(mdl_public_variables.city, mdl_public_variables.state, false) != 0) & (Operators.CompareString(mdl_public_variables.district, "", false) != 0))
				{
					dataRow2["city"] = mdl_public_variables.city + ", " + mdl_public_variables.district + " - " + mdl_public_variables.pin;
				}
				else
				{
					dataRow2["city"] = mdl_public_variables.city + " - " + mdl_public_variables.pin;
				}
				dataRow2["email"] = mdl_public_variables.comemail;
				dataRow2["narration"] = txt_nar.Text;
				if (Operators.CompareString(TrnType, "PAYMENT", false) == 0)
				{
					dataRow2["title"] = "Payment Voucher";
				}
				else if (Operators.CompareString(TrnType, "RECEIPT", false) == 0)
				{
					dataRow2["title"] = "Receipt Voucher";
				}
				dataRow2["vchno"] = txt_vch.Text;
				dataRow2["date"] = dtp1.Value.Date;
				dataRow2["tot_amount"] = txt_paidamt.Text;
				ds_voucher_print2.Tables["company_info"].Rows.Add(dataRow2);
				((ReportDocument)rep_NewVoucher_print2).SetDataSource((DataSet)ds_voucher_print2);
				PrinterSettings[] array = (PrinterSettings[])(object)new PrinterSettings[1]
				{
					new PrinterSettings()
				};
				array[0].PrinterName = mdl_public_variables.comprinter;
				PageSettings pageSettings = new PageSettings();
				frm_KotBilltPrinting frm_KotBilltPrinting2 = new frm_KotBilltPrinting();
				object kotwindow = this;
				frm_KotBilltPrinting2.frmLoad("Bill", (ReportDocument)(object)rep_NewVoucher_print2, 1, "", ref kotwindow, array, pageSettings);
			}
		}

