			{
				((Form)this).Icon = Icon.FromHandle(Resources.Contra1.GetHicon());
				((Form)this).Text = "Contra Entry";
				entry_type = "CONTRA";
			}
			else
			{
				((Form)this).Icon = Icon.FromHandle(Resources.Journal.GetHicon());
				((Form)this).Text = "Journal Entry";
				entry_type = "JOURNAL";
			}
			frmvch_load();
			((Control)dtp1).Select();
			editmode = false;
		}

		private void frmvch_load()
		{
			//IL_00f4: Unknown result type (might be due to invalid IL or missing references)
