			((Control)MyProject.Forms.frm_Form1).Enabled = false;
			if (Operators.CompareString(entry_type, "CONTRA", false) == 0)
			{
				s = "SELECT ledger.ledcode, ledger.name, acgroupmst.actype ,acountname.acname FROM ledger JOIN acountname ON ledger.accode = acountname.accode and ledger.companycode = acountname.companycode  JOIN acgroupmst ON acountname.acgroupcode = acgroupmst.acgroupcode WHERE ledger.companycode = '" + mdl_public_variables.companycode + "' and (acname like '%CASH%' OR acname like '%BANK%' )order by name";
				ds1 = ob.populate(s);
				if (ds1.Tables[0].Rows.Count < 1)
				{
					Interaction.MsgBox((object)"System Can not find any ledger with 'Cash' or 'Bank' Sub Group, please check 'Ledger' in 'Master' menu", (MsgBoxStyle)0, (object)null);
					return;
				}
			}
			else
			{
				s = "SELECT ledger.ledcode, ledger.name, acgroupmst.actype ,acountname.acname FROM ledger JOIN acountname ON ledger.accode = acountname.accode and ledger.companycode = acountname.companycode  JOIN acgroupmst ON acountname.acgroupcode = acgroupmst.acgroupcode WHERE ledger.companycode = '" + mdl_public_variables.companycode + "' order by name";
				ds1 = ob.populate(s);
				if (ds1.Tables[0].Rows.Count < 1)
				{
					Interaction.MsgBox((object)"System Can not find any ledger, please add 'Ledger' in 'Master' menu", (MsgBoxStyle)0, (object)null);
