					else
					{
						currbal = "Current Bal: " + Math.Abs(cas_bank) + " Cr.   ";
					}
					if (Operators.CompareString(dataView[num2][8].ToString(), "", false) != 0)
					{
						if (Operators.CompareString(dataView[num2][10].ToString(), "Yes", false) == 0)
						{
							currbal = currbal.ToString() + lbl_no.Text + " " + dataView[num2][8].ToString() + ",  " + lbl_date.Text + " " + Strings.Format(RuntimeHelpers.GetObjectValue(dataView[num2][9]), "dd/MM/yyyy") + ",  " + lbl_accpay.Text;
