				dtp1.Value = mdl_public_variables.jrldate;
				txt_nar.Text = dataView[0][14].ToString();
				calc();
			}
		}

		private void gettrn()
		{
			s = "select top 1 trnno from journaldetail where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "' order by cast ( trnno As Integer)   desc";
			s = ob.executereader(s);
			if (Operators.CompareString(s, (string)null, false) == 0)
			{
				s = Conversions.ToString(1);
			}
			else
			{
				s = checked(Convert.ToInt32(s) + 1).ToString();
			}
			txt_trn.Text = s;
		}

