		private void currbal_calc()
		{
			currbal = "Current Bal: ";
			s = "select sum(debit-credit) as openingBalance from(SELECT ledger.ledcode, ledger.name, acountname.accode,acountname.acname, case when sum(vw_receipt_accounts.credit)>sum(vw_receipt_accounts.debit) then sum(vw_receipt_accounts.credit-vw_receipt_accounts.debit) else 0 end as debit, case when sum(vw_receipt_accounts.debit)>sum(vw_receipt_accounts.credit) then sum(vw_receipt_accounts.debit-vw_receipt_accounts.credit) else 0 end as credit FROM acountname inner JOIN ledger ON acountname.accode = ledger.accode and acountname.companycode =ledger.companycode left outer JOIN vw_receipt_accounts ON ledger.ledcode = vw_receipt_accounts.ledgercode AND ledger.companycode = vw_receipt_accounts.companycode AND ledger.name = vw_receipt_accounts.name and  vw_receipt_accounts.yearcode='" + mdl_public_variables.yearcode + "' and vw_receipt_accounts.date>='" + Conversions.ToString(mdl_public_variables.comstdate) + "' and vw_receipt_accounts.date<='" + Conversions.ToString(dtp1.Value.Date) + "' where ledger.companycode='" + mdl_public_variables.companycode + "' and ledger.ledCode='" + cash_bank_code + "' group by ledger.companycode,acountname.accode,acname,ledcode,ledger.name union all SELECT ledger.ledcode as ledger,name, acountname.accode,acountname.acname, case when sum(ledger_opening.debit)>sum(ledger_opening.credit) then sum(ledger_opening.debit-ledger_opening.credit) else 0 end as debit, case when sum(ledger_opening.credit)>sum(ledger_opening.debit) then sum(ledger_opening.credit-ledger_opening.debit) else 0 end as credit FROM acountname inner JOIN ledger ON acountname.accode = ledger.accode and acountname.companycode =ledger.companycode left outer JOIN ledger_opening ON ledger.ledcode = ledger_opening.ledcode AND ledger.companycode = ledger_opening.companycode  and ledger_opening.yearcode='" + mdl_public_variables.yearcode + "' where ledger.companycode='" + mdl_public_variables.companycode + "' and ledger.ledCode='" + cash_bank_code + "' group by ledger.companycode,acountname.accode,acname,ledger.ledcode,name )as x group by x.accode,acname,x.ledcode,x.name order by name ";
			cas_bank = Conversions.ToDouble(ob.executereader(s));
			checked
			{
				if (dgv1.Rows.Count > 0)
				{
					int num = dgv1.Rows.Count - 1;
					int num2 = 0;
					while (true)
					{
						int num3 = num2;
						int num4 = num;
						if (num3 > num4)
						{
							break;
						}
						if (Operators.ConditionalCompareObjectEqual(dgv1[6, num2].Value, (object)cash_bank_code, false))
						{
							cas_bank += Conversion.Val(dgv1[6, num2].Value.ToString()) - Conversion.Val(dgv1[6, num2].Value.ToString());
						}
						num2++;
					}
				}
				if (cmb_by_to.SelectedIndex == 0)
				{
					cas_bank -= Conversion.Val(txt_amount.Text);
				}
				else
				{
					cas_bank += Conversion.Val(txt_amount.Text);
				}
				if (cas_bank > 0.0)
				{
					currbal = currbal + cas_bank + " Dr.   ";
				}
				else
				{
					currbal = currbal + Math.Abs(cas_bank) + " Cr.   ";
				}
			}
		}

