					ds_voucher_print2.Tables["company_info"].Rows.Add(dataRow2);
					if (ds_voucher_print2.Tables["vch_detail"].Rows.Count > 0)
					{
						((ReportDocument)rep_voucher_print2).SetDataSource((DataSet)ds_voucher_print2);
						((Control)MyProject.Forms.frm_ReportForm.lbl_from).Visible = false;
						((Control)MyProject.Forms.frm_ReportForm.lbl_filter2).Visible = false;
						((Control)MyProject.Forms.frm_ReportForm.lbl_filter3).Visible = false;
						((Control)MyProject.Forms.frm_ReportForm.cmb_filter2).Visible = false;
						((Control)MyProject.Forms.frm_ReportForm.cmb_filter3).Visible = false;
						((Control)MyProject.Forms.frm_ReportForm.bt_show).Visible = false;
						((Control)MyProject.Forms.frm_ReportForm.dtp1).Visible = false;
						((Control)MyProject.Forms.frm_ReportForm.dtp2).Visible = false;
						MyProject.Forms.frm_ReportForm.CrystalReportViewer1.ToolPanelView = (ToolPanelViewType)0;
						((Form)MyProject.Forms.frm_ReportForm).Text = "Payment Voucher Print";
						MyProject.Forms.frm_ReportForm.CrystalReportViewer1.ReportSource = rep_voucher_print2;
						((Control)MyProject.Forms.frm_ReportForm).Show();
					}
				}
				else
				{
					Interaction.MsgBox((object)"Please Select Print Mode In Company Parameter.", (MsgBoxStyle)64, (object)"Print Mode");
				}
			}
		}

