		private void refreshForm()
		{
			mdl_public_variables.row = -1;
			if (operationFlag == 1)
			{
				if ((Operators.CompareString(counterSalesType, "CREDIT CARD", false) == 0) & mdl_public_variables.sms_creditCardSale)
				{
					smsSaleEditBody = "Dear customer, We have received your payment of Rs " + txt_nett.Text + " Thank you, please visit again";
					Thread thread = new Thread([SpecialName] () =>
					{
						mdl_public_variables.smsSendingThread(smsSaleEditBody, Interaction.InputBox("Enter Mobile No:", "", "", -1, -1), mdl_public_variables.sms_password);
					});
					thread.IsBackground = true;
					thread.Start();
					Thread thread2 = new Thread([SpecialName] () =>
					{
						mdl_public_variables.smsSendingThread(smsSaleEditBody, mdl_public_variables.com_mobile_number1, mdl_public_variables.sms_password);
					});
					thread2.IsBackground = true;
					thread2.Start();
				}
				if ((Operators.CompareString(counterSalesType, "CREDIT ACCOUNT", false) == 0) & mdl_public_variables.sms_PartySale)
				{
					smsSaleEditBody = "Dear sir, You have made a purchase of Rs " + txt_nett.Text + " and paid Rs " + text_payment.Text + " only On " + Strings.Format((object)dtp1.Value, "dd/MM/yyyy").ToString() + " Therefore, your Accounts Details as follows: \r\n1. Previous Outstanding Rs " + text_previous_due.Text + "\r\n2. Current Outstatnding Rs " + txt_nett.Text + "\r\nTotal outstanding is as of now Rs " + Text_net_due.Text;
					string mobileNo = ds1.Tables[0].Rows[cmb_party.SelectedIndex][3].ToString();
					Thread thread3 = new Thread([SpecialName] () =>
					{
						mdl_public_variables.smsSendingThread(smsSaleEditBody, mobileNo, mdl_public_variables.sms_password);
					});
					thread3.IsBackground = true;
					thread3.Start();
					Thread thread4 = new Thread([SpecialName] () =>
					{
						mdl_public_variables.smsSendingThread(smsSaleEditBody, mdl_public_variables.com_mobile_number1, mdl_public_variables.sms_password);
					});
					thread4.IsBackground = true;
					thread4.Start();
				}
				create_dataset_for_datagrid();
			}
			else
			{
				if (operationFlag != 2)
				{
					return;
				}
				if (mdl_public_variables.sms_billEditDelete)
				{
					smsSaleEditBody = smsSaleEditBody + txt_nett.Text + " Please check.";
					Thread thread5 = new Thread([SpecialName] () =>
					{
						mdl_public_variables.smsSendingThread(smsSaleEditBody, mdl_public_variables.com_mobile_number1, mdl_public_variables.sms_password);
					});
					thread5.IsBackground = true;
					thread5.Start();
				}
				((Form)this).Close();
			}
		}

