		}

		private void SalesReturnBillNoLoad()
		{
			//IL_0123: Unknown result type (might be due to invalid IL or missing references)
			cmb_salesReturnBillNo.Text = string.Empty;
			dgv_items.Rows.Clear();
			cmb_salesReturnBillNo.Items.Clear();
			s = "select x.name,x.BillTypeName+'-'+trnno as billNo,x.trnno,x.ledgercode,x.billType from \r\n ( \r\n select name, trnno,ledgercode,trndate, \r\n case when billtype=0 then 'FL' when billType = '1' then 'CS' else 'NAI' end as BillTypeName,billType \r\n from vw_salesbill_main   \r\n where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "'  \r\n and ledgercode='" + ds1.Tables[0].Rows[cmb_party.SelectedIndex][0].ToString() + "' and salestype<>'RETURN'  \r\n )as x \r\n order by convert(datetime,x.trnDate) DESC ,cast(x.trnno as integer)  desc  ";
			ds_salesReturnBillNoLoad = ob.populate(s);
			if (ds_salesReturnBillNoLoad.Tables[0].Rows.Count > 0)
			{
				ob.combofill(ds_salesReturnBillNoLoad.Tables[0], cmb_salesReturnBillNo);
				((Control)cmb_salesReturnBillNo).Enabled = true;
			}
			else
			{
				MessageBox.Show("No bill Exist against this party");
				((Control)cmb_salesReturnBillNo).Enabled = true;
			}
		}

