		private object gettrn(string type)
		{
			if (Operators.CompareString(type, "CS", false) == 0)
			{
				s = "select top 1 cast(trnno as integer) from salesbillmain where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "' AND billType = 1 order by cast(trnno as integer) desc";
			}
			else if (Operators.CompareString(type, "NAI", false) == 0)
			{
				s = "select top 1 cast(trnno as integer) from salesbillmain where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "' AND billType = 2 order by cast(trnno as integer) desc";
			}
			else
			{
				s = "select top 1 cast(trnno as integer) from salesbillmain where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "' AND billType = 0 order by cast(trnno as integer) desc";
			}
			txt_billNo.Text = ob.executereader(s);
			if (Operators.CompareString(txt_billNo.Text, "", false) == 0)
			{
				if ((Operators.CompareString(type, "CS", false) == 0) & (mdl_public_variables.csStartBillNo > 0))
				{
					txt_billNo.Text = Conversions.ToString(mdl_public_variables.csStartBillNo);
				}
				else if ((Operators.CompareString(type, "OffShop", false) == 0) & (Conversions.ToDouble(mdl_public_variables.combillno) > 0.0))
				{
					txt_billNo.Text = mdl_public_variables.combillno;
				}
				else if ((Operators.CompareString(type, "NAI", false) == 0) & (Conversions.ToDouble(mdl_public_variables.naiStartBillNO) > 0.0))
				{
					txt_billNo.Text = mdl_public_variables.naiStartBillNO;
				}
				else
				{
					txt_billNo.Text = Conversions.ToString(1);
				}
			}
			else
			{
				txt_billNo.Text = Conversions.ToString(Conversion.Val(txt_billNo.Text) + 1.0);
			}
			return Conversion.Val(txt_billNo.Text);
		}

		public bool searchgrid(object s)
		{
			searchflag = false;
			checked
			{
				if (mdl_public_variables.batchSale)
				{
					int num = 0;
					int[] array = new int[2];
					DataView dataView = new DataView();
					DataTable dataTable = new DataTable();
					int num2 = dgv_items.Rows.Count - 2;
					int num3 = 0;
					while (true)
					{
						int num4 = num3;
						int num5 = num2;
						if (num4 > num5)
						{
							break;
						}
						if (Operators.ConditionalCompareObjectEqual(dgv_items[11, num3].Value, s, false))
						{
							searchflag = true;
							position = num3;
							num++;
							array = (int[])Utils.CopyArray((Array)array, (Array)new int[num + 1]);
							array[num - 1] = num3;
						}
						num3++;
					}
					if (num > 1)
					{
						int num6 = num - 1;
						int num7 = 0;
						while (true)
						{
							int num8 = num7;
							int num5 = num6;
							if (num8 <= num5)
							{
								dataView.Table = ds_batchdetailsTotal.Tables[0];
								dataView.RowFilter = " itemCode = '" + dgv_items[11, array[num7]].Value.ToString() + "' and batchno = '" + dgv_items[3, array[num7]].Value.ToString() + "'";
								dataTable = dataView.ToTable();
								if (Operators.ConditionalCompareObjectGreater(dataTable.Rows[0][2], (object)0, false))
								{
									position = array[num7];
									break;
								}
								num7++;
								continue;
							}
							break;
						}
					}
				}
				else
				{
					int num9 = dgv_items.Rows.Count - 2;
					int num10 = 0;
					while (true)
					{
						int num11 = num10;
						int num5 = num9;
						if (num11 > num5)
						{
							break;
						}
						if (Operators.ConditionalCompareObjectEqual(dgv_items[11, num10].Value, s, false))
						{
							searchflag = true;
							position = num10;
						}
						num10++;
					}
				}
				return searchflag;
			}
		}

