							}
							else
							{
								double num8 = 0.0;
								num8 = Math.Round(Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[19, num3].Value)), 3) * Conversion.Val((object)(Math.Round(Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[9, num3].Value)), 3) * Math.Round(Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[5, num3].Value)), 3))) / 100.0;
								dgv_items[20, num3].Value = num8;
								totalDisAmount += num8;
								totalAbsDisAmount += Math.Abs(num8);
								dgv_items[19, num3].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[19, num3].Value));
								dgv_items[10, num3].Value = Operators.SubtractObject(Operators.MultiplyObject(dgv_items[9, num3].Value, dgv_items[5, num3].Value), dgv_items[20, num3].Value);
