		public void calculate_ltr()
		{
			FlLiter = 0.0;
			csLiter = 0.0;
			checked
			{
				int num = dgv_items.Rows.Count - 2;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					if (dgv_items[17, num2].Value != null)
					{
						if ((Operators.CompareString(dgv_items[17, num2].Value.ToString().ToUpper(), "CS", false) == 0) & mdl_public_variables.FLCS)
						{
							csLiter = Conversions.ToDouble(Operators.AddObject((object)csLiter, Operators.DivideObject(Operators.MultiplyObject(dgv_items[9, num2].Value, dgv_items[13, num2].Value), (object)1000)));
						}
						else if (mdl_public_variables.FLCS & (Operators.CompareString(dgv_items[17, num2].Value.ToString().ToUpper(), "CS", false) != 0))
						{
							FlLiter = Conversions.ToDouble(Operators.AddObject((object)FlLiter, Operators.DivideObject(Operators.MultiplyObject(dgv_items[9, num2].Value, dgv_items[13, num2].Value), (object)1000)));
						}
						else
						{
							FlLiter = Conversions.ToDouble(Operators.AddObject((object)FlLiter, Operators.DivideObject(Operators.MultiplyObject(dgv_items[9, num2].Value, dgv_items[13, num2].Value), (object)1000)));
						}
					}
					num2++;
				}
				if (mdl_public_variables.FLCS)
				{
					if ((FlLiter > mdl_public_variables.comlimit) | (csLiter > mdl_public_variables.csComLimit))
					{
						((Control)lbl_litre).ForeColor = Color.Red;
					}
					else
					{
						((Control)lbl_litre).ForeColor = Color.Black;
					}
					lbl_litre.Text = "FL " + FlLiter + " \\ CS " + csLiter;
				}
				else
				{
					if (FlLiter > mdl_public_variables.comlimit)
					{
						((Control)lbl_litre).ForeColor = Color.Red;
					}
					lbl_litre.Text = FlLiter.ToString();
				}
			}
		}

