		private void txt_gross_TextChanged(object sender, EventArgs e)
		{
			calc();
		}

		private void calc()
		{
			amt_nett = 0.0;
			amt_rnd = 0.0;
			amt_rounded = 0;
			amt_surcharge = 0.0;
			checked
			{
				if ((Conversion.Val(mdl_public_variables.surcharge_amount) > 0.0) & (Operators.CompareString(txt_surchargerate.Text, "", false) == 0))
				{
					txt_surchargerate.Text = Conversions.ToString(Conversion.Val(mdl_public_variables.surcharge_amount) * 100.0 / Conversion.Val(txt_gross.Text));
				}
				else
				{
					if ((Conversion.Val(txt_surchargerate.Text) > 0.0) & (Operators.CompareString(counterSalesType, "CREDIT CARD", false) == 0))
					{
						amt_surcharge = Conversion.Val(txt_gross.Text) * Conversion.Val(txt_surchargerate.Text) / 100.0;
					}
					if (((TextBoxBase)txt_discount).ReadOnly)
					{
						amt_nett = Conversion.Val(txt_gross.Text) + amt_surcharge;
					}
					else
					{
						amt_nett = Conversion.Val(txt_gross.Text) - amt_discount + amt_surcharge;
					}
					amt_rounded = (int)Math.Round(Conversion.Int(amt_nett));
					amt_rnd = amt_nett - (double)amt_rounded;
					if (Math.Abs(amt_rnd) > 0.5)
					{
						amt_rounded = (int)Math.Round(amt_nett + (1.0 - Math.Abs(amt_rnd)));
						txt_rnd.Text = "+" + Strings.Format((object)(1.0 - Math.Abs(amt_rnd)), "0.00");
					}
					else
					{
						amt_rounded = (int)Math.Round(amt_nett - Math.Abs(amt_rnd));
						txt_rnd.Text = "-" + Strings.Format((object)Math.Abs(amt_rnd), "0.00");
					}
					txt_surchargeamount.Text = Strings.Format((object)amt_surcharge, "0.00");
					txt_nett.Text = Conversions.ToString(amt_rounded);
					if (Conversion.Val(txt_tendered.Text) > 0.0)
					{
						txt_retun.Text = Conversions.ToString(Conversion.Val(txt_tendered.Text) - Conversion.Val(txt_nett.Text));
					}
				}
				if (!mdl_public_variables.isPoleDisplay)
				{
					return;
				}
				poleDisplayLine2 = "Total Net ";
				int num = 20 - Conversion.Val(txt_nett.Text).ToString().Length;
				int num2 = 11;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					poleDisplayLine2 += " ";
					num2++;
				}
				poleDisplayLine2 += Conversion.Val(txt_nett.Text);
				mdl_public_variables.PoleDisplayImportText(poleDisplayLine1, poleDisplayLine2);
			}
		}

		public void calculationAmount(double amount)
		{
			double num = 0.0;
			amt_nett = 0.0;
			amt_rnd = 0.0;
			amt_rounded = 0;
			amt_surcharge = 0.0;
			txt_gross.Text = Conversions.ToString(amount);
			if ((Conversion.Val(txt_surchargerate.Text) > 0.0) & (Operators.CompareString(counterSalesType, "CREDIT CARD", false) == 0))
			{
				amt_surcharge = Conversion.Val(txt_gross.Text) * Conversion.Val(txt_surchargerate.Text) / 100.0;
			}
			if (Conversion.Val(txt_discountrate.Text) > 0.0)
			{
				num = Conversion.Val(txt_gross.Text) * Conversion.Val(txt_discountrate.Text) / 100.0;
			}
			amt_nett = Conversion.Val(txt_gross.Text) - num + amt_surcharge;
			amt_rounded = Conversions.ToInteger(Strings.Format((object)amt_nett, "0.00"));
			if ((double)amt_rounded > amt_nett)
			{
				amt_rnd = (double)amt_rounded - amt_nett;
				txt_rnd.Text = "+" + Strings.Format((object)amt_rnd, "0.00");
			}
			else
			{
				amt_rnd = amt_nett - (double)amt_rounded;
				txt_rnd.Text = "-" + Strings.Format((object)amt_rnd, "0.00");
			}
			if (amt_surcharge > 0.0)
			{
				txt_surchargeamount.Text = Strings.Format((object)amt_surcharge, "0.00");
			}
			txt_nett.Text = Conversions.ToString(amt_rounded);
			if (Conversion.Val(txt_tendered.Text) > 0.0)
			{
				txt_retun.Text = Conversions.ToString(Conversion.Val(txt_tendered.Text) - Conversion.Val(txt_nett.Text));
			}
			if ((num > 0.0) & !((TextBoxBase)txt_discount).ReadOnly)
			{
				txt_discount.Text = Strings.Format((object)num, "0.00");
			}
			else
			{
				txt_discount.Text = Strings.Format((object)0, "0.00");
			}
			if (!mdl_public_variables.isPoleDisplay)
			{
				return;
			}
			poleDisplayLine2 = "Total Net ";
			checked
			{
				int num2 = 20 - Conversion.Val(txt_nett.Text).ToString().Length;
				int num3 = 11;
				while (true)
				{
					int num4 = num3;
					int num5 = num2;
					if (num4 > num5)
					{
						break;
					}
					poleDisplayLine2 += " ";
					num3++;
				}
				poleDisplayLine2 += Conversion.Val(txt_nett.Text);
				mdl_public_variables.PoleDisplayImportText(poleDisplayLine1, poleDisplayLine2);
			}
		}

