			double num2 = 0.0;
			num2 = ((operationFlag != 1) ? 0.0 : Conversion.Val(txt_nett.Text));
			num = ((Operators.CompareString(lbl_opening.Text, "Dr", false) != 0) ? (num2 - Conversion.Val(text_previous_due.Text) - Conversion.Val(text_payment.Text)) : (num2 + Conversion.Val(text_previous_due.Text) - Conversion.Val(text_payment.Text)));
			if (num >= 0.0)
			{
				Text_net_due.Text = Conversions.ToString(num);
				lbl_dr_cr.Text = "Dr";
			}
			else
			{
				Text_net_due.Text = Conversions.ToString(Math.Abs(num));
				lbl_dr_cr.Text = "Cr";
			}
		}

