		private void refreshDebtorsGrid()
		{
			s = "EXEC [dbo].[VoucharsDue] @ComCode = N'" + mdl_public_variables.companycode + "', @YearCode = N'" + mdl_public_variables.yearcode + "',\t@ledgerCode = N'" + salePartyCode + "'";
			ds = ob.populate(s);
			dgv_debtors.DataSource = ds.Tables[0];
			dgv_debtors.Columns[0].Visible = false;
			dgv_debtors.Columns[4].Visible = false;
			dgv_debtors.Columns[5].Visible = false;
			((Control)dgv_debtors).Refresh();
			double num = 0.0;
			checked
			{
				int num2 = ds.Tables[0].Rows.Count - 1;
				int num3 = 0;
				while (true)
				{
					int num4 = num3;
					int num5 = num2;
					if (num4 > num5)
					{
						break;
					}
					num += Conversion.Val(RuntimeHelpers.GetObjectValue(ds.Tables[0].Rows[num3]["Due"]));
					num3++;
				}
				if (num < 0.0)
				{
					text_previous_due.Text = Conversions.ToString(Math.Abs(num));
					lbl_opening.Text = "Dr";
				}
				else
				{
					text_previous_due.Text = Conversions.ToString(num);
					lbl_opening.Text = "Cr";
				}
				if (operationFlag == 1)
				{
					text_current_bill.Text = txt_gross.Text;
					text_discount_rate.Text = txt_discountrate.Text;
					text_discount_amount.Text = txt_discount.Text;
					Text_net_due.Text = Conversions.ToString(Conversion.Val(txt_nett.Text) + num);
				}
				else
				{
					text_current_bill.Text = Conversions.ToString(0);
					text_discount_rate.Text = Conversions.ToString(0);
					text_discount_amount.Text = Conversions.ToString(0);
					Text_net_due.Text = Conversions.ToString(num);
				}
			}
		}

		private void saveReceipt()
		{
			//IL_003d: Unknown result type (might be due to invalid IL or missing references)
			//IL_006e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0073: Unknown result type (might be due to invalid IL or missing references)
			//IL_0074: Unknown result type (might be due to invalid IL or missing references)
			//IL_0076: Invalid comparison between Unknown and I4
			//IL_01b8: Unknown result type (might be due to invalid IL or missing references)
			//IL_01c2: Expected O, but got Unknown
			//IL_00b3: Unknown result type (might be due to invalid IL or missing references)
			if (!((Control)panel_debtors).Visible)
			{
				return;
			}
			if (Conversion.Val(text_payment.Text) <= 0.0)
			{
				Interaction.MsgBox((object)"Please enter received amount", (MsgBoxStyle)16, (object)null);
				return;
			}
			if (Operators.CompareString(lbl_dr_cr.Text, "Cr", false) == 0)
			{
				MsgBoxResult val = Interaction.MsgBox((object)"Enter amount is greater than total selected bills, do you want ot want to pay the rest ON ACCOUNT?", (MsgBoxStyle)4, (object)null);
				if ((int)val == 7)
				{
					return;
				}
			}
			if (cmb_payment.SelectedIndex == 2 && ((TextBoxBase)Text_cheque_no).TextLength != 6)
			{
				Interaction.MsgBox((object)"Please enter a valid cheque no", (MsgBoxStyle)16, (object)null);
				return;
			}
			partyCode = ds1.Tables[0].Rows[cmb_party.SelectedIndex][0].ToString();
			if (Conversion.Val(text_current_bill.Text) > 0.0)
			{
				if (Conversion.Val(txt_discountrate.Text) == 0.0 && Conversion.Val(txt_discount.Text) > 0.0)
				{
					double num = 0.0;
					num = Conversion.Val(txt_discount.Text) * 100.0 / Conversion.Val(txt_gross.Text);
					txt_discountrate.Text = Conversions.ToString(num);
				}
				billSaveCheck();
			}
			refreshDebtorsGrid();
			text_payment_TextChanged(this, (EventArgs)new KeyEventArgs((Keys)32));
			VoucharAddSaveMain();
			refreshDebtorsGrid();
			refreshForm();
		}

		private void VoucharAddSaveMain()
		{
			date_vouchar_new = dtp1.Value;
			ob_payreceive_vouchar = new cls_conpayrec_vch();
			ob_payreceive_vouchar.SetTrnEffect_Party(1);
			ob_payreceive_vouchar.SetTrnType("RECEIPT");
			ob_payreceive_vouchar.SetVchDate(Conversions.ToString(DateTime.Now.Date));
			ob_payreceive_vouchar.SetNarration("");
			if (Operators.CompareString(cmb_payment.Text, "CASH", false) == 0)
			{
				ob_payreceive_vouchar.SetReceiptType("CASH / OTHERS");
				ob_payreceive_vouchar.SetChequeNo("");
				ob_payreceive_vouchar.SetCardNo("");
				ob_payreceive_vouchar.SetTransactionIDDetails(Strings.UCase(""));
				ob_payreceive_vouchar.SetTrnAccount_CashBank(Conversions.ToString(((ListControl)cmb_bank).SelectedValue));
			}
			else if (Operators.CompareString(cmb_payment.Text, "BANK", false) == 0)
			{
				ob_payreceive_vouchar.SetReceiptType(" CARD");
				ob_payreceive_vouchar.SetChequeNo("");
				ob_payreceive_vouchar.SetCardNo("");
				ob_payreceive_vouchar.SetTransactionIDDetails("");
				ob_payreceive_vouchar.SetTrnAccount_CashBank(Conversions.ToString(((ListControl)cmb_bank).SelectedValue));
			}
			else if (Operators.CompareString(cmb_payment.Text, "CHEQUE", false) == 0)
			{
				ob_payreceive_vouchar.SetReceiptType("CHEQUE");
				ob_payreceive_vouchar.SetChequeNo(Strings.UCase(Text_cheque_no.Text));
				ob_payreceive_vouchar.SetCardNo("");
				ob_payreceive_vouchar.SetTransactionIDDetails("");
				ob_payreceive_vouchar.SetTrnAccount_CashBank(Conversions.ToString(((ListControl)cmb_bank).SelectedValue));
			}
			ob_payreceive_vouchar.SetTrnAccount_Party(partyCode);
			ob_payreceive_vouchar.SetTrnAmount_Party(Conversions.ToDouble(text_payment.Text));
			string text = "";
			if (Operators.CompareString(txt_vchNo.Text, "", false) == 0)
			{
				ob_payreceive_vouchar.insertTransaction();
			}
			else
			{
				ob_payreceive_vouchar.insertTransaction(txt_vchNo.Text);
				text = txt_vchNo.Text;
			}
			IndexID = ob_payreceive_vouchar.GetIndexId();
			txt_vchNo.Text = Conversions.ToString(ob_payreceive_vouchar.GetTrnNo());
			VoucharAddSaveDetails(IndexID);
			refreshForm();
		}

		private void VoucharAddSaveDetails(double IndexID)
		{
			double num = Conversion.Val(text_payment.Text);
			double num2 = 0.0;
			num = Conversion.Val(text_payment.Text);
			ob_payreceive_vouchar = new cls_conpayrec_vch();
			if (!((IndexID > 0.0) & (num == Conversion.Val(text_payment.Text))))
			{
				return;
			}
			string trnAccount = partyCode;
			int trnEffect = 1;
			int num3 = 0;
			int serialId = 1;
			long num4 = 0L;
			string text = "";
			checked
			{
				int num5 = dgv_debtors.Rows.Count - 1;
				int num6 = 0;
				while (true)
				{
					int num7 = num6;
					int num8 = num5;
					if (num7 > num8)
					{
						break;
					}
					if (Operators.ConditionalCompareObjectEqual(dgv_debtors[5, num6].Value, (object)(-1), false) && Operators.ConditionalCompareObjectGreater(dgv_debtors[3, num6].Value, (object)0, false))
					{
						num2 = Conversions.ToDouble(dgv_debtors[3, num6].Value);
						num3++;
						string text2 = "";
						string text3 = "";
						double num9 = 0.0;
						num4 = 0L;
						DateTime vchDate;
						if (!(num2 < num))
						{
							text2 = dgv_debtors[0, num6].Value.ToString();
							text3 = dgv_debtors[1, num6].Value.ToString();
							vchDate = Conversions.ToDate(mdl_public_variables.DtpDate(Conversions.ToString(dgv_debtors[2, num6].Value)));
							num4 = Conversions.ToLong(dgv_debtors[4, num6].Value.ToString());
							num9 = Conversion.Val((object)num);
							ob_payreceive_vouchar.insertVoucharDetails((long)Math.Round(IndexID), serialId, num3, vchDate, text2, text3, trnAccount, num9, trnEffect, num4);
							num -= num2;
							break;
						}
						num -= num2;
						text2 = dgv_debtors[0, num6].Value.ToString();
						text3 = dgv_debtors[1, num6].Value.ToString();
						vchDate = Conversions.ToDate(mdl_public_variables.DtpDate(Conversions.ToString(dgv_debtors[2, num6].Value)));
						num4 = Conversions.ToLong(dgv_debtors[4, num6].Value.ToString());
						num9 = Conversion.Val((object)num2);
						ob_payreceive_vouchar.insertVoucharDetails((long)Math.Round(IndexID), serialId, num3, vchDate, text2, text3, trnAccount, num9, trnEffect, num4);
					}
					num6++;
				}
				if (num > 0.0)
				{
					string text2 = "RECEIPT";
					string text3 = "";
					num3++;
					DateTime vchDate = Conversions.ToDate(Strings.Format((object)dtp1.Value.Date, "MM/dd/yyyy"));
					num4 = (long)Math.Round(IndexID);
					double num9 = Conversion.Val((object)num);
					ob_payreceive_vouchar.insertVoucharDetails((long)Math.Round(IndexID), serialId, num3, vchDate, text2, text3, trnAccount, num9, trnEffect, num4);
				}
			}
		}

