		private void cmbbatch_KeyDown(object sender, KeyEventArgs e)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			//IL_0009: Invalid comparison between Unknown and I4
			if ((int)e.KeyData != 13)
			{
				return;
			}
			mdl_public_variables.row = ((DataGridViewBand)dgv_items.CurrentRow).Index;
			int num = mdl_public_variables.row;
			dgv_items.CurrentCell = dgv_items[7, ((DataGridViewBand)dgv_items.CurrentRow).Index];
			dgv_items.CurrentCell.Selected = true;
			((Control)dgv_items).Select();
			((Control)cmbbatch).Visible = false;
			checked
			{
				if (mdl_public_variables.batchEdit & (dgv_items.Rows.Count - 2 > 0))
				{
					if (searchBatch(previousBatch, Conversions.ToString(dgv_items[3, mdl_public_variables.row].Value), mdl_public_variables.row))
					{
						mdl_public_variables.row = batchPosition;
						dgv_items[7, batchPosition].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[7, batchPosition].Value)) + Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[7, num].Value));
						dgv_items[8, batchPosition].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[8, batchPosition].Value)) + Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[8, num].Value));
						if (Conversions.ToDouble(previousBatchQnty) > 0.0)
						{
							dgv_items[9, batchPosition].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[9, batchPosition].Value)) + Conversions.ToDouble(previousBatchQnty);
						}
						else
						{
							dgv_items[9, batchPosition].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[9, batchPosition].Value)) + Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[9, num].Value));
						}
						dgv_items[10, batchPosition].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[10, batchPosition].Value)) + Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[10, num].Value));
						if (Operators.CompareString(mdl_public_variables.comonoff, "ON", false) == 0)
						{
							dgv_items[14, batchPosition].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[14, batchPosition].Value)) + Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[14, num].Value));
							dgv_items[15, batchPosition].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[15, batchPosition].Value)) + Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[15, num].Value));
							dgv_items[16, batchPosition].Value = Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[16, batchPosition].Value)) + Conversion.Val(RuntimeHelpers.GetObjectValue(dgv_items[16, num].Value));
						}
						if (batchsplitCountActivater)
						{
							mdl_public_variables.row = num + batchSplitRowCounter;
							batchsplitCountActivater = false;
							batchSplitRowCounter = 0;
						}
