			SqlCommand val4 = new SqlCommand("insert into ledger(name,accode,ledcode,companycode)select accountname,acgroupcode,accountcode,companycode from barmgmt.dbo.AccountMst", mdl_public_variables.con);
			val3.ExecuteNonQuery();
			val4.ExecuteNonQuery();
			SqlCommand val5 = new SqlCommand("insert into groupmst (companycode,groupcode,groupname) select companycode,matgroupcode,matgroupname from barmgmt.dbo.MatGroupMst", mdl_public_variables.con);
			SqlCommand val6 = new SqlCommand("insert into categorymst (companycode,categorycode,categoryname) select companycode,categorycode,categoryname from barmgmt.dbo.matcategoryMst", mdl_public_variables.con);
			SqlCommand val7 = new SqlCommand("insert into kflmst (companycode,kflcode,kflname) select companycode,kflcode,kflname from barmgmt.dbo.kflmst", mdl_public_variables.con);
			SqlCommand val8 = new SqlCommand("insert into itemgroupml(ml,packing) select distinct measureml,packing from barmgmt.dbo.itemmst", mdl_public_variables.con);
			SqlCommand val9 = new SqlCommand("insert into strength(strengthname) select distinct strength from barmgmt.dbo.itemmst", mdl_public_variables.con);
			SqlCommand val10 = new SqlCommand("insert into itemmst(groupcode,itemcode,itemname,categorycode,kflcode,ml,packing,strengthname,companycode,barcode,salesrate) select itemgroup,itemcode,itemname,itemcategory,kindforeign,measureml,packing,strength,companycode,shortcode,salerate from barmgmt.dbo.itemmst where itemcategory in(select categorycode from barmgmt.dbo.matcategoryMst)", mdl_public_variables.con);
			SqlCommand val11 = new SqlCommand("insert into storage(companycode,shopcode,shopname,address) select companycode,loccode,location,locaddress from barmgmt.dbo.locationmst group by companycode,loccode,location,locaddress", mdl_public_variables.con);
			SqlCommand val12 = new SqlCommand("insert into openingstockmst(shopcode,companycode,itemcode,loose,box,qnty,yearcode,trndate) select loccode,barmgmt.dbo.itmopening.companycode,itemcode,loose,box,stock,barmgmt.dbo.itmopening.yearcode,stdate from barmgmt.dbo.itmopening join barmgmt.dbo.yearmst on barmgmt.dbo.yearmst.companycode=barmgmt.dbo.itmopening.companycode and barmgmt.dbo.yearmst.yearcode=barmgmt.dbo.itmopening.yearcode where loccode in(select loccode from barmgmt.dbo.locationmst)", mdl_public_variables.con);
			val5.ExecuteNonQuery();
			val6.ExecuteNonQuery();
			val7.ExecuteNonQuery();
			val8.ExecuteNonQuery();
			val9.ExecuteNonQuery();
			val10.ExecuteNonQuery();
			val11.ExecuteNonQuery();
			val12.ExecuteNonQuery();
			SqlCommand val13 = new SqlCommand("insert into companyparamtr (companycode,csalebillno,saleaccount_head,bankacc,breakacc,saleretrnacc,purchaseacchd,cashhd,discntacc,defshpgdn,ratecode,expenceacc,printbill,autorefcurrsal,actposmode) select companycode,cntsalebillno,cntrsalehead,crcardpartycode,breakageac,retsaleac,purchasehead,cashsaleac,discaccode,shoploc,defrate,expac,0,0,0 from barmgmt.dbo.parammst", mdl_public_variables.con);
			val13.ExecuteNonQuery();
			SqlCommand val14 = new SqlCommand("select loccode,barmgmt.dbo.itmopening.companycode,itemcode,loose,box,stock,barmgmt.dbo.yearmst.yearcode,stdate from barmgmt.dbo.itmopening join barmgmt.dbo.yearmst on barmgmt.dbo.yearmst.yearcode=barmgmt.dbo.itmopening.yearcode and barmgmt.dbo.yearmst.companycode=barmgmt.dbo.itmopening.companycode ", mdl_public_variables.con);
			SqlCommand val15 = new SqlCommand("insert into itemrateinfo(ratecode,ratename,companycode) select ratecode,ratename,companycode from barmgmt.dbo.itmratemst group by ratecode,ratename,companycode", mdl_public_variables.con);
			SqlCommand val16 = new SqlCommand("insert into itemratemst(companycode,ratecode,itemcode,salesrate) select companycode,ratecode,itemcode,itemrate from barmgmt.dbo.itmratemst where itemcode in(select itemcode from itemmst)", mdl_public_variables.con);
			val14.ExecuteNonQuery();
			val15.ExecuteNonQuery();
			val16.ExecuteNonQuery();
			SqlCommand val17 = new SqlCommand("insert into purchasemain(companycode,yearcode,trnno,trndate,ptype,purchaseacccode,suppliercode,shopcode,docno,docdate,tppassno) select companyparamtr.companycode,yearcode,grnno,grndate,'PURCHASE',purchaseacchd,suppcode,toloccode,chno,chdate,tpassno from barmgmt.dbo.grnmain join companyparamtr on  companyparamtr.companycode=barmgmt.dbo.grnmain.companycode ", mdl_public_variables.con);
			val17.ExecuteNonQuery();
			SqlCommand val18 = new SqlCommand("insert into purchasedetail(companycode,yearcode,itemcode,batchno,itembox,itemloose,itemquantity,trnno) select barmgmt.dbo.grnmain.companycode,yearcode,itemcode,batchno,box,loose,itemqty,grnno from barmgmt.dbo.grndetail join barmgmt.dbo.grnmain on barmgmt.dbo.grnmain.companycode=barmgmt.dbo.grndetail.companycode and barmgmt.dbo.grnmain.systemno=barmgmt.dbo.grndetail.systemno", mdl_public_variables.con);
			val18.ExecuteNonQuery();
			SqlCommand val19 = new SqlCommand("insert into taxdetail(companycode,schemecode,schemename,srno,taxcode,ledcode,taxamount) select barmgmt.dbo.nwtaxdetail.companycode,barmgmt.dbo.nwtaxdetail.schemecode,schemename,srno,taxcode,accode,taxrate from barmgmt.dbo.nwtaxdetail join barmgmt.dbo.nwtaxmain on barmgmt.dbo.nwtaxdetail.companycode=barmgmt.dbo.nwtaxmain.companycode and barmgmt.dbo.nwtaxdetail.schemecode=barmgmt.dbo.nwtaxmain.schemecode ", mdl_public_variables.con);
			val19.ExecuteNonQuery();
			mdl_public_variables.closecon();
		}

