		private void save()
		{
			//IL_026b: Unknown result type (might be due to invalid IL or missing references)
			ob_journalEntry = new cls_journalEntry();
			ob_journalEntry.totalField = 0;
			string result = "";
			ob_journalEntry.setVchDate(voucher_date);
			ob_journalEntry.setTrnType("PAYMENT");
			ob_journalEntry.setReceiptType("EXPENCE");
			ob_journalEntry.setNaration(txt_narration.Text);
			cls_journalEntry cls_journalEntry2 = ob_journalEntry;
			checked
			{
				cls_journalEntry2.totalField++;
				ob_journalEntry.InitilisedArray();
				ob_journalEntry.trnAccountCode[ob_journalEntry.totalField - 1] = mdl_public_variables.comexpenceacc;
				ob_journalEntry.serialId[ob_journalEntry.totalField - 1] = ob_journalEntry.totalField;
				ob_journalEntry.lookUpAccount[ob_journalEntry.totalField - 1] = mdl_public_variables.comcashacc;
				ob_journalEntry.lookUpSerialId[ob_journalEntry.totalField - 1] = ob_journalEntry.totalField - 1;
				ob_journalEntry.trnAmount[ob_journalEntry.totalField - 1] = Conversions.ToString(Conversion.Val(txt_amount.Text));
				ob_journalEntry.trnEffect[ob_journalEntry.totalField - 1] = -1;
				cls_journalEntry2 = ob_journalEntry;
				cls_journalEntry2.totalField++;
				ob_journalEntry.InitilisedArray();
				ob_journalEntry.trnAccountCode[ob_journalEntry.totalField - 1] = mdl_public_variables.comcashacc;
				ob_journalEntry.serialId[ob_journalEntry.totalField - 1] = ob_journalEntry.totalField;
				ob_journalEntry.lookUpAccount[ob_journalEntry.totalField - 1] = mdl_public_variables.comexpenceacc;
				ob_journalEntry.lookUpSerialId[ob_journalEntry.totalField - 1] = ob_journalEntry.totalField + 1;
				ob_journalEntry.trnAmount[ob_journalEntry.totalField - 1] = Conversions.ToString(Conversion.Val(txt_amount.Text));
				ob_journalEntry.trnEffect[ob_journalEntry.totalField - 1] = 1;
				if (!ob_journalEntry.InsertJournalDetails(ref result))
				{
					Interaction.MsgBox((object)result, (MsgBoxStyle)16, (object)null);
				}
				else
				{
					close_expence();
				}
			}
		}

