		public void mainformload()
		{
			row = 0;
			dgv1.Columns.Clear();
			if (mdl_public_variables.count == 1)
			{
				s = "SELECT categorymst.companyCode, categorymst.categorycode, categorymst.categoryname ,isnull(categorymst.ManufacturerCode,0)as ManufacturerCode, isnull(ManufacturerMaster.ManufacturerName,'')as ManufacturerName  FROM categorymst  left outer join ManufacturerMaster  on categorymst.companyCode = ManufacturerMaster.Companycode and categorymst.ManufacturerCode = ManufacturerMaster.ManufacturerCode where categorymst.companyCode = '" + mdl_public_variables.companycode + "' order by categoryname";
			}
			else if (mdl_public_variables.count == 501)
			{
				s = "SELECT naiItemSubGroup.companyCode,naiItemSubGroup.subGroupCode,naiItemSubGroup.subGroupName, \r\n naiItemSubGroup.mainGroupCode,naiItemMainGroup.mainGroupName  \r\n FROM naiItemSubGroup  \r\n LEFT OUTER JOIN naiItemMainGroup ON naiItemSubGroup.companyCode=naiItemMainGroup.companyCode \r\n AND naiItemSubGroup.mainGroupCode=naiItemMainGroup.mainGroupCode \r\n WHERE naiItemSubGroup.companyCode='" + mdl_public_variables.companycode + "' \r\n ORDER BY naiItemSubGroup.subGroupName ";
			}
			else if (mdl_public_variables.count == 2)
			{
				s = "select companycode,kflcode,kflname from KflMst where companycode='" + mdl_public_variables.companycode + "' ORDER BY kflname ";
			}
			else if (mdl_public_variables.count == 3)
			{
				s = "select ml,packing from itemgroupml where companycode = '" + mdl_public_variables.companycode + "' order by ml desc";
			}
			else if (mdl_public_variables.count == 4)
			{
				s = "select companycode,groupcode,groupname from groupMst where companycode ='" + mdl_public_variables.companycode + "' ORDER BY groupname ";
			}
			else if (mdl_public_variables.count == 500)
			{
				s = "select companyCode,mainGroupCode,mainGroupName from naiItemMainGroup where companycode ='" + mdl_public_variables.companycode + "' ORDER BY mainGroupName ";
			}
			else if (mdl_public_variables.count == 5)
			{
				s = "select itemcode,itemname,barcode,groupmst.groupname,categorymst.categoryname,kflmst.kflname,ml,packing,salesrate,strengthname,isnull(purchaserate,0),isnull(min_qnty,0) ,ISNULL(itemImgUrl,'') as itemImgUrl from itemmst join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode join kflmst on kflmst.kflcode=itemmst.kflcode and kflmst.companycode=itemmst.companycode where itemmst.companycode='" + mdl_public_variables.companycode + "' order by itemname";
			}
			else if (mdl_public_variables.count == 501)
			{
				s = "SELECT naiItemSubGroup.companyCode, naiItemSubGroup.subGroupCode, naiItemSubGroup.subGroupName as naiItemSubGroup, naiItemMainGroup.mainGroupName as naiItemMainGroup, naiItemMainGroup.mainGroupCode   \r\n FROM naiItemSubGroup  INNER JOIN naiItemMainGroup ON naiItemSubGroup.companyCode = naiItemMainGroup.companyCode  \r\n AND naiItemSubGroup.mainGroupCode = naiItemMainGroup.mainGroupCode   \r\n where naiItemMainGroup.companyCode = '" + mdl_public_variables.companycode + "' and naiItemSubGroup.maingroupcode is not null  \r\n order by subGroupName ";
			}
			else if (mdl_public_variables.count == 502)
			{
				s = "SELECT unitCode, basicUnitName, basicQnty, bulkUnitName, bulkQnty,type   \r\n FROM naiUnitMaster  \r\n where companyCode='" + mdl_public_variables.companycode + "' \r\n order by bulkUnitName,basicUnitName ";
			}
			else if (mdl_public_variables.count == 503)
			{
				s = "SELECT naiItemMaster.itemCode, naiItemMaster.ItemName, naiItemMaster.BarCode,naiItemSubGroup.subGroupName as subGroupName,  \r\n naiItemMainGroup.mainGroupName mainGroupName,'' kflname, \r\n (convert (varchar,naiUnitMaster.basicQnty) + ' ' +naiUnitMaster.basicUnitName) as IssueUnit,   \r\n (convert (varchar,naiUnitMaster.bulkQnty) + ' ' +naiUnitMaster.BulkUnitName) as PurchaseUnit,  \r\n naiItemMaster.SalesRate,'' strengthname, naiItemMaster.PurchaseRate,naiItemMaster.MinQnty  \r\n FROM naiItemMaster    \r\n LEFT JOIN naiItemMainGroup ON naiItemMaster.companyCode = naiItemMainGroup.companyCode AND naiItemMaster.mainGroupCode = naiItemMainGroup.mainGroupCode    \r\n LEFT JOIN naiItemSubGroup ON naiItemMaster.companyCode = naiItemSubGroup.companyCode AND naiItemMaster.subGroupCode = naiItemSubGroup.subGroupCode     \r\n LEFT JOIN naiUnitMaster ON naiItemMaster.companyCode = naiUnitMaster.companyCode AND naiItemMaster.unitCode = naiUnitMaster.unitCode    \r\n  WHERE naiItemMaster.companyCode = '" + mdl_public_variables.companycode + "' and naiItemMaster.isBaritem = 0  \r\n  order by ItemName ";
			}
			else if (mdl_public_variables.count == 6)
			{
				s = "select strengthname from strength where companycode='" + mdl_public_variables.companycode + "' order by strengthname ";
			}
			else if (mdl_public_variables.count == 7)
			{
				s = "select ratecode,ratename,companycode from itemrateinfo where companycode ='" + mdl_public_variables.companycode + "' order by ratename";
			}
			else if (mdl_public_variables.count == 8)
			{
				s = "select companycode,companyname,address1,address2,city,district,stat,pin,phn,email,website,faxno,lstno,cstno,panno,vatno,stno from companymast order by companyname";
			}
			else if ((mdl_public_variables.count == 10) | (mdl_public_variables.count == 14))
			{
				s = "select companycode,shopcode,shopname,address,ShopType from storage where companycode='" + mdl_public_variables.companycode + "' order by shopname ";
			}
			else if (mdl_public_variables.count == 11)
			{
				s = " SELECT AccMainCode, AccMainName as MainGroup, case when CreditEffects = -1 then 'Debit' else 'Credit' end as Type , AccMainAlias FROM MasterAccountsMain order by sequence";
			}
			else if (mdl_public_variables.count == 12)
			{
				s = "SELECT MasterAccountsGroups.companyCode,MasterAccountsGroups.sequence, MasterAccountsGroups.AccMainCode, MasterAccountsGroups.AccGroupCode,   MasterAccountsGroups.AccGroupName AS SubGroup, MasterAccountsGroups.ShortCode AS shortName, MasterAccountsGroups.PLEffect As 'Effect on PL' ,   MasterAccountsGroups.UnderAccGroupCode, MasterAccountsMain.AccMainName AS MainGroup, case when MasterAccountsGroups.PrimaryGroup = 1 then 'Prime' else MasterAccountsGroups_1.AccGroupName end as GroupName,MasterAccountsGroups.hidden  FROM MasterAccountsGroups  INNER JOIN MasterAccountsMain ON MasterAccountsGroups.AccMainCode = MasterAccountsMain.AccMainCode   Left Outer JOIN MasterAccountsGroups AS MasterAccountsGroups_1 ON MasterAccountsGroups.companyCode = MasterAccountsGroups_1.companyCode AND MasterAccountsGroups.UnderAccGroupCode = MasterAccountsGroups_1.AccGroupCode AND MasterAccountsGroups.AccMainCode = MasterAccountsGroups_1.AccMainCode  where MasterAccountsGroups .companyCode='" + mdl_public_variables.companycode + "'  order by MasterAccountsGroups.sequence ";
			}
			else if (mdl_public_variables.count == 13)
			{
				s = "SELECT MasterAccountsLedger.ledgerCode, MasterAccountsGroups.AccGroupName AS AccountsGroup, MasterAccountsLedger.ledgerName AS LedgerName,    \r\n MasterAccountsLedger.contactPerson AS ContactPerson, MasterAccountsLedger.contactNo AS ContactNo,  \r\n IsNull(MasterAccountsOpening.TrnAmount,0) AS OpeningAmount,   CASE WHEN MasterAccountsOpening.TrnEffect = - 1 THEN 'Debit'  \r\n ELSE CASE WHEN MasterAccountsOpening.TrnEffect = 1 THEN 'Credit' ELSE '' END END AS 'Debit-Credit',MasterAccountsLedger.Hidden   \r\n FROM MasterAccountsLedger  \r\n INNER JOIN  MasterAccountsGroups ON MasterAccountsLedger.companyCode = MasterAccountsGroups.companyCode  \r\n AND   MasterAccountsLedger.AccGroupCode = MasterAccountsGroups.AccGroupCode  \r\n Left JOIN  MasterAccountsOpening ON MasterAccountsLedger.companyCode = MasterAccountsOpening.companyCode  \r\n AND   MasterAccountsLedger.ledgerCode = MasterAccountsOpening.ledgerCode AND MasterAccountsOpening.yearCode = '" + mdl_public_variables.yearcode + "'   \r\n WHERE (MasterAccountsGroups.companyCode = '" + mdl_public_variables.companycode + "') \r\n ORDER BY LedgerName ";
			}
			else if (mdl_public_variables.count == 15)
			{
				s = "select convert(varchar,trndate,103) as trnDate,name,trnno,amount, \r\n case when discamount=0 then \r\n (select SUM(itemDiscountAmount)       \r\n from salesbilldetail  \r\n join vw_itemCodebarCode AS itemmst on itemmst.itemcode=salesbilldetail.itemcode  \r\n and itemmst.companycode=salesbilldetail.companycode  \r\n where trnno=vw_salesbill_main.trnno and salesbilldetail.companycode='" + mdl_public_variables.companycode + "' and salesbilldetail.yearcode='" + mdl_public_variables.yearcode + "'and billType = vw_salesbill_main.billType) \r\n else discamount end discamount, \r\n surcharge_amount,netamount,salestype,ratename, \r\n shopname,ledgercode,storecode,ratecode,date,trntime,trnid,discount_reason, \r\n case when billtype=0 then 'FL' when billType = '1' then 'CS' else 'NAI' end as BillType,billType  \r\n,vw_salesbill_main.referencebillNo,vw_salesbill_main.referencebilltype\r\n from vw_salesbill_main  \r\n where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "'  \r\n order by convert(datetime,trnDate) DESC ,cast(trnno as integer) desc ";
			}
			else if (mdl_public_variables.count == 16)
			{
				s = "select convert(varchar(10),trndate,103) as trndate,trnno,billno,tp_pass_no,shopname,MasterAccountsLedger.ledgerName as name,narration,breakagemain.shopcode,MasterAccountsLedger.ledgercode,breakagemain.companycode,yearcode,trndate as date  \r\n from breakagemain  \r\n join storage on breakagemain.shopcode=storage.shopcode and breakagemain.companycode=storage.companycode  \r\n join MasterAccountsLedger on breakagemain.ledgercode=MasterAccountsLedger.ledgerCode and breakagemain.companycode=MasterAccountsLedger.companycode  \r\n where breakagemain.companycode='" + mdl_public_variables.companycode + "' and breakagemain.yearcode='" + mdl_public_variables.yearcode + "'  \r\n order by cast(trnno as integer)  desc ";
			}
			else
			{
				if (mdl_public_variables.count == 20)
				{
					return;
				}
				if (mdl_public_variables.count == 21)
				{
					s = "select usercode,username,accesslevel,password from users where usercode!='A00001'";
				}
				else if (mdl_public_variables.count == 22)
				{
					s = "select distinct users.usercode,users.username,userrights.companycode,companymast.companyname,users.accesslevel,userrights.accaccess from userrights join users on users.usercode=userrights.usercode join companymast on companymast.companycode=userrights.companycode where users.accesslevel<>'Admin' and userrights.usercode <>'A00001'";
				}
				else if (mdl_public_variables.count == 23)
				{
					s = "select purchasemain.trnno,MasterAccountsLedger.ledgerName,CONVERT(varchar(10),trndate,103) as trndate,docno,tppassno,ptype,totnetamt,billType [Bill Type]  \r\n from purchasemain join  MasterAccountsLedger on MasterAccountsLedger.companyCode=purchasemain.companycode \r\n and MasterAccountsLedger.ledgerCode=purchasemain.suppliercode \r\n where purchasemain.companycode='" + mdl_public_variables.companycode + "' and purchasemain.yearcode = '" + mdl_public_variables.yearcode + "'  \r\n order by cast(purchasemain.trnno as integer)  desc ";
				}
				else if (mdl_public_variables.count == 24)
				{
					s = "select distinct taxdetail.companycode,companymast.companyname,schemecode,taxdetail.schemename from taxdetail join companymast on companymast.companycode=taxdetail.companycode where taxdetail.companycode='" + mdl_public_variables.companycode + "'";
				}
				else if (mdl_public_variables.count == 25)
				{
					s = "select companycode,yearcode,trnno,trndate,shopname_from,shopname_to,shopcode_frm,shopcode_to,trndate as date from stk_transfer_main where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "' order by cast(trnno as integer)  desc";
				}
				else if (mdl_public_variables.count == 26)
				{
					s = "SELECT TransactionMain.VchDate AS [Vch Date], TransactionMain.TrnType AS [Vch Type], TransactionMain.TrnNo AS [Vch No],   MasterAccountsLedger.ledgerName AS Particulars, TransactionDetail.TrnAmount AS Amount,   CASE WHEN TransactionDetail.[TrnEffect] = - 1 THEN 'Debit' ELSE 'Credit' END AS 'Debit-Credit', TransactionMain.IndexId, case when TransactionMain.ReceiptType  = 'KOTRECEIPT' then CONVERT(bit,0) else CONVERT(bit,1) end as EditDelete  FROM TransactionDetail LEFT OUTER JOIN  MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND   TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode LEFT OUTER JOIN  TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND   TransactionDetail.restaurantCode = TransactionMain.restaurantCode And TransactionDetail.IndexId = TransactionMain.IndexId  WHERE (TransactionMain.companycode = '" + mdl_public_variables.companycode + "') AND (TransactionMain.yearcode = '" + mdl_public_variables.yearcode + "') AND (TransactionMain.TrnType = 'RECEIPT') AND (TransactionDetail.SerialId = 1)  ORDER BY [Vch Date] desc, [Vch No] desc ";
				}
				else if (mdl_public_variables.count == 27)
				{
					s = "SELECT TransactionMain.VchDate AS [Vch Date], TransactionMain.TrnType AS [Vch Type], TransactionMain.TrnNo AS [Vch No],   MasterAccountsLedger.ledgerName AS Particulars, TransactionDetail.TrnAmount AS Amount,   CASE WHEN TransactionDetail.[TrnEffect] = - 1 THEN 'Debit' ELSE 'Credit' END AS 'Debit-Credit', TransactionMain.IndexId  FROM TransactionDetail LEFT OUTER JOIN  MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND   TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode LEFT OUTER JOIN  TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND   TransactionDetail.restaurantCode = TransactionMain.restaurantCode And TransactionDetail.IndexId = TransactionMain.IndexId  WHERE     (TransactionMain.companycode = '" + mdl_public_variables.companycode + "') AND (TransactionMain.yearcode = '" + mdl_public_variables.yearcode + "') AND (TransactionMain.TrnType = 'PAYMENT') AND (TransactionDetail.SerialId = 1)  ORDER BY [Vch Date] desc , [Vch No] desc ";
				}
				else if (mdl_public_variables.count == 28)
				{
					s = "SELECT TransactionMain.VchDate AS [Vch Date], TransactionMain.TrnType AS [Vch Type], TransactionMain.TrnNo AS [Vch No],   MasterAccountsLedger.ledgerName AS Particulars, TransactionDetail.TrnAmount AS Amount,   CASE WHEN TransactionDetail.[TrnEffect] = - 1 THEN 'Debit' ELSE 'Credit' END AS 'Debit-Credit', TransactionMain.IndexId  FROM TransactionDetail LEFT OUTER JOIN  MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND   TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode LEFT OUTER JOIN  TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND   TransactionDetail.restaurantCode = TransactionMain.restaurantCode And TransactionDetail.IndexId = TransactionMain.IndexId  WHERE (TransactionMain.companycode = '" + mdl_public_variables.companycode + "') AND (TransactionMain.yearcode = '" + mdl_public_variables.yearcode + "') AND (TransactionMain.TrnType = 'CONTRA') AND (TransactionDetail.SerialId = 1)  ORDER BY [Vch Date] desc, [Vch No] desc ";
				}
				else if (mdl_public_variables.count == 29)
				{
					s = "SELECT TransactionMain.VchDate AS [Vch Date], TransactionMain.TrnType AS [Vch Type], TransactionMain.TrnNo AS [Vch No],  MasterAccountsLedger.ledgerName AS Particulars, ABS(SUM(TransactionDetail.TrnAmount * TransactionDetail.TrnEffect)) AS Amount,   CASE WHEN SIGN(SUM(TransactionDetail.TrnAmount * TransactionDetail.TrnEffect)) = - 1 THEN 'Debit' ELSE 'Credit' END AS 'Debit-Credit', TransactionMain.IndexId  FROM TransactionDetail LEFT OUTER JOIN  MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND   TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode LEFT OUTER JOIN  TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND   TransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId  WHERE (TransactionMain.companycode = '" + mdl_public_variables.companycode + "') AND (TransactionMain.yearcode = '" + mdl_public_variables.yearcode + "') AND (TransactionDetail.SerialId = 1)  GROUP BY TransactionMain.VchDate, TransactionMain.TrnType, TransactionMain.TrnNo, MasterAccountsLedger.ledgerName, TransactionMain.IndexId  HAVING (TransactionMain.TrnType = 'JOURNAL')  ORDER BY [Vch Date] desc, [Vch No] desc ";
				}
