		private void userset()
		{
			if (mdl_public_variables.uadmin)
			{
				((ToolStripItem)bt_add).Enabled = true;
				((ToolStripItem)bt_edit).Enabled = true;
				((ToolStripItem)bt_delet).Enabled = true;
				if (mdl_public_variables.count == 54)
				{
					((ToolStripItem)bt_add).Visible = false;
					((ToolStripItem)bt_edit).Visible = false;
					((ToolStripItem)bt_delet).Visible = false;
					((Control)bt_upload).Visible = true;
					((Control)bt_show).Visible = true;
					((Control)dtp1).Visible = true;
				}
				else
				{
					((ToolStripItem)bt_add).Visible = true;
					((ToolStripItem)bt_edit).Visible = true;
					((ToolStripItem)bt_delet).Visible = true;
					((Control)bt_upload).Visible = false;
					((Control)bt_show).Visible = false;
					((Control)dtp1).Visible = false;
				}
			}
			else
			{
				s = "select pera,pere,perd from userrights where companycode='" + mdl_public_variables.companycode + "' and usercode='" + mdl_public_variables.usercode + "' and modulename like'%" + ((ToolStripItem)tsl_tittle).Text + "%'";
				DataSet dataSet = ob.populate(s);
				if (dataSet.Tables[0].Rows.Count > 0)
				{
					if (Operators.CompareString(dataSet.Tables[0].Rows[0][0].ToString(), "True", false) == 0)
					{
						((ToolStripItem)bt_add).Enabled = true;
					}
					if (Operators.CompareString(dataSet.Tables[0].Rows[0][1].ToString(), "True", false) == 0)
					{
						((ToolStripItem)bt_edit).Enabled = true;
					}
					if (Operators.CompareString(dataSet.Tables[0].Rows[0][2].ToString(), "True", false) == 0)
					{
						((ToolStripItem)bt_delet).Enabled = true;
					}
				}
			}
			if ((mdl_public_variables.count == 14) | (mdl_public_variables.count == 11))
			{
				((ToolStripItem)bt_add).Enabled = false;
				((ToolStripItem)bt_delet).Enabled = false;
				if (mdl_public_variables.count == 11)
				{
					((ToolStripItem)bt_edit).Enabled = false;
				}
			}
		}

