		private void gridsearch_Load(object sender, EventArgs e)
		{
			s = "SELECT itemcode,itemname,barcode,packing,ml,salesrate,kflmst.kflname,itemmst.strengthname   \r\n FROM itemmst  \r\n INNER JOIN kflmst ON itemmst.companycode = kflmst.companycode AND itemmst.kflcode = kflmst.kflcode   \r\n WHERE itemmst.itemname LIKE'%' AND itemmst.companycode='" + mdl_public_variables.companycode + "'  \r\n UNION ALL \r\n SELECT itemCode,itemName,barCode,naiUnitMaster.bulkQnty,naiUnitMaster.basicQnty,salesRate,'NAI' AS kflname,'NO' AS strengthname \r\n FROM naiItemMaster \r\n LEFT JOIN naiUnitMaster ON naiItemMaster.companyCode = naiUnitMaster.companyCode  \r\n AND naiItemMaster.unitCode = naiUnitMaster.unitCode   \r\n WHERE naiItemMaster.itemName LIKE'%' AND naiItemMaster.companycode='" + mdl_public_variables.companycode + "' ";
			data_table.Rows.Clear();
			data_table = ob.populate2(s);
			data_table.TableName = "ItemDetails";
			dv_Item.Table = data_table;
			((Control)TextBox1).TextChanged -= TextBox1_TextChanged;
			TextBox1.Text = string.Empty;
			((Control)TextBox1).TextChanged += TextBox1_TextChanged;
			TextBox1.Text = searchText;
			((Control)mdl_public_variables.countersales.dgv_items).Enabled = false;
		}

