		private void UpdateItemBarcode(string barCode, int rowNo)
		{
			if (Operators.ConditionalCompareObjectNotEqual(dv_Item.ToTable().Rows[rowNo]["barcode"], DataGridView1["barcode", rowNo].Value, false))
			{
				if (ob.populate(Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)string.Concat(string.Concat(string.Concat("select barcode from itemmst where companycode='" + mdl_public_variables.companycode, "' and barcode = '"), barCode), "' AND itemcode <> '"), dv_Item.ToTable().Rows[rowNo]["itemcode"]), (object)"'"))).Tables[0].Rows.Count > 0)
				{
					FillGrid();
					((Control)TextBox1).Select();
					return;
				}
				s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)string.Concat(string.Concat(string.Concat("update itemmst set barcode = '" + barCode, "' where companycode = '"), mdl_public_variables.companycode), "' AND itemcode = '"), dv_Item.ToTable().Rows[rowNo]["itemcode"]), (object)"'"));
				ob.insert(s);
				searchText = TextBox1.Text;
				GridSerachReload();
				TextBox1.Text = searchText;
			}
		}
