			//IL_0150: Unknown result type (might be due to invalid IL or missing references)
			//IL_03ce: Unknown result type (might be due to invalid IL or missing references)
			//IL_03d8: Expected O, but got Unknown
			if (Operators.CompareString(txt_name.Text, "", false) == 0)
			{
				Interaction.MsgBox((object)"Please enter the Item name then brows picture.", (MsgBoxStyle)64, (object)null);
				return;
			}
			((FileDialog)OpenFileDialogItem).AddExtension = true;
			((FileDialog)OpenFileDialogItem).DefaultExt = ".bmp";
			((FileDialog)OpenFileDialogItem).Title = "Select Picture For Item";
			DialogResult val = ((CommonDialog)OpenFileDialogItem).ShowDialog();
			if ((int)val != 1)
			{
				return;
			}
			if (computerName.Contains(((ServerComputer)MyProject.Computer).Name.ToString()))
			{
				mdl_itemmst.itemImgUrl = Application.StartupPath + "\\ItemImage";
				if (!Directory.Exists(mdl_itemmst.itemImgUrl))
				{
					Directory.CreateDirectory(mdl_itemmst.itemImgUrl);
					List<SharePermissionEntry> list = new List<SharePermissionEntry>();
					SharePermissionEntry item = new SharePermissionEntry(string.Empty, "Everyone", SharedFolder.SharePermissions.FullControl, AlloworDenyPermission: true);
					SharePermissionEntry item2 = new SharePermissionEntry(Environment.UserDomainName, Environment.UserName, SharedFolder.SharePermissions.FullControl, AlloworDenyPermission: true);
					list.Add(item2);
					list.Add(item);
					SharedFolder.NET_API_STATUS nET_API_STATUS = SharedFolder.ShareExistingFolder("ItemImage", "Menu Images Access For Madhushala Outlet package", mdl_itemmst.itemImgUrl, list);
					if (nET_API_STATUS != 0)
					{
						MessageBox.Show("Share was not created as the following error was returned: " + nET_API_STATUS.ToString() + ", you can not access this picture from client Computer");
					}
				}
				mdl_itemmst.itemImgUrl = mdl_itemmst.itemImgUrl + "\\" + Strings.Trim(txt_name.Text).Replace("\\", "").Replace(".", "")
					.Replace("/", "")
					.Replace("'", "") + ".png";
				menuPicture = (Bitmap)((Control)PictureBox_itemImgUpload).BackgroundImage;
				if (menuPicture != null)
				{
					((Image)menuPicture).Dispose();
					((Control)PictureBox_itemImgUpload).BackgroundImage = null;
				}
				if (File.Exists(mdl_itemmst.itemImgUrl))
				{
					try
					{
						File.Delete(mdl_itemmst.itemImgUrl);
					}
					catch (Exception ex)
					{
						ProjectData.SetProjectError(ex);
						Exception ex2 = ex;
						ProjectData.ClearProjectError();
					}
				}
				try
				{
					File.Copy(((FileDialog)OpenFileDialogItem).FileName, mdl_itemmst.itemImgUrl, overwrite: false);
				}
				catch (Exception ex3)
				{
					ProjectData.SetProjectError(ex3);
					Exception ex4 = ex3;
					ProjectData.ClearProjectError();
				}
				menuPicture = new Bitmap(mdl_itemmst.itemImgUrl);
				((Control)PictureBox_itemImgUpload).BackgroundImage = (Image)(object)menuPicture;
				return;
			}
			mdl_itemmst.itemImgUrl = "\\\\" + computerName + "\\ItemImage\\";
			ClientAccessCredentialOpen();
			try
			{
				if (!Directory.Exists(mdl_itemmst.itemImgUrl))
				{
					Interaction.MsgBox((object)"Sorry image path is not exist you can not add any image, please contact software vendor.", (MsgBoxStyle)64, (object)null);
					mdl_itemmst.itemImgUrl = "";
					ClientAccessCredentialClose();
					return;
				}
			}
			catch (Exception ex5)
			{
				ProjectData.SetProjectError(ex5);
				Exception ex6 = ex5;
				ProjectData.ClearProjectError();
			}
			try
			{
				mdl_itemmst.itemImgUrl += Strings.Trim(txt_name.Text).Replace("\\", "").Replace(".", "")
					.Replace("/", "")
					.Replace("'", "");
				if (menuPicture != null)
				{
					((Control)PictureBox_itemImgUpload).BackgroundImage = null;
					((Image)menuPicture).Dispose();
				}
				if (File.Exists(mdl_itemmst.itemImgUrl))
				{
					File.Delete(mdl_itemmst.itemImgUrl);
				}
				if (Operators.CompareString(computerName, "", false) != 0)
				{
					File.Copy(((FileDialog)OpenFileDialogItem).FileName, mdl_itemmst.itemImgUrl, overwrite: false);
					menuPicture = new Bitmap(mdl_itemmst.itemImgUrl);
					((Control)PictureBox_itemImgUpload).BackgroundImage = (Image)(object)menuPicture;
				}
			}
			catch (Exception ex7)
			{
				ProjectData.SetProjectError(ex7);
				Exception ex8 = ex7;
				ProjectData.ClearProjectError();
			}
			ClientAccessCredentialClose();
		}

		private bool ClientAccessCredentialOpen()
		{
			string username = ConfigurationManager.AppSettings["DomainName"];
			string password = ConfigurationManager.AppSettings["DomainPassword"];
			Impersonator = new Impersonator(username, password);
			bool result;
			try
			{
				Impersonator.BeginImpersonation();
				result = true;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				result = false;
				ProjectData.ClearProjectError();
			}
			return result;
		}

		private void ClientAccessCredentialClose()
		{
			try
			{
				Impersonator.EndImpersonation();
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
		}
	}
