		public void formLoad(object sender, string openType)
		{
			((Form)this).Text = openType;
			transactionType = openType;
			LastChequeNo = "";
			if (sender.GetType().ToString().Equals("System.String"))
			{
				loadType = "Add";
				((Control)this).Show();
			}
			else
			{
				loadType = "Edit";
				editablePortion = RuntimeHelpers.GetObjectValue(sender);
				((Control)this).Show();
			}
		}

		private void frm_journal_vch_Load(object sender, EventArgs e)
		{
			if (Operators.CompareString(loadType, "Edit", false) == 0)
			{
				ob_journalEntry = (cls_journalEntry)editablePortion;
				ob_journalEntry.GetVchMinMaxDates(NewVch: false, "Journal");
				ob_journalEntry.SelectJournalDetails();
			}
			else
			{
				date_vouchar_new = DateAndTime.Today.Date;
				ob_journalEntry = new cls_journalEntry();
				ob_journalEntry.GetVchMinMaxDates(NewVch: true, "Journal");
			}
			if (mdl_public_variables.VoucharDateLock)
			{
				dtp1.MaxDate = ob_journalEntry.getVchMaxDate();
				dtp1.MinDate = ob_journalEntry.getVchMinDate();
			}
			frmvch_load();
			((Control)dtp1).Select();
			editmode = false;
			((ToolStripItem)tsl_Title).Text = ((Form)this).Text;
		}

