		private void currbal_calc()
		{
			currbal = "Current Bal: ";
			cash_bank_code = Conversions.ToString(ds1.Tables[0].Rows[cmb_account.SelectedIndex][0]);
			cas_bank = Conversions.ToDouble(ds1.Tables[0].Rows[cmb_account.SelectedIndex][2]);
			checked
			{
				if (dgv1.Rows.Count > 0)
				{
					int num = dgv1.Rows.Count - 1;
					int num2 = 0;
					while (true)
					{
						int num3 = num2;
						int num4 = num;
						if (num3 > num4)
						{
							break;
						}
						if (Operators.ConditionalCompareObjectEqual(dgv1[6, num2].Value, (object)cash_bank_code, false))
						{
							cas_bank += Conversion.Val(dgv1[11, num2].Value.ToString()) - Conversion.Val(dgv1[12, num2].Value.ToString());
						}
						num2++;
					}
				}
				if (cmb_by_to.SelectedIndex == 0)
				{
					cas_bank += Conversion.Val(txt_amount.Text);
				}
				else
				{
					cas_bank -= Conversion.Val(txt_amount.Text);
				}
				if (cas_bank > 0.0)
				{
					currbal = currbal + cas_bank + " Cr.   ";
				}
				else
				{
					currbal = currbal + Math.Abs(cas_bank) + " Dr.   ";
				}
			}
		}

