		private void calc()
		{
			totdr = 0.0;
			totcr = 0.0;
			checked
			{
				int num = dgv1.Rows.Count - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					totdr += Conversion.Val(RuntimeHelpers.GetObjectValue(dgv1[11, num2].Value));
					totcr += Conversion.Val(RuntimeHelpers.GetObjectValue(dgv1[12, num2].Value));
					num2++;
				}
				txt_totdebit.Text = "Dr. " + totdr;
				txt_totcredit.Text = "Cr. " + totcr;
				txt_amount.Text = Conversions.ToString(0);
				txt_chq.Text = "";
				cmb_account.SelectedIndex = 0;
				dtp2.Value = DateTime.Today.Date;
				if (Operators.CompareString(Strings.Format((object)totcr, "0.00"), Strings.Format((object)totdr, "0.00"), false) != 0)
				{
					if (totcr > totdr)
					{
						cmb_by_to.SelectedIndex = 1;
					}
					else if (totdr > totcr)
					{
						cmb_by_to.SelectedIndex = 0;
					}
					((Control)panel_entry).Visible = true;
					((Control)cmb_by_to).Select();
				}
				else
				{
					((Control)txt_nar).Enabled = true;
					((Control)txt_nar).Select();
				}
			}
		}

