		public void frmLoad(string documentType, ReportDocument[] crptDocument, int copies, string restaurantCode, ref object kotwindow, PrinterSettings[] PrinterSettings, PageSettings pageSettings)
		{
			//IL_00c0: Unknown result type (might be due to invalid IL or missing references)
			((Control)this).Height = 180;
			((Control)this).Width = 350;
			((Control)tsb_setDefault).Visible = false;
			printcount = checked(crptDocument.Length - 1);
			try
			{
				myKotWindow = RuntimeHelpers.GetObjectValue(kotwindow);
				myDocumentType = documentType;
				myCrtDocument = crptDocument;
				myCopies = copies;
				myrestaurantCode = restaurantCode;
				myPrinter = PrinterSettings;
				myPage = pageSettings;
				txt_copies1.Text = Conversions.ToString(myCopies);
				((Control)tsb_setDefault).Visible = false;
				((Form)this).Text = " Print";
				((ButtonBase)tsb_print2).Text = "&Print";
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				Interaction.MsgBox((object)ex2.ToString(), (MsgBoxStyle)0, (object)null);
				ProjectData.ClearProjectError();
			}
			((Control)this).Show();
		}

		public void frmLoad(string documentType, ReportDocument crptDocument, int copies, string restaurantCode, ref object kotwindow, PrinterSettings[] PrinterSettings, PageSettings pageSettings)
		{
			((Control)this).Height = 180;
			((Control)this).Width = 350;
			((Control)tsb_setDefault).Visible = false;
			printcount = 1;
			myKotWindow = RuntimeHelpers.GetObjectValue(kotwindow);
			myDocumentType = documentType;
			myCrtDocument = (ReportDocument[])Utils.CopyArray((Array)myCrtDocument, (Array)new ReportDocument[1]);
			myCrtDocument[0] = crptDocument;
			myCopies = copies;
			myrestaurantCode = restaurantCode;
			myPrinter = PrinterSettings;
			myPage = pageSettings;
			txt_copies1.Text = Conversions.ToString(myCopies);
			((Control)tsb_setDefault).Visible = false;
			((Form)this).Text = " Print";
			((ButtonBase)tsb_print2).Text = "&Print";
			((Control)this).Show();
		}

