		private void tsb1_Click(object sender, EventArgs e)
		{
			checked
			{
				int num = myCrtDocument.Length - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					print(num2);
					num2++;
				}
				((Form)this).Close();
			}
		}

		private void RemoveArrayItem(int rowNum)
		{
			checked
			{
				int num = printcount - 2;
				int num2 = rowNum;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					myCrtDocument[num2] = myCrtDocument[num2 + 1];
					myPrinter[num2] = myPrinter[num2 + 1];
					num2++;
				}
				printcount--;
				myCrtDocument = (ReportDocument[])Utils.CopyArray((Array)myCrtDocument, (Array)new ReportDocument[printcount - 1 + 1]);
				myPrinter = (PrinterSettings[])Utils.CopyArray((Array)myPrinter, (Array)new PrinterSettings[printcount - 1 + 1]);
			}
		}

		private void print(int i)
		{
			try
			{
				myPrinter[i].Copies = checked((short)(myCopies - 1));
				myCrtDocument[i].PrintToPrinter(myPrinter[i], myPage, false);
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
		}

		private void tsb2_Click(object sender, EventArgs e)
		{
			preview();
			((Control)Panel1).Visible = false;
			((ToolStripItem)tsb_print1).Visible = false;
			((ToolStripItem)tsb_preview).Visible = false;
			((ToolStripItem)tsb_cancel).Visible = true;
			((Control)this).Height = 700;
			((Control)this).Width = 1000;
			((Control)this).Top = 10;
			((Control)this).Left = checked((int)Math.Round((double)(((Computer)MyProject.Computer).Screen.Bounds.Width - ((Control)this).Width) / 2.0));
			((Control)tsb_print2).Select();
		}

