		private void txt_copies1_KeyPress(object sender, KeyPressEventArgs e)
		{
			switch (e.KeyChar)
			{
			case '\b':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				return;
			}
			e.Handled = true;
		}

		private void txt_copies1_KeyUp(object sender, KeyEventArgs e)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			//IL_0009: Invalid comparison between Unknown and I4
			if ((int)e.KeyData == 13)
			{
				((ToolStripItem)tsb_print1).Select();
				return;
			}
			if ((double)myCopies != Conversions.ToDouble(txt_copies1.Text))
			{
				((Control)tsb_print2).Visible = true;
			}
			txt_copies2.Text = txt_copies1.Text;
			myCopies = Conversions.ToInteger(txt_copies1.Text);
		}

