		private void tsb5_Click(object sender, EventArgs e)
		{
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			if (Conversion.Val(txt_copies1.Text) < 1.0)
			{
				Interaction.MsgBox((object)"Copies can not be less than 1", (MsgBoxStyle)0, (object)null);
				txt_copies1.Text = Conversions.ToString(1);
				((Control)txt_copies1).Select();
				return;
			}
			try
			{
				cls_DataAccess cls_DataAccess2 = new cls_DataAccess();
				string s = ((Operators.CompareString(myDocumentType, "KOT/BOT", false) != 0) ? ("update restaurantMaster set billCopies='" + txt_copies1.Text + "' where companyCode='" + mdl_public_variables.companycode + "' and restaurantCode='" + myrestaurantCode + "'") : ("update restaurantMaster set KotCopies='" + txt_copies1.Text + "' where companyCode='" + mdl_public_variables.companycode + "' and restaurantCode='" + myrestaurantCode + "'"));
				cls_DataAccess2.insert(s);
				NewLateBinding.LateCall(myKotWindow, (Type)null, "restaurantDetailLoad", new object[0], (string[])null, (Type[])null, (bool[])null, true);
				((Control)tsb_setDefault).Visible = false;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
