		public void formLoad(object sender, string openType, object openBy = null)
		{
			//IL_008f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0079: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Expected O, but got Unknown
			((Form)this).Text = openType;
			transactionType = openType;
			openByWhome = RuntimeHelpers.GetObjectValue(openBy);
			if (sender.GetType().ToString().Equals("System.String"))
			{
				loadType = "Add";
			}
			else
			{
				loadType = "Edit";
				editablePortion = RuntimeHelpers.GetObjectValue(sender);
				((Control)this).Show();
			}
			if (myParentForm != null)
			{
				((Form)this).MdiParent = (Form)myParentForm;
				((Control)this).Show();
			}
			else
			{
				((Form)this).ShowDialog();
			}
		}

		private void frm_ledger_FormClosing(object sender, FormClosingEventArgs e)
		{
			if (openByWhome != null && Operators.ConditionalCompareObjectEqual(NewLateBinding.LateGet(openByWhome, (Type)null, "Name", new object[0], (string[])null, (Type[])null, (bool[])null), (object)"frm_purchase", false))
			{
				((frm_purchase)openByWhome).DataLoadInCombo();
			}
		}

		private void frm_ledger_Load(object sender, EventArgs e)
		{
			if (Operators.CompareString(transactionType, "Ledger Master", false) == 0)
			{
				((Control)txt_LockAmount).Visible = true;
				((Control)GroupBoxLockEffect).Visible = true;
				string s = "SELECT AccGroupCode, AccGroupName, CreditEffects, ShortCode FROM  MasterAccountsGroups WHERE (companyCode = '" + mdl_public_variables.companycode + "') AND (Hidden = 0) ORDER BY AccGroupName";
				ds = ob_dataAccess.populate(s);
				ob_dataAccess.combofill(ds.Tables[0], cmb_accGroup);
				if (Operators.CompareString(loadType, "Edit", false) == 0)
				{
					ledgerMasterEditLoad();
				}
				((Control)rad_debit_male).TabIndex = 100;
				((Control)rad_credit_female).TabIndex = 200;
			}
			else if (Operators.CompareString(transactionType, "Customer Details", false) == 0)
			{
				((Control)txt_LockAmount).Visible = false;
				((Control)GroupBoxLockEffect).Visible = false;
				ds = ob_dataAccess.populate("SELECT ledgerCode, ledgerName FROM MasterAccountsLedger WHERE (companyCode = '" + mdl_public_variables.companycode + "') AND (Hidden = 0) ORDER BY ledgerName");
				cmb_accGroup.Items.Clear();
				ob_dataAccess.combofill(ds.Tables[0], cmb_accGroup);
				customerDetailsLoad();
			}
		}

		public void DataLoadInCombo()
		{
			if (Operators.CompareString(transactionType, "Ledger Master", false) == 0)
			{
				AccountSubGroupComboLoad();
			}
			else if (Operators.CompareString(transactionType, "Customer Details", false) == 0)
			{
				ledgerComboLoad();
			}
		}

		private void AccountSubGroupComboLoad()
		{
			cmb_accGroup.SelectedIndex = -1;
			cmb_accGroup.Items.Clear();
			string s = "SELECT AccGroupCode, AccGroupName, CreditEffects, ShortCode FROM  MasterAccountsGroups WHERE (companyCode = '" + mdl_public_variables.companycode + "') AND (Hidden = 0) ORDER BY AccGroupName";
			ds = ob_dataAccess.populate(s);
			ob_dataAccess.combofill(ds.Tables[0], cmb_accGroup);
		}

		private void ledgerComboLoad()
		{
			cmb_accGroup.SelectedIndex = -1;
			cmb_accGroup.Items.Clear();
			ds = ob_dataAccess.populate("SELECT ledgerCode, ledgerName FROM MasterAccountsLedger WHERE (companyCode = '" + mdl_public_variables.companycode + "') AND (Hidden = 0) ORDER BY ledgerName");
			ob_dataAccess.combofill(ds.Tables[0], cmb_accGroup);
		}

		private void ledgerMasterSave()
		{
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			//IL_05ec: Unknown result type (might be due to invalid IL or missing references)
			//IL_02cf: Unknown result type (might be due to invalid IL or missing references)
			if (cmb_accGroup.SelectedIndex < 0)
			{
				Interaction.MsgBox((object)"Please select Group for this ledger", (MsgBoxStyle)64, (object)null);
			}
			else if (Operators.CompareString(txt_name.Text, "", false) == 0)
			{
				Interaction.MsgBox((object)"Please type a ledger name for ledger creation.", (MsgBoxStyle)64, (object)null);
			}
			else if (Operators.CompareString(loadType, "Add", false) == 0)
			{
				cls_ledger cls_ledger2 = new cls_ledger();
				cls_ledger2.setAddr1(txt_add1.Text.ToUpper());
				cls_ledger2.setAddr2(txt_add2.Text.ToUpper());
				cls_ledger2.setArea(txt_area.Text.ToUpper());
				cls_ledger2.setCity(txt_city.Text.ToUpper());
				cls_ledger2.setContactNo(txt_contactNo.Text);
				cls_ledger2.setContactPerson(txt_person.Text.ToUpper());
				cls_ledger2.setDistrict(txt_district.Text.ToUpper());
				cls_ledger2.setFaxNo(txt_faxNo.Text);
				cls_ledger2.setGroupCode(Conversions.ToString(ds.Tables[0].Rows[cmb_accGroup.SelectedIndex][0]));
				cls_ledger2.setLedgerName(txt_name.Text.ToUpper());
				cls_ledger2.setbankName(txt_bankName.Text.ToUpper());
				cls_ledger2.setbranchName(txt_branchName.Text.ToUpper());
				cls_ledger2.setAccName(txt_accountNo.Text);
				cls_ledger2.setIFc(txt_IFCcode.Text.ToUpper());
				if (rad_credit_female.Checked)
				{
					cls_ledger2.setTrnEffect(1);
				}
				else
				{
					cls_ledger2.setTrnEffect(-1);
				}
				cls_ledger2.setMailId(txt_mail.Text.ToLower());
				cls_ledger2.setPan(txt_pan.Text);
				cls_ledger2.setPhn(txt_phone.Text);
				cls_ledger2.setState(txt_state.Text.ToUpper());
				cls_ledger2.setVat(txt_vat.Text);
				cls_ledger2.setWebSite(txt_www.Text);
				cls_ledger2.setBalance(Conversion.Val(txt_balance.Text));
				cls_ledger2.setLockAmount(Conversion.Val(txt_balance.Text));
				if (!RadioCredit.Checked)
				{
					cls_ledger2.setLockEffect(1);
				}
				else
				{
					cls_ledger2.setLockEffect(-1);
				}
				if (!cls_ledger2.checkLedgerName(1))
				{
					cls_ledger2.setShortCode(Conversions.ToString(ds.Tables[0].Rows[cmb_accGroup.SelectedIndex][3]));
					cls_ledger2.getNewLedgerCode();
					cls_ledger2.insertLedgerMaster();
					cls_ledger2.insertLedgerOpening();
					try
					{
						if (openByWhome == null)
						{
							refreshForm();
							return;
						}
						NewLateBinding.LateCall(openByWhome, (Type)null, "DataLoadInCombo", new object[0], (string[])null, (Type[])null, (bool[])null, true);
						((Form)this).Close();
						return;
					}
					catch (Exception ex)
					{
						ProjectData.SetProjectError(ex);
						Exception ex2 = ex;
						ProjectData.ClearProjectError();
						return;
					}
				}
				Interaction.MsgBox((object)"Ledger name already exist for this company, change ledger name", (MsgBoxStyle)0, (object)null);
			}
			else
			{
				ledgerdetails.setAddr1(txt_add1.Text.ToUpper());
				ledgerdetails.setAddr2(txt_add2.Text.ToUpper());
				ledgerdetails.setArea(txt_area.Text.ToUpper());
				ledgerdetails.setCity(txt_city.Text.ToUpper());
				ledgerdetails.setContactNo(txt_contactNo.Text);
				ledgerdetails.setContactPerson(txt_person.Text.ToUpper());
				ledgerdetails.setDistrict(txt_district.Text.ToUpper());
				ledgerdetails.setFaxNo(txt_faxNo.Text);
				ledgerdetails.setGroupCode(Conversions.ToString(ds.Tables[0].Rows[cmb_accGroup.SelectedIndex][0]));
				ledgerdetails.setLedgerName(txt_name.Text.ToUpper());
				if (rad_credit_female.Checked)
				{
					ledgerdetails.setTrnEffect(1);
				}
				else
				{
					ledgerdetails.setTrnEffect(-1);
				}
				ledgerdetails.setMailId(txt_mail.Text.ToLower());
				ledgerdetails.setPan(txt_pan.Text);
				ledgerdetails.setPhn(txt_phone.Text);
				ledgerdetails.setState(txt_state.Text.ToUpper());
				ledgerdetails.setVat(txt_vat.Text);
				ledgerdetails.setWebSite(txt_www.Text);
				ledgerdetails.setBalance(Conversion.Val(txt_balance.Text));
				ledgerdetails.setLockAmount(Conversion.Val(txt_LockAmount.Text));
				if (!RadioCredit.Checked)
				{
					ledgerdetails.setLockEffect(1);
				}
				else
				{
					ledgerdetails.setLockEffect(-1);
				}
				if (ledgerdetails.checkLedgerName(2))
				{
					Interaction.MsgBox((object)"Ledger name already exist for this company, change ledger name", (MsgBoxStyle)0, (object)null);
					return;
				}
				ledgerdetails.setbankName(txt_bankName.Text);
				ledgerdetails.setbranchName(txt_branchName.Text);
				ledgerdetails.setAccName(txt_accountNo.Text);
				ledgerdetails.setIFc(txt_IFCcode.Text);
				ledgerdetails.updateLedger();
				ledgerdetails.updateLedgerOpening();
				((Form)this).Close();
			}
		}

		private void ledgerMasterEditLoad()
		{
			ledgerdetails = new cls_ledger();
			ledgerdetails = (cls_ledger)editablePortion;
			ledgerdetails.selectLedgerDetails();
			txt_add1.Text = ledgerdetails.getAddr1();
			txt_add2.Text = ledgerdetails.getAddr2();
			txt_area.Text = ledgerdetails.getArea();
			txt_city.Text = ledgerdetails.getCity();
			txt_contactNo.Text = ledgerdetails.getContactNo();
			txt_district.Text = ledgerdetails.getDistrict();
			txt_faxNo.Text = ledgerdetails.getFaxNo();
			txt_mail.Text = ledgerdetails.getMailId();
			txt_name.Text = ledgerdetails.getLedgerName();
			txt_pan.Text = ledgerdetails.getPan();
			txt_person.Text = ledgerdetails.getContactPerson();
			txt_phone.Text = ledgerdetails.getPhn();
			txt_state.Text = ledgerdetails.getState();
			txt_vat.Text = ledgerdetails.getVat();
			txt_www.Text = ledgerdetails.getWebSite();
			txt_balance.Text = Conversions.ToString(ledgerdetails.getBalance());
			cmb_accGroup.SelectedItem = ledgerdetails.getGroupName();
			if (ledgerdetails.getTrnEffect() == -1)
			{
				rad_debit_male.Checked = true;
			}
			else
			{
				rad_credit_female.Checked = true;
			}
			txt_LockAmount.Text = Conversions.ToString(ledgerdetails.getLockAmount());
			if (ledgerdetails.getLockEffect() == -1)
			{
				RadioDebit.Checked = true;
			}
			else
			{
				RadioCredit.Checked = true;
			}
			txt_bankName.Text = ledgerdetails.getBankName();
			txt_branchName.Text = ledgerdetails.getBranchName();
			txt_accountNo.Text = ledgerdetails.getAccountNo();
			txt_IFCcode.Text = ledgerdetails.getIfcCode();
		}

