		private void customerDetailsLoad()
		{
			((Control)rad_corporate).Visible = true;
			((Control)lbl_person).Visible = false;
			((Control)lbl_group).Visible = false;
			((Control)lbl_balance).Visible = false;
			((Control)txt_person).Visible = false;
			((Control)cmb_accGroup).Visible = false;
			((Control)txt_balance).Visible = false;
			((Control)txt_pan).Visible = false;
			((Control)txt_www).Visible = false;
			((Control)lbl_dob).Visible = true;
			((Control)dtp_Dob).Visible = true;
			((Control)dtp_aniversory).Visible = true;
			((Control)dtp_firstVisitDate).Visible = true;
			((Control)dtp_LastVisit).Visible = true;
			((Control)txt_LockAmount).Visible = false;
			((Control)GroupBoxLockEffect).Visible = false;
			lbl_website.Text = "First Visit";
			lbl_pan.Text = "Disount Rate";
			lbl_vat.Text = "Visit Count";
			lbl_Fax.Text = "E-Mail";
			lbl_email.Text = "Last Visit";
			((Control)txt_mail).Visible = false;
			((ButtonBase)rad_credit_female).Text = "Male";
			((ButtonBase)rad_debit_male).Text = "Female";
			((Control)lbl_discount).Visible = true;
			((Control)txt_discount).Visible = true;
			if (Operators.CompareString(loadType, "Edit", false) != 0)
			{
				return;
			}
			((Control)lbl_discount).Visible = true;
			((Control)txt_discount).Visible = true;
			customerDetails = new cls_customer();
			customerDetails = (cls_customer)editablePortion;
			customerDetails.initilisationFromDatabase();
			txt_name.Text = customerDetails.getCustomerName();
			txt_add1.Text = customerDetails.getAddress1();
			txt_add2.Text = customerDetails.getAddress2();
			txt_area.Text = customerDetails.getPin();
			txt_city.Text = customerDetails.getCity();
			txt_contactNo.Text = customerDetails.getContactNo();
			txt_district.Text = customerDetails.getDistrict();
			txt_faxNo.Text = customerDetails.getMail();
			txt_phone.Text = customerDetails.getPhoneNo();
			txt_state.Text = customerDetails.getState();
			txt_vat.Text = customerDetails.getVisitingCount();
			dtp_aniversory.Value = Conversions.ToDate(customerDetails.getAniversory());
			if (Operators.CompareString(customerDetails.getDob().ToString(), "1/1/2050", false) == 0)
			{
				dtp_Dob.Value = DateTime.Today;
			}
			else
			{
				dtp_Dob.Value = Conversions.ToDate(customerDetails.getDob());
			}
			dtp_firstVisitDate.Value = Conversions.ToDate(customerDetails.getFirstVisit());
			dtp_LastVisit.Value = Conversions.ToDate(customerDetails.getLastVisit());
			txt_discount.Text = Conversions.ToString(customerDetails.getDiscountRate());
			if (Operators.CompareString(customerDetails.getSex(), "Male", false) == 0)
			{
				rad_credit_female.Checked = true;
				return;
			}
			if (Operators.CompareString(customerDetails.getSex(), "Female", false) == 0)
			{
				rad_debit_male.Checked = true;
				return;
			}
			rad_corporate.Checked = true;
			if (Operators.CompareString(customerDetails.getLedgerCode(), (string)null, false) != 0)
			{
				EnumerableRowCollection<object> source = from p in ds.Tables[0].AsEnumerable()
					where Operators.ConditionalCompareObjectEqual(p[0], (object)customerDetails.getLedgerCode(), false)
					select p[1];
				if (source.Count() > 0)
				{
					cmb_accGroup.SelectedItem = source.ElementAtOrDefault(0).ToString();
				}
			}
		}

		private void customerDetilsSave()
		{
			if (Operators.CompareString(loadType, "Add", false) == 0)
			{
				customerDetails = new cls_customer();
				customerDetails.setCustomerName(txt_name.Text.ToUpper());
				customerDetails.setAddrress1(txt_add1.Text.ToUpper());
				customerDetails.setAddress2(txt_add2.Text.ToUpper());
				customerDetails.setAniversoryDate(mdl_public_variables.convertDateFormat(dtp_aniversory.Value.Date));
				customerDetails.setCity(txt_city.Text.ToUpper());
				customerDetails.setCustomerNo(txt_contactNo.Text);
				customerDetails.setDob(mdl_public_variables.convertDateFormat(dtp_Dob.Value.Date));
				customerDetails.setEmail(txt_faxNo.Text);
				customerDetails.setFirstVisitDate(mdl_public_variables.convertDateFormat(dtp_firstVisitDate.Value.Date));
				customerDetails.setLastVisitDate(mdl_public_variables.convertDateFormat(dtp_LastVisit.Value.Date));
				customerDetails.setPhnNo(txt_phone.Text);
				customerDetails.setPin(txt_area.Text.ToUpper());
				if (rad_credit_female.Checked)
				{
					customerDetails.setSex("Male");
				}
				else if (rad_debit_male.Checked)
				{
					customerDetails.setSex("Female");
				}
				else
				{
					if (cmb_accGroup.SelectedIndex >= 0)
					{
						customerDetails.setLedgerCode(Conversions.ToString(ds.Tables[0].Rows[cmb_accGroup.SelectedIndex][0]));
					}
					customerDetails.setSex("Corporate");
				}
				customerDetails.setState(txt_state.Text.ToUpper());
				customerDetails.setVisitingCount(checked((int)Math.Round(Conversion.Val(txt_vat.Text))));
				customerDetails.setDistrict(txt_district.Text.ToUpper());
				customerDetails.setDiscountRate(Conversion.Val(txt_discount.Text));
				customerDetails.getNewCustomerCode();
				customerDetails.insertCustomerDetails();
				refreshForm();
				return;
			}
			customerDetails.setCustomerName(txt_name.Text.ToUpper());
			customerDetails.setAddrress1(txt_add1.Text.ToUpper());
			customerDetails.setAddress2(txt_add2.Text.ToUpper());
			customerDetails.setAniversoryDate(mdl_public_variables.convertDateFormat(dtp_aniversory.Value.Date));
			customerDetails.setCity(txt_city.Text.ToUpper());
			customerDetails.setCustomerNo(txt_contactNo.Text);
			if (DateTime.Compare(dtp_Dob.Value.Date, DateTime.Today) == 0)
			{
				customerDetails.setDob("1/1/2050");
			}
			else
			{
				customerDetails.setDob(mdl_public_variables.convertDateFormat(dtp_Dob.Value.Date));
			}
			customerDetails.setEmail(txt_faxNo.Text);
			customerDetails.setFirstVisitDate(mdl_public_variables.convertDateFormat(dtp_firstVisitDate.Value.Date));
			customerDetails.setLastVisitDate(mdl_public_variables.convertDateFormat(dtp_LastVisit.Value.Date));
			customerDetails.setPhnNo(txt_phone.Text.ToUpper());
			customerDetails.setPin(txt_area.Text.ToUpper());
			customerDetails.setLedgerCode("");
			if (rad_credit_female.Checked)
			{
				customerDetails.setSex("Male");
			}
			else if (rad_debit_male.Checked)
			{
				customerDetails.setSex("Female");
			}
			else
			{
				if (cmb_accGroup.SelectedIndex >= 0)
				{
					customerDetails.setLedgerCode(Conversions.ToString(ds.Tables[0].Rows[cmb_accGroup.SelectedIndex][0]));
				}
				customerDetails.setSex("Corporate");
			}
			customerDetails.setState(txt_state.Text.ToUpper());
			customerDetails.setVisitingCount(Conversions.ToInteger(txt_vat.Text.ToUpper()));
			customerDetails.setDistrict(txt_district.Text.ToUpper());
			customerDetails.setDiscountRate(Conversion.Val(txt_discount.Text));
			customerDetails.updateCustomerDetails();
			((Form)this).Close();
		}

