		private void cmb_accGroup_SelectedIndexChanged(object sender, EventArgs e)
		{
			if (cmb_accGroup.SelectedIndex <= -1)
			{
				return;
			}
			if (cmb_accGroup.Text.Contains("CREDITOR") | cmb_accGroup.Text.Contains("DEBTOR"))
			{
				((Control)grp_bankDetails).Visible = true;
				txt_bankName.Text = "";
				txt_branchName.Text = "";
				txt_IFCcode.Text = "";
				txt_accountNo.Text = "";
			}
			else
			{
				((Control)grp_bankDetails).Visible = false;
			}
			if (Operators.CompareString(transactionType, "Ledger Master", false) != 0)
			{
				return;
			}
			if (Operators.ConditionalCompareObjectEqual(ds.Tables[0].Rows[cmb_accGroup.SelectedIndex][2], (object)1, false))
			{
				rad_credit_female.Checked = true;
				if (Operators.CompareString(loadType, "Add", false) == 0)
				{
					RadioCredit.Checked = true;
				}
			}
			else
			{
				rad_debit_male.Checked = true;
				if (Operators.CompareString(loadType, "Add", false) == 0)
				{
					RadioDebit.Checked = true;
				}
			}
		}

		private void txt_balance_KeyPress(object sender, KeyPressEventArgs e)
		{
			switch (e.KeyChar)
			{
			case '\b':
			case '.':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				e.Handled = false;
				break;
			default:
				e.Handled = true;
				break;
			}
		}

