		private bool serverCheck()
		{
			config = ConfigurationManager.OpenExeConfiguration((ConfigurationUserLevel)0);
			bool result;
			if (config.AppSettings.Settings["type"] == null)
			{
				config.AppSettings.Settings.Add("type", "single");
				result = true;
			}
			else if (Operators.CompareString(config.AppSettings.Settings["type"].Value, "", false) == 0)
			{
				config.AppSettings.Settings["type"].Value = "single";
				result = true;
			}
			else if (Operators.CompareString(config.AppSettings.Settings["type"].Value, "multi", false) == 0)
			{
				((Form)MyProject.Forms.frm_sign_in).MdiParent = (Form)(object)this;
				((Form)MyProject.Forms.frm_sign_in).Show((IWin32Window)(object)this);
				result = false;
			}
			else
			{
				result = true;
			}
			config.Save((ConfigurationSaveMode)0);
			ConfigurationManager.RefreshSection("appSettings");
			return result;
		}

