		private void Compress(FileInfo fi)
		{
			using FileStream fileStream2 = fi.OpenRead();
			if (!(((File.GetAttributes(fi.FullName) & FileAttributes.Hidden) != FileAttributes.Hidden) & (Operators.CompareString(fi.Extension, ".txt", false) != 0)))
			{
				return;
			}
			using FileStream fileStream = File.Create(fi.FullName + ".txt");
			using GZipStream gZipStream = new GZipStream(fileStream, CompressionMode.Compress, leaveOpen: false);
			byte[] array = new byte[4097];
			for (int num = fileStream2.Read(array, 0, array.Length); num != 0; num = fileStream2.Read(array, 0, array.Length))
			{
				gZipStream.Write(array, 0, num);
			}
			Console.WriteLine("Compressed {0} from {1} to {2} bytes.", fi.Name, fi.Length.ToString(), fileStream.Length.ToString());
		}

