					string text2 = ob.executereader("Select serverproperty('machinename')");
					if (Operators.CompareString(text2.ToUpper(), ((ServerComputer)MyProject.Computer).Name.ToUpper(), false) == 0)
					{
						text = text + "\\" + mdl_public_variables.GetDayOfWeek(DateTime.Now);
						if (Directory.Exists(text))
						{
							if (File.Exists(text + "\\barmanager.bak"))
							{
								File.Delete(text + "\\barmanager.bak");
							}
						}
						else
						{
							Directory.CreateDirectory(text);
						}
						s = "backup database barmanager to disk= '" + text + "\\barmanager.bak' ";
						ob.insert(s);
						result = true;
					}
					else
					{
						try
						{
							if (Directory.Exists(mdl_public_variables.back_up_path + "\\" + mdl_public_variables.GetDayOfWeek(DateTime.Now)))
							{
								if (File.Exists(mdl_public_variables.back_up_path + "\\" + mdl_public_variables.GetDayOfWeek(DateTime.Now) + "\\barmanager.bak"))
								{
									File.Delete(mdl_public_variables.back_up_path + "\\" + mdl_public_variables.GetDayOfWeek(DateTime.Now) + "\\barmanager.bak");
								}
							}
							else
							{
								Directory.CreateDirectory(mdl_public_variables.back_up_path + "\\" + mdl_public_variables.GetDayOfWeek(DateTime.Now));
							}
							SQLLocalBackup sQLLocalBackup = new SQLLocalBackup(mdl_public_variables.server, mdl_public_variables.server_id, mdl_public_variables.server_password, "barmanager");
							sQLLocalBackup.DoLocalBackup(text, mdl_public_variables.back_up_path + "\\" + mdl_public_variables.GetDayOfWeek(DateTime.Now));
							if (Directory.Exists(text) && File.Exists(text + "\\barmanager.bak"))
							{
								File.Delete(text + "\\barmanager.bak");
							}
							result = true;
						}
						catch (Exception ex)
						{
							ProjectData.SetProjectError(ex);
							Exception ex2 = ex;
							if (Directory.Exists(text) && File.Exists(text + "\\barmanager.bak"))
							{
								File.Delete(text + "\\barmanager.bak");
							}
							MessageBox.Show("Due to access level data backup is Faild To Cerate!! \r\n Please Update data Backup path in Company Parameter to a public and Shareable path From Server Device ");
							result = false;
							ProjectData.ClearProjectError();
						}
					}
				}
			}
			catch (SqlException val)
			{
				ProjectData.SetProjectError((Exception)val);
				SqlException val2 = val;
				result = false;
				ProjectData.ClearProjectError();
			}
			return result;
		}

