		private void updates()
		{
			UpdateForUltimate();
			NaiUpdates();
			if (config.AppSettings.Settings["ver"] == null)
			{
				config.AppSettings.Settings.Add("ver", Application.ProductVersion.ToString());
			}
			else if ((Operators.CompareString(config.AppSettings.Settings["ver"].Value, "", false) == 0) | (Operators.CompareString(config.AppSettings.Settings["ver"].Value, Application.ProductVersion.ToString(), false) != 0))
			{
				config.AppSettings.Settings["ver"].Value = Application.ProductVersion.ToString();
			}
			try
			{
				config.Save((ConfigurationSaveMode)0);
				ConfigurationManager.RefreshSection("appSettings");
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
		}

