				s = "create view vw_detors as select ledcode, name,ledger.companycode from ledger join acountname on acountname.accode=ledger.accode where acountname.acname like '%DEBTORS'  or acountname.acname like 'DEBTORS%'";
				ob.insert(s);
				s = "create view vw_creditors as select ledcode, name,ledger.companycode from ledger join acountname on acountname.accode=ledger.accode where acountname.acname like '%CREDITORS'  or acountname.acname like 'CREDITORS%'";
				ob.insert(s);
				s = "CREATE view vw_sale as select salestype,sum(bottles_sold) as bottles_sold,sum(large) as large,sum(small) as small,sum(westage)as westage,sum(total_amount)as total_amount,companycode,yearcode,trndate from(select salestype,qnty as BOTTLES_SOLD,isnull(large,0) as large,isnull(small,0)as small,isnull(westage,0) as westage,itemamount as TOTAL_AMOUNT,salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.trndate from salesbillmain join salesbilldetail  on salesbillmain.companycode=salesbilldetail.companycode  and salesbillmain.trnno=salesbilldetail.trnno and salesbillmain.yearcode=salesbilldetail.yearcode join itemmst on itemmst.itemcode=salesbilldetail.itemcode and salesbilldetail.companycode=itemmst.companycode union all select 'DISCOUNT' as saletype,'0' as bottles_sold,'0' as large,'0' as small , '0' as westage,discamount as total_amount,companycode,yearcode,trndate from salesbillmain where salestype<>'RETURN' and discamount<>0 union all select 'DISCOUNT' as saletype,'0' as bottles_sold,'0' as large,'0' as small , '0' as westage,(-1)*discamount as total_amount,companycode,yearcode,trndate from salesbillmain where salestype='RETURN' and discamount<>0 union all select 'EXPENCE' as saletype,'0' as BOTTLES_SOLD,'0' as large,'0' as small , '0' as westage,debit as total_amount,payment_main.companycode as companycode,payment_main.yearcode as yearcode,payment_main.vchdate as trndate from payment_main join payment_detail on payment_main.companycode=payment_detail.companycode and payment_main.yearcode=payment_detail.yearcode and payment_main.vchno=payment_detail.vchno join companyparamtr on companyparamtr.companycode=payment_main.companycode and companyparamtr.expenceacc=payment_main.head_account )as x group by salestype,companycode,yearcode,trndate";
				ob.insert(s);
				s = "create view vw_tally_data as select saletype,x.companycode,x.yearcode,x.trnno,date,head,client,itemname,itemqty,itemrate,itemamount,tottaxamt,totnetamt from(select salestype as saletype,salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.trnno,salesbillmain.trndate as date,name as head,itemname,qnty as itemqty,rate as itemrate,itemamount,discamount as tottaxamt,itemamount-discamount as totnetamt from salesbillmain join ledger on ledger.ledcode=salesbillmain.account_head and ledger.companycode=salesbillmain.companycode join salesbilldetail on salesbilldetail.companycode=salesbillmain.companycode and salesbilldetail.yearcode=salesbillmain.yearcode and salesbilldetail.trnno=salesbillmain.trnno join itemmst on itemmst.companycode=salesbilldetail.companycode and itemmst.itemcode=salesbilldetail.itemcode ) as x join( select salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.trnno,name as client from salesbillmain join ledger on ledger.ledcode=salesbillmain.ledgercode and ledger.companycode=salesbillmain.companycode join salesbilldetail on salesbilldetail.companycode=salesbillmain.companycode and salesbilldetail.yearcode=salesbillmain.yearcode and salesbilldetail.trnno=salesbillmain.trnno join itemmst on itemmst.companycode=salesbilldetail.companycode and itemmst.itemcode=salesbilldetail.itemcode group by salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.trnno,name) as y on  x.companycode = y.companycode and x.yearcode = y.yearcode and x.trnno = y.trnno";
				ob.insert(s);
				s = "create view vw_tally_purchase as select x.trnno as no,x.companycode,x.yearcode,date,achead,supplier,itempurchased,loose,box,itemqty,itemrate,itemamount,chno,chdate,tpassno,batchno,x.ptype, x.discount from (select purchasemain.trnno,purchasemain.companycode,purchasemain.yearcode,purchasemain.trndate as date,name as achead,itemname as itempurchased,itemloose as loose,itembox as box,itemquantity as itemqty,isnull(itemrate,0) as itemrate,isnull(itemamount,0) as itemamount,docno as chno,docdate as chdate,tppassno as tpassno,batchno,ptype,ISNULL(dbo.purchasedetail.itemdiscount, 0) AS discount from purchasemain join ledger on ledger.ledcode=purchasemain.purchaseacccode and ledger.companycode=purchasemain.companycode join purchasedetail on purchasedetail.companycode=purchasemain.companycode and purchasedetail.yearcode=purchasemain.yearcode and purchasedetail.trnno=purchasemain.trnno join itemmst on itemmst.itemcode=purchasedetail.itemcode and itemmst.companycode=purchasedetail.companycode ) as x join( select trnno,purchasemain.companycode,yearcode,name as supplier from purchasemain join ledger  on ledger.companycode=purchasemain.companycode and ledger.ledcode=purchasemain.suppliercode )as y on y.companycode=x.companycode and y.yearcode=x.yearcode and y.trnno=x.trnno";
				ob.insert(s);
				s = "CREATE view [dbo].[vw_cash_sale_daywise] as select itemmst.itemcode,itemmst.itemname,sum(qnty) as BOTTLES_SOLD,sum(salesbilldetail.itemamount)as amnt, salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode from salesbillmain join salesbilldetail on salesbillmain.companycode=salesbilldetail.companycode and salesbillmain.yearcode=salesbilldetail.yearcode and salesbillmain.trnno=salesbilldetail.trnno join itemmst on itemmst.itemcode=salesbilldetail.itemcode and salesbilldetail.companycode=itemmst.companycode where salestype='CASH'group by itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode";
				ob.insert(s);
				s = "CREATE view vw_return_sale_daywise as select itemmst.itemcode,itemmst.itemname,sum(qnty) as BOTTLES_SOLD,sum(salesbilldetail.itemamount)as amnt, salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode from salesbillmain join salesbilldetail on salesbillmain.companycode=salesbilldetail.companycode And salesbillmain.yearcode = salesbilldetail.yearcode And salesbillmain.trnno = salesbilldetail.trnno join itemmst on itemmst.itemcode=salesbilldetail.itemcode and salesbilldetail.companycode=itemmst.companycode where salestype='return' group by itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode";
				ob.insert(s);
				s = "CREATE view [dbo].[vw_credit_sale_daywise] as select itemmst.itemcode,itemmst.itemname,sum(qnty) as BOTTLES_SOLD,sum(salesbilldetail.itemamount)as amnt, salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode from salesbillmain join salesbilldetail on salesbillmain.companycode=salesbilldetail.companycode And salesbillmain.yearcode = salesbilldetail.yearcode And salesbillmain.trnno = salesbilldetail.trnno join itemmst on itemmst.itemcode=salesbilldetail.itemcode and salesbilldetail.companycode=itemmst.companycode where salestype='credit account' group by itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode";
				ob.insert(s);
				s = "CREATE view [dbo].[vw_creditcard_sale_daywise] as select itemmst.itemcode,itemmst.itemname,sum(qnty) as BOTTLES_SOLD,sum(salesbilldetail.itemamount)as amnt, salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode from salesbillmain join salesbilldetail on salesbillmain.companycode=salesbilldetail.companycode And salesbillmain.yearcode = salesbilldetail.yearcode And salesbillmain.trnno = salesbilldetail.trnno join itemmst on itemmst.itemcode=salesbilldetail.itemcode and salesbilldetail.companycode=itemmst.companycode where salestype='credit card' group by itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode";
				ob.insert(s);
				s = "create view vw_payment_detail as select trndate as date,purchasemain.companycode,yearcode,suppliercode as ledgercode,name,convert(varchar(max),docno) as billno,0 as debit,totnetamt as credit from purchasemain join ledger on ledger.ledcode=purchasemain.suppliercode and ledger.companycode=purchasemain.companycode where ptype='PURCHASE' union all select payment_detail.vchdate as date,payment_detail.companycode,payment_detail.yearcode,head_account as ledgercode,name,convert(varchar(max),trnno) as billno,payment_detail.debit as debit,0 as credit from payment_detail join  payment_main on payment_detail.companycode=payment_main.companycode and payment_detail.yearcode=payment_main.yearcode And payment_detail.vchno = payment_main.vchno join ledger on ledger.ledcode=payment_main.head_account and ledger.companycode=payment_main.companycode union all select vchdate as date,payment_main.companycode,yearcode,head_account as ledgercode,name,'Voucher no.'+convert(varchar(max),vchno) as billno,discount as debit,0 as credit from payment_main join ledger on ledger.ledcode=payment_main.head_account And ledger.companycode = payment_main.companycode where discount<>0";
				ob.insert(s);
				s = "CREATE view stock with schemabinding as select itemcode,itemname,sum(bottles) as stock,companycode,storecode,yearcode,packing from (/********for adding the qunatities in the stock******/ select dbo.itemmst.itemcode,itemname,sum(qnty) as bottles,dbo.itemmst.companycode,shopcode as storecode,yearcode,packing from dbo.openingstockmst join dbo.itemmst on dbo.openingstockmst.companycode=dbo.itemmst.companycode and dbo.openingstockmst.itemcode=dbo.itemmst.itemcode group by dbo.itemmst.companycode,yearcode,shopcode,dbo.itemmst.itemcode,dbo.itemmst.itemname,packing union all select dbo.itemmst.itemcode,dbo.itemmst.itemname,(-1)*sum(qnty) as bottles,dbo.salesbillmain.companycode,storecode,dbo.salesbillmain.yearcode,packing from dbo.salesbillmain join dbo.salesbilldetail on dbo.salesbillmain.companycode=dbo.salesbilldetail.companycode and dbo.salesbillmain.yearcode=dbo.salesbilldetail.yearcode and dbo.salesbillmain.trnno=dbo.salesbilldetail.trnno join dbo.itemmst on dbo.salesbilldetail.companycode=dbo.itemmst.companycode and dbo.itemmst.itemcode=dbo.salesbilldetail.itemcode where salestype='cash' or salestype='credit card' or salestype ='credit account' group by dbo.salesbillmain.companycode,dbo.salesbillmain.yearcode,storecode,dbo.itemmst.itemcode,dbo.itemmst.itemname,packing union all select dbo.itemmst.itemcode,dbo.itemmst.itemname,sum(qnty) as bottles,dbo.salesbillmain.companycode,storecode,dbo.salesbillmain.yearcode,packing from dbo.salesbillmain join dbo.salesbilldetail on dbo.salesbillmain.companycode=dbo.salesbilldetail.companycode and dbo.salesbillmain.yearcode=dbo.salesbilldetail.yearcode and dbo.salesbillmain.trnno=dbo.salesbilldetail.trnno join dbo.itemmst on dbo.salesbilldetail.companycode=dbo.itemmst.companycode and dbo.itemmst.itemcode=dbo.salesbilldetail.itemcode where salestype='return' group by dbo.salesbillmain.companycode,dbo.salesbillmain.yearcode,storecode,dbo.itemmst.itemcode,dbo.itemmst.itemname,packing union all select dbo.itemmst.itemcode,dbo.itemmst.itemname,sum(itemquantity) as bottles,dbo.purchasemain.companycode,shopcode as storecode,dbo.purchasemain.yearcode,packing  from dbo.purchasemain join dbo.purchasedetail on dbo.purchasedetail.companycode=dbo.purchasemain.companycode and dbo.purchasedetail.yearcode=dbo.purchasemain.yearcode and dbo.purchasedetail.trnno=dbo.purchasemain.trnno  join dbo.itemmst on dbo.itemmst.companycode=dbo.purchasedetail.companycode and dbo.itemmst.itemcode=dbo.purchasedetail.itemcode where ptype='PURCHASE' group by dbo.purchasemain.companycode,dbo.purchasemain.yearcode,shopcode,dbo.itemmst.itemcode,dbo.itemmst.itemname,packing union all select dbo.itemmst.itemcode,dbo.itemmst.itemname,-1*sum(itemquantity) as bottles,dbo.purchasemain.companycode,shopcode as storecode,dbo.purchasemain.yearcode,packing from dbo.purchasemain join dbo.purchasedetail on dbo.purchasedetail.companycode=dbo.purchasemain.companycode and dbo.purchasedetail.yearcode=dbo.purchasemain.yearcode and dbo.purchasedetail.trnno=dbo.purchasemain.trnno join dbo.itemmst on dbo.itemmst.companycode=dbo.purchasedetail.companycode and dbo.itemmst.itemcode=dbo.purchasedetail.itemcode where ptype='PURCHASE RETURN' group by dbo.purchasemain.companycode,dbo.purchasemain.yearcode,shopcode,dbo.itemmst.itemcode,dbo.itemmst.itemname,packing union all /********for deducting the qunatities form the storage of the stock from where the items has been sold ******/ select dbo.itemmst.itemcode,itemname,(-1)*sum(qnty) as bottles,dbo.stk_transfer_detail.companycode,shopcode_frm as storecode,dbo.stk_transfer_detail.yearcode,packing from dbo.stk_transfer_detail join dbo.itemmst on dbo.stk_transfer_detail.companycode=dbo.itemmst.companycode and dbo.itemmst.itemcode=dbo.stk_transfer_detail.itemcode join dbo.stk_transfer_main on dbo.stk_transfer_main.companycode=dbo.stk_transfer_detail.companycode and dbo.stk_transfer_main.yearcode=dbo.stk_transfer_detail.yearcode and dbo.stk_transfer_main.trnno=dbo.stk_transfer_detail.trnno group by dbo.stk_transfer_detail.companycode,dbo.stk_transfer_detail.yearcode,shopcode_frm,dbo.itemmst.itemcode,dbo.itemmst.itemname,packing union all /********for adding the qunatities to the storage of the stock  where the items has been sold ******/ select dbo.itemmst.itemcode,itemname,sum(qnty) as bottles,dbo.stk_transfer_detail.companycode,shopcode_to as storecode,dbo.stk_transfer_detail.yearcode,packing from dbo.stk_transfer_detail join dbo.itemmst on dbo.stk_transfer_detail.companycode=dbo.itemmst.companycode and dbo.itemmst.itemcode=dbo.stk_transfer_detail.itemcode join dbo.stk_transfer_main on dbo.stk_transfer_main.companycode=dbo.stk_transfer_detail.companycode and dbo.stk_transfer_main.yearcode=dbo.stk_transfer_detail.yearcode and dbo.stk_transfer_main.trnno=dbo.stk_transfer_detail.trnno group by dbo.stk_transfer_detail.companycode,dbo.stk_transfer_detail.yearcode,shopcode_to,dbo.itemmst.itemcode,dbo.itemmst.itemname,packing )as x group by companycode,yearcode,storecode,itemcode,itemname,packing ";
				ob.insert(s);
				s = "CREATE view [dbo].[vw_receipt_accounts] as SELECT trnid,trndate AS date,salesbillmain.companycode,yearcode,account_head AS ledgercode, 'Sale' AS Vchtype,convert(varchar(24),trnno) as billno, ledger.name, amount AS debit, 0 AS credit, ledgercode AS other_ledgercode , '' as cheque_no FROM salesbillmain JOIN ledger ON ledger.companycode = salesbillmain.companycode AND salesbillmain.account_head = ledger.ledcode  and salestype<>'RETURN'    union all select trnid, trndate as date,salesbillmain.companycode,yearcode, ledgercode,'Sale' as Vchtype,convert(varchar(24),trnno) as billno,ledger.name,0 as debit,netamount as credit, account_head as other_ledgercode , '' as cheque_no FROM salesbillmain join ledger on ledger.ledcode=salesbillmain.ledgercode and ledger.companycode=salesbillmain.companycode  and salestype<>'RETURN'  union all  select trnid, trndate as date,salesbillmain.companycode,yearcode,discount_account_head as ledgercode,'Sale' as Vchtype,convert(varchar(24),trnno) as billno,ledger.name,0 as debit,discamount as credit, account_head as other_ledgercode , '' as cheque_no FROM salesbillmain join ledger on ledger.ledcode=salesbillmain.discount_account_head and ledger.companycode=salesbillmain.companycode where discamount<>0   and salestype<>'RETURN'   union all  select trnid, trndate as date,salesbillmain.companycode,yearcode,discount_account_head as ledgercode,'Sale' as Vchtype,convert(varchar(24),trnno) as billno,ledger.name,discamount as debit,0 as credit, account_head as other_ledgercode , '' as cheque_no FROM salesbillmain join ledger on ledger.ledcode=salesbillmain.discount_account_head and ledger.companycode=salesbillmain.companycode where discamount<>0   and salestype='RETURN'   union all  select trnid, sales_tax.date, sales_tax.companycode, sales_tax.yearcode, sales_tax.tax_book AS ledgercode, 'Sale' AS Vchtype, CONVERT(varchar(24), sales_tax.trnno) AS billno,ledger.name, ABS(sales_tax.tax_amount) AS debit, 0 AS credit, ledgercode AS other_ledgercode, '' AS cheque_no FROM sales_tax INNER JOIN ledger ON ledger.companycode = sales_tax.companycode AND ledger.ledcode = sales_tax.tax_book INNER JOIN salesbillmain ON sales_tax.companycode = salesbillmain.companycode AND sales_tax.yearcode = salesbillmain.yearcode AND sales_tax.trnno = salesbillmain.trnno WHERE (sales_tax.tax_amount > 0) union all select 0 as trnid, date,sales_tax.companycode,yearcode,tax_book as ledgercode,'Sale' as Vchtype,convert(varchar(24),trnno) as billno,ledger.name,0 as debit,abs(tax_amount) as credit, cash_bank_book as other_ledgercode , '' as cheque_no FROM sales_tax join ledger on ledger.companycode=sales_tax.companycode and ledger.ledcode=sales_tax.tax_book  where tax_amount<0   union all  select trnid, vchdate as date,receipt_main.companycode,yearcode,head_account as ledgercode,'Receipt' as Vchtype,convert(varchar(24),vchno) as billno,ledger.name,amount_paid as debit,0 as credit, client_account as other_ledgercode ,cheque_no FROM receipt_main join ledger on ledger.ledcode=receipt_main.head_account and ledger.companycode=receipt_main.companycode  union all  select trnid, vchdate as date,receipt_main.companycode,yearcode,client_account as ledgercode,'Receipt' as Vchtype,convert(varchar(24),vchno) as billno,ledger.name,0 as debit,amount_paid as credit, head_account as other_ledgercode ,cheque_no FROM receipt_main join ledger on ledger.ledcode=receipt_main.client_account and ledger.companycode=receipt_main.companycode   union all  select trnid, trndate as date,salesbillmain.companycode,yearcode,account_head as ledgercode,'Return' as Vchtype,convert(varchar(24),trnno) as billno,ledger.name,0 as debit,netamount as credit,ledgercode as  other_ledgercode , '' as cheque_no FROM salesbillmain  join ledger  on ledger.ledcode=salesbillmain.account_head  and ledger.companycode=salesbillmain.companycode where salestype='RETURN'   union all  select trnid, trndate as date,salesbillmain.companycode,yearcode,ledgercode as ledgercode,'Return' as Vchtype,convert(varchar(24),trnno) as billno,ledger.name,netamount as debit,0 as credit,account_head as  other_ledgercode , '' as cheque_no FROM salesbillmain  join ledger on  ledger.ledcode=salesbillmain.ledgercode  and ledger.companycode=salesbillmain.companycode where salestype='RETURN'   union all  select trnid, trndate as date,purchasemain.companycode,yearcode,purchaseacccode as ledgercode,'Purchase' as Vchtype,docno as billno,ledger.name,0 as debit,totamount as credit,suppliercode as ledgercode , '' as cheque_no FROM purchasemain join ledger  on ledger.ledcode=purchasemain.purchaseacccode and ledger.companycode=purchasemain.companycode where ptype='PURCHASE'   union all  select trnid, trndate as date,purchasemain.companycode,yearcode,suppliercode as ledgercode,'Purchase' as Vchtype,docno as billno,ledger.name,totnetamt as debit,0 as credit ,purchaseacccode as ledgercode , '' as cheque_no FROM purchasemain join ledger  on ledger.ledcode=purchasemain.suppliercode and ledger.companycode=purchasemain.companycode where ptype='PURCHASE'   union all  select trnid, trndate as date,purchasemain.companycode,yearcode,purchaseacccode as ledgercode,'Purchase' as Vchtype,docno as billno,ledger.name,totnetamt as debit,0 as credit,suppliercode as ledgercode , '' as cheque_no FROM purchasemain join ledger  on ledger.ledcode=purchasemain.purchaseacccode and ledger.companycode=purchasemain.companycode where ptype='RETURN'   union all  select trnid, trndate as date,purchasemain.companycode,yearcode,suppliercode as ledgercode,'Purchase' as Vchtype,docno as billno,ledger.name,0 as debit,totnetamt as credit ,purchaseacccode as ledgercode , '' as cheque_no FROM purchasemain join ledger  on ledger.ledcode=purchasemain.suppliercode and ledger.companycode=purchasemain.companycode where ptype='RETURN'   union all  select trnid, docdate as date,purchasetaxdetail.companycode,purchasemain.yearcode,taxdetail.ledcode as ledgercode,'Purchase' as vchtype,purchasemain.docno as billno,ledger.name, 0 as debit,purchasetaxdetail.taxamount as credit, purchaseacccode as other_ledgercode , '' as cheque_no FROM purchasetaxdetail join taxdetail  on taxdetail.companycode=purchasetaxdetail.companycode and taxdetail.schemecode=purchasetaxdetail.schemecode and taxdetail.taxcode=purchasetaxdetail.taxcode join purchasemain  on purchasemain.companycode=purchasetaxdetail.companycode and purchasemain.yearcode=purchasetaxdetail.yearcode and purchasemain.trnno=purchasetaxdetail.trnno join ledger  on ledger.companycode=taxdetail.companycode and ledger.ledcode=taxdetail.ledcode where sig='-'   union all  select trnid, docdate as date,purchasetaxdetail.companycode,purchasemain.yearcode,taxdetail.ledcode as ledgercode,'Purchase' as vchtype,purchasemain.docno as billno,ledger.name,purchasetaxdetail.taxamount as debit, 0 as credit, suppliercode as other_ledgercode , '' as cheque_no FROM purchasetaxdetail left join taxdetail  on taxdetail.companycode=purchasetaxdetail.companycode and taxdetail.schemecode=purchasetaxdetail.schemecode and taxdetail.taxcode=purchasetaxdetail.taxcode left join purchasemain  on purchasemain.companycode=purchasetaxdetail.companycode and purchasemain.yearcode=purchasetaxdetail.yearcode and purchasemain.trnno=purchasetaxdetail.trnno left join ledger  on ledger.companycode=taxdetail.companycode and ledger.ledcode=taxdetail.ledcode where sig='+'   union all  select trnid, docdate as date,purchasetaxdetail.companycode,purchasemain.yearcode,purchasetaxdetail.taxaccount as ledgercode,'Purchase' as vchtype,purchasemain.docno as billno, ledger.name, abs(taxamount) as debit, 0 as credit, purchaseacccode as other_ledgercode , '' as cheque_no FROM purchasetaxdetail join purchasemain  on purchasemain.companycode=purchasetaxdetail.companycode and purchasemain.yearcode=purchasetaxdetail.yearcode and purchasemain.trnno=purchasetaxdetail.trnno join ledger  on ledger.companycode=purchasetaxdetail.companycode and ledger.ledcode=purchasetaxdetail.taxaccount where purchasetaxdetail.schemecode is null and taxamount<0   union all  select trnid, docdate as date,purchasetaxdetail.companycode,purchasemain.yearcode,purchasetaxdetail.taxaccount as ledgercode,'Purchase' as vchtype,purchasemain.docno as billno, ledger.name,0 as debit, taxamount as credit, purchaseacccode as other_ledgercode , '' as cheque_no FROM purchasetaxdetail join purchasemain  on purchasemain.companycode=purchasetaxdetail.companycode and purchasemain.yearcode=purchasetaxdetail.yearcode and purchasemain.trnno=purchasetaxdetail.trnno join ledger  on ledger.companycode=purchasetaxdetail.companycode and ledger.ledcode=purchasetaxdetail.taxaccount where purchasetaxdetail.schemecode is null and taxamount>0   union all select trnid, vchdate as date,payment_main.companycode,yearcode,head_account as ledgercode,'Payment' as Vchtype,convert(varchar(24),vchno) as billno,ledger.name,0 as debit,amount_paid as credit, client_account as other_ledgercode , cheque_no FROM payment_main join ledger on ledger.ledcode=payment_main.head_account and ledger.companycode=payment_main.companycode   union all  select trnid, vchdate as date,payment_main.companycode,yearcode,client_account as ledgercode,'Payment' as Vchtype,convert(varchar(24),vchno) as billno,ledger.name,amount_paid as debit,0 as credit, head_account as other_ledgercode , cheque_no FROM payment_main join ledger on ledger.ledcode=payment_main.client_account and ledger.companycode=payment_main.companycode   union all  select journaldetail.trnid, journaldetail.trndate as date,journaldetail.companycode, journaldetail.yearcode,journaldetail.ledcode as ledgercode,journaldetail.type as vchtype,convert(varchar(24),bill) as billno,ledger.name,journaldetail.credit as debit,journaldetail.debit as credit,journaldetail_1.ledcode as other_ledgercode,journaldetail.chqno as cheque_no FROM journaldetail join (SELECT companycode, yearcode,type,trndate, trnno as bill,count(ledcode)as lcount FROM journaldetail GROUP BY companycode, yearcode,type, trndate, trnno having count(ledcode)=2) as X  on journaldetail.companycode=x.companycode and journaldetail.yearcode=x.yearcode and journaldetail.trndate=x.trndate and journaldetail.trnno=x.bill and journaldetail.type=x.type join ledger on journaldetail.companycode=ledger.companycode and journaldetail.ledcode=ledger.ledcode join journaldetail as journaldetail_1 on journaldetail.companycode=journaldetail_1.companycode and journaldetail.yearcode=journaldetail_1.yearcode and journaldetail.trndate=journaldetail_1.trndate and journaldetail.trnno=journaldetail_1.trnno and journaldetail.ledcode<>journaldetail_1.ledcode and journaldetail.type=journaldetail_1.type   union all  select journaldetail.trnid, journaldetail.trndate as date,journaldetail.companycode,journaldetail.yearcode,journaldetail.ledcode as ledgercode,journaldetail.type as vchtype,journaldetail.trnno as billno,name,case when journaldetail.to_by='To' and journaldetail_1.debit < journaldetail.credit then journaldetail_1.debit else journaldetail.credit end as debit,case when journaldetail.to_by='By' and journaldetail.debit < journaldetail_1.credit then journaldetail.debit else journaldetail_1.credit end as credit,journaldetail_1.ledcode as other_ledgercode,journaldetail.chqno as cheque_no from journaldetail join journaldetail as journaldetail_1 on journaldetail.companycode=journaldetail_1.companycode and journaldetail.yearcode=journaldetail_1.yearcode and journaldetail.trndate=journaldetail_1.trndate and journaldetail.trnno=journaldetail_1.trnno and journaldetail.ledcode<>journaldetail_1.ledcode and journaldetail.type=journaldetail_1.type and journaldetail.to_by<>journaldetail_1.to_by join (SELECT companycode, yearcode,type,trndate, trnno as bill,count(ledcode)as lount FROM journaldetail GROUP BY companycode, yearcode,type, trndate, trnno having count(ledcode)=3) as X on journaldetail.companycode=x.companycode and journaldetail.yearcode=x.yearcode and journaldetail.trndate=x.trndate and journaldetail.trnno=x.bill and journaldetail.type=x.type join ledger on journaldetail.companycode=ledger.companycode and journaldetail.ledcode=ledger.ledcode   union all  select journaldetail.trnid, journaldetail.trndate as date,journaldetail.companycode, journaldetail.yearcode,journaldetail.ledcode as ledgercode,journaldetail.type as vchtype,convert(varchar(24),bill) as billno,ledger.name,journaldetail.credit as debit,journaldetail.debit as credit,'' as other_ledgercode,journaldetail.chqno as cheque_no FROM journaldetail join (SELECT companycode, yearcode,type,trndate, trnno as bill,count(ledcode)as lcount FROM journaldetail GROUP BY companycode, yearcode,type, trndate, trnno having count(ledcode)>3 ) as X  on journaldetail.companycode=x.companycode and journaldetail.yearcode=x.yearcode and journaldetail.trndate=x.trndate and journaldetail.trnno=x.bill and journaldetail.type=x.type join ledger on journaldetail.companycode=ledger.companycode and journaldetail.ledcode=ledger.ledcode ";
				ob.insert(s);
				s = "CREATE FUNCTION [dbo].[opening_closing_stock] \r\n ( \r\n @day1 DATETIME, \r\n @day2 DATETIME, \r\n @day3 DATETIME \r\n )  \r\n RETURNS TABLE AS RETURN \r\n SELECT itemcode,itemname,SUM (opening_stock) AS opening_stock,SUM (bottles_purchased) AS bottles_purchased, \r\n SUM (bottles_sold) AS bottles_sold,SUM (stock)+SUM (opening_stock)+ SUM (bottles_purchased)-SUM (bottles_sold) AS stock, \r\n companycode,storecode,yearcode,SUM (breakage) AS breakage  \r\n FROM \r\n (  \r\n \tSELECT itemmst.itemcode,itemname,SUM (qnty) AS opening_stock, \r\n \t0 AS bottles_purchased,0 AS bottles_sold,0 AS stock,itemmst.companycode,shopcode AS storecode,yearcode,0 AS breakage  \r\n \tFROM openingstockmst JOIN itemmst ON openingstockmst.itemcode=itemmst.itemcode AND openingstockmst.companycode=itemmst.companycode  \r\n \tWHERE openingstockmst.trndate=@day1  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,itemmst.companycode,shopcode,openingstockmst.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemmst.itemname,(-1)*SUM (qnty) AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,0 AS stock, \r\n \tsalesbillmain.companycode,storecode,salesbillmain.yearcode,0 AS breakage  \r\n \tFROM salesbillmain JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode  \r\n \tAND salesbillmain.yearcode=salesbilldetail.yearcode AND salesbillmain.trnno=salesbilldetail.trnno  \r\n \tAND salesbillmain.billType = salesbilldetail.billType  \r\n \tJOIN itemmst ON itemmst.itemcode=salesbilldetail.itemcode AND salesbilldetail.companycode=itemmst.companycode  \r\n \tWHERE salestype<>'RETURN' AND salesbillmain.trndate >=@day1 AND salesbillmain.trndate <@day2  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemmst.itemname,SUM (qnty) AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,0 AS stock, \r\n \tsalesbillmain.companycode,storecode,salesbillmain.yearcode,0 AS breakage  \r\n \tFROM salesbillmain JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode  \r\n \tAND salesbillmain.yearcode=salesbilldetail.yearcode AND salesbillmain.trnno=salesbilldetail.trnno  \r\n \tAND salesbillmain.billType = salesbilldetail.billType  \r\n \tJOIN itemmst ON itemmst.itemcode=salesbilldetail.itemcode AND salesbilldetail.companycode=itemmst.companycode  \r\n \tWHERE salestype='RETURN' AND salesbillmain.trndate >=@day1 AND salesbillmain.trndate <@day2  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemmst.itemname,SUM (itemquantity) AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold, \r\n \t0 AS stock,purchasemain.companycode,shopcode AS storecode,purchasemain.yearcode,0 AS breakage  \r\n \tFROM purchasemain JOIN purchasedetail ON purchasedetail.companycode=purchasemain.companycode  \r\n \tAND purchasedetail.trnno=purchasemain.trnno AND purchasedetail.yearcode=purchasemain.yearcode  \r\n \tJOIN itemmst ON itemmst.itemcode=purchasedetail.itemcode AND itemmst.companycode=purchasedetail.companycode  \r\n \tWHERE ptype='PURCHASE' AND purchasemain.trndate >=@day1 AND purchasemain.trndate <@day2  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,purchasemain.companycode,shopcode,purchasemain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemmst.itemname,-1*SUM (itemquantity) AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold, \r\n \t0 AS stock,purchasemain.companycode,shopcode AS storecode,purchasemain.yearcode,0 AS breakage  \r\n \tFROM purchasemain JOIN purchasedetail ON purchasedetail.companycode=purchasemain.companycode  \r\n \tAND purchasedetail.trnno=purchasemain.trnno AND purchasedetail.yearcode=purchasemain.yearcode  \r\n \tJOIN itemmst ON itemmst.itemcode=purchasedetail.itemcode AND itemmst.companycode=purchasedetail.companycode  \r\n \tWHERE ptype='RETURN' AND purchasemain.trndate >=@day1 AND purchasemain.trndate <@day2  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,purchasemain.companycode,shopcode,purchasemain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemname,(-1)*SUM (qnty) AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,0 AS stock, \r\n \tstk_transfer_detail.companycode,shopcode_frm AS storecode,stk_transfer_detail.yearcode,0 AS breakage  \r\n \tFROM stk_transfer_detail  \r\n \tJOIN itemmst ON itemmst.itemcode=stk_transfer_detail.itemcode AND stk_transfer_detail.companycode=itemmst.companycode  \r\n \tJOIN stk_transfer_main ON stk_transfer_main.companycode=stk_transfer_detail.companycode  \r\n \tAND stk_transfer_main.yearcode=stk_transfer_detail.yearcode AND stk_transfer_main.trnno=stk_transfer_detail.trnno  \r\n \tWHERE stk_transfer_main.trndate>=@day1 AND stk_transfer_main.trndate<@day2  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,stk_transfer_detail.companycode,shopcode_frm,stk_transfer_detail.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemname,SUM (qnty) AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,0 AS stock, \r\n \tstk_transfer_detail.companycode,shopcode_to AS storecode,stk_transfer_detail.yearcode,0 AS breakage  \r\n \tFROM stk_transfer_detail JOIN itemmst ON itemmst.itemcode=stk_transfer_detail.itemcode  \r\n \tAND stk_transfer_detail.companycode=itemmst.companycode  \r\n \tJOIN stk_transfer_main ON stk_transfer_main.companycode=stk_transfer_detail.companycode  \r\n \tAND stk_transfer_main.yearcode=stk_transfer_detail.yearcode AND stk_transfer_main.trnno=stk_transfer_detail.trnno  \r\n \tWHERE stk_transfer_main.trndate>=@day1 AND stk_transfer_main.trndate<@day2  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,stk_transfer_detail.companycode,shopcode_to,stk_transfer_detail.yearcode  \r\n \tUNION ALL  \r\n \tSELECT breakagedetail.itemcode,itemname,-1*SUM (quantity) AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,0 AS stock, \r\n \tbreakagedetail.companycode,shopcode,breakagedetail.yearcode,0 AS breakage  \r\n \tFROM breakagedetail JOIN breakagemain ON breakagedetail.companycode=breakagemain.companycode  \r\n \tAND breakagedetail.yearcode=breakagemain.yearcode AND breakagedetail.trnno=breakagemain.trnno  \r\n \tJOIN itemmst ON itemmst.itemcode=breakagedetail.itemcode AND itemmst.companycode=breakagedetail.companycode  \r\n \tWHERE receivd='False' AND breakagemain.trndate>=@day1 AND breakagemain.trndate<@day2  \r\n \tGROUP BY breakagedetail.itemcode,itemname,breakagedetail.companycode,shopcode,breakagedetail.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemmst.itemname,0 AS opening_stock,0 AS bottles_purchased,SUM (qnty) AS bottles_sold,0 AS stock, \r\n \tsalesbillmain.companycode,storecode,salesbillmain.yearcode,0 AS breakage  \r\n \tFROM salesbillmain JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode  \r\n \tAND salesbillmain.yearcode=salesbilldetail.yearcode AND salesbillmain.trnno=salesbilldetail.trnno  \r\n \tAND salesbillmain.billType = salesbilldetail.billType JOIN itemmst ON itemmst.itemcode=salesbilldetail.itemcode  \r\n \tAND salesbilldetail.companycode=itemmst.companycode  \r\n \tWHERE salestype='cash' AND salesbillmain.trndate >=@day2 AND salesbillmain.trndate <=@day3 or salestype='credit card'  \r\n \tAND salesbillmain.trndate >=@day2 AND salesbillmain.trndate <=@day3 or salestype ='credit account'  \r\n \tAND salesbillmain.trndate >=@day2 AND salesbillmain.trndate <=@day3  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemmst.itemname,0 AS opening_stock,0 AS bottles_purchased,(-1)*SUM (qnty) AS bottles_sold,0 AS stock, \r\n \tsalesbillmain.companycode,storecode,salesbillmain.yearcode,0 AS breakage  \r\n \tFROM salesbillmain JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode  \r\n \tAND salesbillmain.yearcode=salesbilldetail.yearcode AND salesbillmain.trnno=salesbilldetail.trnno  \r\n \tAND salesbillmain.billType = salesbilldetail.billType JOIN itemmst ON itemmst.itemcode=salesbilldetail.itemcode  \r\n \tAND salesbilldetail.companycode=itemmst.companycode  \r\n \tWHERE salestype='return' AND salesbillmain.trndate >=@day2 AND salesbillmain.trndate <=@day3  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemmst.itemname,0 AS opening_stock,SUM (itemquantity) AS bottles_purchased,0 AS bottles_sold, \r\n \t0 AS stock,purchasemain.companycode,shopcode AS storecode,purchasemain.yearcode,0 AS breakage  \r\n \tFROM purchasemain JOIN purchasedetail ON purchasedetail.companycode=purchasemain.companycode  \r\n \tAND purchasedetail.trnno=purchasemain.trnno AND purchasedetail.yearcode=purchasemain.yearcode  \r\n \tJOIN itemmst ON itemmst.itemcode=purchasedetail.itemcode AND itemmst.companycode=purchasedetail.companycode  \r\n \tWHERE ptype='PURCHASE' AND purchasemain.trndate >=@day2 AND purchasemain.trndate <=@day3  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,purchasemain.companycode,shopcode,purchasemain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemmst.itemname,0 AS opening_stock,(-1)*SUM (itemquantity) AS bottles_purchased,0 AS bottles_sold, \r\n \t0 AS stock,purchasemain.companycode,shopcode AS storecode,purchasemain.yearcode,0 AS breakage  \r\n \tFROM purchasemain  \r\n \tJOIN purchasedetail ON purchasedetail.companycode=purchasemain.companycode AND purchasedetail.trnno=purchasemain.trnno  \r\n \tAND purchasedetail.yearcode=purchasemain.yearcode  \r\n \tJOIN itemmst ON itemmst.itemcode=purchasedetail.itemcode AND itemmst.companycode=purchasedetail.companycode  \r\n \tWHERE ptype='RETURN' AND purchasemain.trndate >=@day2 AND purchasemain.trndate <=@day3  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,purchasemain.companycode,shopcode,purchasemain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemname,0 AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,(-1)*SUM (qnty) AS stock, \r\n \tstk_transfer_detail.companycode,shopcode_frm AS storecode,stk_transfer_detail.yearcode,0 AS breakage  \r\n \tFROM stk_transfer_detail  \r\n \tJOIN itemmst ON itemmst.itemcode=stk_transfer_detail.itemcode AND stk_transfer_detail.companycode=itemmst.companycode  \r\n \tJOIN stk_transfer_main ON stk_transfer_main.companycode=stk_transfer_detail.companycode  \r\n \tAND stk_transfer_main.yearcode=stk_transfer_detail.yearcode AND stk_transfer_main.trnno=stk_transfer_detail.trnno  \r\n \tWHERE stk_transfer_main.trndate>=@day2 AND stk_transfer_main.trndate<=@day3  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,stk_transfer_detail.companycode,shopcode_frm,stk_transfer_detail.yearcode  \r\n \tUNION ALL  \r\n \tSELECT itemmst.itemcode,itemname,0 AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,SUM (qnty) AS stock, \r\n \tstk_transfer_detail.companycode,shopcode_to AS storecode,stk_transfer_detail.yearcode,0 AS breakage  \r\n \tFROM stk_transfer_detail JOIN itemmst ON itemmst.itemcode=stk_transfer_detail.itemcode  \r\n \tAND stk_transfer_detail.companycode=itemmst.companycode  \r\n \tJOIN stk_transfer_main ON stk_transfer_main.companycode=stk_transfer_detail.companycode  \r\n \tAND stk_transfer_main.yearcode=stk_transfer_detail.yearcode AND stk_transfer_main.trnno=stk_transfer_detail.trnno  \r\n \tWHERE stk_transfer_main.trndate>=@day2 AND stk_transfer_main.trndate<=@day3  \r\n \tGROUP BY itemmst.itemcode,itemmst.itemname,stk_transfer_detail.companycode,shopcode_to,stk_transfer_detail.yearcode  \r\n \tUNION ALL  \r\n \tSELECT breakagedetail.itemcode,itemname,0 AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,-1*SUM (quantity) AS stock, \r\n \tbreakagedetail.companycode,shopcode,breakagedetail.yearcode,SUM (quantity) AS breakage  \r\n \tFROM breakagedetail JOIN breakagemain ON breakagedetail.companycode=breakagemain.companycode  \r\n \tAND breakagedetail.yearcode=breakagemain.yearcode AND breakagedetail.trnno=breakagemain.trnno  \r\n \tJOIN itemmst ON itemmst.itemcode=breakagedetail.itemcode AND itemmst.companycode=breakagedetail.companycode  \r\n \tWHERE receivd='False' AND breakagemain.trndate>=@day2 AND breakagemain.trndate<=@day3  \r\n \tGROUP BY breakagedetail.itemcode,itemname,breakagedetail.companycode,shopcode,breakagedetail.yearcode  \r\n \t--NEXT PART UNION FPR NAI ITEMS \r\n \t \r\n \tUNION ALL \r\n \tSELECT naiItemMaster.itemCode,itemname,SUM (qnty) AS opening_stock, \r\n \t0 AS bottles_purchased,0 AS bottles_sold,0 AS stock,naiItemMaster.companycode,shopcode AS storecode,yearcode,0 AS breakage  \r\n \tFROM openingstockmst JOIN naiItemMaster ON openingstockmst.itemcode=naiItemMaster.itemcode AND openingstockmst.companycode=naiItemMaster.companycode  \r\n \tWHERE openingstockmst.trndate=@day1  \r\n \tGROUP BY naiItemMaster.itemcode,naiItemMaster.itemname,naiItemMaster.companycode,shopcode,openingstockmst.yearcode  \r\n \tUNION ALL  \r\n \tSELECT naiItemMaster.itemcode,naiItemMaster.itemname,(-1)*SUM (qnty) AS opening_stock,0 AS bottles_purchased,0 AS bottles_sold,0 AS stock, \r\n \tsalesbillmain.companycode,storecode,salesbillmain.yearcode,0 AS breakage  \r\n \tFROM salesbillmain JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode  \r\n \tAND salesbillmain.yearcode=salesbilldetail.yearcode AND salesbillmain.trnno=salesbilldetail.trnno  \r\n \tAND salesbillmain.billType = salesbilldetail.billType  \r\n \tJOIN naiItemMaster ON naiItemMaster.itemcode=salesbilldetail.itemcode AND salesbilldetail.companycode=naiItemMaster.companycode  \r\n \tWHERE salestype<>'RETURN' AND salesbillmain.trndate >=@day1 AND salesbillmain.trndate <@day2  \r\n \tGROUP BY naiItemMaster.itemcode,naiItemMaster.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode  \r\n \tUNION ALL  \r\n \tSELECT naiItemMaster.itemcode,naiItemMaster.itemn