				ob.insert(s);
				s = "create function xcise_statement2(@day1 as datetime,@day2 as datetime,@day3 as datetime) returns table as return select companycode,yearcode,kflname,type,groupname,categoryname,ml,sum(qnty) as 'qnty' from(select itemmst.companycode,yearcode,kflname,'1-Opening' as type,groupname,categoryname,ml,opening_stock as 'qnty' from  opening_closing_stock(@day1,@day2,@day3) join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode where not (opening_stock=0 and bottles_purchased=0 and stock=0 and bottles_sold=0) union all select itemmst.companycode,yearcode,kflname,'2-Purchase' as type,groupname,categoryname,ml,bottles_purchased as 'qnty' from opening_closing_stock(@day1,@day2,@day3) join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode where not (opening_stock=0 and bottles_purchased=0 and stock=0 and bottles_sold=0) union all select itemmst.companycode,yearcode,kflname,'3-Total' as type,groupname,categoryname,ml,bottles_purchased+opening_stock as 'qnty' from opening_closing_stock(@day1,@day2,@day3) join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode where not (opening_stock=0 and bottles_purchased=0 and stock=0 and bottles_sold=0) union all select itemmst.companycode,yearcode,kflname,'4-Closing' as type,groupname,categoryname,ml,stock as 'qnty' from  opening_closing_stock(@day1,@day2,@day3) join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode where not (opening_stock=0 and bottles_purchased=0 and stock=0 and bottles_sold=0) union all select itemmst.companycode,yearcode,kflname,'5-Difference' as type,groupname,categoryname,ml,bottles_sold as 'qnty' from  opening_closing_stock(@day1,@day2,@day3) join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode where not (opening_stock=0 and bottles_purchased=0 and stock=0 and bottles_sold=0)union all select itemmst.companycode,yearcode,kflname,'6-Difference in BL' as type,groupname,categoryname,ml,convert(float,convert(float,ml*bottles_sold)/1000) as 'qnty' from  opening_closing_stock(@day1,@day2,@day3) join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode where not (opening_stock=0 and bottles_purchased=0 and stock=0 and bottles_sold=0)) as x group by companycode,yearcode,kflname,type,groupname,categoryname,ml";
				ob.insert(s);
				s = "INSERT INTO openingStockDetail(companyCode, yearCode, shopCode, trndate, itemCode, batchNo, loose, box, qnty) SELECT companycode, yearcode, shopcode, trndate, itemcode, 'openingBatch' AS batchNo, sum(loose) as loose, sum(box) as box, sum(qnty) as qnty  FROM openingstockmst group by companyCode,yearCode,shopCode,trndate,itemCode ";
