				ob.insert(s);
				s = "update purchasedetail set purchasedetail.trndate = purchasemain.docdate   from purchasedetail INNER JOIN purchasemain ON purchasemain.companycode = purchasedetail.companycode AND purchasemain.yearcode = purchasedetail.yearcode AND purchasemain.trnno = purchasedetail.trnno ";
				ob.insert(s);
				s = "create procedure [dbo].[serialise_n_reference_sale_bills] @companycode varchar(6),@yearcode varchar(6) as begin begin tran t1 declare @trnno_previous int declare @trnno int declare @diff int declare @count int set @count=0 set @trnno_previous=0 declare c cursor for select convert(int,trnno) from salesbillmain where companycode=@companycode and yearcode =@yearcode  order by convert(int,trnno) asc open c fetch c into @trnno while @@fetch_status=0 begin  set @diff=@trnno-@trnno_previous-1 if @diff>0 begin set @count=@count+1 End set @trnno_previous=@trnno fetch c into @trnno End Close c deallocate c while @count>0  begin set @trnno_previous=0 declare c cursor for select convert(int,trnno) from salesbillmain where companycode=@companycode and yearcode =@yearcode  order by convert(int,trnno) asc  open c fetch c into @trnno while @@fetch_status=0  begin set @diff=@trnno-@trnno_previous-1 if @diff>0  begin update salesbillmain set trnno=(convert(int,trnno)-@diff) where convert(int,trnno)>=@trnno and companycode=@companycode and yearcode =@yearcode  End set @trnno_previous=@trnno fetch c into @trnno  End Close c  deallocate c set @count=@count-1  End commit tran t1  End ";
