.groupcode and groupmst.companycode=itemmst.companycode  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode  union all  select itemmst.companycode,yearcode, storecode,kflname,'4-Closing' as type,groupname,categoryname,ml,stock as 'qnty' , strengthName  from opening_closing_stock(@day1,@day2,@day3)  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode  union all  select itemmst.companycode,yearcode, storecode,kflname,'5-Difference' as type,groupname,categoryname,ml,bottles_sold as 'qnty' , strengthName  from opening_closing_stock(@day1,@day2,@day3)  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode  union all  select itemmst.companycode,yearcode, storecode,kflname,'6-Difference in BL' as type,groupname,categoryname,ml,convert(float,convert(float,ml*bottles_sold)/1000) as 'qnty' , strengthName  from opening_closing_stock(@day1,@day2,@day3)  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode  ) as x group by companycode,yearcode, storecode,kflname,type,groupname,categoryname,ml,strengthName  ";
