chasemain on purchasedetail.companycode=purchasemain.companycode and purchasedetail.yearcode=purchasemain.yearcode and purchasedetail.trndate=purchasemain.docdate and purchasedetail.trnno=purchasemain.trnno left outer join ledger on purchasemain.companycode=ledger.companycode and purchasemain.suppliercode=ledger.ledcode group by opening_closing_stock.companycode, opening_closing_stock.yearcode, kflmst.kflname, groupmst.groupname, categorymst.categoryname,ml, batchno FOR XML PATH ('') ) else '' end as batchno, case when  sum(purchasedetail.itemquantity)<>0 then (select distinct((', ')+ name) FROM dbo.opening_closing_stock(@day1,@day2,@day2) JOIN itemmst ON opening_closing_stock.companycode = itemmst.companycode AND opening_closing_stock.itemcode = itemmst.itemcode  JOIN kflmst ON itemmst.companycode = kflmst.companycode AND itemmst.kflcode = kflmst.kflcode  JOIN groupmst ON itemmst.companycode = groupmst.companycode AND itemmst.groupcode = groupmst.groupcode  JOIN categorymst ON itemmst.companycode = categorymst.companycode AND itemmst.categorycode = categorymst.categorycode  LEFT OUTER JOIN purchasedetail ON opening_closing_stock.companycode = purchasedetail.companycode AND opening_closing_stock.yearcode = purchasedetail.yearcode AND  opening_closing_stock.itemcode = purchasedetail.itemcode AND purchasedetail.trndate =@day2 left outer join purchasemain on purchasedetail.companycode=purchasemain.companycode and purchasedetail.yearcode=purchasemain.yearcode and purchasedetail.trndate=purchasemain.docdate and purchasedetail.trnno=purchasemain.trnno left outer join ledger on purchasemain.companycode=ledger.companycode and purchasemain.suppliercode=ledger.ledcode group by opening_closing_stock.companycode, opening_closing_stock.yearcode, kflmst.kflname, groupmst.groupname, categorymst.categoryname,ml, name FOR XML PATH ('') ) else '' end as party FROM dbo.opening_closing_stock(@day1,@day2,@day2) JOIN itemmst ON opening_closing_stock.companycode = itemmst.companycode AND 