alesbillmain.yearcode,trndate   ,users.userCode,users.userName,case when salesbillMain.billtype = 0 then 'FL'  when salesbillMain.billtype = 1 then 'CS' else 'NAI' end as itemType     from salesbillmain    Inner Join trnIdmst on salesBillMain.companyCode = trnIdmst.companyCode and salesBillMain.yearCode = trnIdmst.yearCode and salesBillMain.trnid = trnidmst.trnid   Inner Join users on trnIdmst.userCode = users.userCode where salestype='RETURN' and discamount<>0  union all    select 'EXPENCE' as saletype,'0' as BOTTLES_SOLD,'0' as large,'0' as small , '0' as westage,debit as total_amount,payment_main.companycode as companycode,payment_main.yearcode as yearcode, payment_main.vchdate as trndate ,users.userCode,users.userName,'NONE'as itemType   from payment_main    join payment_detail on payment_main.companycode=payment_detail.companycode and payment_main.yearcode=payment_detail.yearcode and payment_main.vchno=payment_detail.vchno    join companyparamtr on companyparamtr.companycode=payment_main.companycode and companyparamtr.expenceacc=payment_main.head_account    Inner Join trnIdmst on payment_main.companyCode = trnIdmst.companyCode and payment_main.yearCode = trnIdmst.yearCode and payment_main.trnid = trnidmst.trnid   Inner Join users on trnIdmst.userCode = users.userCode   )as x  group by salestype,companycode,yearcode,trndate,x.userCode,x.userName,x.itemType ";
