					s = "Create function [dbo].[onShopStockBookCalculation](@companyCode varchar(6),@yearCode varchar(6),@comStartDate as datetime,@trndateFrom as dateTime,@trnDateTo as datetime,@storeCode as varchar(6)) Returns Table AS return  Select X.brandCode,x.BrandName,X.itemcode,X.itemname,X.ml,sum(X.openingInBottle) as openingInBottle,0 as openingInMl,sum(X.receivedInBottle) as ReceivedInBottle, 0 as ReceivedInMl,  (sum(X.openingInBottle)+Sum(X.receivedInBottle)) as TotalStockInBottle,0 as TotalStockInMl,Sum(X.ClosingInBottle) as ClosingInBottle,0 as ClosingInMl,Sum(X.saleInBottle) as differenceInBottle,  0 as differenceInMl,X.kflname  From(  Select categorymst.categorycode as brandCode,categorymst.categoryname as BrandName,itemmst.itemcode,itemmst.itemname,itemmst.ml,opening_closing_stock.opening_stock as openingInBottle,opening_closing_stock.bottles_purchased as receivedInBottle,  opening_closing_stock.bottles_sold as saleInBottle,opening_closing_stock.stock as ClosingInBottle,kflmst.kflname   from opening_closing_stock(@comStartDate,@trndateFrom,@trnDateTo)  Inner Join itemmst On itemmst.companycode = opening_closing_stock.companycode AND itemmst.itemcode = opening_closing_stock.itemcode  Inner Join categorymst On  itemmst.companycode = categorymst.companycode AND itemmst.categorycode = categorymst.categorycode  Inner Join kflmst On kflmst.companycode = itemmst.companycode AND kflmst.kflcode = itemmst.kflcode  where opening_closing_stock.companycode = @companyCode AND opening_closing_stock.yearcode = @yearCode AND opening_closing_stock.storecode = @storeCode  union All  select categorymst.categorycode AS brandCode,categorymst.categoryname as brandName,itemmst.itemcode,itemmst.itemname,itemmst.ml,0 as openingInBottle,sum(stk_transfer_detail.qnty) as receivedInBottle,    0 as saleInBottle,0 as ClosingInBottle,kflmst.kflname  from stk_transfer_detail  Inner Join stk_transfer_main On stk_transfer_main.CompanyCode = stk_transfer_detail.CompanyCode AND stk_transfer_main.YearCode = stk_transfer_detail.yearcode AND stk_transfer_main.TrnDate = stk_transfer_detail.trndate  AND stk_transfer_main.TrnNo = stk_transfer_detail.trnno  Inner Join itemmst On itemmst.companycode = stk_transfer_detail.companycode AND itemmst.itemcode = stk_transfer_detail.itemcode  Inner Join categorymst On  itemmst.companycode = categorymst.companycode AND itemmst.categorycode = categorymst.categorycode  Inner Join kflmst On kflmst.companycode = itemmst.companycode AND kflmst.kflcode = itemmst.kflcode  Where stk_transfer_main.CompanyCode = @companyCode AND stk_transfer_main.YearCode = @yearCode AND stk_transfer_main.shopcode_to = @storeCode AND stk_transfer_main.TrnDate >= @trndateFrom AND stk_transfer_main.TrnDate <= @trnDateTo  Group BY categorymst.categorycode,categorymst.categoryname,itemmst.itemcode,itemmst.itemname,itemmst.ml,kflmst.kflname   ) AS X   Group By X.brandCode,X.BrandName,X.itemcode,X.itemname,X.ml,X.kflname ";
