				{
					s = "CREATE PROCEDURE [dbo].[LedgerCashBank] @ComCode varchar(6) , @YearCode varchar(6) AS  \r\n  SELECT ledgerCode, ledgerName, SUM(Total) AS Amount,SUM(Lockamt) AS LockAmount  \r\n  FROM ( \r\n  SELECT XTransactions.ledgerCode, MasterAccountsLedger.ledgerName, XTransactions.Amount AS Total, 0 AS Lockamt  \r\n  FROM ( \r\n  SELECT companyCode, yearcode, ledgerCode, TrnAmount * TrnEffect AS Amount FROM MasterAccountsOpening  \r\n  UNION ALL  \r\n  SELECT companycode, yearcode, TrnAccount AS ledgerCode, TrnAmount * TrnEffect AS Amount FROM TransactionDetail \r\n  ) AS XTransactions   \r\n  LEFT OUTER JOIN MasterAccountsLedger ON XTransactions.ledgerCode = MasterAccountsLedger.ledgerCode AND   \r\n  XTransactions.companyCode = MasterAccountsLedger.companyCode  \r\n  WHERE (XTransactions.yearcode = @YearCode) AND (MasterAccountsLedger.companyCode = @ComCode)  \r\n   \r\n  UNION ALL  \r\n   \r\n  SELECT ledgerCode, ledgerName, 0 AS Amount, LockAmount * LockEffect AS Lockamt FROM MasterAccountsLedger  \r\n  WHERE (companyCode = @ComCode) AND (Hidden = 0) \r\n   \r\n  UNION ALL \r\n   \r\n  Select ledgerCode,ledgerName, 0 AS Amount, LockAmount * LockEffect AS Lockamt \r\n  FROM MasterAccountsLedger \r\n  Inner Join companyparamtr On companyparamtr.companycode = MasterAccountsLedger.companyCode AND companyparamtr.cashhd = MasterAccountsLedger.ledgerCode \r\n  WHERE (MasterAccountsLedger.companyCode = @ComCode) \r\n  ) AS Transactions  \r\n  GROUP BY ledgerCode, ledgerName  \r\n  HAVING (ledgerName LIKE '%Cash%') OR (ledgerName LIKE '%Bank%') or (ledgerName LIKE  (Select ledgerName \r\n  FROM MasterAccountsLedger \r\n  Inner Join companyparamtr On companyparamtr.companycode = MasterAccountsLedger.companyCode AND companyparamtr.cashhd = MasterAccountsLedger.ledgerCode \r\n  WHERE (MasterAccountsLedger.companyCode = @ComCode))) \r\n  ORDER BY ledgerName  ";
