TransactionDetail.yearcode = TransactionMain.yearcode AND \r\n \t\t\t\tTransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId \r\n \t\t\tUNION ALL \r\n \t\t\tSELECT companyCode, yearcode, 0 AS IndexId, EffectDate, ledgerCode AS TrnAccount, TrnAmount, TrnEffect \r\n \t\t\tFROM MasterAccountsOpening) AS Transactions ON Masters.ledgerCode = Transactions.TrnAccount AND Masters.companyCode = Transactions.companycode \r\n \t\t\tWHERE     (Masters.companyCode = @comCode) AND (Transactions.yearcode = @YearCode) AND (Transactions.VchDate BETWEEN CONVERT(VARCHAR, @dayFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103)) \r\n \t\t\tGROUP BY Masters.ledgerName, Masters.AccGroupName, Masters.AccGroupCode \r\n \t\t\tORDER BY Masters.AccGroupName, Masters.ledgerName \r\n \t\tEND \r\n \tELSE\t\t\t\t\t\t\t--All Groups Without Zero Values \r\n \t\tBEGIN \r\n \t\t\tSELECT TOP (100) PERCENT Masters.AccGroupName As 'Group Name', Masters.ledgerName As Particulars,  \r\n \t\t\tCASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = - 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect *-1) AS FLOAT) ELSE '' END AS Debit,  \r\n \t\t\tCASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect) AS FLOAT) ELSE '' END AS Credit \r\n \t\t\tFROM (SELECT TOP (100) PERCENT MasterAccountsGroups.companyCode, MasterAccountsGroups.AccGroupName, MasterAccountsLedger.ledgerName, MasterAccountsGroups.AccGroupCode, MasterAccountsLedger.ledgerCode \r\n \t\t\tFROM MasterAccountsGroups RIGHT OUTER JOIN MasterAccountsLedger ON MasterAccountsGroups.AccGroupCode = MasterAccountsLedger.AccGroupCode AND MasterAccountsGroups.companyCode = MasterAccountsLedger.companyCode \r\n \t\t\tWHERE (MasterAccountsGroups.Hidden = 0)) AS Masters RIGHT OUTER JOIN (SELECT TransactionMain.companycode, TransactionMain.yearcode, TransactionMain.IndexId, TransactionMain.VchDate, TransactionDetail.TrnAccount,  \r\n \t\t\t\tTransactionDetail.TrnAmount, TransactionDetail.TrnEffect \r\n \t\t\tFROM TransactionDetail LEFT OUTER JOIN TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND \r\n \t\t\t\tTransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId \r\n \t\t\tUNION ALL \r\n \t\t\tSELECT companyCode, yearcode, 0 AS IndexId, EffectDate, ledgerCode AS TrnAccount, TrnAmount, TrnEffect  \r\n \t\t\tFROM MasterAccountsOpening) AS Transactions ON Masters.ledgerCode = Transactions.TrnAccount AND Masters.companyCode = Transactions.companycode \r\n \t\t\tWHERE (Masters.companyCode = @comCode) AND (Transactions.yearcode = @YearCode) AND (Transactions.VchDate BETWEEN CONVERT(VARCHAR, @dayFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103))\t\t                       \r\n \t\t\tGROUP BY Masters.ledgerName, Masters.AccGroupName, Masters.AccGroupCode \r\n \t\t\tHAVING (SUM(Transactions.TrnAmount * Transactions.TrnEffect) <> 0) \r\n \t\t\tORDER BY Masters.AccGroupName, Masters.ledgerName \r\n \t\tEND\t \r\n ELSE\t\t\t\t\t\t\t\t--Selected Groups \r\n \tIF @ShowZeroAlso=1 \t\t\t--Selected Groups With Zero Values \r\n \t\tBEGIN \r\n \t\t\tSELECT TOP (100) PERCENT Masters.AccGroupName As 'Group Name', Masters.ledgerName As Particulars, \r\n \t\t\tCASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = - 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect *-1) AS FLOAT) ELSE '' END AS Debit,  \r\n \t\t\tCASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect) AS FLOAT) ELSE '' END AS Credit \r\n \t\t\tFROM (SELECT TOP (100) PERCENT MasterAccountsGroups.companyCode, MasterAccountsGroups.AccGroupName, MasterAccountsLedger.ledgerName, MasterAccountsGroups.AccGroupCode, MasterAccountsLedger.ledgerCode \r\n \t\t\tFROM MasterAccountsGroups RIGHT OUTER JOIN MasterAccountsLedger ON MasterAccountsGroups.AccGroupCode = MasterAccountsLedger.AccGroupCode AND MasterAccountsGroups.companyCode = MasterAccountsLedger.companyCode \r\n \t\t\tWHERE (MasterAccountsGroups.Hidden = 0)) AS Masters RIGHT OUTER JOIN (SELECT TransactionMain.companycode, TransactionMain.yearcode, TransactionMain.IndexId, TransactionMain.VchDate, TransactionDetail.TrnAccount,  \r\n \t\t\t\tTransactionDetail.TrnAmount, TransactionDetail.TrnEffect \r\n \t\t\tFROM TransactionDetail LEFT OUTER JOIN TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND \r\n \t\t\t\tTransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId \r\n \t\t\tUNION ALL \r\n \t\t\tSELECT companyCode, yearcode, 0 AS IndexId, EffectDate, ledgerCode AS TrnAccount, TrnAmount, TrnEffect \r\n \t\t\tFROM MasterAccountsOpening) AS Transactions ON Masters.ledgerCode = Transactions.TrnAccount AND Masters.companyCode = Transactions.companycode \r\n \t\t\tWHERE (Masters.companyCode = @comCode) AND (Transactions.yearcode = @YearCode) AND (Transactions.VchDate BETWEEN CONVERT(VARCHAR, @dayFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103)) \r\n \t\t\tGROUP BY Masters.ledgerName, Masters.AccGroupName, Masters.AccGroupCode \r\n \t\t\tHAVING (Masters.AccGroupCode = @GroupCode) \r\n \t\t\tORDER BY Masters.AccGroupName, Masters.ledgerName \r\n \t\tEND \r\n \tELSE\t\t\t\t\t\t\t--Selected Groups Without Zero Values \r\n \t\tBEGIN \r\n \t\t\tSELECT TOP (100) PERCENT Masters.AccGroupName As 'Group Name', Masters.ledgerName As Particulars,  \r\n \t\t\tCASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = - 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect * - 1) AS FLOAT) ELSE '' END AS Debit,  \r\n \t\t\tCASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect) AS FLOAT) ELSE '' END AS Credit \r\n \t\t\tFROM (SELECT TOP (100) PERCENT MasterAccountsGroups.companyCode, MasterAccountsGroups.AccGroupName, MasterAccountsLedger.ledgerName, MasterAccountsGroups.AccGroupCode, MasterAccountsLedger.ledgerCode \r\n \t\t\tFROM MasterAccountsGroups RIGHT OUTER JOIN MasterAccountsLedger ON MasterAccountsGroups.AccGroupCode = MasterAccountsLedger.AccGroupCode AND MasterAccountsGroups.companyCode = MasterAccountsLedger.companyCode \r\n \t\t\tWHERE (MasterAccountsGroups.Hidden = 0)) AS Masters RIGHT OUTER JOIN (SELECT TransactionMain.companycode, TransactionMain.yearcode, TransactionMain.IndexId, TransactionMain.VchDate, TransactionDetail.TrnAccount,  \r\n \t\t\t\tTransactionDetail.TrnAmount, TransactionDetail.TrnEffect \r\n \t\t\tFROM TransactionDetail LEFT OUTER JOIN TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND \r\n \t\t\t\tTransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId \r\n \t\t\tUNION ALL \r\n \t\t\tSELECT companyCode, yearcode, 0 AS IndexId, EffectDate, ledgerCode AS TrnAccount, TrnAmount, TrnEffect  \r\n \t\t\tFROM MasterAccountsOpening) AS Transactions ON Masters.ledgerCode = Transactions.TrnAccount AND Masters.companyCode = Transactions.companycode \r\n \t\t\tWHERE (Masters.companyCode = @comCode) AND (Transactions.yearcode = @YearCode) AND (Transactions.VchDate BETWEEN CONVERT(VARCHAR, @dayFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103)) \r\n \t\t\tGROUP BY Masters.ledgerName, Masters.AccGroupName, Masters.AccGroupCode \r\n \t\t\tHAVING (SUM(Transactions.TrnAmount * Transactions.TrnEffect) <> 0) AND (Masters.AccGroupCode = @GroupCode) \r\n \t\t\tORDER BY Masters.AccGroupName, Masters.ledgerName \r\n \t\tEND \r\n \t \r\n ------------------------------------------------------------------------------------ \r\n ------------------------------------------------------------------------------------ \r\n END \r\n";
					ob.insert(s);
