				if (Conversions.ToDouble(ob.executereader("IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[Sp_Tally_Journal]') AND type in (N'P', N'PC')) select 0 else select 1")) == 0.0)
				{
					s = "CREATE Procedure [dbo].[Sp_Tally_Journal] @companyCode varchar(6) ,@yearCode varchar(6),@dateFrom datetime,@dateTo datetime AS \r\n SELECT companycode, yearcode,TrnNo,VchDate, Amount, DebitorCreditor, case when isDebit = 1 then convert(bit,0) else CONVERT(bit,1) end as isDebit \r\n from \r\n (select TransactionDetail.companycode, TransactionDetail.yearcode,TransactionMain.TrnNo, convert(varchar(10),TransactionMain.VchDate,112) as VchDate, (TransactionDetail.TrnAmount * TransactionDetail.TrnEffect) as Amount, ledgerName as DebitorCreditor, TransactionDetail.TrnEffect as isDebit \r\n from TransactionDetail  \r\n inner join TransactionMain on TransactionDetail.companycode = TransactionMain.companycode and TransactionDetail.yearcode = TransactionMain.yearcode and TransactionDetail.restaurantCode = TransactionMain.restaurantCode and TransactionDetail.IndexId = TransactionMain.IndexId  \r\n inner join MasterAccountsLedger on TransactionDetail.companycode = MasterAccountsLedger.companyCode and TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode \r\n where TransactionDetail.TrnEffect = 1 and TransactionMain.TrnType = 'JOURNAL' and TransactionMain.companycode = @companyCode and TransactionMain.yearcode=@yearCode and  \r\n TransactionMain.VchDate >= @dateFrom and TransactionMain.VchDate <= @dateTo \r\n union all \r\n select TransactionDetail.companycode, TransactionDetail.yearcode,TransactionMain.TrnNo, convert(varchar(10),TransactionMain.VchDate,112) as VchDate, (TransactionDetail.TrnAmount * TransactionDetail.TrnEffect) as Amount, ledgerName as DebitorCreditor, TransactionDetail.TrnEffect as isDebit \r\n from TransactionDetail  \r\n inner join TransactionMain on TransactionDetail.companycode = TransactionMain.companycode and TransactionDetail.yearcode = TransactionMain.yearcode and TransactionDetail.restaurantCode = TransactionMain.restaurantCode and TransactionDetail.IndexId = TransactionMain.IndexId  \r\n inner join MasterAccountsLedger on TransactionDetail.companycode = MasterAccountsLedger.companyCode and TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode \r\n where TransactionDetail.TrnEffect = -1 and TransactionMain.TrnType = 'JOURNAL' and TransactionMain.companycode = @companyCode and TransactionMain.yearcode=@yearCode and  \r\n TransactionMain.VchDate >= @dateFrom and TransactionMain.VchDate <= @dateTo \r\n ) as X order by TrnNo ";
