				{
					s = "CREATE Procedure [dbo].[Sp_Tally_Receipt] @companyCode varchar(6) ,@yearCode varchar(6),@dateFrom datetime,@dateTo datetime AS \r\n SELECT companycode, yearcode,TrnNo as VchNo,VchDate, AmountPaid, AccountName,ChequeNo,Narration, case when isDebit = 1 then convert(bit,0) else CONVERT(bit,1) end as isDebit \r\n from \r\n (select TransactionDetail.companycode, TransactionDetail.yearcode,TransactionMain.TrnNo, convert(varchar(10),TransactionMain.VchDate,112) as VchDate, (TransactionDetail.TrnAmount * TransactionDetail.TrnEffect) as AmountPaid, ledgerName as AccountName, TransactionMain.ChequeNo,TransactionMain.Narration, TransactionDetail.TrnEffect as isDebit \r\n from TransactionDetail  \r\n inner join TransactionMain on TransactionDetail.companycode = TransactionMain.companycode and TransactionDetail.yearcode = TransactionMain.yearcode and TransactionDetail.restaurantCode = TransactionMain.restaurantCode and TransactionDetail.IndexId = TransactionMain.IndexId  \r\n inner join MasterAccountsLedger on TransactionDetail.companycode = MasterAccountsLedger.companyCode and TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode \r\n  where TransactionDetail.TrnEffect = 1 and TransactionMain.TrnType = 'RECEIPT' and TransactionMain.companycode = @companyCode and TransactionMain.yearcode=@yearCode and   \r\n  TransactionMain.VchDate >= @dateFrom and TransactionMain.VchDate <=@dateTo  \r\n union all \r\n select TransactionDetail.companycode, TransactionDetail.yearcode,TransactionMain.TrnNo, convert(varchar(10),TransactionMain.VchDate,112) as VchDate, (TransactionDetail.TrnAmount * TransactionDetail.TrnEffect) as AmountPaid, ledgerName as AccountName, TransactionMain.ChequeNo,TransactionMain.Narration, TransactionDetail.TrnEffect as isDebit \r\n from TransactionDetail  \r\n inner join TransactionMain on TransactionDetail.companycode = TransactionMain.companycode and TransactionDetail.yearcode = TransactionMain.yearcode and TransactionDetail.restaurantCode = TransactionMain.restaurantCode and TransactionDetail.IndexId = TransactionMain.IndexId  \r\n inner join MasterAccountsLedger on TransactionDetail.companycode = MasterAccountsLedger.companyCode and TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode \r\n  where TransactionDetail.TrnEffect = -1 and TransactionMain.TrnType = 'RECEIPT' and TransactionMain.companycode = @companyCode and TransactionMain.yearcode=@yearCode and   \r\n  TransactionMain.VchDate >= @dateFrom and TransactionMain.VchDate <=@dateTo  \r\n ) as X order by TrnNo ";
					ob.insert(s);
				}
				if (Conversion.Val(RuntimeHelpers.GetObjectValue(ob.populate("IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[sp_XciseDaily]') AND type in (N'P', N'PC')) select 0 else select 1").Tables[0].Rows[0][0])) > 0.0)
				{
					s = "Create procedure [dbo].[sp_XciseDaily] @ComCode as varchar(6),@yearCode as varchar(6),@ComStDate as date,@startDate as date,@endDate as date as  \r\n Delete from TempExcizeWeekly  \r\n declare @dateC date = @StartDate  \r\n while(@dateC<=@endDate)   \r\n BEGIN  \r\n Insert into TempExcizeWeekly  Select *  from (  \r\n  select  @dateC as StockDate,SpritType,SUM (x.[1-opening] ) as Opening,SUM(x.[2-Reciept] )as Reciept,SUM(x.[3-Sale] ) as Sale,SUM(x.[4-Closing] ) as Closing from (  \r\n --This Part Is For OTHER  \r\n select openingStockDetail .companyCode ,openingStockDetail.yearCode ,  \r\n case when  itemmst  .strengthname  = 'BEER' then 'Beer(IN BL)' else 'Foreign Liquor(IN BL)'end as SpritType,  \r\n (CONVERT(FLOAT,(isnull (openingStockDetail .opening_stock,0)*itemmst .ml ))/1000)  as [1-opening],  \r\n (CONVERT(FLOAT,(isnull (openingStockDetail .bottles_purchased,0)*itemmst .ml))/1000) as [2-Reciept],  \r\n (CONVERT(FLOAT,(isnull(openingStockDetail .bottles_sold,0)*itemmst .ml))/1000) as [3-Sale],  \r\n (CONVERT(FLOAT,(isnull(openingStockDetail .stock,0)*itemmst .ml))/1000) as [4-Closing]   \r\n from opening_closing_stock(@ComStDate,@dateC,@dateC) as openingStockDetail  \r\n inner join itemmst on openingStockDetail.companyCode =itemmst.companycode and openingStockDetail.itemCode =itemmst.itemcode   \r\n inner join kflmst on itemmst.companyCode =kflmst.companycode and itemmst.kflcode =kflmst.kflcode   \r\n where (kflmst.kflname<>'CS'AND kflmst.kflname<>'CFS') and   \r\n openingStockDetail.companycode in(select @ComCode AS comanyCode union all select mergeCompanyCode  AS companycode from ExizeCompany where companycode =@ComCode )  \r\n  AND openingStockDetail.yearcode in(select @yearCode as yearCode union all select yearcode from yearmst where companycode =@ComCode and stdate =@startDate and enddate=@endDate)   \r\n  union all  \r\n --This Part is for CS  \r\n select openingStockDetail .companyCode ,openingStockDetail.yearCode ,  \r\n case when kflmst.kflname='CS'or kflmst.kflname='CFS'   \r\n then 'Country Spirit(IN LPL)'  end as SpritType,  \r\n (CONVERT(FLOAT,(isnull (openingStockDetail .opening_stock,0)*itemmst .ml ))/100000) *(100-(CONVERT (float,left(itemmst .strengthname ,2)))) as [1-opening],  \r\n (CONVERT(FLOAT,(isnull (openingStockDetail .bottles_purchased,0)*itemmst .ml))/100000)*(100-(CONVERT (float,left(itemmst .strengthname ,2)))) as [2-Reciept],  \r\n (CONVERT(FLOAT,(isnull(openingStockDetail.bottles_sold ,0)*itemmst.ml ))/100000) *(100-(CONVERT (float,left(itemmst .strengthname ,2)))) as [3-Sale], \r\n (CONVERT(FLOAT,(isnull(openingStockDetail .stock,0)*itemmst .ml))/100000)*(100-(CONVERT (float,left(itemmst .strengthname ,2)))) as [4-Closing]   \r\n from opening_closing_stock(@ComStDate,@dateC,@dateC) as openingStockDetail  \r\n inner join itemmst on openingStockDetail.companyCode =itemmst.companycode and openingStockDetail.itemCode =itemmst.itemcode   \r\n inner join kflmst on itemmst.companyCode =kflmst.companycode and itemmst.kflcode =kflmst.kflcode   \r\n where (kflmst.kflname='CS'or kflmst.kflname='CFS') and   \r\n openingStockDetail.companycode in(select @ComCode AS comanyCode union all select mergeCompanyCode  AS companycode from ExizeCompany where companycode =@ComCode )  \r\n  AND openingStockDetail.yearcode in(select @yearCode as yearCode union all select yearcode from yearmst where companycode =@ComCode and stdate =@startDate and enddate=@endDate)   \r\n   ) as x  \r\n group by SpritType   \r\n ) as y  \r\n set @dateC =DATEADD(day,1,@datec)   \r\n end ";
				}
