				s = "CREATE procedure [dbo].[sp_xcise_statement1]@day1 as datetime,@day2 as datetime,@day3 as datetime ,@day4 as datetime,@day5 as datetime,@day6 as datetime as   \r\n  SELECT * INTO ##tempOpeningStock FROM opening_closing_stock(@day1,@day2,@day3 )   \r\n  select * into ##temp1 from(   \r\n  select companycode,yearcode, storecode,kflname,type,groupname,categoryname,ml,sum(qnty) as 'qnty' , strengthName     \r\n  from(     \r\n  select itemmst.companycode,yearcode, storecode,kflname,'1-Opening' as type,groupname,categoryname,ml,opening_stock as 'qnty',strengthName    \r\n  from ##tempOpeningStock as  opening_closing_stock  \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'2-Purchase' as type,groupname,categoryname,ml,bottles_purchased as 'qnty' , strengthName    \r\n  from ##tempOpeningStock as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'3-Total' as type,groupname,categoryname,ml,bottles_purchased+opening_stock as 'qnty' , strengthName    \r\n  from ##tempOpeningStock as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'4-Closing' as type,groupname,categoryname,ml,stock as 'qnty' , strengthName    \r\n  from ##tempOpeningStock as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'5-Difference' as type,groupname,categoryname,ml,bottles_sold as 'qnty' , strengthName    \r\n  from ##tempOpeningStock as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'6-Difference in BL' as type,groupname,categoryname,ml,convert(float,convert(float,ml*bottles_sold)/1000) as 'qnty' , strengthName    \r\n  from ##tempOpeningStock as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  Union all   \r\n  select itemmst.companycode,yearcode, storecode,kflname,'5-Difference' as type,groupname,categoryname,ml,breakage as 'qnty' , strengthName    \r\n  from ##tempOpeningStock as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'6-Difference in BL' as type,groupname,categoryname,ml,convert(float,convert(float,ml*breakage)/1000) as 'qnty' , strengthName    \r\n  from ##tempOpeningStock as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  ) as x group by companycode,yearcode, storecode,kflname,type,groupname,categoryname,ml,strengthName     \r\n  ) AS X   \r\n  SELECT * INTO ##tempOpeningStock_prev FROM opening_closing_stock(@day4,@day5,@day6)   \r\n  select * into ##temp2 from(   \r\n  select companycode,yearcode, storecode,kflname,type,groupname,categoryname,ml,sum(qnty) as 'qnty' , strengthName     \r\n  from(     \r\n  select itemmst.companycode,yearcode, storecode,kflname,'1-Opening' as type,groupname,categoryname,ml,opening_stock as 'qnty',strengthName    \r\n  from ##tempOpeningStock_prev as  opening_closing_stock  \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'2-Purchase' as type,groupname,categoryname,ml,bottles_purchased as 'qnty' , strengthName    \r\n  from ##tempOpeningStock_prev as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'3-Total' as type,groupname,categoryname,ml,bottles_purchased+opening_stock as 'qnty' , strengthName    \r\n  from ##tempOpeningStock_prev as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'4-Closing' as type,groupname,categoryname,ml,stock as 'qnty' , strengthName    \r\n  from ##tempOpeningStock_prev as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'5-Difference' as type,groupname,categoryname,ml,bottles_sold as 'qnty' , strengthName    \r\n  from ##tempOpeningStock_prev as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'6-Difference in BL' as type,groupname,categoryname,ml,convert(float,convert(float,ml*bottles_sold)/1000) as 'qnty' , strengthName    \r\n  from ##tempOpeningStock_prev as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  Union all   \r\n  select itemmst.companycode,yearcode, storecode,kflname,'5-Difference' as type,groupname,categoryname,ml,breakage as 'qnty' , strengthName    \r\n  from ##tempOpeningStock_prev as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  union all    \r\n  select itemmst.companycode,yearcode, storecode,kflname,'6-Difference in BL' as type,groupname,categoryname,ml,convert(float,convert(float,ml*breakage)/1000) as 'qnty' , strengthName    \r\n  from ##tempOpeningStock_prev as  opening_closing_stock    \r\n  right outer join itemmst on itemmst.itemcode=opening_closing_stock.itemcode and itemmst.companycode=opening_closing_stock.companycode    \r\n  right outer join groupmst on groupmst.groupcode=itemmst.groupcode and groupmst.companycode=itemmst.companycode    \r\n  right outer join categorymst on categorymst.categorycode=itemmst.categorycode and categorymst.companycode=itemmst.companycode    \r\n  right outer join kflmst on kflmst.companycode=itemmst.companycode and kflmst.kflcode=itemmst.kflcode    \r\n  ) as x group by companycode,yearcode, storecode,kflname,type,groupname,categoryname,ml,strengthName     \r\n  ) as Y  ";
