				if (Conversion.Val(RuntimeHelpers.GetObjectValue(ob.populate("IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[Fnc_Sale]') AND type in (N'FN', N'IF', N'TF', N'FS', N'FT'))Select 0 else select 1 ").Tables[0].Rows[0][0])) > 0.0)
				{
					s = "CREATE function [dbo].[Fnc_Sale](@dateFrom VARCHAR(10), @dateTo VARCHAR(10) , @comCode varchar(6) , @YearCode varchar(6)) returns table as return   \r\n select salestype,sum(bottles_sold) as bottles_sold,sum(large) as large,sum(small) as small,sum(westage)as westage,sum(total_amount)as total_amount, companycode,yearcode,trndate,userCode,userName,itemType  \r\n from (   \r\n   \r\n select salestype,qnty as BOTTLES_SOLD,isnull(large,0) as large,isnull(small,0)as small, isnull(westage,0) as westage,itemamount as TOTAL_AMOUNT,  salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.trndate,users.userCode, users.userName, \r\n case when salesbillMain.billtype = 0 then 'FL'  when salesbillMain.billtype = 1 then 'CS' else 'NAI' end as itemType      \r\n from salesbillmain   \r\n Inner Join trnIdmst on salesBillMain.companyCode = trnIdmst.companyCode and salesBillMain.yearCode = trnIdmst.yearCode and salesBillMain.trnid = trnidmst.trnid    \r\n Inner Join users on trnIdmst.userCode = users.userCode    \r\n join salesbilldetail  on salesbillmain.companycode=salesbilldetail.companycode and salesbillmain.yearcode = salesbilldetail.yearcode AND salesBillMain.billType = salesBillDetail.billType And salesbillmain.trndate = salesbilldetail.trndate and salesbillmain.trnno=salesbilldetail.trnno  \r\n join itemmst on salesbilldetail.companycode=itemmst.companycode and itemmst.itemcode=salesbilldetail.itemcode       \r\n where salesbillmain.companycode = @comCode and salesbillmain.yearcode = @YearCode and salesbillmain.trndate >= @dateFrom and salesbillmain.trndate <= @dateTo  \r\n union all   \r\n select 'DISCOUNT' as saletype,'0' as bottles_sold,'0' as large,'0' as small , '0' as westage,discamount as total_amount, salesbillmain.companycode,salesbillmain.yearcode,trndate ,users.userCode,users.userName , \r\n case when salesbillMain.billtype = 0 then 'FL'  when salesbillMain.billtype = 1 then 'CS' else 'NAI' end as itemType      \r\n from salesbillmain     \r\n Inner Join trnIdmst on salesBillMain.companyCode = trnIdmst.companyCode and salesBillMain.yearCode = trnIdmst.yearCode and salesBillMain.trnid = trnidmst.trnid    \r\n Inner Join users on trnIdmst.userCode = users.userCode      \r\n where salesbillmain.companycode = @comCode and salesbillmain.yearcode = @YearCode and salesbillmain.trndate >= @dateFrom and salesbillmain.trndate <= @dateTo and salestype<>'RETURN' and discamount<>0 \r\n union all  \r\n select 'DISCOUNT' as saletype,'0' as bottles_sold,'0' as large,'0' as small , '0' as westage,(-1)*discamount as total_amount,salesbillmain.companycode,salesbillmain.yearcode,trndate   ,users.userCode,users.userName, \r\n case when salesbillMain.billtype = 0 then 'FL'  when salesbillMain.billtype = 1 then 'CS' else 'NAI' end as itemType      \r\n from salesbillmain     \r\n Inner Join trnIdmst on salesBillMain.companyCode = trnIdmst.companyCode and salesBillMain.yearCode = trnIdmst.yearCode and salesBillMain.trnid = trnidmst.trnid    \r\n Inner Join users on trnIdmst.userCode = users.userCode  \r\n where salesbillmain.companycode = @comCode and salesbillmain.yearcode = @YearCode and salesbillmain.trndate >= @dateFrom and salesbillmain.trndate <= @dateTo and salestype='RETURN' and discamount<>0   \r\n union all     \r\n select 'EXPENCE' as saletype,'0' as BOTTLES_SOLD,'0' as large,'0' as small , '0' as westage,TransactionDetail.TrnAmount as total_amount,TransactionMain.companycode as companycode,TransactionMain.yearcode as yearcode, TransactionMain.vchdate as trndate ,'' as userCode,'' as userName,'NONE'as itemType    \r\n from TransactionMain      \r\n join TransactionDetail on TransactionMain.companycode=TransactionDetail.companycode and TransactionMain.yearcode=TransactionDetail.yearcode and TransactionMain.IndexId =TransactionDetail.IndexId and TransactionDetail.TrnEffect = -1      \r\n where TransactionMain.companycode = @comCode and TransactionMain.yearcode = @YearCode and TransactionMain.VchDate >= @dateFrom and TransactionMain.VchDate  <= @dateTo and TransactionMain.TrnType = 'JOURNAL' and TransactionMain.ReceiptType = 'EXPENCE' \r\n )as x \r\n group by salestype,companycode,yearcode,trndate,x.userCode,x.userName,x.itemType  ";
