ype = 'CS' and salestype <> 'DISCOUNT' AND salestype <> 'EXPENCE'   \r\n  \t\t\tgroup by salestype    \r\n  \t\t\tunion all  \r\n  \t\t\tselect salestype, '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, '0' as CS_bottles,'0' as CS_Peg , '0' as CS_amount,  sum(bottles_sold) as NAI_Qnty, SUM(total_amount) as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)   \r\n  \t\t\twhere itemType = 'NAI' and salestype <> 'DISCOUNT' AND  salestype <> 'EXPENCE'   \r\n  \t\t\tgroup by salestype  \r\n  \t\t) as x   group by salestype  \r\n  \t\tunion all  \r\n  \t\tselect 'NET' as salestype , '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, '0' as CS_bottles , '0' as CS_Peg,'0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount ,(select SUM(total_amount) as Total   \r\n  \t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)    \r\n  \t\twhere salestype = 'CASH' or salestype = 'CREDIT ACCOUNT' or salestype = 'CREDIT CARD')  \r\n  \t\tunion all  \r\n  \t\tselect salestype,'0' as FL_bottles,'0' as FL_Peg,'0' as FL_amount,'0' as CS_bottles,'0' as CS_Peg,'0' as CS_amount, '0' as NAI_Qnty,'0' as NAI_amount,sum(total_amount) as Total   \r\n  \t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)   \r\n  \t\twhere salestype = 'EXPENCE'    \r\n  \t\tgroup by  salestype  \r\n  \t\tunion all  \r\n  \t\tselect 'Cash Ledger Closing' as salestype,'0' as FL_bottles, '0' as FL_Peg , '0' FL_amount, '0' as CS_bottles,'0' as CS_Peg , '0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount, (sum(debit) - sum(credit)) as Total   \r\n  \t\tfrom #temp   \r\n  \tend  \r\n  else  \r\n  \tbegin  \r\n  \t\tselect salestype,sum(FL_bottles)as FL_bottles,sum(FL_Peg)as FL_Peg,sum(FL_amount) as FL_amount,sum(CS_bottles) as CS_bottles,sum(CS_Peg) as CS_Peg, sum(CS_amount) as CS_amount, sum(NAI_Qnty) as NAI_Qnty,sum(NAI_amount) as NAI_amount,sum(FL_amount + CS_amount + NAI_amount) as Total   \r\n  \t\tfrom(  \r\n  \t\t\tselect userName,salestype, SUM(bottles_sold) as FL_bottles, sum(large + (small * 0.5)) as FL_Peg ,  SUM(total_amount)as FL_amount, '0' as CS_bottles, '0' as CS_Peg, '0' as CS_amount,  '0' as NAI_Qnty, '0' as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)  \r\n  \t\t\twhere itemType = 'FL'   \r\n  \t\t\tgroup by  salestype, userName  \r\n  \t\t\tunion all  \r\n  \t\t\tselect  userName,salestype, '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, SUM(bottles_sold) as CS_bottles,sum(large + (small * 0.5)) as CS_Peg , SUM(total_amount)as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)  \r\n  \t\t\twhere itemType = 'CS'   \r\n  \t\t\tgroup by salestype , userName  \r\n  \t\t\tunion all  \r\n  \t\t\tselect userName,salestype, '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, '0' as CS_bottles,'0' as CS_Peg , '0' as CS_amount, sum (bottles_sold) as NAI_Qnty, SUM(total_amount) as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)   \r\n  \t\t\twhere itemType = 'NAI'   \r\n  \t\t\tgroup by   \r\n  \t\t\tsalestype,userName   \r\n  \t\t\t) as x where salestype <> 'DISCOUNT' AND salestype <> 'EXPENCE' and userName = @username group by  salestype  \r\n  \t\t\tunion all  \r\n  \t\t\tselect 'NET' as salestype , '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, '0' as CS_bottles , '0' as CS_Peg,'0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount ,(select SUM(total_amount) as Total   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)    \r\n  \t\t\twhere salestype = 'CASH' or salestype = 'CREDIT ACCOUNT' or salestype = 'CREDIT CARD' and userName = @username   \r\n  \t\t\t)  \r\n  \t\tunion all  \r\n  \t\tselect salestype,'0' as FL_bottles,'0' as FL_Peg,'0' as FL_amount,'0' as CS_bottles,'0' as CS_Peg,'0' as CS_amount, '0' as NAI_Qnty,'0' as NAI_amount,sum(total_amount) as Total   \r\n  \t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)   \r\n  \t\twhere salestype = 'EXPENCE'  \r\n  \t\tgroup by salestype  \r\n  \t\tunion all  \r\n  \t\tselect 'Cash Ledger Closing' as salestype,'0' as FL_bottles, '0' as FL_Peg , '0' FL_amount, '0' as CS_bottles,'0' as CS_Peg , '0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount, (sum(debit) - sum(credit)) as Total   \r\n  \t\tfrom #temp   \r\n  \tend  \r\n  drop table #temp  ";
