				{
					s = "create function opening_stock_show2(@y varchar(6),@c varchar(6),@s varchar(6)) returns table \r\n as \r\n return \r\n select @s as shopcode,itemcode,itemname,companycode,yearcode,sum(loose)as loose,sum(box) as box,sum(qnty)as qnty,sum(rate) as rate,SUM(totalAmt) as totalAmt \r\n from( \r\n select  \r\n shopcode,itemmst.itemname,itemmst.itemcode,itemmst.companycode,yearcode,sum(loose)as loose,sum(box) as box,sum(qnty)as qnty ,sum(ISNULL( openingstockmst.purchaseRate,0) )as rate,sum(ISNULL( openingstockmst.purchaseRate,0) )as totalAmt \r\n from openingstockmst \r\n join itemmst \r\n on openingstockmst.companycode=itemmst.companycode \r\n and openingstockmst.itemcode=itemmst.itemcode \r\n where yearcode=@y and itemmst.companycode=@c and shopcode=@s \r\n group by shopcode,itemmst.itemcode,itemname,itemmst.companycode,yearcode \r\n union all \r\n select @s as shopcode,itemname,itemcode,companycode,@y as yearcode,'0' as loose,'0' as box,'0' as qnty,'0' as  rate,'0' as totalAmt \r\n from itemmst \r\n where companycode=@c \r\n group by itemcode,itemname,companycode \r\n )x group by shopcode,itemcode,itemname,companycode,yearcode ";
