				ob.insert(s);
				s = "alter view [dbo].[vw_ratemst] as \r\n select companycode,ratecode,itemcode,itemname,sum(salesrate) as salesrate,kflname as itemType from( \r\n select itemmst.companycode,ratecode,itemcode,itemname,'0' as salesrate,itemmst.kflname \r\n from vw_itemCodebarCode AS itemmst join  \r\n itemrateinfo \r\n on itemrateinfo.companycode=itemmst.companycode \r\n union all \r\n select itemratemst.companycode,ratecode,itemratemst.itemcode,itemname,itemratemst.salesrate ,itemmst.kflname \r\n from itemratemst \r\n join vw_itemCodebarCode AS itemmst on itemratemst.itemcode=itemmst.itemcode \r\n and itemmst.companycode=itemratemst.companycode \r\n ) as x \r\n group by companycode,ratecode,itemcode,itemname,kflname  ";
				if (Conversion.Val(RuntimeHelpers.GetObjectValue(ob.populate("IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[FUN_OpeningClosing]') AND type in (N'FN', N'IF', N'TF', N'FS', N'FT'))Select 0 else select 1 ").Tables[0].Rows[0][0])) > 0.0)
				{
					s = "CREATE FUNCTION [dbo].[FUN_OpeningClosing] \r\n ( \r\n @reportName AS VARCHAR(50), \r\n @particular AS VARCHAR(50), \r\n @comCode AS VARCHAR(6), \r\n @yearCode AS VARCHAR(6), \r\n @comStDate AS DATE, \r\n @endDate AS DATE, \r\n @type AS VARCHAR(50), \r\n @trnType AS VARCHAR(50)  \r\n )  \r\n RETURNS TABLE \r\n AS \r\n RETURN \r\n SELECT '2' AS GroupNo,@reportName AS ReportName,@particular AS Particular,'0' AS Bottle,'0' AS Litre, \r\n \t\tSUM(x.TrnAmount) AS NetAmount FROM \r\n  ( \r\n \t\tSELECT @type AS Particular, \r\n \t\tSUM(TransactionDetail.TrnAmount)*(-1) AS TrnAmount  \r\n \t\tFROM TransactionDetail  \r\n \t\tINNER JOIN vw_accGroupNameFromLedgerCode AGNFLC ON AGNFLC.companyCode=TransactionDetail.companycode \r\n \t\tAND AGNFLC.ledgerCode=TransactionDetail.TrnAccount \r\n \t\tINNER JOIN TransactionMain ON TransactionMain.companycode=TransactionDetail.companycode \r\n \t\tAND TransactionMain.yearcode=TransactionDetail.yearcode \r\n \t\tAND TransactionMain.restaurantCode=TransactionDetail.restaurantCode \r\n \t\tAND TransactionMain.IndexId=TransactionDetail.IndexId \r\n \t\tWHERE AGNFLC.companyCode=@comCode AND TransactionDetail.yearcode=@yearCode and AGNFLC.AccGroupName  like @trnType \r\n \t\tAND TransactionDetail.TrnEffect='-1' \r\n \t\tAND TransactionMain.VchDate>=@comStDate AND TransactionMain.VchDate<=@endDate \r\n \t\tGROUP BY AGNFLC.AccGroupName \r\n \t\tUNION ALL \r\n \t\tSELECT @type AS Particular, \r\n \t\tSUM(TransactionDetail.TrnAmount) AS TrnAmount  \r\n \t\tFROM TransactionDetail  \r\n \t\tINNER JOIN vw_accGroupNameFromLedgerCode AGNFLC ON AGNFLC.companyCode=TransactionDetail.companycode \r\n \t\tAND AGNFLC.ledgerCode=TransactionDetail.TrnAccount \r\n \t\tINNER JOIN TransactionMain ON TransactionMain.companycode=TransactionDetail.companycode \r\n \t\tAND TransactionMain.yearcode=TransactionDetail.yearcode \r\n \t\tAND TransactionMain.restaurantCode=TransactionDetail.restaurantCode \r\n \t\tAND TransactionMain.IndexId=TransactionDetail.IndexId \r\n \t\tWHERE AGNFLC.companyCode=@comCode AND TransactionDetail.yearcode=@yearCode and AGNFLC.AccGroupName  like @trnType \r\n \t\tAND TransactionDetail.TrnEffect='1' \r\n \t\tAND TransactionMain.VchDate>=@comStDate AND TransactionMain.VchDate<=@endDate \r\n \t\tGROUP BY AGNFLC.AccGroupName \r\n \t) AS x  \r\n \tGROUP BY x.Particular ";
