 itemmst.groupcode = groupmst.groupcode \r\n   group by purchasemain.companycode ,purchasemain.yearcode ,purchasemain.trndate,purchasemain.suppliercode,ledgerName,purchasemain.docno,purchasedetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode,categoryname,itemmst.groupcode,groupname \r\n    \r\n   union all \r\n    \r\n   SELECT purchasemain.companycode ,purchasemain.yearcode ,purchasemain.trndate,purchasemain.suppliercode,ledgerName as Account,  (sum(isnull(convert(float,(itemquantity * ml))/1000,0)))  as Litre ,purchasemain.docno as BillNo,sum(purchasedetail.itemAmount)as Amount ,purchasedetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode as BrandCode,categoryname as Brand , \r\n itemmst.groupcode as CategoryCode,groupname as Category \r\n FROM  purchasemain \r\n inner join purchasedetail on purchasemain.companycode = purchasedetail.companycode and purchasemain.yearcode = purchasedetail.yearcode and purchasemain.trndate = purchasedetail.trndate and purchasemain.trnno = purchasedetail.trnno  \r\n join MasterAccountsLedger on purchasemain.companycode = MasterAccountsLedger.companyCode and purchasemain.suppliercode = MasterAccountsLedger.ledgerCode join itemmst on purchasedetail.companycode = itemmst.companycode and purchasedetail.itemcode = itemmst.itemcode  \r\n  join kflmst on itemmst.companycode = kflmst.companycode and itemmst.kflcode = kflmst.kflcode and kflname <> 'CS' \r\n  join categorymst on itemmst.companycode = categorymst.companycode and itemmst.categorycode = categorymst.categorycode \r\n  join groupmst on itemmst.companycode = groupmst.companycode and itemmst.groupcode = groupmst.groupcode \r\n   group by purchasemain.companycode ,purchasemain.yearcode ,purchasemain.trndate,purchasemain.suppliercode,ledgerName,purchasemain.docno,purchasedetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode,categoryname,itemmst.groupcode,groupname \r\n   ) as X \r\n  where x.companycode = @CompanyCode and x.yearcode = @