				{
					s = "CREATE procedure [dbo].[Sp_SchemeDetails]  \r\n (@Companycode varchar(6), @YearCode varchar(6), @datefrom datetime, @dateto datetime ) \r\n as begin \r\n select 0 as [check], categoryname as Brand,ManufacturerName as Manufacturer, ledgername as Supplier, itemname, sum(itembox) as [Case] ,   \r\n sum(isnull(itemloose,0)) as Bottle, sum(isnull(itemfreeqnty,0)) as freeQuantity,  docno as Billno,convert(varchar,purchasemain.trndate,103) as Date, purchasedetail.batchno as BatchNo,purchasedetail.itemrate as Rate, isnull(purchasedetail.itemdiscount,0) as Discount , purchasedetail.itemamount as Amount, totnetamt as NetAmount   from purchasemain  \r\n join purchasedetail on purchasemain.companycode = purchasedetail.companycode and purchasemain.yearcode =purchasedetail.yearcode and purchasemain.trnno =purchasedetail.trnno \r\n join MasterAccountsLedger on purchasemain.companycode = MasterAccountsLedger.companyCode and purchasemain.suppliercode = MasterAccountsLedger.ledgerCode  \r\n join itemmst on purchasedetail.companycode = itemmst.companycode and purchasedetail.itemcode = itemmst.itemcode \r\n join categorymst on itemmst.companycode =categorymst.companycode and itemmst.categorycode = categorymst.categorycode  \r\n join ManufacturerMaster on categorymst.companycode = ManufacturerMaster.Companycode and categorymst.ManufacturerCode = ManufacturerMaster.ManufacturerCode  \r\n where purchasemain.companycode = @Companycode and purchasemain.yearcode = @YearCode and docdate >= @datefrom and docdate <= @dateto \r\n group by itemfreeqnty,docno,purchasemain.trndate,batchno,itemrate,itemdiscount ,itemamount ,totnetamt,categoryname,ManufacturerName,ledgerName,itemname \r\n end ";
				}
