				ob.insert(s);
				if (Conversion.Val(RuntimeHelpers.GetObjectValue(ob.populate("IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[GroupDetails]') AND type in (N'P', N'PC'))Select 0 else select 1").Tables[0].Rows[0][0])) > 0.0)
				{
					s = "CREATE PROCEDURE    \r\n   \t[dbo].[GroupDetails] @comCode varchar(6), @YearCode varchar(6), @dayFrom VARCHAR(10), @dateTo VARCHAR(10), @GroupCode varchar(6), @ShowZeroAlso Bit , @Type varchar(20) = '' \r\n   \tas Begin   \r\n  IF @ShowZeroAlso=1 \t\t\t--Selected Groups With Zero Values   \r\n  BEGIN   \r\n   \tIF \t @Type = 'DEBTOR' \r\n   \tBegin \r\n  select  AccGroupCode,AccGroupName as 'Group Name',ledgerName as Particulars, abs(sum(opening)) as 'Opening Balance',abs(sum(sale)) as 'Bill Amount', abs(sum(receipt)) as Receipt,   --ABS(SUM(ClosingBalance)) as 'Closing Balance'  \r\n  ABS(SUM(Debit)) as Debit,ABS(SUM(Credit)) as Credit  \r\n  from  \r\n  (  \r\n  SELECT  MasterAccountsGroups.AccGroupCode , MasterAccountsGroups.AccGroupName , MasterAccountsLedger.ledgerName , (TrnAmount * TrnEffect) as Opening, 0 as Sale, 0 as Receipt,  \r\n  --0 as ClosingBalance  \r\n  0 AS Debit, 0 AS Credit   \r\n  FROM MasterAccountsOpening   \r\n  Inner Join MasterAccountsLedger on MasterAccountsOpening.companyCode = MasterAccountsLedger.companyCode and MasterAccountsOpening.ledgerCode =MasterAccountsLedger.ledgerCode    \r\n  Inner Join MasterAccountsGroups on MasterAccountsGroups.companyCode = MasterAccountsLedger.companyCode and MasterAccountsGroups.AccGroupCode = MasterAccountsLedger.AccGroupCode  \r\n  where MasterAccountsOpening.companyCode =@comCode and yearcode =@YearCode and EffectDate <= @dayFrom and AccGroupName Like '%DEBTOR%'   \r\n  union all  \r\n  select MasterAccountsGroups.AccGroupCode,MasterAccountsGroups.AccGroupName , MasterAccountsLedger.ledgerName , 0 as Opening, (TransactionDetail.TrnAmount* TransactionDetail.TrnEffect ) as Sale, 0 as Receipt,  \r\n  --0 as ClosingBalance   \r\n  0 AS Debit, 0 AS Credit   \r\n  from TransactionDetail   \r\n  Inner Join TransactionMain on TransactionDetail.companycode = TransactionMain.companycode and TransactionDetail.yearcode = TransactionMain.yearcode and TransactionDetail.IndexId = TransactionMain.IndexId and TransactionMain.TrnType ='SALE'  \r\n  Inner Join MasterAccountsLedger on TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode    \r\n  Inner Join MasterAccountsGroups on MasterAccountsGroups.companyCode = MasterAccountsLedger.companyCode and MasterAccountsGroups.AccGroupCode = MasterAccountsLedger.AccGroupCode  \r\n  WHERE (TransactionMain.companyCode =@comCode) AND (TransactionMain.yearcode = @YearCode) AND (TransactionMain.VchDate BETWEEN CONVERT(VARCHAR, @dayFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103)) and AccGroupName Like '%DEBTOR%'  \r\n  union all  \r\n  select MasterAccountsGroups.AccGroupCode,MasterAccountsGroups.AccGroupName , MasterAccountsLedger.ledgerName , 0 as Opening, 0 as Sale, (TransactionDetail.TrnAmount* TransactionDetail.TrnEffect ) as Receipt,  \r\n  --0 as ClosingBalance   \r\n  0 AS Debit, 0 AS Credit   \r\n  from TransactionDetail   \r\n  Inner Join TransactionMain on TransactionDetail.companycode = TransactionMain.companycode and TransactionDetail.yearcode = TransactionMain.yearcode and TransactionDetail.IndexId = TransactionMain.IndexId and TransactionMain.TrnType ='RECEIPT'  \r\n  Inner Join MasterAccountsLedger on TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode    \r\n  Inner Join MasterAccountsGroups on MasterAccountsGroups.companyCode = MasterAccountsLedger.companyCode and MasterAccountsGroups.AccGroupCode = MasterAccountsLedger.AccGroupCode  \r\n  WHERE (TransactionMain.companyCode =@comCode) AND (TransactionMain.yearcode = @YearCode) AND (TransactionMain.VchDate BETWEEN CONVERT(VARCHAR, @dayFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103)) and AccGroupName Like '%DEBTOR%'  \r\n  Union All  \r\n  SELECT TOP (100) PERCENT Masters.AccGroupCode,Masters.AccGroupName , Masters.ledgerName , 0 as opening,0 AS  Sale,0 AS Receipt,  \r\n  --SUM(Transactions.TrnAmount * Transactions.TrnEffect) AS ClosingBalance  \r\n  CASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = - 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect *-1) AS FLOAT) ELSE '' END AS Debit,    \r\n   \t\t\tCASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect) AS FLOAT) ELSE '' END AS Credit   \r\n  FROM (SELECT TOP (100) PERCENT MasterAccountsGroups.companyCode, MasterAccountsGroups.AccGroupName, MasterAccountsLedger.ledgerName, MasterAccountsGroups.AccGroupCode, MasterAccountsLedger.ledgerCode   \r\n  FROM MasterAccountsGroups RIGHT OUTER JOIN MasterAccountsLedger ON MasterAccountsGroups.AccGroupCode = MasterAccountsLedger.AccGroupCode AND MasterAccountsGroups.companyCode = MasterAccountsLedger.companyCode   \r\n  WHERE (MasterAccountsGroups.Hidden = 0) ) AS Masters   \r\n  RIGHT OUTER JOIN (SELECT TransactionMain.companycode, TransactionMain.yearcode, TransactionMain.IndexId, TransactionMain.VchDate, TransactionDetail.TrnAccount,    \r\n  TransactionDetail.TrnAmount, TransactionDetail.TrnEffect   \r\n  FROM TransactionDetail LEFT OUTER JOIN TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND   \r\n  TransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId   \r\n  UNION ALL   \r\n  SELECT companyCode, yearcode, 0 AS IndexId, EffectDate, ledgerCode AS TrnAccount, TrnAmount, TrnEffect   \r\n  FROM MasterAccountsOpening) AS Transactions   \r\n  ON Masters.ledgerCode = Transactions.TrnAccount AND Masters.companyCode = Transactions.companycode   \r\n  WHERE (Masters.companyCode =@comCode) AND (Transactions.yearcode = @YearCode) AND (Transactions.VchDate BETWEEN CONVERT(VARCHAR, @dayFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103)) and AccGroupName Like '%DEBTOR%'  \r\n  GROUP BY Masters.ledgerName, Masters.AccGroupName, Masters.AccGroupCode ,ledgerCode   \r\n  ORDER BY Masters.AccGroupName, Masters.ledgerName  \r\n  ) as x   \r\n  where AccGroupCode = @Gro