TrnAmount * Transactions.TrnEffect *-1) AS FLOAT) ELSE '' END AS Debit,    \r\n   \t\t\tCASE WHEN SIGN(SUM(Transactions.TrnAmount * Transactions.TrnEffect)) = 1 THEN CAST(SUM(Transactions.TrnAmount * Transactions.TrnEffect) AS FLOAT) ELSE '' END AS Credit   \r\n  FROM (SELECT TOP (100) PERCENT MasterAccountsGroups.companyCode, MasterAccountsGroups.AccGroupName, MasterAccountsLedger.ledgerName, MasterAccountsGroups.AccGroupCode, MasterAccountsLedger.ledgerCode   \r\n  FROM MasterAccountsGroups RIGHT OUTER JOIN MasterAccountsLedger ON MasterAccountsGroups.AccGroupCode = MasterAccountsLedger.AccGroupCode AND MasterAccountsGroups.companyCode = MasterAccountsLedger.companyCode   \r\n  WHERE (MasterAccountsGroups.Hidden = 0) ) AS Masters   \r\n  RIGHT OUTER JOIN (SELECT TransactionMain.companycode, TransactionMain.yearcode, TransactionMain.IndexId, TransactionMain.VchDate, TransactionDetail.TrnAccount,    \r\n  TransactionDetail.TrnAmount, TransactionDetail.TrnEffect   \r\n  FROM TransactionDetail LEFT OUTER JOIN TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND   \r\n  TransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId   \r\n  UNION ALL   \r\n  SELECT companyCode, yearcode, 0 AS IndexId, EffectDate, ledgerCode AS TrnAccount, TrnAmount, TrnEffect   \r\n  FROM MasterAccountsOpening) AS Transactions   \r\n  ON Masters.ledgerCode = Transactions.TrnAccount AND Masters.companyCode = Transactions.companycode   \r\n  WHERE (Masters.companyCode =@comCode) AND (Transactions.yearcode = @YearCode) AND (Transactions.VchDate BETWEEN CONVERT(VARCHAR, @dayFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103)) and AccGroupName Like '%DEBTOR%'  \r\n  GROUP BY Masters.ledgerName, Masters.AccGroupName, Masters.AccGroupCode ,ledgerCode   \r\n  ORDER BY Masters.AccGroupName, Masters.ledgerName  \r\n  ) as x   \r\n  where AccGroupCode = @Grou