					s = "ALTER PROCEDURE  [dbo].[SP_SaleNewFORsALESdETAILS] @dateFrom VARCHAR(10), @dateTo VARCHAR(10) , @comCode varchar(6) , @YearCode varchar(6)  , @LedgerCode varchar(6) , @username varchar(20) as  \r\n  create table #temp  \r\n  (  \r\n  OrderNo int,  \r\n  VchDate datetime,  \r\n  TrnType varchar(50),  \r\n  TrnNo varchar(200),  \r\n  Particulars varchar(50),  \r\n  LedgerEffected varchar (50),  \r\n  SubAmount float,  \r\n  Debit float,  \r\n  Credit float,  \r\n  ReceiptType varchar(50),  \r\n  ChequeNo varchar(50),  \r\n  CardNo varchar(50),  \r\n  TransactionIDDetails varchar(50),  \r\n  Narration varchar(50)  \r\n  )  \r\n  insert into #temp (OrderNo,VchDate,TrnType,TrnNo,Particulars,LedgerEffected,SubAmount,Debit,Credit,ReceiptType,ChequeNo,CardNo,TransactionIDDetails,Narration)   \r\n  exec [LedgerBalanceNew] @dateFrom, @dateTo, @comCode, @YearCode, @LedgerCode  \r\n  --select * from #temp  \r\n  if @username = ''  \r\n  \tbegin  \r\n  \tdelete from TempCounterSale \r\n  \tinsert into TempCounterSale \r\n  \t\tselect salestype,sum(FL_bottles)as FL_bottles,sum(FL_Peg)as FL_Peg,sum(FL_amount) as FL_amount,sum(CS_bottles) as CS_bottles,sum(CS_Peg) as CS_Peg,sum(CS_amount) as CS_amount, sum(NAI_Qnty) as NAI_Qnty,sum(NAI_amount) as NAI_amount,sum(FL_amount + CS_amount + NAI_amount) as Total   \r\n  \t\tfrom(  \r\n  \t\t\tselect  salestype, SUM(bottles_sold) as FL_bottles, sum(large + (small * 0.5)) as FL_Peg ,  SUM(total_amount)as FL_amount, '0' as CS_bottles, '0' as CS_Peg, '0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)  \r\n  \t\t\twhere  itemType = 'FL' and salestype <> 'DISCOUNT' AND salestype <> 'EXPENCE'   \r\n  \t\t\tgroup by salestype   \r\n  \t\t\tunion all  \r\n  \t\t\tselect salestype, '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, SUM(bottles_sold) as CS_bottles,sum(large + (small * 0.5)) as CS_Peg , SUM (total_amount)as CS_amount,  '0' as NAI_Qnty, '0' as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)  \r\n  \t\t\twhere itemType = 'CS' and salestype <> 'DISCOUNT' AND salestype <> 'EXPENCE'   \r\n  \t\t\tgroup by salestype    \r\n  \t\t\tunion all  \r\n  \t\t\tselect salestype, '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, '0' as CS_bottles,'0' as CS_Peg , '0' as CS_amount,  sum(bottles_sold) as NAI_Qnty, SUM(total_amount) as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)   \r\n  \t\t\twhere itemType = 'NAI' and salestype <> 'DISCOUNT' AND  salestype <> 'EXPENCE'   \r\n  \t\t\tgroup by salestype  \r\n  \t\t) as x   group by salestype  \r\n  \t\tunion all  \r\n  \t\tselect 'NET' as salestype , '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, '0' as CS_bottles , '0' as CS_Peg,'0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount ,(select SUM(total_amount) as Total   \r\n  \t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)    \r\n  \t\twhere salestype = 'CASH' or salestype = 'CREDIT ACCOUNT' or salestype = 'CREDIT CARD')  \r\n  \t\tunion all  \r\n  \t\tselect salestype,'0' as FL_bottles,'0' as FL_Peg,'0' as FL_amount,'0' as CS_bottles,'0' as CS_Peg,'0' as CS_amount, '0' as NAI_Qnty,'0' as NAI_amount,sum(total_amount) as Total   \r\n  \t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)   \r\n  \t\twhere salestype = 'EXPENCE'    \r\n  \t\tgroup by  salestype  \r\n  \t\tunion all  \r\n  \t\tselect 'Cash Ledger Closing' as salestype,'0' as FL_bottles, '0' as FL_Peg , '0' FL_amount, '0' as CS_bottles,'0' as CS_Peg , '0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount, (sum(debit) - sum(credit)) as Total   \r\n  \t\tfrom #temp   \r\n  \tend  \r\n  else  \r\n  \tbegin  \r\n  \tdelete from TempCounterSale \r\n  \tinsert into TempCounterSale \r\n  \t\tselect salestype,sum(FL_bottles)as FL_bottles,sum(FL_Peg)as FL_Peg,sum(FL_amount) as FL_amount,sum(CS_bottles) as CS_bottles,sum(CS_Peg) as CS_Peg, sum(CS_amount) as CS_amount, sum(NAI_Qnty) as NAI_Qnty,sum(NAI_amount) as NAI_amount,sum(FL_amount + CS_amount + NAI_amount) as Total   \r\n  \t\tfrom(  \r\n  \t\t\tselect userName,salestype, SUM(bottles_sold) as FL_bottles, sum(large + (small * 0.5)) as FL_Peg ,  SUM(total_amount)as FL_amount, '0' as CS_bottles, '0' as CS_Peg, '0' as CS_amount,  '0' as NAI_Qnty, '0' as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)  \r\n  \t\t\twhere itemType = 'FL'   \r\n  \t\t\tgroup by  salestype, userName  \r\n  \t\t\tunion all  \r\n  \t\t\tselect  userName,salestype, '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, SUM(bottles_sold) as CS_bottles,sum(large + (small * 0.5)) as CS_Peg , SUM(total_amount)as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)  \r\n  \t\t\twhere itemType = 'CS'   \r\n  \t\t\tgroup by salestype , userName  \r\n  \t\t\tunion all  \r\n  \t\t\tselect userName,salestype, '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, '0' as CS_bottles,'0' as CS_Peg , '0' as CS_amount, sum (bottles_sold) as NAI_Qnty, SUM(total_amount) as NAI_amount   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)   \r\n  \t\t\twhere itemType = 'NAI'   \r\n  \t\t\tgroup by   \r\n  \t\t\tsalestype,userName   \r\n  \t\t\t) as x where salestype <> 'DISCOUNT' AND salestype <> 'EXPENCE' and userName = @username group by  salestype  \r\n  \t\t\tunion all  \r\n  \t\t\tselect 'NET' as salestype , '0' as FL_bottles, '0' as FL_Peg, '0' as FL_amount, '0' as CS_bottles , '0' as CS_Peg,'0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount ,(select SUM(total_amount) as Total   \r\n  \t\t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)    \r\n  \t\t\twhere salestype = 'CASH' or salestype = 'CREDIT ACCOUNT' or salestype = 'CREDIT CARD' and userName = @username   \r\n  \t\t\t)  \r\n  \t\tunion all  \r\n  \t\tselect salestype,'0' as FL_bottles,'0' as FL_Peg,'0' as FL_amount,'0' as CS_bottles,'0' as CS_Peg,'0' as CS_amount, '0' as NAI_Qnty,'0' as NAI_amount,sum(total_amount) as Total   \r\n  \t\tfrom Fnc_Sale(@datefrom,@dateto,@comCode,@yearCode)   \r\n  \t\twhere salestype = 'EXPENCE'  \r\n  \t\tgroup by salestype  \r\n  \t\tunion all  \r\n  \t\tselect 'Cash Ledger Closing' as salestype,'0' as FL_bottles, '0' as FL_Peg , '0' FL_amount, '0' as CS_bottles,'0' as CS_Peg , '0' as CS_amount, '0' as NAI_Qnty, '0' as NAI_amount, (sum(debit) - sum(credit)) as Total   \r\n  \t\tfrom #temp   \r\n  \tend  \r\n  drop table #temp  ";
				}
				ob.insert(s);
				if (Conversion.Val(RuntimeHelpers.GetObjectValue(ob.populate("IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[Sp_salesDetails]') AND type in (N'P', N'PC'))Select 0 else select 1").Tables[0].Rows[0][0])) > 0.0)
				{
					s = "CREATE procedure [dbo].[Sp_salesDetails]  \r\n  (  \r\n  @CompanyCode varchar(6),  \r\n  @YearCode varchar(6),  \r\n  @date1 varchar(20),  \r\n  @date2 varchar(20) , \r\n  @ComCash varchar(20) \r\n  ) as begin  \r\n  Select 0 as [check],companycode,yearcode, ledgercode as Code,Account,sum(Litre) as Litre,BillNo,sum(Amount) as Amount,itemcode,itemname,kflcode,kflname,BrandCode,Brand,categorycode,Category,billType from  \r\n  (  \r\n  SELECT salesbillmain.companycode ,salesbillmain.yearcode ,salesbillmain.trndate,salesbillmain.ledgercode,ledgerName as Account,  sum(isnull(((convert(float,(qnty * ml))/1000) * (convert(float,(100 -(substring(strengthname,1,2))))/100)),0))  as Litre ,salesbillmain.trnno as BillNo,sum(salesbilldetail.itemAmount)as Amount ,salesbilldetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode as BrandCode,categoryname as Brand ,  \r\n  itemmst.groupcode as CategoryCode,groupname as Category,salesbilldetail.billType  \r\n  FROM  salesbillmain  \r\n  inner join salesbilldetail on salesbillmain.companycode = salesbilldetail.companycode and salesbillmain.yearcode = salesbilldetail.yearcode and salesbillmain.trndate = salesbilldetail.trndate and salesbillmain.trnno = salesbilldetail.trnno   \r\n   join MasterAccountsLedger on salesbillmain.companycode = MasterAccountsLedger.companyCode and salesbillmain.ledgercode = MasterAccountsLedger.ledgerCode    \r\n   join itemmst on salesbilldetail.companycode = itemmst.companycode and salesbilldetail.itemcode = itemmst.itemcode and strengthname <> 'BEER'  \r\n   join kflmst on itemmst.companycode = kflmst.companycode and itemmst.kflcode = kflmst.kflcode and kflname = 'CS'  \r\n   join categorymst on itemmst.companycode = categorymst.companycode and itemmst.categorycode = categorymst.categorycode  \r\n   join groupmst on itemmst.companycode = groupmst.companycode and itemmst.groupcode = groupmst.groupcode  \r\n    group by salesbillmain.companycode ,salesbillmain.yearcode ,salesbillmain.trndate,salesbillmain.ledgercode,ledgerName,salesbillmain.trnno,salesbilldetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode,categoryname,itemmst.groupcode,groupname,salesbilldetail.billType  \r\n      \r\n   union all  \r\n     \r\n   SELECT salesbillmain.companycode ,salesbillmain.yearcode ,salesbillmain.trndate, salesbillmain.ledgercode,ledgerName as Account,  (sum(isnull(convert(float,(qnty * ml))/1000,0)))  as Litre ,salesbillmain.trnno as BillNo,sum(salesbilldetail.itemAmount)as Amount ,salesbilldetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode as BrandCode,categoryname as Brand ,itemmst.groupcode as CategoryCode,groupname as Category,salesbilldetail.billType  \r\n  FROM  salesbillmain  \r\n  inner join salesbilldetail on salesbillmain.companycode = salesbilldetail.companycode and salesbillmain.yearcode = salesbilldetail.yearcode and salesbillmain.trndate = salesbilldetail.trndate and salesbillmain.trnno = salesbilldetail.trnno   \r\n   join MasterAccountsLedger on salesbillmain.companycode = MasterAccountsLedger.companyCode and salesbillmain.ledgercode = MasterAccountsLedger.ledgerCode    \r\n   join itemmst on salesbilldetail.companycode = itemmst.companycode and salesbilldetail.itemcode = itemmst.itemcode   \r\n   join kflmst on itemmst.companycode = kflmst.companycode and itemmst.kflcode = kflmst.kflcode and kflname <> 'CS'  \r\n   join categorymst on itemmst.companycode = categorymst.companycode and itemmst.categorycode = categorymst.categorycode  \r\n   join groupmst on itemmst.companycode = groupmst.companycode and itemmst.groupcode = groupmst.groupcode  \r\n   group by salesbillmain.companycode ,salesbillmain.yearcode ,salesbillmain.trndate,salesbillmain.ledgercode,ledgerName,salesbillmain.trnno,salesbilldetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode,categoryname,itemmst.groupcode,groupname,salesbilldetail.billType  \r\n   ) as x   \r\n   where x.companycode = @CompanyCode and x.yearcode = @YearCode and x.trndate >= @date1 and  x.trndate <=@date2  \r\n   group by companycode,yearcode,ledgercode,Account,BillNo,itemcode,itemname,kflcode,kflname,BrandCode,Brand,CategoryCode,Category,billType  \r\n    \r\n   exec [SP_SaleNewFORsALESdETAILS] @date1,@date2,@CompanyCode,@YearCode,@ComCash,'' \r\n  end  ";
				}
				else
				{
					s = "ALTER procedure [dbo].[Sp_salesDetails]  \r\n  (  \r\n  @CompanyCode varchar(6),  \r\n  @YearCode varchar(6),  \r\n  @date1 varchar(20),  \r\n  @date2 varchar(20) , \r\n  @ComCash varchar(20) \r\n  ) as begin  \r\n  Select 0 as [check],companycode,yearcode, ledgercode as Code,Account,sum(Litre) as Litre,BillNo,sum(Amount) as Amount,itemcode,itemname,kflcode,kflname,BrandCode,Brand,categorycode,Category,billType from  \r\n  (  \r\n  SELECT salesbillmain.companycode ,salesbillmain.yearcode ,salesbillmain.trndate,salesbillmain.ledgercode,ledgerName as Account,  sum(isnull(((convert(float,(qnty * ml))/1000) * (convert(float,(100 -(substring(strengthname,1,2))))/100)),0))  as Litre ,salesbillmain.trnno as BillNo,sum(salesbilldetail.itemAmount)as Amount ,salesbilldetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode as BrandCode,categoryname as Brand ,  \r\n  itemmst.groupcode as CategoryCode,groupname as Category,salesbilldetail.billType  \r\n  FROM  salesbillmain  \r\n  inner join salesbilldetail on salesbillmain.companycode = salesbilldetail.companycode and salesbillmain.yearcode = salesbilldetail.yearcode and salesbillmain.trndate = salesbilldetail.trndate and salesbillmain.trnno = salesbilldetail.trnno   \r\n   join MasterAccountsLedger on salesbillmain.companycode = MasterAccountsLedger.companyCode and salesbillmain.ledgercode = MasterAccountsLedger.ledgerCode    \r\n   join itemmst on salesbilldetail.companycode = itemmst.companycode and salesbilldetail.itemcode = itemmst.itemcode and strengthname <> 'BEER'  \r\n   join kflmst on itemmst.companycode = kflmst.companycode and itemmst.kflcode = kflmst.kflcode and kflname = 'CS'  \r\n   join categorymst on itemmst.companycode = categorymst.companycode and itemmst.categorycode = categorymst.categorycode  \r\n   join groupmst on itemmst.companycode = groupmst.companycode and itemmst.groupcode = groupmst.groupcode  \r\n    group by salesbillmain.companycode ,salesbillmain.yearcode ,salesbillmain.trndate,salesbillmain.ledgercode,ledgerName,salesbillmain.trnno,salesbilldetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode,categoryname,itemmst.groupcode,groupname,salesbilldetail.billType  \r\n      \r\n   union all  \r\n     \r\n   SELECT salesbillmain.companycode ,salesbillmain.yearcode ,salesbillmain.trndate, salesbillmain.ledgercode,ledgerName as Account,  (sum(isnull(convert(float,(qnty * ml))/1000,0)))  as Litre ,salesbillmain.trnno as BillNo,sum(salesbilldetail.itemAmount)as Amount ,salesbilldetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode as BrandCode,categoryname as Brand ,itemmst.groupcode as CategoryCode,groupname as Category,salesbilldetail.billType  \r\n  FROM  salesbillmain  \r\n  inner join salesbilldetail on salesbillmain.companycode = salesbilldetail.companycode and salesbillmain.yearcode = salesbilldetail.yearcode and salesbillmain.trndate = salesbilldetail.trndate and salesbillmain.trnno = salesbilldetail.trnno   \r\n   join MasterAccountsLedger on salesbillmain.companycode = MasterAccountsLedger.companyCode and salesbillmain.ledgercode = MasterAccountsLedger.ledgerCode    \r\n   join itemmst on salesbilldetail.companycode = itemmst.companycode and salesbilldetail.itemcode = itemmst.itemcode   \r\n   join kflmst on itemmst.companycode = kflmst.companycode and itemmst.kflcode = kflmst.kflcode and kflname <> 'CS'  \r\n   join categorymst on itemmst.companycode = categorymst.companycode and itemmst.categorycode = categorymst.categorycode  \r\n   join groupmst on itemmst.companycode = groupmst.companycode and itemmst.groupcode = groupmst.groupcode  \r\n   group by salesbillmain.companycode ,salesbillmain.yearcode ,salesbillmain.trndate,salesbillmain.ledgercode,ledgerName,salesbillmain.trnno,salesbilldetail.itemcode,itemname,itemmst.kflcode,kflname,itemmst.categorycode,categoryname,itemmst.groupcode,groupname,salesbilldetail.billType  \r\n   ) as x   \r\n   where x.companycode = @CompanyCode and x.yearcode = @YearCode and x.trndate >= @date1 and  x.trndate <=@date2  \r\n   group by companycode,yearcode,ledgercode,Account,BillNo,itemcode,itemname,kflcode,kflname,BrandCode,Brand,CategoryCode,Category,billType  \r\n    \r\n   exec [SP_SaleNewFORsALESdETAILS] @date1,@date2,@CompanyCode,@YearCode,@ComCash,'' \r\n  end  ";
				}
				ob.insert(s);
				if (Conversion.Val(RuntimeHelpers.GetObjectValue(ob.populate("IF  EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[Sp_StockNewDetails]') AND type in (N'P', N'PC'))Select 0 else select 1").Tables[0].Rows[0][0])) > 0.0)
				{
					s = "CREATE Procedure [dbo].[Sp_StockNewDetails]  @CompanyCode varchar(6),  @YearCode varchar(6),  @date1 NVARCHAR(MAX),  @date2 NVARCHAR(MAX),  @yearstartdate NVARCHAR(MAX)  \r\n  --,@brandCode varchar(6) = '',  @categoryCode varchar(6) = '' ,@storeCode varchar(6) = ''  \r\n  as Begin  \r\n   \r\n select 0 as [check], kflcode,KFL, BrandCode,Brand,CategoryCode,Category,ml, itemcode, itemname,Opening, Purchased , isnull(suppliercode,0) as suppliercode, isnull(PurchaseFrom,'') as PurchaseFrom, isnull(BatchNo,'') as BatchNo,isnull(TpPassNo,'') as TpPassNo, Total, [Difference], Closing, Closing@Bottle \r\n from (  \r\n  SELECT x.companycode, x.yearcode , itemmst.kflcode,kflmst.kflname as KFL, itemmst.categorycode as BrandCode,categorymst.categoryname as Brand, itemmst.groupcode as CategoryCode,groupmst.groupname as Category, convert(varchar,itemmst.ml) as ml,  x.itemcode, x.itemname, Sum(opening_stock) as Opening, convert(float,sum(bottles_purchased)) as Purchased, Purchasemain.suppliercode ,MasterAccountsLedger.ledgerName as PurchaseFrom, purchasedetail.batchno as BatchNo , purchasemain.tppassno as TpPassNo,  sum(opening_stock + bottles_purchased) as Total, (convert(float,sum(bottles_sold)) + sum(breakage)) as [Difference] ,sum(stock) as Closing ,sum(stock) as Closing@Bottle  \r\n  FROM         dbo.opening_closing_stock(@yearstartdate, @date1, @date2)  as x  \r\n  left join purchasedetail on x.companycode = purchasedetail.companycode and x.yearcode = purchasedetail.yearcode and x.itemcode = purchasedetail.itemcode  \r\n  left join purchasemain on purchasedetail.companycode = purchasemain.companycode and purchasedetail.yearcode = purchasemain.yearcode and purchasedetail.trnno = purchasemain.trnno  \r\n  left join MasterAccountsLedger on purchasemain.companycode = MasterAccountsLedger.companyCode and purchasemain.suppliercode = MasterAccountsLedger.ledgerCode   \r\n   --join storage on x.companycode = storage.companycode and x.storecode = storage.shopcode   \r\n   join itemmst on x.companycode = itemmst.companycode and x.itemcode = itemmst.itemcode   \r\n    join categorymst on itemmst.companycode = categorymst.companycode and itemmst.categorycode = categorymst.categorycode   \r\n   join groupmst on itemmst.companycode = groupmst.companycode and itemmst.groupcode = groupmst.groupcode   \r\n   join kflmst  on itemmst.companycode = kflmst.companycode and itemmst.kflcode = kflmst.kflcode   \r\n   group by x.companycode, x.yearcode,itemmst.kflcode,kflmst.kflname,itemmst.categorycode ,categorymst.categoryname , itemmst.groupcode ,groupmst.groupname , itemmst.ml, x.itemname , x.itemcode,  Purchasemain.suppliercode ,MasterAccountsLedger.ledgerName , purchasedetail.batchno , purchasemain.tppassno  \r\n    ) as y \r\n    where companycode = @CompanyCode and yearcode = @YearCode   \r\n   End  ";
				}
				else
