in itemmst on x.companycode = itemmst.companycode and x.itemcode = itemmst.itemcode   \r\n    join categorymst on itemmst.companycode = categorymst.companycode and itemmst.categorycode = categorymst.categorycode   \r\n   join groupmst on itemmst.companycode = groupmst.companycode and itemmst.groupcode = groupmst.groupcode   \r\n   join kflmst  on itemmst.companycode = kflmst.companycode and itemmst.kflcode = kflmst.kflcode   \r\n   group by x.companycode, x.yearcode,itemmst.kflcode,kflmst.kflname,itemmst.categorycode ,categorymst.categoryname , itemmst.groupcode ,groupmst.groupname , itemmst.ml, x.itemname , x.itemcode,  Purchasemain.suppliercode ,MasterAccountsLedger.ledgerName , purchasedetail.batchno , purchasemain.tppassno  \r\n    ) as y \r\n    where companycode = @CompanyCode and yearcode = @YearCode   \r\n   End  ";
