  SELECT     VchDate, TrnType, TrnNo, Particulars,   \r\n  CASE WHEN SIGN(FoundAmount) = - 1 THEN CAST(FoundAmount * -1 AS FLOAT) ELSE 0 END AS Debit,   \r\n  CASE WHEN SIGN(FoundAmount) = 1 THEN CAST(FoundAmount AS FLOAT) ELSE 0 END AS Credit,  \r\n  ReceiptType, ChequeNo, CardNo, TransactionIDDetails, Narration  \r\n  FROM         (SELECT     TransactionMain.VchDate, TransactionMain.TrnType, case when TransactionMain.ReceiptType IN ('FL','CS','NAI') Then (TransactionMain.ReceiptType) + '-' + Convert(varchar,TransactionMain.TrnNo) else CONVERT(varchar,TransactionMain.TrnNo) end As TrnNo, MasterAccountsLedger.ledgerName AS Particulars,   \r\n                                                TransactionDetail.TrnAmount * TransactionDetail.TrnEffect * - 1 AS FoundAmount, TransactionMain.ReceiptType, TransactionMain.ChequeNo,   \r\n                                                TransactionMain.CardNo, TransactionMain.TransactionIDDetails, TransactionMain.Narration  \r\n                         FROM          TransactionDetail LEFT OUTER JOIN  \r\n                                                MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND   \r\n                                                TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode LEFT OUTER JOIN  \r\n                                                TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND   \r\n                                                TransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId  \r\n                         WHERE      (TransactionDetail.IndexId IN  \r\n                                                    (SELECT     IndexId  \r\n                                                      FROM          TransactionDetail AS TransactionDetail_1  \r\n                               