n  SELECT     VchDate, TrnType, TrnNo, Particulars,   \r\n  CASE WHEN SIGN(FoundAmount) = - 1 THEN CAST(FoundAmount * -1 AS FLOAT) ELSE 0 END AS Debit,   \r\n  CASE WHEN SIGN(FoundAmount) = 1 THEN CAST(FoundAmount AS FLOAT) ELSE 0 END AS Credit,  \r\n  ReceiptType, ChequeNo, CardNo, TransactionIDDetails, Narration  \r\n  FROM         (SELECT     TransactionMain.VchDate, TransactionMain.TrnType, case when TransactionMain.ReceiptType IN ('FL','CS','NAI') Then (TransactionMain.ReceiptType) + '-' + Convert(varchar,TransactionMain.TrnNo) else CONVERT(varchar,TransactionMain.TrnNo) end As TrnNo, MasterAccountsLedger.ledgerName AS Particulars,   \r\n                                                TransactionDetail.TrnAmount * TransactionDetail.TrnEffect * - 1 AS FoundAmount, TransactionMain.ReceiptType, TransactionMain.ChequeNo,   \r\n                                                TransactionMain.CardNo, TransactionMain.TransactionIDDetails, TransactionMain.Narration  \r\n                         FROM          TransactionDetail LEFT OUTER JOIN  \r\n                                                MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND   \r\n                                                TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode LEFT OUTER JOIN  \r\n                                                TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND   \r\n                                                TransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId  \r\n                         WHERE      (TransactionDetail.IndexId IN  \r\n                                                    (SELECT     IndexId  \r\n                                                      FROM          TransactionDetail AS TransactionDetail_1  \r\n                                                      WHERE      (TrnAccount = @LedgerCode) AND (companycode = @comCode) AND (yearcode = @YearCode))) AND (TransactionDetail.companycode = @comCode) AND   \r\n                                                (TransactionDetail.yearcode = @YearCode) AND (TransactionDetail.TrnAccount <> @LedgerCode) AND (TransactionMain.TrnType <> 'JOURNAL') AND   \r\n                                                (TransactionMain.VchDate BETWEEN CONVERT(varchar, @dateFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103))  \r\n                         UNION ALL  \r\n  \t\t\t\t\t\tSELECT     TransactionMain.VchDate, TransactionMain.TrnType, case when TransactionMain.ReceiptType IN ('FL','CS','NAI') Then (TransactionMain.ReceiptType) + '-' + Convert(varchar,TransactionMain.TrnNo) else CONVERT(varchar,TransactionMain.TrnNo) end As TrnNo, 'JOURNAL' AS Particulars,   \r\n  \t\t\t\t\t\t\t\t\t\t\t  TransactionDetail.TrnAmount * TransactionDetail.TrnEffect AS FoundAmount, TransactionMain.ReceiptType, TransactionMain.ChequeNo,   \r\n  \t\t\t\t\t\t\t\t\t\t\t  TransactionMain.CardNo, TransactionMain.TransactionIDDetails, TransactionMain.Narration  \r\n  \t\t\t\t\t\tFROM         TransactionDetail AS TransactionDetail LEFT OUTER JOIN  \r\n  \t\t\t\t\t\t\t\t\t\t\t  TransactionMain AS TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND   \r\n  \t\t\t\t\t\t\t\t\t\t\t  TransactionDetail.yearcode = TransactionMain.yearcode AND TransactionDetail.restaurantCode = TransactionMain.restaurantCode AND   \r\n  \t\t\t\t\t\t\t\t\t\t\t  TransactionDetail.IndexId = TransactionMain.IndexId  \r\n  \t\t\t\t\t\tWHERE     (TransactionDetail.companycode = @comCode) AND (TransactionDetail.yearcode = @YearCode) AND (TransactionDetail.TrnAccount = @LedgerCode) AND   \r\n  \t\t\t\t\t\t\t\t\t\t\t  (TransactionMain.TrnType = 'JOURNAL') AND (TransactionMain.VchDate BETWEEN CONVERT(VARCHAR, @dateFrom, 103) AND CONVERT(VARCHAR,   \r\n  \t\t\t\t\t\t\t\t\t\t\t  @dateTo, 103))) AS Transactions  \r\n  ORDER BY VchDate, TrnType Desc, TrnNo  \r\n  END  ";
