onMain.ReceiptType + '-' + Convert(varchar,TransactionMain.TrnNo) else Convert(varchar,TransactionMain.TrnNo) end as TrnNo, MasterAccountsLedger.ledgerName AS Particulars,    \r\n TransactionDetail.TrnAmount * TransactionDetail.TrnEffect AS FoundAmount, '' AS LedgerEffected, 0 AS SubAmount, TransactionMain.ReceiptType,  \r\n TransactionMain.ChequeNo, TransactionMain.CardNo,   TransactionMain.TransactionIDDetails, TransactionMain.Narration   \r\n FROM TransactionDetail  \r\n LEFT OUTER JOIN  MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND    \r\n TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode  \r\n LEFT OUTER JOIN  TransactionMain ON TransactionDetail.companycode = TransactionMain.companycode AND TransactionDetail.yearcode = TransactionMain.yearcode AND    \r\n TransactionDetail.restaurantCode = TransactionMain.restaurantCode AND TransactionDetail.IndexId = TransactionMain.IndexId   \r\n WHERE (TransactionDetail.companycode = @comCode) AND (TransactionDetail.yearcode = @YearCode) AND (TransactionDetail.TrnAccount = @LedgerCode) AND    \r\n (TransactionMain.VchDate BETWEEN CONVERT(varchar, @dateFrom, 103) AND CONVERT(VARCHAR, @dateTo, 103))   \r\n UNION ALL   \r\n SELECT  2 As OrderNo, TransactionMain.VchDate, TransactionMain.TrnType, case when TransactionMain.ReceiptType IN ('FL','CS','NAI') Then TransactionMain.ReceiptType + '-' + Convert(varchar,TransactionMain.TrnNo) else convert(varchar,TransactionMain.TrnNo) end as TrnNo, '' AS Particulars, 0 AS FoundAmount, MasterAccountsLedger.ledgerName AS LedgerEffected,    \r\n TransactionDetail.TrnAmount * TransactionDetail.TrnEffect AS SubAmount, '' AS ReceiptType, '' AS ChequeNo, '' AS CardNo,   '' AS TransactionIDDetails, '' AS Narration   \r\n FROM TransactionDetail  \r\n LEFT OUTER JOIN  MasterAccountsLedger ON TransactionDetail.companycode = MasterAccountsLedger.companyCode AND    \r\n TransactionDetail.TrnAccount = MasterAccountsLedger.ledgerCode  \r\n LEF