				{
					s = "CREATE FUNCTION [dbo].[fun_Sales_Summary]  \r\n ( \r\n @ComCode varchar(6) ,  \r\n @YearCode varchar(6), \r\n @comStDate AS DATE,   \r\n @endDate AS DATE \r\n ) \r\n RETURNS TABLE AS RETURN   \r\n   SELECT '1' AS GroupNo,'1. Sales Summary' AS ReportName,x.Particular,SUM(ISNULL(x.bottle,0)) AS Bottle,  \r\n   (SUM(ISNULL(x.ml,0))/1000) AS Litre,SUM(ISNULL(x.amount,0)) NetAmount ,1 AS srlNo     \r\n   FROM   \r\n   (   \r\n \tSELECT 0 bottle,'0' ml,'0' amount,@endDate AS trndate,'Cash Sale' Particular,@yearCode yearcode,@comCode companycode \r\n \tUNION ALL \r\n \tSELECT '0'bottle,'0' ml,'0' amount,@endDate trndate,'Card Sale' Particular,@yearCode yearcode,@comCode companycode \r\n \tUNION ALL \r\n \tSELECT '0'bottle,'0' ml,'0' amount,@endDate trndate,'Credit Sale' Particular,@yearCode yearcode,@comCode companycode  \r\n \tUNION ALL \r\n \tSELECT '0'bottle,'0' ml,'0' amount,@endDate trndate,'Sale Return' Particular,@yearCode yearcode,@comCode companycode \r\n \tUNION ALL \r\n \tSELECT SUM(ISNULL(salesbilldetail.qnty,0)) bottle,   \r\n \tCONVERT(FLOAT,SUM(ISNULL(itemmst.ml*salesbilldetail.qnty,0))) as ml,MAX(ISNULL(salesbillmain.amount,0)) AS amount,   \r\n \tsalesbillmain.trndate,CASE WHEN salesbillmain.salestype='CASH' THEN 'Cash Sale'     \r\n \tWHEN salesbillmain.salestype='CREDIT ACCOUNT' THEN 'Credit Sale' WHEN salesbillmain.salestype='RETURN' THEN 'Sale Return' \r\n \tELSE 'Card Sale'  END  AS Particular ,   \r\n \tsalesbillmain.yearcode,salesbillmain.companycode \r\n \tFROM salesbilldetail   \r\n \tINNER JOIN itemmst ON salesbilldetail.companycode=itemmst.companycode   \r\n \tAND salesbilldetail.itemcode=itemmst.itemcode   \r\n \tINNER JOIN salesbillmain ON salesbillmain.companycode=salesbilldetail.companycode   \r\n \tAND salesbillmain.yearcode=salesbilldetail.yearcode   \r\n \tAND salesbillmain.trnno=salesbilldetail.trnno   \r\n \tAND salesbillmain.trndate=salesbilldetail.trndate   \r\n \tWHERE salesbillmain.companycode=@comCode AND salesbillmain.yearcode=@yearCode  \r\n \tAND salesbillmain.trndate>=@endDate AND salesbillmain.trndate<=@endDate   \r\n \tGROUP BY salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.salestype,salesbillmain.trndate,   \r\n \tsalesbillmain.trnno   \r\n   ) AS x   \r\n   GROUP BY x.Particular   \r\n   UNION ALL   \r\n   SELECT '1' AS GroupNo,'1. Sales Summary' AS ReportName,'Gross Sale' AS Particular, ISNULL(SUM(ISNULL(x.bottle,0)),0) AS Bottle,   \r\n   ISNULL((SUM(ISNULL(x.ml,0))/1000),0) AS Litre,ISNULL(SUM(ISNULL(x.netamount,0)),0) NetAmount ,1 AS srlNo    \r\n   FROM   \r\n   (   \r\n \tSELECT SUM(ISNULL(salesbilldetail.qnty,0)) bottle,   \r\n \tCONVERT(FLOAT,SUM(ISNULL(itemmst.ml*salesbilldetail.qnty,0))) AS ml,MAX(ISNULL(salesbillmain.netamount,0)) AS netamount,   \r\n \tsalesbillmain.trndate,salesbillmain.yearcode,salesbillmain.companycode   \r\n \tFROM salesbilldetail   \r\n \tINNER JOIN itemmst ON salesbilldetail.companycode=itemmst.companycode   \r\n \tAND salesbilldetail.itemcode=itemmst.itemcode   \r\n \tINNER JOIN salesbillmain ON salesbillmain.companycode=salesbilldetail.companycode   \r\n \tAND salesbillmain.yearcode=salesbilldetail.yearcode   \r\n \tAND salesbillmain.trnno=salesbilldetail.trnno   \r\n \tAND salesbillmain.trndate=salesbilldetail.trndate   \r\n \tWHERE salesbillmain.companycode=@comCode AND salesbillmain.yearcode=@yearCode AND   \r\n \tsalesbillmain.salestype<>'RETURN'   \r\n \tAND salesbillmain.trndate>=@endDate AND salesbillmain.trndate<=@endDate   \r\n \tGROUP BY salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.trndate,salesbillmain.trnno   \r\n   ) AS x  \r\n   UNION ALL   \r\n   SELECT '1' AS GroupNo,'1. Sales Summary' AS ReportName,'Total Discount' AS Particular, '0' AS Bottle,  \r\n   '0' AS Litre,ISNULL(SUM(ISNULL(x.discamount,0)),0) NetAmount,1 AS srlNo     \r\n   FROM   \r\n   (   \r\n \tSELECT 0 bottle,0 AS ml,MAX(ISNULL(salesbillmain.discamount,0)) AS discamount,   \r\n \tsalesbillmain.trndate,salesbillmain.yearcode