				{
					s = "CREATE procedure [dbo].[sp_SaleSpiritBeerCompare] \r\n @companycode varchar(6), @yearcode varchar(6), @yearStartdate datetime , @yearEndDate datetime , @PrevYearCode varchar(6), @PrevYearStartDate datetime , @PrevYearEndCode datetime  as    \r\n   begin   \r\n    create table #tempSaleCurrent   \r\n   (   \r\n    [Check] bit, \r\n   [Month] varchar(100),   \r\n   [BEER] float,   \r\n   [TotalBEER] float, \r\n   [SPIRIT] float, \r\n   [TotalSPIRIT] float \r\n   )   \r\n   insert into #tempSaleCurrent ([Check],[Month],[BEER],[TotalBEER],[SPIRIT],[TotalSPIRIT])    \r\n   exec Sp_salecompare @companycode, @yearcode, @yearStartdate, @yearEndDate   \r\n    \r\n    create table #tempSalePrevious \r\n   (   \r\n    [Check] bit, \r\n   [Month] varchar(100),   \r\n   [BEER] float,   \r\n   [TotalBEER] float, \r\n   [SPIRIT] float, \r\n   [TotalSPIRIT] float \r\n   )   \r\n   insert into #tempSalePrevious ([Check],[Month],[BEER],[TotalBEER],[SPIRIT],[TotalSPIRIT])    \r\n   exec Sp_salecompare @companycode, @PrevYearCode, @PrevYearStartDate , @PrevYearEndCode   \r\n    \r\n   select 0 as [Check], #tempSaleCurrent.[Month], #tempSaleCurrent.[BEER], #tempSaleCurrent.[TotalBEER],#tempSaleCurrent.[SPIRIT],#tempSaleCurrent.[TotalSPIRIT] , #tempSalePrevious.[BEER] as PrevYrBEER,#tempSalePrevious.[TotalBEER] as PrevYrTotalBEER,#tempSalePrevious.[SPIRIT] as PrevYrSPIRIT,#tempSalePrevious.[TotalSPIRIT] as PrevYrTotalSPIRIT \r\n   from #tempSaleCurrent \r\n   inner join #tempSalePrevious \r\n   on #tempSaleCurrent.[Month] = #tempSalePrevious.[Month]  \r\n    \r\n   drop table #tempSaleCurrent \r\n   drop table #tempSalePrevious \r\n    \r\n   end ";
