=vw_itemCodebarCode.companycode AND vw_itemCodebarCode.itemcode=salesbilldetail.itemcode  \r\n \tWHERE salestype='return'  \r\n \tGROUP BY salesbillmain.companycode,salesbillmain.yearcode,storecode,vw_itemCodebarCode.itemcode,vw_itemCodebarCode.itemname,packing  \r\n \tUNION ALL  \r\n \tSELECT vw_itemCodebarCode.itemcode,vw_itemCodebarCode.itemname,SUM(itemquantity) AS bottles,purchasemain.companycode,shopcode AS storecode, \r\n \tpurchasemain.yearcode,packing   \r\n \tFROM purchasemain JOIN purchasedetail ON purchasedetail.companycode=purchasemain.companycode  \r\n \tAND purchasedetail.yearcode=purchasemain.yearcode AND purchasedetail.trnno=purchasemain.trnno   \r\n \tJOIN vw_itemCodebarCode ON vw_itemCodebarCode.companycode=purchasedetail.companycode AND vw_itemCodebarCode.itemcode=purchasedetail.itemcode  \r\n \tWHERE ptype='PURCHASE'  \r\n \tGROUP BY purchasemain.companycode,purchasemain.yearcode,shopcode,vw_itemCodebarCode.itemcode,vw_itemCodebarCode.itemname,packing  \r\n \tUNION ALL  \r\n \tSELECT vw_itemCodebarCode.itemcode,vw_itemCodebarCode.itemname,-1*SUM(itemquantity) AS bottles,purchasemain.companycode,shopcode AS storecode,purchasemain.yearcode,packing  \r\n \tFROM purchasemain JOIN purchasedetail ON purchasedetail.companycode=purchasemain.companycode  \r\n \tAND purchasedetail.yearcode=purchasemain.yearcode AND purchasedetail.trnno=purchasemain.trnno  \r\n \tJOIN vw_itemCodebarCode ON vw_itemCodebarCode.companycode=purchasedetail.companycode AND vw_itemCodebarCode.itemcode=purchasedetail.itemcode  \r\n \tWHERE ptype='PURCHASE RETURN' GROUP BY purchasemain.companycode,purchasemain.yearcode,shopcode,vw_itemCodebarCode.itemcode,vw_itemCodebarCode.itemname,packing  \r\n \tUNION ALL  \r\n \t/********for deducting the qunatities form the storage of the fun_stock FROM WHERE the items hAS been sold ******/  \r\n \tSELECT vw_itemCodebarCode.itemcode,itemname,(-1)*SUM(qnty) AS bottles,stk_transfer_detail.companycode,shopcode_frm AS storecode,stk_transfer_detail.yearcode,packing  \r\n \tFROM stk_transfer_detail JOIN vw_itemCodebarCode ON stk_transfer_detail.companycode=vw_itemCodebarCode.companycode  \r\n \tAND vw_itemCodebarCode.itemcode=stk_transfer_detail.itemcode  \r\n \tJOIN stk_transfer_main ON stk_transfer_main.companycode=stk_transfer_detail.companycode  \r\n \tAND stk_transfer_main.yearcode=stk_transfer_detail.yearcode AND stk_transfer_main.trnno=stk_transfer_detail.trnno  \r\n \tGROUP BY stk_transfer_detail.companycode,stk_transfer_detail.yearcode,shopcode_frm,vw_itemCodebarCode.itemcode,vw_itemCodebarCode.itemname,packing  \r\n \tUNION ALL  \r\n \t/********for adding the qunatities to the storage of the fun_stock  WHERE the items hAS been sold ******/  \r\n \tSELECT vw_itemCodebarCode.itemcode,itemname,SUM(qnty) AS bottles,stk_transfer_detail.companycode,shopcode_to AS storecode, \r\n \tstk_transfer_detail.yearcode,packing  \r\n \tFROM stk_transfer_detail JOIN vw_itemCodebarCode ON stk_transfer_detail.companycode=vw_itemCodebarCode.companycode  \r\n \tAND vw_itemCodebarCode.itemcode=stk_transfer_detail.itemcode JOIN stk_transfer_main ON stk_transfer_main.companycode=stk_transfer_detail.companycode  \r\n \tAND stk_transfer_main.yearcode=stk_transfer_detail.yearcode AND stk_transfer_main.trnno=stk_transfer_detail.trnno  \r\n \tGROUP BY stk_transfer_detail.companycode,stk_transfer_detail.yearcode,shopcode_to,vw_itemCodebarCode.itemcode,vw_itemCodebarCode.itemname,packing  \r\n )AS x  \r\n WHERE companycode=@comCode AND yearcode=@YearCode \r\n GROUP BY companycode,yearcode,storecode,itemcode,itemname,packing  ";
