			s = "ALTER VIEW [dbo].[vw_cash_sale_daywise]  \r\n AS   \r\n select itemmst.itemcode,itemmst.itemname,SUM(qnty) AS BOTTLES_SOLD,SUM(salesbilldetail.itemamount)AS amnt, \r\n salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate,ratecode,users.userCode,users.userName, \r\n salesbillmain.billType     \r\n FROM salesbillmain      \r\n JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode AND salesbillmain.yearcode=salesbilldetail.yearcode  \r\n AND salesbillmain.trnno=salesbilldetail.trnno AND salesBillMain.billType = salesBillDetail.billType      \r\n JOIN vw_itemCodebarCode AS itemmst ON itemmst.itemcode=salesbilldetail.itemcode AND salesbilldetail.companycode=itemmst.companycode      \r\n INNER JOIN trnIdmst ON salesBillMain.companyCode = trnIdmst.companyCode AND salesBillMain.yearCode = trnIdmst.yearCode  \r\n AND salesBillMain.trnid = trnidmst.trnid INNER JOIN users ON trnIdmst.userCode = users.userCode     \r\n WHERE salestype='CASH'     \r\n GROUP BY itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate, \r\n ratecode,users.userCode,users.userName,salesbillmain.billType ";
			ob.insert(s);
			s = "ALTER VIEW [dbo].[vw_return_sale_daywise]  \r\n AS   \r\n SELECT itemmst.itemcode,itemmst.itemname,SUM(qnty) AS BOTTLES_SOLD,SUM(salesbilldetail.itemamount)AS amnt, \r\n salesbillmain.companycode,storecode,salesbillmain.yearcode,  salesbillmain.trndate,ratecode,users.userCode,users.userName, \r\n salesbillmain.billType       \r\n FROM salesbillmain      \r\n JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode  \r\n AND salesbillmain.yearcode = salesbilldetail.yearcode AND salesbillmain.trnno = salesbilldetail.trnno  \r\n AND salesBillMain.billType = salesBillDetail.billType     \r\n JOIN vw_itemCodebarCode itemmst ON itemmst.itemcode=salesbilldetail.itemcode AND salesbilldetail.companycode=itemmst.companycode      \r\n INNER JOIN trnIdmst ON salesBillMain.companyCode = trnIdmst.companyCode AND salesBillMain.yearCode = trnIdmst.yearCode  \r\n AND salesBillMain.trnid = trnidmst.trnid  \r\n INNER JOIN users ON trnIdmst.userCode = users.userCode     \r\n WHERE salestype='return'      \r\n GROUP BY itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate, \r\n ratecode,users.userCode,users.userName,salesbillmain.billType  ";
			ob.insert(s);
			s = "ALTER VIEW [dbo].[vw_credit_sale_daywise]  \r\n AS   \r\n SELECT itemmst.itemcode,itemmst.itemname,SUM(qnty) AS BOTTLES_SOLD,SUM(salesbilldetail.itemamount)AS amnt, \r\n salesbillmain.companycode,storecode,  salesbillmain.yearcode,salesbillmain.trndate,ratecode,users.userCode,users.userName, \r\n salesbillmain.billType       \r\n FROM salesbillmain       \r\n JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode AND salesbillmain.yearcode = salesbilldetail.yearcode  \r\n AND salesbillmain.trnno = salesbilldetail.trnno AND salesBillMain.billType = salesBillDetail.billType   \r\n JOIN vw_itemCodebarCode AS itemmst ON itemmst.itemcode=salesbilldetail.itemcode AND salesbilldetail.companycode=itemmst.companycode   \r\n INNER JOIN trnIdmst ON salesBillMain.companyCode = trnIdmst.companyCode AND salesBillMain.yearCode = trnIdmst.yearCode  \r\n AND salesBillMain.trnid = trnidmst.trnid     INNER JOIN users ON trnIdmst.userCode = users.userCode       \r\n WHERE salestype='credit account'       \r\n GROUP BY itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate, \r\n ratecode,users.userCode,users.userName,salesbillmain.billType  ";
			ob.insert(s);
			s = "ALTER view [dbo].[vw_creditcard_sale_daywise]  \r\n AS   \r\n SELECT itemmst.itemcode,itemmst.itemname,SUM(qnty) AS BOTTLES_SOLD,SUM(salesbilldetail.itemamount)AS amnt, \r\n salesbillmain.companycode,storecode,  salesbillmain.yearcode,salesbillmain.trndate,ratecode,users.userCode,users.userName, \r\n salesbillmain.billType       \r\n FROM salesbillmain      \r\n JOIN salesbilldetail ON salesbillmain.companycode=salesbilldetail.companycode  \r\n AND salesbillmain.yearcode = salesbilldetail.yearcode AND salesbillmain.trnno = salesbilldetail.trnno  \r\n AND salesBillMain.billType = salesBillDetail.billType     \r\n JOIN vw_itemCodebarCode AS itemmst ON itemmst.itemcode=salesbilldetail.itemcode AND salesbilldetail.companycode=itemmst.companycode     \r\n INNER JOIN trnIdmst ON salesBillMain.companyCode = trnIdmst.companyCode AND salesBillMain.yearCode = trnIdmst.yearCode  \r\n AND salesBillMain.trnid = trnidmst.trnid     \r\n INNER JOIN users ON trnIdmst.userCode = users.userCode    \r\n WHERE salestype='credit card'      \r\n GROUP BY itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,salesbillmain.trndate, \r\n ratecode,users.userCode,users.userName,salesbillmain.billType ";
			ob.insert(s);
			s = "ALTER VIEW [dbo].[vw_sale]   \r\n  AS   \r\n  SELECT salestype,SUM(bottles_sold) AS bottles_sold,SUM(large) AS large,SUM(small) AS small,SUM(westage)AS westage,  \r\n  SUM(total_amount)AS total_amount,companycode,yearcode,trndate,userCode,userName,itemType      \r\n  from  \r\n  (     \r\n  \tSELECT salestype,qnty AS BOTTLES_SOLD,ISNULL(large,0) AS large,ISNULL(small,0)AS small, ISNULL(westage,0) AS westage,  \r\n  \titemamount AS TOTAL_AMOUNT,  salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.trndate,users.userCode,   \r\n  \tusers.userName,CASE WHEN salesbillMain.billtype = 0 THEN 'FL'  WHEN salesbillMain.billtype = 1 THEN 'CS' ELSE 'NAI' END AS itemType       \r\n  \tFROM salesbillmain    \r\n  \tINNER JOIN trnIdmst ON salesBillMain.companyCode = trnIdmst.companyCode AND salesBillMain.yearCode = trnIdmst.yearCode   \r\n  \tAND salesBillMain.trnid = trnidmst.trnid     \r\n  \tINNER JOIN users ON trnIdmst.userCode = users.userCode     \r\n  \tJOIN salesbilldetail  ON salesbillmain.companycode=salesbilldetail.companycode  AND salesbillmain.trnno=salesbilldetail.trnno   \r\n  \tAND salesbillmain.yearcode=salesbilldetail.yearcode AND salesBillMain.billType = salesBillDetail.billType   \r\n  \tJOIN vw_itemCodebarCode AS itemmst ON itemmst.itemcode=salesbilldetail.itemcode AND salesbilldetail.companycode=itemmst.companycode      \r\n  \tUNION ALL   \r\n  \tSELECT 'DISCOUNT' AS saletype,'0' AS bottles_sold,'0' AS large,'0' AS small , '0' AS westage,discamount AS total_amount,   \r\n  \tsalesbillmain.companycode,salesbillmain.yearcode,trndate ,users.userCode,users.userName ,  \r\n  \tCASE WHEN salesbillMain.billtype = 0 THEN 'FL'  WHEN salesbillMain.billtype = 1 THEN 'CS' ELSE 'NAI' END AS itemType       \r\n  \tFROM salesbillmain INNER JOIN trnIdmst ON salesBillMain.companyCode = trnIdmst.companyCode   \r\n  \tAND salesBillMain.yearCode = trnIdmst.yearCode AND salesBillMain.trnid = trnidmst.trnid     \r\n  \tINNER JOIN users ON trnIdmst.userCode = users.userCode where salestype<>'RETURN' AND discamount<>0      \r\n  \tUNION ALL    \r\n  \tSELECT 'DISCOUNT' AS saletype,'0' AS bottles_sold,'0' AS large,'0' AS small , '0' AS westage,(-1)*discamount AS total_amount,  \r\n  \tsalesbillmain.companycode,salesbillmain.yearcode,trndate   ,users.userCode,users.userName,  \r\n  \tCASE WHEN salesbillMain.billtype = 0 THEN 'FL'  WHEN salesbillMain.billtype = 1 THEN 'CS' ELSE 'NAI' END AS itemType       \r\n  \tFROM salesbillmain    INNER JOIN trnIdmst ON salesBillMain.companyCode = trnIdmst.companyCode   \r\n  \tAND salesBillMain.yearCode = trnIdmst.yearCode AND salesBillMain.trnid = trnidmst.trnid     \r\n  \tINNER JOIN users ON trnIdmst.userCode = users.userCode where salestype='RETURN' AND discamount<>0    \r\n  \tUNION ALL     \r\n \tSELECT 'EXPENCE' AS saletype,'0' AS BOTTLES_SOLD,'0' AS large,'0' AS small , '0' AS westage,     \r\n \tISNULL(SUM(ISNULL(TransactionDetail.TrnAmount,0)),0) AS total_amount,AGNFLC.companyCode,TransactionDetail.yearcode, \r\n \tTransactionMain.VchDate AS trndate,ISNULL(users.userCode,'A00001') userCode,ISNULL(users.userName,'ADMIN') userName,'NONE'AS itemType    \r\n \tFROM TransactionDetail     \r\n \tINNER JOIN vw_accGroupNameFromLedgerCode AGNFLC ON AGNFLC.companyCode=TransactionDetail.companycode    \r\n \tAND AGNFLC.ledgerCode=TransactionDetail.TrnAccount    \r\n \tINNER JOIN TransactionMain ON TransactionMain.companycode=TransactionDetail.companycode    \r\n \tAND TransactionMain.yearcode=TransactionDetail.yearcode    \r\n \tAND TransactionMain.restaurantCode=TransactionDetail.restaurantCode    \r\n \tAND TransactionMain.IndexId=TransactionDetail.IndexId   \r\n \tLEFT JOIN trnIdmst ON TransactionMain.companyCode = trnIdmst.companyCode AND TransactionMain.yearCode = trnIdmst.yearCode   \r\n \tAND TransactionMain.TrnId = trnidmst.trnid    \r\n \tLEFT JOIN users ON trnIdmst.userCode = users.userCode  \r\n \tINNER JOIN companyparamtr ON companyparamtr.companycode = TransactionDetail.companycode  \r\n  \tAND companyparamtr.expenceacc = TransactionDetail.TrnAccount   \r\n \tWHERE TransactionMain.TrnType='PAYMENT'    \r\n \tGROUP BY AGNFLC.AccGroupName,AGNFLC.companyCode,TransactionDetail.yearcode,TransactionMain.VchDate, \r\n \tusers.usercode,users.username   \r\n  )AS x    \r\n  GROUP BY salestype,companycode,yearcode,trndate,x.userCode,x.userName,x.itemType ";
			ob.insert(s);
			s = "Alter function [dbo].[sales_statement] \r\n ( \r\n @day1 datetime, \r\n @day2 datetime \r\n ) \r\n returns table  as  return      \r\n select itemcode,itemname,companycode,storecode,yearcode,sum(itemamount) as itemamount,rate ,ml,sum(qnty) as qnty,ratecode, \r\n x.userCode,x.userName,x.billType      \r\n from \r\n (      \r\n \tselect itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,sum(itemamount) as itemamount, \r\n \trate ,ml,sum(qnty) as qnty, ratecode, users.userCode,users.userName,salesbillmain.billType       \r\n \tfrom salesbillmain      \r\n \tjoin salesbilldetail   on salesbillmain.companycode=salesbilldetail.companycode and salesbillmain.yearcode=salesbilldetail.yearcode  \r\n \tand salesbillmain.trnno=salesbilldetail.trnno And salesBillMain.billType = salesBillDetail.billType     \r\n \tjoin vw_itemCodebarCode as itemmst on itemmst.itemcode=salesbilldetail.itemcode and salesbilldetail.companycode=itemmst.companycode      \r\n \tInner Join trnIdmst on salesBillMain.companyCode = trnIdmst.companyCode and salesBillMain.yearCode = trnIdmst.yearCode  \r\n \tand salesBillMain.trnid = trnidmst.trnid      \r\n \tInner Join users on trnIdmst.userCode = users.userCode       \r\n \twhere salestype='cash'  and salesbillmain.trndate >=@day1 and salesbillmain.trndate <=@day2   or salestype='credit card'    \r\n \tand salesbillmain.trndate >=@day1 and salesbillmain.trndate <=@day2   or salestype ='credit account'  \r\n \tand salesbillmain.trndate >=@day1 and salesbillmain.trndate <=@day2      \r\n \tgroup by itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,ratecode,rate,ml, \r\n \tusers.userCode,users.userName,salesbillmain.billType        \r\n \tunion all    \r\n \tselect itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,(-1)*sum(itemamount) as itemamount, \r\n \trate ,ml,(-1)*sum(qnty) as qnty,ratecode ,users.userCode,users.userName,salesbillmain.billType      \r\n \tfrom salesbillmain      \r\n \tjoin salesbilldetail   on salesbillmain.companycode=salesbilldetail.companycode and salesbillmain.yearcode=salesbilldetail.yearcode  \r\n \tand salesbillmain.trnno=salesbilldetail.trnno  And salesBillMain.billType = salesBillDetail.billType    \r\n \tjoin vw_itemCodebarCode as itemmst on itemmst.itemcode=salesbilldetail.itemcode and salesbilldetail.companycode=itemmst.companycode      \r\n \tInner Join trnIdmst on salesBillMain.companyCode = trnIdmst.companyCode and salesBillMain.yearCode = trnIdmst.yearCode  \r\n \tand salesBillMain.trnid = trnidmst.trnid     Inner Join users on trnIdmst.userCode = users.userCode      \r\n \twhere salestype='return'  and salesbillmain.trndate >=@day1 and salesbillmain.trndate <=@day2        \r\n \tgroup by itemmst.itemcode,itemmst.itemname,salesbillmain.companycode,storecode,salesbillmain.yearcode,ratecode,rate,ml, \r\n \tusers.userCode,users.userName,salesbillmain.billType     \r\n )x  \r\n group by itemcode,itemname,companycode,storecode,yearcode,rate,ml,ratecode,x.userCode,x.userName,x.billType  ";
			ob.insert(s);
