		public void formload(object sender, string openType, object openBy = null)
		{
			((Form)this).Text = openType;
			((ToolStripItem)tsl_Title).Text = openType;
			trnsactionType = openType;
			openByWhome = RuntimeHelpers.GetObjectValue(openBy);
			if (myParentForm == null)
			{
				((Control)ToolStrip1).Visible = true;
			}
			if (sender.GetType().ToString().Equals("System.String"))
			{
				loadType = "Add";
				((Control)this).Show();
			}
			else
			{
				loadType = "Edit";
				editablePortion = RuntimeHelpers.GetObjectValue(sender);
				((Control)this).Show();
			}
		}

		private void bt_save_Click(object sender, EventArgs e)
		{
			if ((Operators.CompareString(trnsactionType, "Item Main Group", false) == 0) | (Operators.CompareString(trnsactionType, "Category Master", false) == 0))
			{
				mainGroupSave();
			}
			else if ((Operators.CompareString(trnsactionType, "Item Sub Group", false) == 0) | (Operators.CompareString(trnsactionType, "Brand Master", false) == 0))
			{
				subGroupSave();
			}
			else if ((Operators.CompareString(trnsactionType, "Unit Master", false) == 0) | (Operators.CompareString(trnsactionType, "Measure & Packing", false) == 0))
			{
				unitMasterSave();
			}
			else if (Operators.CompareString(trnsactionType, "KFL Master", false) == 0)
			{
				kflMasterSave();
			}
			else if (Operators.CompareString(trnsactionType, "Strength Master", false) == 0)
			{
				strengthMasterSave();
			}
			else if (Operators.CompareString(trnsactionType, "Main Menu", false) == 0)
			{
				mainMenuSave();
			}
			else if (Operators.CompareString(trnsactionType, "Sub Menu", false) == 0)
			{
				subMenuSave();
			}
			else if (Operators.CompareString(trnsactionType, "Floor Master", false) == 0)
			{
				floorMasterSave();
			}
			else if (Operators.CompareString(trnsactionType, "Store Kitchen Master", false) == 0)
			{
				storeKitchenSave();
			}
			else if (Operators.CompareString(trnsactionType, "Employee Master", false) == 0)
			{
				waiterDetailsSave();
			}
			else if (Operators.CompareString(trnsactionType, "Accounts Main Group", false) == 0)
			{
				accountsMainGroupSave();
			}
			else if (Operators.CompareString(trnsactionType, "Accounts Sub Group", false) == 0)
			{
				accountSubGroupSave();
			}
			else if (Operators.CompareString(trnsactionType, "Department Master", false) == 0)
			{
				departmentMasterSave();
			}
			else if (Operators.CompareString(trnsactionType, "Designation Master", false) == 0)
			{
				designationMasterSave();
			}
			try
			{
				Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
		}

		private void bt_cancel_Click(object sender, EventArgs e)
		{
			if (myParentForm == null)
			{
				((Form)this).Close();
			}
			else
			{
				NewLateBinding.LateCall(myParentForm, (Type)null, "close", new object[0], (string[])null, (Type[])null, (bool[])null, true);
			}
		}

