						NewLateBinding.LateCall(openByWhome, (Type)null, "DataLoadInCombo", new object[0], (string[])null, (Type[])null, (bool[])null, true);
						((Form)this).Close();
					}
					refreshForm();
				}
			}
			else if (accountsGroupDetails.checkSubGroupName(txt_Master1.Text.ToUpper(), 2))
			{
				Interaction.MsgBox((object)"Sub group name already exist for this company change sub group name", (MsgBoxStyle)64, (object)null);
			}
			else if ((Operators.CompareString(txt_master3.Text, "", false) != 0) & accountsGroupDetails.checkSubGroupShortName(txt_master3.Text, 2))
			{
				Interaction.MsgBox((object)"Sub group short code already exist please change sub group short Code", (MsgBoxStyle)64, (object)null);
			}
			else
			{
				accountsGroupDetails.setEffectOnPl((int)chk_isRawItem.CheckState > 0);
				accountsGroupDetails.setSubGroupName(txt_Master1.Text.ToUpper());
				accountsGroupDetails.setSubGroupShortName(txt_master3.Text);
				checked
				{
					if (cmb_master.SelectedIndex == 0)
					{
						accountsGroupDetails.setNestedSubGroupCode(accountsGroupDetails.getSubGroupCode());
						accountsGroupDetails.setMainGroupCode(Conversions.ToString(ds2.Tables[0].Rows[cmb_subGroup.SelectedIndex][0]));
						accountsGroupDetails.setCreditEffect(Conversions.ToInteger(ds2.Tables[0].Rows[cmb_subGroup.SelectedIndex][2]));
						accountsGroupDetails.setPrimaryGroup(isPrimaryGroup: true);
					}
					else
					{
						accountsGroupDetails.setNestedSubGroupCode(Conversions.ToString(ds.Tables[0].Rows[cmb_master.SelectedIndex - 1][0]));
						accountsGroupDetails.setMainGroupCode(Conversions.ToString(ds.Tables[0].Rows[cmb_master.SelectedIndex - 1][2]));
						accountsGroupDetails.setCreditEffect(Conversions.ToInteger(ds.Tables[0].Rows[cmb_master.SelectedIndex - 1][3]));
						accountsGroupDetails.setPrimaryGroup(isPrimaryGroup: false);
					}
					accountsGroupDetails.updateSubGroup();
					Application.DoEvents();
					((Form)this).Close();
				}
			}
		}

