		private void Button1_Click(object sender, EventArgs e)
		{
			s = "update companyparamtr set message='' where companycode='" + mdl_public_variables.companycode + "'";
			ob.insert(s);
			Timer1.Enabled = false;
			((Form)this).Close();
		}

		private void Timer1_Tick(object sender, EventArgs e)
		{
			//IL_00cd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d7: Expected O, but got Unknown
			//IL_00ac: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b6: Expected O, but got Unknown
			s = "select message from companyparamtr where companycode='" + mdl_public_variables.companycode + "'";
			string text = "";
			text = ob.executereader(s);
			checked
			{
				if ((Operators.CompareString(text, "", false) != 0) & (Operators.CompareString(lbl_msg.Text, text, false) != 0))
				{
					int num = Strings.Len(text) - 1;
					int num2 = 0;
					while (true)
					{
						int num3 = num2;
						int num4 = num;
						if (num3 > num4)
						{
							break;
						}
						if ((Strings.Asc(text[num2]) > 64) & (Strings.Asc(text[num2]) < 118))
						{
							((Control)lbl_msg).Font = new Font("Microsoft Sans Serif", 8f, (FontStyle)0, (GraphicsUnit)3, (byte)0);
						}
						else
						{
							((Control)lbl_msg).Font = new Font("Microsoft Sans Serif", 12f, (FontStyle)0, (GraphicsUnit)3, (byte)0);
						}
						num2++;
					}
					lbl_msg.Text = text;
					if (Operators.CompareString(MyProject.Forms.frm_main.noticmsg, "", false) == 0)
					{
						MyProject.Forms.frm_main.noticmsg = text;
					}
					else
					{
						MyProject.Forms.frm_main.noticmsg = MyProject.Forms.frm_main.noticmsg + "\r\n" + text;
					}
				}
				txt_chat.Text = MyProject.Forms.frm_main.noticmsg;
				((TextBoxBase)txt_chat).SelectionStart = txt_chat.Text.Length;
				((TextBoxBase)txt_chat).ScrollToCaret();
			}
		}

		private void TextBox1_KeyPress(object sender, KeyPressEventArgs e)
		{
			if (Strings.Asc(e.KeyChar) == 13)
			{
				s = "update companyparamtr set message=N'" + txt_msg.Text + "' where companycode='" + mdl_public_variables.companycode + "'";
				ob.insert(s);
				txt_msg.Text = "";
				e.Handled = true;
			}
		}

		private void Timer2_Tick(object sender, EventArgs e)
		{
			checked
			{
				if (((Control)this).Top != ((Computer)MyProject.Computer).Screen.Bounds.Height - (((Control)this).Height + 40))
				{
					((Control)this).Top = ((Control)this).Top - 1;
				}
				else
				{
					Timer2.Enabled = false;
				}
			}
		}
	}
