		{
			s = "select ledgerCode,ledgerName from MasterAccountsLedger where companyCode = '" + mdl_public_variables.companycode + "' and ledgerCode = '" + mdl_public_variables.comcashacc + "' or ledgerCode ='" + mdl_public_variables.combankacc + "'";
			ds1 = ob.populate(s);
			s = "select ledgerCode,ledgerName from MasterAccountsLedger where companyCode = '" + mdl_public_variables.companycode + "' and ledgerCode<>'" + mdl_public_variables.comcashacc + "' or companycode='" + mdl_public_variables.companycode + "' and ledgerCode<>'" + mdl_public_variables.combankacc + "'";
			ds2 = ob.populate(s);
			ob.combofill(ds1.Tables[0], ComboBox1);
			ob.combofill(ds2.Tables[0], ComboBox2);
			TextBox1.Text = "0";
			TextBox2.Text = "0";
		}

		private void TextBox1_TextChanged(object sender, EventArgs e)
		{
			TextBox2.Text = "0";
		}

		private void TextBox2_TextChanged(object sender, EventArgs e)
		{
			TextBox1.Text = "0";
		}
	}
