		private void purchase_Load(object sender, EventArgs e)
		{
			((Form)this).Icon = Icon.FromHandle(Resources.Purchase.GetHicon());
			dtp1.MaxDate = DateTime.Today;
			taxctrl = false;
			editmode = false;
			ob.combo_fill_by_code(dsled, cmb_puchaseacc, mdl_public_variables.compuracc);
			ob.combofill(dssupp.Tables[0], cmb_supplier);
			ob.combofill(dsstore.Tables[0], cmb_storage);
			ob.combofill(dsscheme.Tables[0], cmb_scheme);
			EnumerableRowCollection<object> source = from p in dsled.Tables[0].AsEnumerable()
				where Operators.ConditionalCompareObjectEqual(p[0], (object)mdl_public_variables.compuracc, false)
				select p[1];
			cmb_puchaseacc.Text = source.ElementAtOrDefault(0).ToString();
			if (Operators.CompareString(mdl_public_variables.purchase_discount_type, "BOTTLE", false) == 0)
			{
				rad_bottle.Checked = true;
				discount_type = "BOTTLE";
			}
			else if (Operators.CompareString(mdl_public_variables.purchase_discount_type, "CASE", false) == 0)
			{
				rad_case.Checked = true;
				discount_type = "CASE";
			}
			else if (Operators.CompareString(mdl_public_variables.purchase_discount_type, "ITEM", false) == 0)
			{
				rad_item.Checked = true;
				discount_type = "ITEM";
			}
			chk_saletaxincludingfree.Checked = mdl_public_variables.saletaxincludingfree;
			rad_purchase.Checked = true;
			((Control)rad_purchase).Visible = false;
			((Control)rad_return).Visible = false;
		}

