			//IL_021f: Unknown result type (might be due to invalid IL or missing references)
			s = "select ledgerCode,ledgerName from MasterAccountsLedger where companyCode = '" + mdl_public_variables.companycode + "' order by ledgerName";
			dsled = ob.populate(s);
			s = "select ledgerCode,ledgerName,isnull(address1,'')as address1,isnull(address2,'') as address2,isnull(district,'')as district,isnull(pin,'') as pin,isnull(contactNo,'')as contactNo from MasterAccountsLedger join MasterAccountsGroups on MasterAccountsGroups.AccGroupCode=MasterAccountsLedger.AccGroupCode \r\n and MasterAccountsGroups.companyCode=MasterAccountsLedger.companyCode \r\n where MasterAccountsLedger.companyCode='" + mdl_public_variables.companycode + "' \r\n and MasterAccountsGroups.AccGroupName like '%SUPPLIERS' or MasterAccountsLedger.companyCode='" + mdl_public_variables.companycode + "' \r\n and MasterAccountsGroups.AccGroupName like '%CREDITORS' order by ledgerName ";
			dssupp = ob.populate(s);
			s = "select shopcode,shopname from storage where companycode='" + mdl_public_variables.companycode + "' order by shopname";
			dsstore = ob.populate(s);
			s = "select distinct schemecode,schemename from taxdetail where companycode='" + mdl_public_variables.companycode + "' order by schemename";
			dsscheme = ob.populate(s);
			AiOrNaiItemLoad();
			if (dsled.Tables[0].Rows.Count <= 0)
			{
				Interaction.MsgBox((object)"Purchase Account not set, please set Purchase Account in Admin - Company Parameter.", (MsgBoxStyle)48, (object)"Master MIssings");
				mdl_public_variables.flag = 0;
			}
			else if (dssupp.Tables[0].Rows.Count <= 0)
			{
				Interaction.MsgBox((object)"Can not find any Supplier Name, Please enter Ledger with 'Sundry Creditors' as A/C Group in in Masters - Ledger", (MsgBoxStyle)48, (object)"Master MIssings");
				mdl_public_variables.flag = 0;
			}
			else if (dsstore.Tables[0].Rows.Count <= 0)
			{
				Interaction.MsgBox((object)"Can not find any store. Please Enter Store in Masters - Storage Location", (MsgBoxStyle)48, (object)"Master MIssings");
				mdl_public_variables.flag = 0;
			}
			else if (dsitem.Tables[0].Rows.Count <= 0)
			{
				Interaction.MsgBox((object)"Can not find any Item, Please Enter Items in Masters - Item Information.", (MsgBoxStyle)48, (object)"Master MIssings");
				mdl_public_variables.flag = 0;
			}
			else if (Operators.CompareString(mdl_public_variables.com_salesonmrp_acc, "", false) == 0)
			{
				Interaction.MsgBox((object)"'Sales Tax on MRP' Account is not set, please set 'Sales Tax on MRP' Account in Admin - Company Parameter.", (MsgBoxStyle)48, (object)"Master MIssings");
				mdl_public_variables.flag = 0;
			}
		}

		public void AiOrNaiItemLoad()
		{
			if ((mdl_public_variables.flag == 2) & (Operators.CompareString(mdl_public_variables.purchaseBilltype, "AI", false) == 0))
			{
				rbd_AIitem.CheckedChanged -= rbd_AIitem_CheckedChanged;
				rbd_AIitem.Checked = true;
				rbd_AIitem.CheckedChanged += rbd_AIitem_CheckedChanged;
			}
			else if ((mdl_public_variables.flag == 2) & (Operators.CompareString(mdl_public_variables.purchaseBilltype, "NAI", false) == 0))
			{
				rbd_NaiItem.CheckedChanged -= rbd_NaiItem_CheckedChanged;
				rbd_NaiItem.Checked = true;
				rbd_NaiItem.CheckedChanged += rbd_NaiItem_CheckedChanged;
			}
			else if (isFirstTimeLoad)
			{
				mdl_public_variables.purchaseBilltype = "AI";
			}
			if (Operators.CompareString(mdl_public_variables.purchaseBilltype, "AI", false) == 0)
			{
				s = "select itemcode,itemname,packing,isnull(purchaserate,0)as purchaserate,isnull(salesrate,0)as salesrate,ml,kflname  \r\n from vw_itemCodebarCode itemmst  \r\n where companycode='" + mdl_public_variables.companycode + "' and kflname<>'NAI' \r\n order by itemname ";
			}
			else if (Operators.CompareString(mdl_public_variables.purchaseBilltype, "NAI", false) == 0)
			{
				s = "select itemcode,itemname,packing,isnull(purchaserate,0)as purchaserate,isnull(salesrate,0)as salesrate,ml,kflname  \r\n from vw_itemCodebarCode itemmst  \r\n where companycode='" + mdl_public_variables.companycode + "' and kflname='NAI' \r\n order by itemname ";
			}
			dsitem = ob.populate(s);
		}

		private void RadioButton1_CheckedChanged(object sender, EventArgs e)
		{
