		private void taxcalc()
		{
			txt_rounding_plus.Text = "0.00";
			txt_rounding_minus.Text = "0.00";
			double num = 0.0;
			double num2 = 0.0;
			round = 0.0;
			checked
			{
				ratelist = (double[])Utils.CopyArray((Array)ratelist, (Array)new double[taxcount + 1]);
				glist = (double[])Utils.CopyArray((Array)glist, (Array)new double[taxcount + 1 + 1]);
				amountlist = (double[])Utils.CopyArray((Array)amountlist, (Array)new double[taxcount + 1]);
				num2 = Conversion.Val(txt_gross.Text);
				if ((dsscheme.Tables[0].Rows.Count > 0) & (taxcount > 0))
				{
					glist[0] = Conversion.Val(txt_gross.Text);
					int num3 = taxcount - 1;
					int num4 = 0;
					while (true)
					{
						int num5 = num4;
						int num6 = num3;
						if (num5 > num6)
						{
							break;
						}
						if (glist[num4] > 0.0)
						{
							if (ratelist[num4] == 0.0)
							{
								try
								{
									try
									{
										if (!flratecal)
										{
											taxcalc_2(num4);
										}
									}
									catch (IndexOutOfRangeException ex)
									{
										ProjectData.SetProjectError((Exception)ex);
										IndexOutOfRangeException ex2 = ex;
										ProjectData.ClearProjectError();
									}
								}
								catch (NullReferenceException ex3)
								{
									ProjectData.SetProjectError((Exception)ex3);
									NullReferenceException ex4 = ex3;
									ProjectData.ClearProjectError();
								}
								if (Operators.CompareString(Strings.Trim(dstax.Tables[0].Rows[num4][7].ToString()), "+", false) == 0)
								{
									glist[num4 + 1] = Conversions.ToDouble(Strings.Format((object)(glist[num4] + amountlist[num4]), "0.00"));
									num2 = Conversions.ToDouble(Strings.Format((object)(num2 + amountlist[num4]), "0.00"));
								}
								else
								{
									glist[num4 + 1] = Conversions.ToDouble(Strings.Format((object)(glist[num4] - amountlist[num4]), "0.00"));
									num2 = Conversions.ToDouble(Strings.Format((object)(num2 - amountlist[num4]), "0.00"));
								}
							}
							else
							{
								if (flratecal)
								{
									taxcalc_2(num4);
								}
								if (Operators.CompareString(Strings.Trim(dstax.Tables[0].Rows[num4][7].ToString()), "+", false) == 0)
								{
									glist[num4 + 1] = Conversions.ToDouble(Strings.Format((object)(glist[num4] + Conversion.Val(txt2[num4].Text)), "0.00"));
									num2 = Conversions.ToDouble(Strings.Format((object)(num2 + Conversion.Val(txt2[num4].Text)), "0.00"));
								}
								else
								{
									glist[num4 + 1] = Conversions.ToDouble(Strings.Format((object)(glist[num4] - Conversion.Val(txt2[num4].Text)), "0.00"));
									num2 = Conversions.ToDouble(Strings.Format((object)(num2 - Conversion.Val(txt2[num4].Text)), "0.00"));
								}
							}
						}
						num4++;
					}
					num = glist[taxcount];
				}
				else
				{
					num = Conversion.Val(txt_gross.Text);
				}
				num2 = num2 + Conversion.Val(txt_tot_mrp.Text) - Conversion.Val(txt_discount.Text);
				if (num2 > Conversion.Int(num2))
				{
					round = Conversions.ToDouble(Strings.Format((object)(num2 - Conversion.Int(num2)), "0.00"));
					if (round >= 0.5)
					{
						num2 += 1.0;
						txt_rounding_plus.Text = Strings.Format((object)(1.0 - round), "0.00");
					}
					else
					{
						txt_rounding_minus.Text = Strings.Format((object)round, "0.00");
					}
				}
				else if (num2 < Conversion.Int(num2))
				{
					round = Conversions.ToDouble(Strings.Format((object)(num2 - Conversion.Int(num2)), "0.00"));
					if (round > 0.49)
					{
						num2 += 1.0;
					}
					txt_rounding_plus.Text = Strings.Format((object)round, "0.00");
				}
				txt_net.Text = Conversions.ToString(Conversion.Int(num2));
			}
		}

