		public bool deleteAccountsDetails(ref string result)
		{
			ob_Accounts = new cls_journalEntry();
			ob_Accounts.setTrnNo(Conversions.ToInteger(txt_trnno.Text));
			if (rad_return.Checked)
			{
				return ob_Accounts.deletePurchaseEffect(ref result, "DEBIT NOTE");
			}
			return ob_Accounts.deletePurchaseEffect(ref result, "PURCHASE");
		}

