		public void formload(object sender, string openType, object openBy = null)
		{
			((Form)this).Text = openType;
			trnsactionType = openType;
			openByWhome = RuntimeHelpers.GetObjectValue(openBy);
			if (!mdl_public_variables.uadmin)
			{
				string s = "select pera,pere,perd from userrights where companycode='" + mdl_public_variables.companycode + "' and usercode='" + mdl_public_variables.usercode + "' and modulename like'%" + ((ToolStripItem)tsl_tittle).Text + "%'";
				DataSet dataSet = ob.populate(s);
				if (Operators.CompareString(dataSet.Tables[0].Rows[0][0].ToString(), "False", false) == 0)
				{
					((Control)bt_save).Enabled = false;
				}
			}
			if (sender.GetType().ToString().Equals("System.String"))
			{
				loadType = "Add";
				((Control)this).Show();
			}
			else
			{
				loadType = "Edit";
				editablePortion = RuntimeHelpers.GetObjectValue(sender);
				((Control)this).Show();
			}
		}

		private void frrm_reconciliation_Load(object sender, EventArgs e)
		{
			comboLoad();
			dtp_from.Value = DateTime.Now.AddYears(-1).Date;
			ob_reconcilation = new cls_reconciliation();
		}

		private void comboLoad()
		{
			string s = "select distinct MasterAccountsLedger.ledgerCode,MasterAccountsLedger.ledgerName from TransactionDetail  \r\n inner join MasterAccountsLedger on TransactionDetail.TrnAccount=MasterAccountsLedger.ledgerCode and  \r\n TransactionDetail.companycode=MasterAccountsLedger.companyCode \r\n where TransactionDetail.companycode='" + mdl_public_variables.companycode + "' and TransactionDetail.yearcode='" + mdl_public_variables.yearcode + "' \r\n AND MasterAccountsLedger.ledgerName LIKE '%BANK%'";
			DataSet dataSet = ob.populate(s);
			cmb_bank.DataSource = dataSet.Tables[0];
			((ListControl)cmb_bank).ValueMember = "ledgerCode";
			((ListControl)cmb_bank).DisplayMember = "ledgerName";
		}

		private void ReconciliationDataLoad()
		{
			if (cmb_bank.SelectedIndex > -1)
			{
				ob_reconcilation.setTrnAccount(Conversions.ToString(((ListControl)cmb_bank).SelectedValue));
				ob_reconcilation.setFromeDate(dtp_from.Value);
				ob_reconcilation.setToDate(Conversions.ToString(dtp_to.Value));
				dsload = ob_reconcilation.selectReconciliationDetails();
				dgv_reconciliation.DataSource = dsload.Tables[0];
				DataGridView val = dgv_reconciliation;
				val.Columns["RowIndex"].HeaderText = "Row Index";
