		private void bt_save_Click(object sender, EventArgs e)
		{
			List<VB$AnonymousType_0<string>> listIndex = (from row in dsload.Tables[0].AsEnumerable()
				select new VB$AnonymousType_0<string>(row.Field<string>("IndexId"))).Distinct().ToList();
