		private bool CheckDateValid(string checkDate)
		{
			string[] array = checkDate.Split(new char[1] { '/' });
			bool result;
			if (array.Count() == 3)
			{
				try
				{
					DateTime t = new DateTime(int.Parse(array[2]), int.Parse(array[1]), int.Parse(array[0]));
					result = (((DateTime.Compare(t, mdl_public_variables.comstdate) >= 0) & (DateTime.Compare(t, mdl_public_variables.comenddate) <= 0)) ? true : false);
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					result = false;
					ProjectData.ClearProjectError();
				}
			}
			else
			{
				result = false;
			}
			return result;
		}

