		private void bt_show_Click(object sender, EventArgs e)
		{
			set_control();
			report_show();
			if (((Control)cmb_filter2).Visible)
			{
				((Control)cmb_filter2).Select();
			}
			else
			{
				((Control)dtp1).Select();
			}
		}

		private void report_show()
		{
			if (((Control)dtp1).Visible && !ob.date_check(dtp1.Value.Date.Date))
			{
				((Control)lbl_wait).Visible = false;
				return;
			}
			if (((Control)dtp2).Visible && Operators.CompareString(lbl_from.Text, "Month", false) != 0 && !ob.date_check(dtp2.Value.Date.Date))
			{
				((Control)lbl_wait).Visible = false;
				return;
			}
			frm_load();
			((Control)lbl_wait).Visible = false;
			if (CrystalReportViewer1.GetCurrentPageNumber() != 0)
			{
				((ToolStripControlHost)txt_startpage).Text = Conversions.ToString(1);
				CrystalReportViewer1.ShowLastPage();
				((ToolStripControlHost)txt_endpage).Text = Conversions.ToString(CrystalReportViewer1.GetCurrentPageNumber());
				CrystalReportViewer1.ShowFirstPage();
				((ToolStripControlHost)txt_copies).Text = Conversions.ToString(1);
				if ((report_no == 54) | (report_no == 67))
				{
					((Control)bt_upload).Visible = true;
				}
				((Control)bt_upload).Enabled = true;
			}
			else
			{
				((ToolStripControlHost)txt_startpage).Text = Conversions.ToString(0);
				((ToolStripControlHost)txt_endpage).Text = Conversions.ToString(0);
				((ToolStripControlHost)txt_copies).Text = Conversions.ToString(0);
				if ((report_no == 54) | (report_no == 67))
				{
					((Control)bt_upload).Visible = false;
				}
				((Control)bt_upload).Enabled = false;
			}
		}

