		private void dtpicker_date_set()
		{
			((Control)dtp2).Visible = false;
			lbl_from.Text = "Date";
			dtp1.CustomFormat = "dd/MM/yyyy";
			date_string = " OF : " + Strings.Format((object)dtp1.Value.Date, "dd/MM/yyyy").ToString();
		}

		private void dtpicker_month_set()
		{
			dtp1.Value = Conversions.ToDate(DateAndTime.Month(dtp1.Value) + "/1/" + DateAndTime.Year(dtp1.Value));
			dtp1.ShowUpDown = true;
			((Control)dtp2).Visible = false;
			lbl_from.Text = "Month";
			dtp1.CustomFormat = "MMMM-yyyy";
			((Control)dtp1).Width = 120;
			days = DateTime.DaysInMonth(dtp1.Value.Date.Year, dtp1.Value.Date.Month);
			date_string = " FOR THE MONTH OF : " + Strings.Format((object)dtp1.Value.Date, "MMMMMMMMMMMMM").ToString().ToUpper() + " " + dtp1.Value.Date.Year;
			dtstr1 = Conversions.ToDate(dtp1.Value.Date.Year + "-" + dtp1.Value.Date.Month + "-01");
			dtstr2 = Conversions.ToDate(dtp1.Value.Date.Year + "-" + dtp1.Value.Date.Month + "-" + days);
			checked
			{
				prevdtstr0 = Conversions.ToDate(mdl_public_variables.comstdate.Year - 1 + "-04-01");
				prevdtstr1 = Conversions.ToDate(dtp1.Value.Date.Year - 1 + "-" + dtp1.Value.Date.Month + "-01");
				if (days == 29)
				{
					prevdtstr2 = Conversions.ToDate(dtp1.Value.Date.Year - 1 + "-" + dtp1.Value.Date.Month + "-" + (days - 1));
				}
				else
				{
					prevdtstr2 = Conversions.ToDate(dtp1.Value.Date.Year - 1 + "-" + dtp1.Value.Date.Month + "-" + days);
				}
				DataSet dataSet = new DataSet();
				dataSet = ob.populate("select yearcode from yearmst where stdate='" + Conversions.ToString(prevdtstr0) + "'");
				if (dataSet.Tables[0].Rows.Count > 0)
				{
					prevyearcode = Conversions.ToString(dataSet.Tables[0].Rows[0][0]);
				}
				else
				{
					prevyearcode = Conversions.ToString(0);
				}
			}
		}

		private void dtpicker_daterange_set()
		{
			if ((report_no == 27) | (report_no == 28))
			{
				dtp1.Value = mdl_public_variables.comstdate;
			}
			days = DateTime.DaysInMonth(dtp1.Value.Date.Year, dtp1.Value.Date.Month);
			checked
			{
				prevdtstr0 = Conversions.ToDate(mdl_public_variables.comstdate.Year - 1 + "-04-01");
				if ((dtp1.Value.Date.Month == 2) & (unchecked(dtp1.Value.Year % 4) == 0) & (dtp1.Value.Day >= 29))
				{
					prevdtstr1 = Conversions.ToDate(dtp1.Value.Date.Year - 1 + "-" + dtp1.Value.Date.Month + "-28");
				}
				else if ((dtp1.Value.Month == 2) & (dtp1.Value.Year - 1 == 0))
				{
					prevdtstr1 = Conversions.ToDate(dtp1.Value.Date.Year - 1 + "-" + dtp1.Value.Date.Month + "-30");
				}
				else
				{
					prevdtstr1 = Conversions.ToDate(dtp1.Value.Date.Year - 1 + "-" + dtp1.Value.Date.Month + "-" + dtp1.Value.Date.Day);
				}
				if ((dtp2.Value.Month == 2) & (unchecked(dtp2.Value.Year % 4) == 0) & (dtp2.Value.Day >= 29))
				{
					prevdtstr2 = Conversions.ToDate(dtp2.Value.Date.Year - 1 + "-" + dtp2.Value.Date.Month + "-28");
				}
				else if ((dtp1.Value.Month == 2) & (dtp1.Value.Year - 1 == 0))
				{
					prevdtstr2 = Conversions.ToDate(dtp2.Value.Date.Year - 1 + "-" + dtp2.Value.Date.Month + "-30");
				}
				else
				{
					prevdtstr2 = Conversions.ToDate(dtp2.Value.Date.Year - 1 + "-" + dtp2.Value.Date.Month + "-" + dtp2.Value.Date.Day);
				}
				DataSet dataSet = new DataSet();
				dataSet = ob.populate("select yearcode from yearmst where stdate='" + Conversions.ToString(prevdtstr0) + "'");
				if (dataSet.Tables[0].Rows.Count > 0)
				{
					prevyearcode = Conversions.ToString(dataSet.Tables[0].Rows[0][0]);
				}
				else
				{
					prevyearcode = Conversions.ToString(0);
				}
				((Control)dtp2).Visible = true;
				lbl_from.Text = "From                                To";
				dtp1.CustomFormat = "dd/MM/yyyy";
				date_string = " FROM : " + Strings.Format((object)dtp1.Value.Date, "dd/MM/yyyy").ToString() + " TO : " + Strings.Format((object)dtp2.Value.Date, "dd/MM/yyyy").ToString();
			}
		}

		private void cmb_load()
		{
			cmb_filter2.Items.Clear();
			cmb_filter3.Items.Clear();
			int num = report_no;
			checked
			{
				if (num == 2 || num == 5)
				{
