						s = "SELECT  usercode, username FROM users";
						ds_filter1 = ob.populate(s);
						cmb_filter1.Items.Clear();
						cmb_filter1.Items.Add((object)"ALL");
						ob.combofill(ds_filter1.Tables[0], cmb_filter1);
					}
					((Control)lbl_filter2).Visible = true;
					((Control)cmb_filter2).Visible = true;
					lbl_filter2.Text = "Rate";
					s = "select distinct salesbillmain.ratecode,ratename from salesbillmain join itemrateinfo on salesbillmain.companycode=itemrateinfo.companycode and salesbillmain.ratecode=itemrateinfo.ratecode where salesbillmain.companycode='" + mdl_public_variables.companycode + "'";
