			}
			else
			{
				dataRow["companyname"] = mdl_public_variables.companyname + ",  " + mdl_public_variables.comaddress1 + " " + mdl_public_variables.comaddress2 + " " + mdl_public_variables.comcity + "  " + mdl_public_variables.comdistrict + " " + mdl_public_variables.comstate + " " + mdl_public_variables.compin + " Phone:" + mdl_public_variables.comphone + ", E-Mail:" + mdl_public_variables.comemail;
			}
			if (Operators.CompareString(mdl_public_variables.comonoff, "ON", false) == 0)
			{
				dataRow["licensetype"] = "On Shop";
			}
			else
			{
				dataRow["licensetype"] = "Off Shop";
			}
			if (report_no == 58)
			{
				dataRow["date_string"] = Strings.Format((object)dtp1.Value.Date, "dd/MM/yyyy");
				dataRow["zone"] = mdl_public_variables.comphone;
				dataRow["district"] = Strings.Format((object)dtp1.Value, "MMMMMM yyyy").ToString().ToUpper();
			}
			else if (report_no == 23)
			{
				date_string = Strings.Format((object)dtp1.Value.Date, "MMMMMMM - yyyy").ToString();
				dataRow["zone"] = "Kind of Liquor :";
			}
			else if (report_no == 24)
			{
				date_string = Strings.Format((object)dtp1.Value.Date, "MMMMMMM - yyyy").ToString();
				dataRow["zone"] = "Brand Name :";
			}
			else
			{
				dataRow["zone"] = mdl_public_variables.comzone;
				dataRow["recno"] = recno;
				dataRow["district"] = mdl_public_variables.comdistrict;
			}
			dataRow["date_string"] = date_string;
			data_set.Tables["dt_information"].Rows.Add(dataRow);
		}

