				SmtpClient smtpClient = new SmtpClient();
				MailMessage mailMessage = new MailMessage();
				smtpClient.Credentials = new NetworkCredential(mdl_public_variables.com_sender + "@gmail.com", mdl_public_variables.com_password);
				smtpClient.Port = 587;
				smtpClient.Host = "smtp.gmail.com";
				smtpClient.EnableSsl = true;
				mailMessage.To.Add(anothemailId);
				mailMessage.From = new MailAddress(mdl_public_variables.com_sender + "@gmail.com");
				mailMessage.Body = "PLease find the attachment.";
				mailMessage.Attachments.Add(new Attachment(Application.StartupPath + "\\\\" + Rpt.Name + ".pdf"));
				smtpClient.Send(mailMessage);
