		private void frm_ReportsPreview_FormClosing(object sender, FormClosingEventArgs e)
		{
			try
			{
				if (objSheetNew != null)
				{
					if (objSheetNew.Visible == XlSheetVisibility.xlSheetVisible)
					{
						objExcelNew.Workbooks.Close();
						objExcelNew.UserControl = true;
						objExcelNew.Quit();
						objExcelNew.Visible = false;
					}
					ReleaseComObject(objSheetNew);
					ReleaseComObject(objWorkbookNew);
					ReleaseComObject(objExcelNew);
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				if (Operators.CompareString(ex2.Message, "Exception from HRESULT: 0x800401A8", false) == 0)
				{
					ReleaseComObject(objSheetNew);
					ReleaseComObject(objWorkbookNew);
					ReleaseComObject(objExcelNew);
				}
				ProjectData.ClearProjectError();
			}
			finally
			{
				GC.Collect();
			}
		}

		private void ReleaseComObject(object obj)
		{
			try
			{
				Marshal.ReleaseComObject(RuntimeHelpers.GetObjectValue(obj));
				obj = null;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				obj = null;
				ProjectData.ClearProjectError();
			}
			finally
			{
				GC.Collect();
			}
		}

