		private void dtpicker_month_set()
		{
			dtp_monthVisibility.Value = Conversions.ToDate(DateAndTime.Month(dtp_monthVisibility.Value) + "/1/" + DateAndTime.Year(dtp_monthVisibility.Value));
			days = DateTime.DaysInMonth(dtp_monthVisibility.Value.Date.Year, dtp_monthVisibility.Value.Date.Month);
			dateString = " FOR THE MONTH OF : " + Strings.Format((object)dtp_monthVisibility.Value.Date, "MMMMMMMMMMMMM").ToString().ToUpper() + " " + dtp_monthVisibility.Value.Date.Year;
			dtstr1 = Conversions.ToDate(dtp_monthVisibility.Value.Date.Year + "-" + dtp_monthVisibility.Value.Date.Month + "-01");
			dtstr2 = Conversions.ToDate(dtp_monthVisibility.Value.Date.Year + "-" + dtp_monthVisibility.Value.Date.Month + "-" + days);
			checked
			{
				prevdtstr0 = Conversions.ToDate(dtp_monthVisibility.Value.Year - 1 + "-04-01");
				prevdtstr1 = Conversions.ToDate(dtp_monthVisibility.Value.Date.Year - 1 + "-" + dtp_monthVisibility.Value.Date.Month + "-01");
				if (Conversions.ToDouble(days.ToString()) == 29.0)
				{
					prevdtstr2 = Conversions.ToDate(dtp_monthVisibility.Value.Date.Year - 1 + "-" + dtp_monthVisibility.Value.Date.Month + "-" + (days - 1));
				}
				else
				{
					prevdtstr2 = Conversions.ToDate(dtp_monthVisibility.Value.Date.Year - 1 + "-" + dtp_monthVisibility.Value.Date.Month + "-" + days);
				}
				DataSet dataSet = new DataSet();
				dataSet = clsconnect.populate("select yearcode from yearmaster where startdate='" + Conversions.ToString(prevdtstr0) + "'");
				if (dataSet.Tables[0].Rows.Count > 0)
				{
					prevYearCode = Conversions.ToString(dataSet.Tables[0].Rows[0][0]);
				}
				else
				{
					prevYearCode = Conversions.ToString(0);
				}
			}
		}

