		private void rad_category_CheckedChanged(object sender, EventArgs e)
		{
			if (Operators.CompareString(transactionName, "Liquor Register", false) == 0 && rad_category.Checked)
			{
				lbl_categoryBrand.Text = "Category";
				string s = "select mainGroupCode as categoryCode,mainGroupName as categoryName from itemMainGroup where CompanyCode = '" + mdl_public_variables.companycode + "' And isBarItem = 1 ";
				ds_brandCategory = clsconnect.populate(s);
				cmb_brandCatyegory.Items.Clear();
				clsconnect.combofill(ds_brandCategory.Tables[0], cmb_brandCatyegory);
				if (cmb_brandCatyegory.Items.Count > 0)
				{
					cmb_brandCatyegory.SelectedIndex = 0;
				}
			}
		}

