			//IL_01a1: Unknown result type (might be due to invalid IL or missing references)
			if (Operators.CompareString(TextBox2.Text, (string)null, false) == 0)
			{
				Interaction.MsgBox((object)"Please select the backup database to restore.", (MsgBoxStyle)0, (object)null);
				return;
			}
			backuppath = TextBox2.Text;
			mdl_public_variables.con.Close();
			((Component)(object)mdl_public_variables.con).Dispose();
			SqlConnection.ClearAllPools();
			((Control)Label1).Visible = true;
			((Control)bt_restore).Enabled = false;
			mdl_public_variables.server_authentication = ConfigurationManager.AppSettings["authentication"];
			if (Operators.CompareString(mdl_public_variables.server_authentication, "WINDOWS AUTHENTICATION", false) == 0)
			{
				conr = new SqlConnection("Data Source=" + mdl_public_variables.server + ";Initial Catalog=master;Trusted_Connection=True");
			}
			else
			{
				mdl_public_variables.server_id = ConfigurationManager.AppSettings["server_id"];
				mdl_public_variables.server_password = ConfigurationManager.AppSettings["server_password"];
				conr = new SqlConnection("Data Source=" + mdl_public_variables.server + ";Initial Catalog=master;User ID=sa;password=123");
			}
			try
			{
				conr.Open();
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				Interaction.MsgBox((object)"Connection cannot be open", (MsgBoxStyle)0, (object)null);
				((Control)this).Enabled = true;
				((Control)Label2).Visible = false;
				ProjectData.ClearProjectError();
				return;
			}
			s = "RESTORE DATABASE barmanager FROM DISK='" + backuppath + "'";
			SqlCommand val = new SqlCommand(s, conr);
			val.ExecuteNonQuery();
			MyProject.Forms.frm_main.logout();
			Interaction.MsgBox((object)"Database Restored Successfully", (MsgBoxStyle)0, (object)null);
			config = ConfigurationManager.OpenExeConfiguration((ConfigurationUserLevel)0);
			if (config.AppSettings.Settings["ver"] != null)
			{
				config.AppSettings.Settings["ver"].Value = "";
			}
			config.Save((ConfigurationSaveMode)0);
			ConfigurationManager.RefreshSection("appSettings");
			((Form)this).Close();
			conr.Close();
			((Control)bt_restore).Enabled = true;
			((Control)Label2).Visible = false;
		}

