		private void SalesRate_Load(object sender, EventArgs e)
		{
			TextBox1.Text = null;
			TextBox2.Text = null;
			if (mdl_public_variables.count == 7)
			{
				if (mdl_public_variables.flag == 2)
				{
					((Form)this).Icon = Icon.FromHandle(Resources.Rate.GetHicon());
					TextBox1.Text = mdl_public_variables.sales_rate_name.ToUpper();
					((ToolStripItem)tssb_print).Visible = true;
				}
				((Control)TextBox1).Select();
			}
			else if (mdl_public_variables.count == 14)
			{
				((Form)this).Icon = Icon.FromHandle(Resources.Opening.GetHicon());
				((TextBoxBase)TextBox1).ReadOnly = true;
				Label1.Text = "Shop Name";
				((Form)this).Text = "Opening Stock";
				((ToolStripItem)tsl_title).Text = "Opening Stock";
				TextBox1.Text = mdl_public_variables.col1;
				((ToolStripItem)tssb_print).Visible = false;
				((Control)TextBox2).Select();
			}
			refresh_grid();
			dgv1.ClearSelection();
		}

		private void refresh_grid()
		{
			if (mdl_public_variables.count == 7)
			{
				if (mdl_public_variables.flag == 1)
				{
					s = "select itemname,itemcode,0 as salesrate from itemmst where companycode='" + mdl_public_variables.companycode + "' ";
				}
				else
				{
					s = "select itemname,itemcode,salesrate from vw_ratemst where companycode='" + mdl_public_variables.companycode + "' and ratecode='" + mdl_public_variables.sales_rate_code + "'";
				}
			}
			else if (mdl_public_variables.count == 14)
			{
				s = "select shopcode,companycode,itemname,loose,box,qnty,itemcode,rate,totalAmt from opening_stock_show2('" + mdl_public_variables.yearcode + "','" + mdl_public_variables.companycode + "','" + mdl_public_variables.shopcode + "') order by itemname";
			}
			ds = ob.populate(s);
			dgv1.DataSource = ds.Tables[0];
			setvisible();
			dgv1.ClearSelection();
		}

		private void TextBox1_Keydown(object sender, KeyEventArgs e)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			//IL_0009: Invalid comparison between Unknown and I4
			//IL_0061: Unknown result type (might be due to invalid IL or missing references)
			if (!(((int)e.KeyData == 13) & (Operators.CompareString(TextBox1.Text, (string)null, false) != 0)))
			{
				return;
			}
			if (mdl_public_variables.flag == 1 && Operators.CompareString(TextBox1.Text.ToUpper(), "GENERAL", false) == 0)
			{
				Interaction.MsgBox((object)"You Can not create 'GENERAL' rate name", (MsgBoxStyle)16, (object)null);
				return;
			}
			if (!((mdl_public_variables.flag == 1) & (Operators.CompareString(TextBox1.Text, "", false) != 0)) && mdl_public_variables.flag == 2)
			{
				refresh_grid();
			}
			((Control)TextBox2).Select();
		}

		private void TextBox2_KeyDown(object sender, KeyEventArgs e)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			//IL_0009: Invalid comparison between Unknown and I4
			if ((int)e.KeyData == 13)
			{
				dgv1.ClearSelection();
				dgv1.CurrentCell = dgv1[2, 0];
				dgv1.CurrentCell.Selected = true;
				((Control)dgv1).Select();
			}
		}

		private void TextBox2_KeyUp(object sender, KeyEventArgs e)
		{
			dv.Table = ds.Tables[0];
			if (mdl_public_variables.count == 7)
			{
				dv.RowFilter = "itemname like '" + TextBox2.Text + "%' or convert(salesrate, System.String) like '" + TextBox2.Text + "%' ";
			}
			else if (mdl_public_variables.count == 14)
			{
				dv.RowFilter = "itemname like '" + TextBox2.Text + "%' and shopcode='" + mdl_public_variables.shopcode + "'";
			}
			dgv1.DataSource = dv;
			setvisible();
			dgv1.ClearSelection();
		}

		private void setvisible()
		{
			if (mdl_public_variables.count == 7)
			{
				dgv1.Columns[0].ReadOnly = true;
				dgv1.Columns[1].Visible = false;
				dgv1.Columns[0].SortMode = (DataGridViewColumnSortMode)2;
				dgv1.Columns[2].SortMode = (DataGridViewColumnSortMode)2;
			}
			else if (mdl_public_variables.count == 14)
			{
				dgv1.Columns[0].Visible = false;
				dgv1.Columns[1].Visible = false;
				dgv1.Columns[6].Visible = false;
				dgv1.Columns["itemname"].SortMode = (DataGridViewColumnSortMode)2;
				dgv1.Columns["loose"].SortMode = (DataGridViewColumnSortMode)2;
				dgv1.Columns["box"].SortMode = (DataGridViewColumnSortMode)2;
				dgv1.Columns["qnty"].SortMode = (DataGridViewColumnSortMode)2;
				dgv1.Columns["itemname"].ReadOnly = true;
				dgv1.Columns["rate"].SortMode = (DataGridViewColumnSortMode)2;
				dgv1.Columns["totalAmt"].SortMode = (DataGridViewColumnSortMode)2;
				dgv1.Columns["totalAmt"].Visible = false;
			}
		}

		private void Create_Click(object sender, EventArgs e)
		{
			//IL_0a99: Unknown result type (might be due to invalid IL or missing references)
			DataSet dataSet = new DataSet();
			dataSet = ds.GetChanges();
			checked
			{
				if (Operators.CompareString(TextBox1.Text, (string)null, false) != 0)
				{
					if (mdl_public_variables.count == 7)
					{
						if (mdl_public_variables.flag == 1)
						{
							s = "select top 1  ratecode from itemratemst where ratecode like '" + Conversions.ToString(TextBox1.Text[0]) + "%'order by ratecode desc ";
							newratecode = ob.getcode(s, TextBox1.Text);
							mdl_public_variables.sales_rate_code = newratecode;
							s = "insert into itemrateinfo(ratecode,ratename,companycode) values('" + newratecode + "','" + TextBox1.Text.ToUpper() + "','" + mdl_public_variables.companycode + "')";
							ob.insert(s);
						}
						else if (mdl_public_variables.flag == 2)
						{
							s = "update itemrateinfo set ratename='" + TextBox1.Text.ToUpper() + "' where ratecode='" + mdl_public_variables.sales_rate_code + "' and companycode='" + mdl_public_variables.companycode + "'";
							ob.insert(s);
						}
						s = "delete from itemratemst where companycode='" + mdl_public_variables.companycode + "' and ratecode='" + mdl_public_variables.sales_rate_code + "'";
						ob.insert(s);
						int num = ds.Tables[0].Rows.Count - 1;
						int num2 = 0;
						while (true)
						{
							int num3 = num2;
							int num4 = num;
							if (num3 <= num4)
							{
								s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)string.Concat(string.Concat(string.Concat("insert into itemratemst (companycode,ratecode,itemcode,salesrate) values('" + mdl_public_variables.companycode, "','"), mdl_public_variables.sales_rate_code), "','"), ds.Tables[0].Rows[num2][1]), (object)"','"), ds.Tables[0].Rows[num2][2]), (object)"')"));
								ob.insert(s);
								if (Operators.CompareString(mdl_public_variables.sales_rate_code, "G00001", false) == 0)
								{
									s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)"update itemmst set salesrate='", ds.Tables[0].Rows[num2][2]), (object)"' where itemcode='"), ds.Tables[0].Rows[num2][1]), (object)"'"));
									ob.insert(s);
								}
								num2++;
								continue;
							}
							break;
						}
					}
					else if (mdl_public_variables.count == 14 && ds.GetChanges() != null)
					{
						int num5 = dataSet.Tables[0].Rows.Count - 1;
						int num6 = 0;
						while (true)
						{
							int num7 = num6;
							int num4 = num5;
							if (num7 <= num4)
							{
								s1 = Conversions.ToInteger(dataSet.Tables[0].Rows[num6][3]);
								s2 = Conversions.ToInteger(dataSet.Tables[0].Rows[num6][4]);
								s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)"select packing,ml,kflname from vw_itemCodebarCode itemmst where itemcode='", dataSet.Tables[0].Rows[num6][6]), (object)"' and companycode= '"), (object)mdl_public_variables.companycode), (object)"'"));
								DataSet dataSet2 = ob.populate(s);
								if (Operators.ConditionalCompareObjectEqual(dataSet2.Tables[0].Rows[0]["kflname"], (object)"NAI", false))
								{
									count = (int)Math.Round(Convert.ToDouble(RuntimeHelpers.GetObjectValue(dataSet2.Tables[0].Rows[0]["ml"])));
									count = s2 * count + s1;
								}
								else
								{
									count = (int)Math.Round(Convert.ToDouble(RuntimeHelpers.GetObjectValue(dataSet2.Tables[0].Rows[0]["packing"])));
									count = s2 * count + s1;
								}
								dataSet.Tables[0].Rows[num6][5] = count;
								s = "delete from openingStockDetail where itemcode='" + dataSet.Tables[0].Rows[num6][6].ToString().ToUpper() + "' and shopcode='" + mdl_public_variables.shopcode + "' and companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "'";
								ob.insert(s);
								s = "delete from openingstockmst where itemcode='" + dataSet.Tables[0].Rows[num6][6].ToString().ToUpper() + "' and shopcode='" + mdl_public_variables.shopcode + "' and companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "'";
								ob.insert(s);
								s = "insert into openingstockmst(shopcode,companycode,yearcode,itemcode,loose,box,qnty,trndate,purchaseRate,totalAmount) values('" + mdl_public_variables.shopcode + "','" + mdl_public_variables.companycode + "','" + mdl_public_variables.yearcode + "','" + dataSet.Tables[0].Rows[num6][6].ToString().ToUpper() + "','" + dataSet.Tables[0].Rows[num6][3].ToString().ToUpper() + "','" + dataSet.Tables[0].Rows[num6][4].ToString().ToUpper() + "','" + dataSet.Tables[0].Rows[num6][5].ToString().ToUpper() + "','" + Conversions.ToString(mdl_public_variables.comstdate) + "','" + dataSet.Tables[0].Rows[num6][7].ToString() + "','" + dataSet.Tables[0].Rows[num6][8].ToString() + "')";
								ob.insert(s);
								s = "insert into openingStockDetail(shopcode,companycode,yearcode,itemcode,loose,box,qnty,trndate,batchNo,purchaseRate,totalAmount) values('" + mdl_public_variables.shopcode + "','" + mdl_public_variables.companycode + "','" + mdl_public_variables.yearcode + "','" + dataSet.Tables[0].Rows[num6][6].ToString().ToUpper() + "','" + dataSet.Tables[0].Rows[num6][3].ToString().ToUpper() + "','" + dataSet.Tables[0].Rows[num6][4].ToString().ToUpper() + "','" + dataSet.Tables[0].Rows[num6][5].ToString().ToUpper() + "','" + Conversions.ToString(mdl_public_variables.comstdate) + "','openingBatch','" + dataSet.Tables[0].Rows[num6][7].ToString() + "','" + dataSet.Tables[0].Rows[num6][8].ToString() + "')";
								ob.insert(s);
								num6++;
								continue;
							}
							break;
						}
					}
				}
				else
				{
					Interaction.MsgBox((object)"Fields can not be blank.", (MsgBoxStyle)48, (object)"Blank Fields");
				}
				if (mdl_public_variables.flag == 0)
				{
					((Control)TextBox1).Select();
					return;
				}
				((Form)this).Close();
				((Control)MyProject.Forms.frm_Form1).Enabled = true;
				try
				{
					Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
				}
			}
		}

