		private void sign_in_Load(object sender, EventArgs e)
		{
			cmb_authentication.SelectedItem = RuntimeHelpers.GetObjectValue(cmb_authentication.Items[0]);
			config = ConfigurationManager.OpenExeConfiguration((ConfigurationUserLevel)0);
			checked
			{
				if (Operators.CompareString(ConfigurationManager.AppSettings["type"], "single", false) == 0)
				{
					((Control)txt_server).Visible = true;
					((Control)cmb_server).Visible = false;
					if (Operators.CompareString(ConfigurationManager.AppSettings["server_name"], "", false) == 0)
					{
						txt_server.Text = ((ServerComputer)MyProject.Computer).Name.ToString().ToUpper() + "\\SQLEXPRESS";
					}
					else
					{
						txt_server.Text = ConfigurationManager.AppSettings["server_name"];
					}
					((Control)txt_server).Select();
				}
				else
				{
					if (Operators.CompareString(ConfigurationManager.AppSettings["type"], "multi", false) != 0)
					{
						return;
					}
					((Control)bt_add).Visible = true;
					((Control)cmb_server).Visible = true;
					((Control)txt_server).Visible = false;
					if (Operators.CompareString(ConfigurationManager.AppSettings["server_name"], "", false) == 0)
					{
						cmb_server.Items.Add((object)(((ServerComputer)MyProject.Computer).Name.ToString().ToUpper() + "\\SQLEXPRESS"));
					}
					else
					{
						string[] array = ConfigurationManager.AppSettings["server_name"].Split(new char[1] { ',' });
						int num = array.Length - 1;
						int num2 = 0;
						while (true)
						{
							int num3 = num2;
							int num4 = num;
							if (num3 > num4)
							{
								break;
							}
							cmb_server.Items.Add((object)array[num2]);
							num2++;
						}
					}
					cmb_server.SelectedIndex = 0;
					((Control)cmb_server).Select();
				}
			}
		}

		private void Button1_Click(object sender, EventArgs e)
		{
			if (Operators.CompareString(config.AppSettings.Settings["type"].Value, "single", false) == 0)
			{
				if (config.AppSettings.Settings["server_name"] == null)
				{
					config.AppSettings.Settings.Add("server_name", txt_server.Text);
					config.AppSettings.Settings.Add("authentication", cmb_authentication.Text);
				}
				else
				{
					config.AppSettings.Settings["server_name"].Value = txt_server.Text;
					config.AppSettings.Settings["authentication"].Value = cmb_authentication.Text;
				}
			}
			else
			{
				if (config.AppSettings.Settings["server_name"] == null)
				{
					config.AppSettings.Settings.Add("server_name", cmb_server.Text);
					config.AppSettings.Settings.Add("authentication", cmb_authentication.Text);
				}
				else if (!config.AppSettings.Settings["server_name"].Value.ToString().Contains(cmb_server.Text))
				{
					config.AppSettings.Settings["server_name"].Value = config.AppSettings.Settings["server_name"].Value + "," + cmb_server.Text;
					config.AppSettings.Settings["authentication"].Value = cmb_authentication.Text;
				}
				mdl_public_variables.server = cmb_server.Text;
			}
			if (config.AppSettings.Settings["printer"] == null)
			{
				config.AppSettings.Settings.Add("printer", "");
			}
			if (config.AppSettings.Settings["backup"] == null)
			{
				config.AppSettings.Settings.Add("backup", "");
			}
			if (config.AppSettings.Settings["ver"] == null)
			{
				config.AppSettings.Settings.Add("ver", "");
			}
			if (config.AppSettings.Settings["SERVER"] == null)
			{
				config.AppSettings.Settings.Add("SERVER", "");
			}
			config.Save((ConfigurationSaveMode)0);
			ConfigurationManager.RefreshSection("appSettings");
			((Form)this).Close();
			if (!((Control)MyProject.Forms.frm_sys_admin).Visible)
			{
				MyProject.Forms.frm_main.comcheck();
			}
		}

