		private void blk_ltr_calc()
		{
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c3: Expected O, but got Unknown
			flblk = true;
			ds_bulk_liter ds_bulk_liter2 = new ds_bulk_liter();
			s = "select liquor,groupname,kflname,sum(ltr_sale) as  'ltr_sale' from vw_ltr_sale where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "' and trndate>='" + Conversions.ToString(dtp1.Value.Date) + "' and trndate<='" + Conversions.ToString(dtp2.Value.Date) + "' group by liquor,companycode,yearcode,groupname,kflname order by liquor";
			mdl_public_variables.closecon();
			mdl_public_variables.opencon();
			SqlDataAdapter val = new SqlDataAdapter(s, mdl_public_variables.con);
			((DbDataAdapter)(object)val).Fill((DataSet)ds_bulk_liter2, "DataTable1");
			mdl_public_variables.closecon();
			DataTable dataTable = ds_bulk_liter2.Tables["DataTable2"];
			DataRow dataRow = dataTable.NewRow();
			dataRow["companyname"] = mdl_public_variables.companyname;
			dataRow["date1"] = dtp1.Value.Date.ToString();
			dataRow["date2"] = dtp2.Value.Date.ToString();
			ds_bulk_liter2.Tables["DataTable2"].Rows.Add(dataRow);
			Rpt = (ReportDocument)(object)new rep_bulk_liter();
			if (ds_bulk_liter2.Tables["DataTable2"].Rows.Count > 0)
			{
				Rpt.SetDataSource((DataSet)ds_bulk_liter2);
				create_pdf(Rpt, Application.StartupPath + "\\Bulk_ltr.pdf");
			}
			else
			{
				flblk = false;
			}
		}

