		private void stocktransfer_Load(object sender, EventArgs e)
		{
			((Control)MyProject.Forms.frm_Form1).Enabled = false;
			((Form)this).Icon = Icon.FromHandle(Resources.truck.GetHicon());
			s = "select itemcode,itemname,packing,ml,kflname as itemtype  \r\n from vw_itemCodebarCode itemmst  \r\n where companycode='" + mdl_public_variables.companycode + "'  \r\n order by itemname ";
			dsitem = ob.populate(s);
			cmb_item.Items.Clear();
			cmb_item.Items.Add((object)"All");
			ob.combofill(dsitem.Tables[0], cmb_item);
			s = "select companycode,shopcode,shopname from storage where companycode='" + mdl_public_variables.companycode + "' order by shopname";
			ds1 = ob.populate(s);
			checked
			{
				int num = ds1.Tables[0].Rows.Count - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					cmb_from.Items.Add((object)ds1.Tables[0].Rows[num2][2].ToString());
					cmb_to.Items.Add((object)ds1.Tables[0].Rows[num2][2].ToString());
					num2++;
				}
				cmb_from.Text = ds1.Tables[0].Rows[0][2].ToString();
				cmb_to.Text = ds1.Tables[0].Rows[0][2].ToString();
				if (mdl_public_variables.flag == 2)
				{
					dtp1.Value = mdl_public_variables.transaction_date;
					cmb_from.SelectedItem = mdl_public_variables.storename1;
					cmb_to.SelectedItem = mdl_public_variables.storename2;
					TextBox1.Text = mdl_public_variables.transaction;
					s = "select trnid from stk_transfer_main where TrnNo='" + mdl_public_variables.transaction + "' and companycode='" + mdl_public_variables.companycode + "' and yearcode='" + mdl_public_variables.yearcode + "' and shopcode_to='" + mdl_public_variables.storecode2 + "'";
					newid = (int)Convert.ToInt64(ob.executereader(s));
				}
				dgv1.ClearSelection();
				((Control)dtp1).Select();
			}
		}

