		private void fill_datagrid()
		{
			dgv1.Rows.Clear();
			s = "select opening_closing_stock.itemcode,opening_closing_stock.itemname,stock,opening_closing_stock.companycode,storecode,yearcode,packing,ml from opening_closing_stock('" + Conversions.ToString(mdl_public_variables.comstdate) + "','" + Conversions.ToString(dtp1.Value.Date) + "','" + Conversions.ToString(dtp1.Value.Date) + "')JOIN vw_itemCodebarCode AS itemmst ON opening_closing_stock.companycode = itemmst.companycode and opening_closing_stock.itemcode = itemmst.itemcode where opening_closing_stock.companycode='" + mdl_public_variables.companycode + "' and storecode='" + store_code1 + "' and yearcode='" + mdl_public_variables.yearcode + "' and  (stock <> 0 or bottles_sold <> 0) order by itemname";
			dsstock = ob.populate(s);
			cmb_item.SelectedIndex = 0;
			dv.Table = dsstock.Tables[0];
			dv.RowFilter = "storecode='" + store_code1 + "'";
			dgv2.DataSource = dv;
			gettrn();
			checked
			{
				if (mdl_public_variables.flag == 2)
				{
					s = "SELECT vw_itemCodebarCode.itemcode, vw_itemCodebarCode.itemname,fun_stock.stock,stk_transfer_main.CompanyCode, stk_transfer_main.shopcode_frm,  \r\n stk_transfer_main.YearCode, vw_itemCodebarCode.packing, stk_transfer_detail.loose, stk_transfer_detail.box, stk_transfer_detail.qnty  \r\n FROM stk_transfer_detail  \r\n JOIN stk_transfer_main ON stk_transfer_main.CompanyCode = stk_transfer_detail.CompanyCode  \r\n AND stk_transfer_main.YearCode = stk_transfer_detail.yearcode AND stk_transfer_main.TrnNo = stk_transfer_detail.trnno  \r\n JOIN vw_itemCodebarCode ON vw_itemCodebarCode.itemcode = stk_transfer_detail.ItemCode  \r\n AND vw_itemCodebarCode.companycode = stk_transfer_detail.CompanyCode  \r\n JOIN fun_stock('" + mdl_public_variables.companycode + "','" + mdl_public_variables.yearcode + "') ON stk_transfer_detail.yearcode = fun_stock.yearcode AND stk_transfer_detail.CompanyCode = fun_stock.companycode  \r\n AND stk_transfer_detail.ItemCode = fun_stock.itemcode AND stk_transfer_main.shopcode_frm = fun_stock.storecode  \r\n AND stk_transfer_main.CompanyCode = fun_stock.companycode AND stk_transfer_main.YearCode = fun_stock.yearcode  \r\n WHERE stk_transfer_detail.trnno='" + mdl_public_variables.transaction + "' AND stk_transfer_detail.companycode='" + mdl_public_variables.companycode + "' AND stk_transfer_detail.yearcode='" + mdl_public_variables.yearcode + "'  \r\n AND stk_transfer_main.shopcode_to='" + mdl_public_variables.storecode2 + "'  \r\n ORDER BY vw_itemCodebarCode.itemname ";
					dsedit = ob.populate(s);
					int num = dsedit.Tables[0].Rows.Count - 1;
					int num2 = 0;
					while (true)
					{
						int num3 = num2;
						int num4 = num;
						if (num3 > num4)
						{
							break;
						}
						dgv1.Rows.Add(new object[10]
						{
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][0]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][1]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][2]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][3]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][4]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][5]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][6]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][7]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][8]),
							RuntimeHelpers.GetObjectValue(dsedit.Tables[0].Rows[num2][9])
						});
						num2++;
					}
					dgv1.ClearSelection();
				}
				DataGridView val = dgv2;
				val.Columns[0].Visible = false;
				val.Columns[3].Visible = false;
				val.Columns[4].Visible = false;
				val.Columns[5].Visible = false;
				val.Columns[6].Visible = false;
				val.Columns[7].Visible = false;
				val.Columns[1].ReadOnly = true;
				val.Columns[2].ReadOnly = true;
				val.Columns[1].HeaderText = "Item Name";
				val.Columns[2].HeaderText = "Stock";
				val.Columns[1].Width = 180;
				val.Columns[2].Width = 50;
				val.ClearSelection();
				val.AllowUserToAddRows = false;
				val = null;
			}
		}

