		private void Button1_Click(object sender, EventArgs e)
		{
			//IL_044e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0439: Unknown result type (might be due to invalid IL or missing references)
			if (!ob.date_check(dtp1.Value.Date))
			{
				return;
			}
			checked
			{
				if (Operators.CompareString(store_code1, store_code2, false) != 0)
				{
					newid = (int)Math.Round(Conversion.Val(RuntimeHelpers.GetObjectValue(ob.get_id())) + 1.0);
					if (mdl_public_variables.flag == 1)
					{
						ob.add_id(newid, "Stocktransfer_add");
					}
					else if (mdl_public_variables.flag == 2)
					{
						ob.add_id(newid, "Stocktransfer_edit");
					}
					if (mdl_public_variables.flag == 2)
					{
						s = "delete from stk_transfer_detail where stk_transfer_detail.trnno='" + mdl_public_variables.transaction + "' and stk_transfer_detail.companycode='" + mdl_public_variables.companycode + "' and stk_transfer_detail.yearcode='" + mdl_public_variables.yearcode + "' ";
						ob.insert(s);
						s = "delete from stk_transfer_main where stk_transfer_main.trnno='" + mdl_public_variables.transaction + "' and stk_transfer_main.companycode='" + mdl_public_variables.companycode + "' and stk_transfer_main.yearcode='" + mdl_public_variables.yearcode + "'";
						ob.insert(s);
					}
					DataSet dataSet = new DataSet();
					if (dgv1.Rows.Count > 0)
					{
						s = "insert into stk_transfer_main(companycode,yearcode,trnno,trndate,shopname_from,shopname_to,shopcode_frm,shopcode_to,trnid) values('" + mdl_public_variables.companycode + "','" + mdl_public_variables.yearcode + "','" + TextBox1.Text + "','" + Conversions.ToString(dtp1.Value.Date) + "','" + cmb_from.Text + "','" + cmb_to.Text + "','" + store_code1 + "','" + store_code2 + "','" + Conversions.ToString(newid) + "')";
						ob.insert(s);
						int num = dgv1.Rows.Count - 1;
						int num2 = 0;
						while (true)
						{
							int num3 = num2;
							int num4 = num;
							if (num3 <= num4)
							{
								s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)string.Concat("insert into stk_transfer_detail(     companycode,                               itemcode,                                    box,                      loose,                          qnty,                       trnno,                trndate,                     yearcode) values(                       '" + mdl_public_variables.companycode, "','"), dgv1[0, num2].Value), (object)"','"), dgv1[8, num2].Value), (object)"','"), dgv1[7, num2].Value), (object)"','"), dgv1[9, num2].Value), (object)"','"), (object)TextBox1.Text), (object)"','"), (object)dtp1.Value.Date), (object)"','"), (object)mdl_public_variables.yearcode), (object)"')"));
								ob.insert(s);
								num2++;
								continue;
							}
							break;
						}
						try
						{
							Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
						}
						catch (Exception ex)
						{
							ProjectData.SetProjectError(ex);
							Exception ex2 = ex;
							ProjectData.ClearProjectError();
						}
						fill_datagrid();
						if (mdl_public_variables.flag == 2)
						{
							((Form)this).Close();
						}
					}
					else
					{
						Interaction.MsgBox((object)"Please enter item for transfer", (MsgBoxStyle)0, (object)null);
					}
				}
				else
				{
					Interaction.MsgBox((object)"Please select different stores for stock transfer.", (MsgBoxStyle)64, (object)null);
					dgv1.ClearSelection();
					((Control)cmb_to).Select();
				}
			}
		}

		private void gettrn()
		{
			DataSet dataSet = new DataSet();
			s = "select top 1 trnno from stk_transfer_main order by cast ( trnno As Integer)   desc";
			dataSet = ob.populate(s);
			if (dataSet.Tables[0].Rows.Count == 0)
			{
				TextBox1.Text = Conversions.ToString(1);
			}
			else
			{
				TextBox1.Text = Conversions.ToString(checked(Convert.ToInt32(RuntimeHelpers.GetObjectValue(dataSet.Tables[0].Rows[0][0])) + 1));
			}
		}

		private void Button2_Click(object sender, EventArgs e)
		{
			if (myParentForm == null)
			{
				((Form)this).Close();
			}
