		private void storage_Load(object sender, EventArgs e)
		{
			if (mdl_public_variables.flag == 2)
			{
				if (mdl_public_variables.count == 3)
				{
					TextBox1.Text = mdl_itemmst.ml.ToString();
					TextBox2.Text = mdl_itemmst.packing.ToString();
				}
				else if (mdl_public_variables.count == 10)
				{
					TextBox1.Text = mdl_public_variables.col1;
					TextBox2.Text = mdl_public_variables.col2;
					cmb_type.SelectedItem = mdl_public_variables.col3;
				}
			}
			if (mdl_public_variables.count == 3)
			{
				((Form)this).Text = "Measure & Packing";
				((TextBoxBase)TextBox1).MaxLength = 4;
				((TextBoxBase)TextBox2).MaxLength = 2;
				TextBox2.Multiline = false;
				((Control)TextBox2).Height = 25;
				Label1.Text = "ML";
				Label2.Text = "Packing";
			}
			else
			{
				((Form)this).Text = "Strore Master";
				((Control)lbl_type).Visible = true;
				((Control)cmb_type).Visible = true;
			}
			((Control)TextBox1).Select();
		}

