		private void frm_sys_admin_Load(object sender, EventArgs e)
		{
			if (Operators.CompareString(ConfigurationManager.AppSettings["type"], "multi", false) == 0)
			{
				chk_connectivity.Checked = true;
			}
			else
			{
				chk_connectivity.Checked = false;
			}
			((Form)this).Icon = Resources.Madhushala_icon;
			checked
			{
				((Control)this).Width = ((Control)Panel2).Width + 5;
				((Control)this).Height = ((Control)Panel2).Height + 35;
				((Control)GroupBox1).Visible = false;
				((Control)GroupBox2).Visible = false;
				chk_salesStatus.Checked = mdl_public_variables.sms_on;
				chk_upload.Checked = mdl_public_variables.backupupload;
				txt_smspassword.Text = mdl_public_variables.sms_password;
				chk_EditDelete.Checked = mdl_public_variables.sms_billEditDelete;
				chk_partySale.Checked = mdl_public_variables.sms_PartySale;
				chk_creditCard.Checked = mdl_public_variables.sms_creditCardSale;
				chk_payment.Checked = mdl_public_variables.sms_payment;
				chk_receipt.Checked = mdl_public_variables.sms_receipt;
				chk_FlCs.Checked = mdl_public_variables.FLCS;
				txt_SenderSmsId.Text = mdl_public_variables.senderSMSid;
				try
				{
					DataSet dataSet = new DataSet();
					s = "select isnull(exciseId,''),isnull(excisePassword,'') from companyparamtr";
					dataSet = ob.populate(s);
					txt_exciseId.Text = dataSet.Tables[0].Rows[0][0].ToString();
					txt_excise_password.Text = dataSet.Tables[0].Rows[0][1].ToString();
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
				}
			}
		}

