		private void bt_startSerilization_Click(object sender, EventArgs e)
		{
			//IL_008b: Unknown result type (might be due to invalid IL or missing references)
			((Control)panel_CompanyYear).Visible = true;
			ds_company = ob.populate("Select companycode,companyName from companymast ");
			cmb_company.Items.Clear();
			ob.combofill(ds_company.Tables[0], cmb_company);
			if (cmb_company.Items.Count > 0)
			{
				cmb_company.SelectedIndex = 0;
			}
