		private void cmb_company_SelectedIndexChanged(object sender, EventArgs e)
		{
			//IL_00d3: Unknown result type (might be due to invalid IL or missing references)
			if (cmb_company.SelectedIndex > -1)
			{
				ds_year = ob.populate(Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)"select yearCode,yearRange from yearmst where companycode = '", ds_company.Tables[0].Rows[cmb_company.SelectedIndex][0]), (object)"' order by yearCode DESC ")));
				cmb_year.Items.Clear();
				ob.combofill(ds_year.Tables[0], cmb_year);
				if (cmb_year.Items.Count > 0)
				{
					cmb_year.SelectedIndex = 0;
				}
				else
				{
					Interaction.MsgBox((object)"No finincial year present for this company, please change company, click ok to close bill serilization.", (MsgBoxStyle)64, (object)Application.ProductName);
				}
			}
		}

		private void bt_billSerilizationOk_Click(object sender, EventArgs e)
		{
			//IL_017d: Unknown result type (might be due to invalid IL or missing references)
