				{
					s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)"exec serialise_n_reference_sale_bills '", ds_company.Tables[0].Rows[cmb_company.SelectedIndex][0]), (object)"','"), ds_year.Tables[0].Rows[cmb_year.SelectedIndex][0]), (object)"','0' "));
				}
				else
				{
					s = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)" exec serialise_n_reference_sale_bills '", ds_company.Tables[0].Rows[cmb_company.SelectedIndex][0]), (object)"','"), ds_year.Tables[0].Rows[cmb_year.SelectedIndex][0]), (object)"','1' "));
