			string text2 = Conversions.ToString(text[0]) + Conversions.ToString(text[11]) + Conversions.ToString(text[1]) + Conversions.ToString(text[9]) + Conversions.ToString(text[3]) + Conversions.ToString(text[8]) + Conversions.ToString(text[4]) + Conversions.ToString(text[7]) + Conversions.ToString(text[6]);
			if (Operators.CompareString(txt_password.Text, text2, false) == 0)
			{
				((Control)txt_reportCategory).Visible = true;
				((Control)cmb_reportCategory).Visible = false;
				((Control)Panel3).Visible = false;
			}
			else
			{
				CheckBox1.Checked = false;
			}
		}

