		}

		private void but_sales_Click(object sender, EventArgs e)
		{
			//IL_005b: Unknown result type (might be due to invalid IL or missing references)
			if (rad_tally.Checked)
			{
				path = Application.StartupPath.ToString();
			}
			else
			{
				path = txt_path.Text;
			}
			if ((path.Length == 0) & rad_xml.Checked)
			{
				Interaction.MsgBox((object)"Please select path for save xml file", (MsgBoxStyle)64, (object)null);
				return;
			}
			if (chk_sales.Checked)
			{
				salesexport();
			}
			if (chk_purchase.Checked)
			{
				purchaseexport();
			}
			if (chk_payment.Checked)
			{
				paymentExport();
			}
			if (chk_receipt.Checked)
			{
				receipt_export();
			}
			if (chk_journal.Checked)
			{
				journalexport();
			}
			if (chk_contra.Checked)
			{
				contra_export();
			}
		}

		private void salesexport()
		{
			//IL_20b7: Unknown result type (might be due to invalid IL or missing references)
			//IL_2178: Unknown result type (might be due to invalid IL or missing references)
			//IL_2144: Unknown result type (might be due to invalid IL or missing references)
			//IL_1fd0: Unknown result type (might be due to invalid IL or missing references)
			//IL_0277: Unknown result type (might be due to invalid IL or missing references)
			//IL_0281: Expected O, but got Unknown
			//IL_2083: Unknown result type (might be due to invalid IL or missing references)
			//IL_10c2: Unknown result type (might be due to invalid IL or missing references)
			//IL_10cc: Expected O, but got Unknown
			//IL_0731: Unknown result type (might be due to invalid IL or missing references)
			//IL_073b: Expected O, but got Unknown
			DataSet dataSet = new DataSet();
			s = "IF  EXISTS (SELECT * FROM sys.views WHERE  name='vwsalesdata') drop view vwsalesdata";
			ob1.insert(s);
			s = "create view vwSalesData  as SELECT salesbillmain.trndate as date, salesbillmain.salestype as SalesAcount, ledger.ledgerName as AcountHead, salesbillmain.trnno, itemmst.itemname,salesbilldetail.qnty as itemqty, salesbilldetail.rate as itemrate, salesbilldetail.itemAmount, (salesbilldetail.itemAmount*((salesbillmain.discamount)/(salesbillmain.netamount+salesbillmain.discamount)))as discount,(salesbilldetail.itemAmount-(salesbilldetail.itemAmount*((salesbillmain.discamount)/(salesbillmain.netamount+salesbillmain.discamount)))) as totnetamt ,(salesbilldetail.itemAmount*(isnull(sales_tax.tax_amount,0)/(salesbillmain.amount)))as surcharge FROM salesbillmain JOIN salesbilldetail ON salesbillmain.companycode = salesbilldetail.companycode AND salesbillmain.trndate = salesbilldetail.trndate AND salesbillmain.trnno = salesbilldetail.trnno AND salesbillmain.yearcode = salesbilldetail.yearcode JOIN MasterAccountsLedger as ledger ON salesbillmain.companycode = ledger.companycode AND salesbillmain.ledgercode = ledger.ledgerCode JOIN itemmst ON salesbilldetail.companycode = itemmst.companycode AND salesbilldetail.itemcode = itemmst.itemcode left join sales_tax on salesbillmain.companycode = sales_tax.companycode and salesbillmain.yearcode = sales_tax.yearcode and salesbillmain.trnno = sales_tax.trnno left join MasterAccountsLedger as ledger1 on  sales_tax.companycode = ledger1.companycode AND sales_tax.tax_book = ledger1.ledgerCode and ledger1.ledgerName = 'SURCHARGE ACCOUNT'where salesbillmain.companycode='" + mdl_public_variables.companycode + "' and salesbillmain.yearcode='" + mdl_public_variables.yearcode + "' and salesbillmain.trndate>='" + Conversions.ToString(dtp1.Value.Date) + "'  and salesbillmain.trndate<='" + Conversions.ToString(dtp2.Value.Date) + "' group by salesbillmain.trnno,salesbillmain.companycode,salesbillmain.yearcode,salesbillmain.trndate,ledger.ledgerName,salestype,itemmst.itemname,salesbilldetail.qnty, salesbilldetail.rate, salesbilldetail.itemAmount,salesbillmain.discamount,salesbillmain.netamount,salesbillmain.amount,sales_tax.tax_amount";
			ob1.insert(s);
			s = "SELECT convert(varchar(10),date,112) as date, SalesAcount, AcountHead, trnno, itemname, itemqty, itemrate, round (itemAmount,2)as itemAmount,round (discount,2)as discount , round (totnetamt,2)as totnetamt,round (surcharge,2)   FROM  vwsalesdata where SalesAcount not like 'RETURN' union all  SELECT convert(varchar(10),date,112) as date, SalesAcount, AcountHead, trnno, itemname, (itemqty * -1) as itemqty , itemrate, round((itemAmount*-1),2) as itemAmount, round (discount*-1,2) as discount, round((totnetamt*-1),2) as totnetamt,round((surcharge*-1),2) from vwsalesdata where SalesAcount like 'RETURN' ";
			dataSet = ob1.populate(s);
			string outputFileName = path + "\\SalesMaster.xml";
			string outputFileName2 = path + "\\sales.xml";
