			s = "SELECT PurchaseTaxDetail.trnno,  PurchaseTaxDetail.TaxAmount, taxdetail.taxname,taxdetail.sig FROM PurchaseTaxDetail INNER JOIN taxdetail ON PurchaseTaxDetail.companycode = taxdetail.companycode AND PurchaseTaxDetail.schemecode = taxdetail.SchemeCode AND  PurchaseTaxDetail.TaxCode = taxdetail.TaxCode WHERE PurchaseTaxDetail.trnno in (select distinct no from vwgrndata) and PurchaseTaxDetail.companycode ='" + mdl_public_variables.companycode + "' and PurchaseTaxDetail.yearcode = '" + mdl_public_variables.yearcode + "'union all select PurchaseTaxDetail.trnno, PurchaseTaxDetail.TaxAmount, 'SALES TAX ON MRP' as taxname, '+' as sig from purchasetaxdetail where taxaccount = '" + mdl_public_variables.com_salesonmrp_acc + "' and PurchaseTaxDetail.trnno in (SELECT DISTINCT no FROM vwgrndata) and PurchaseTaxDetail.companycode ='" + mdl_public_variables.companycode + "' and PurchaseTaxDetail.yearcode = '" + mdl_public_variables.yearcode + "'";
