		private void Taxscm_Load(object sender, EventArgs e)
		{
			cls_conn cls_conn2 = new cls_conn();
			string s = "select ledgerCode,ledgerName from MasterAccountsLedger where companyCode='" + mdl_public_variables.companycode + "' order by ledgerName";
			ds = cls_conn2.populate(s);
			checked
			{
				int num = ds.Tables[0].Rows.Count - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					cmb_account.Items.Add(RuntimeHelpers.GetObjectValue(ds.Tables[0].Rows[num2][1]));
					num2++;
				}
				schemeload();
			}
		}

		private void schemeload()
		{
			r = 0;
			@base = 0;
			code1 = "";
			txt_schemename.Text = "";
			cmb_tax.Items.Clear();
			cmb_formula.Items.Clear();
			cmb_calcon.Items.Clear();
			cmb_formula.Items.Add((object)"+");
			cmb_formula.Items.Add((object)"-");
			cmb_calcon.Items.Add((object)"Main Gross");
			cmb_calcon.Items.Add((object)"Gross and");
			cmb_calcon.Items.Add((object)"After TAX");
			cmb_calcon.Items.Add((object)"On Tax");
			taxload();
			checked
			{
				if (mdl_public_variables.flag == 2)
				{
					cls_conn cls_conn2 = new cls_conn();
					string s = "Select taxdetail.companycode,schemecode,schemename,srno,taxcode,taxname,MasterAccountsLedger.ledgerCode,MasterAccountsLedger.ledgerName,sig,taxrate,taxamount,calc_on,after_discount,after_saletax,base  \r\n from taxdetail join MasterAccountsLedger on MasterAccountsLedger.companycode=taxdetail.companycode and MasterAccountsLedger.ledgerCode=taxdetail.ledcode  \r\n where schemecode='" + mdl_public_variables.col1 + "' and taxdetail.companycode='" + mdl_public_variables.companycode + "'  \r\n order by srno ";
					ds1 = cls_conn2.populate(s);
					txt_schemename.Text = ds1.Tables[0].Rows[0][2].ToString();
					code1 = ds1.Tables[0].Rows[0][1].ToString();
					int num = ds1.Tables[0].Rows.Count - 1;
					int num2 = 0;
					while (true)
					{
						int num3 = num2;
						int num4 = num;
						if (num3 > num4)
						{
							break;
						}
						cmb_tax.Items.Add((object)ds1.Tables[0].Rows[num2][5].ToString());
						num2++;
					}
					dgv1.DataSource = ds1.Tables[0];
					r = dgv1.Rows.Count;
				}
				griddesign();
				((Control)txt_schemename).Select();
			}
		}

