		private void frm_unit_Load(object sender, EventArgs e)
		{
			if (mdl_public_variables.flag == 2)
			{
				if (mdl_public_variables.count == 502)
				{
					txt_issueUnit.Text = mdl_itemmst.issueunit;
					txt_issueQnty.Text = Conversions.ToString(mdl_itemmst.issueqnty);
					txt_purchaseUnit.Text = mdl_itemmst.purchaseunit;
					txt_purchaseQnty.Text = Conversions.ToString(mdl_itemmst.purchaseqnty);
				}
				((ButtonBase)btn_save).Text = "&Update";
			}
		}

		private void btn_save_Click(object sender, EventArgs e)
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d8: Unknown result type (might be due to invalid IL or missing references)
			//IL_02b7: Unknown result type (might be due to invalid IL or missing references)
			//IL_0410: Unknown result type (might be due to invalid IL or missing references)
			if (Operators.CompareString(Strings.Trim(txt_issueUnit.Text), "", false) == 0)
			{
				Interaction.MsgBox((object)"Please enter Basic Unit Name", (MsgBoxStyle)64, (object)null);
				return;
			}
			if (Conversion.Val(txt_issueQnty.Text) < 0.0)
			{
				Interaction.MsgBox((object)"Please enter Basic Qnty ", (MsgBoxStyle)64, (object)null);
				return;
			}
			if (Operators.CompareString(Strings.Trim(txt_purchaseUnit.Text), "", false) == 0)
			{
				Interaction.MsgBox((object)"Please Enter Bulk Unit Name", (MsgBoxStyle)64, (object)null);
				return;
			}
			if (Conversion.Val(txt_purchaseQnty.Text) < 0.0)
			{
				Interaction.MsgBox((object)"Please Enter Bulk Qnty", (MsgBoxStyle)64, (object)null);
				return;
			}
			string text = "";
			if (mdl_public_variables.flag == 1)
			{
				if (duplicateUnitCheckAddEditTime())
				{
					text = "select top 1 unitCode from naiUnitMaster where unitCode like '" + Conversions.ToString(txt_issueUnit.Text[0]) + "%' order by unitCode desc";
					mdl_itemmst.unitcode = ob.getcode(text, txt_issueUnit.Text);
					text = "INSERT INTO naiUnitMaster(companyCode,                     unitCode,                 basicUnitName,                      basicQnty,                      bulkUnitName,                               bulkQnty,                type,                 userCode) VALUES('" + mdl_public_variables.companycode + "','" + mdl_itemmst.unitcode + "' ,'" + txt_issueUnit.Text.Trim() + "' ,'" + Conversions.ToString(Conversion.Val(txt_issueQnty.Text)) + "' ,'" + txt_purchaseUnit.Text.Trim() + "' ,'" + Conversions.ToString(Conversion.Val(txt_purchaseQnty.Text)) + "','Unit Master','" + mdl_itemmst.unitcode + "' ) ";
					ob.insert(text);
					txt_issueUnit.Text = string.Empty;
					txt_issueQnty.Text = string.Empty;
					txt_purchaseUnit.Text = string.Empty;
					txt_purchaseQnty.Text = string.Empty;
					((Control)MyProject.Forms.frm_Form1).Enabled = true;
					try
					{
						Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
						return;
					}
					catch (Exception ex)
					{
						ProjectData.SetProjectError(ex);
						Exception ex2 = ex;
						ProjectData.ClearProjectError();
						return;
					}
				}
				Interaction.MsgBox((object)"This unit already present", (MsgBoxStyle)16, (object)null);
			}
			else
			{
				if (mdl_public_variables.flag != 2)
				{
					return;
				}
				if (duplicateUnitCheckAddEditTime())
				{
					text = "UPDATE  naiUnitMaster \r\nSET basicUnitName ='" + txt_issueUnit.Text.Trim() + "', basicQnty =" + Conversions.ToString(Conversion.Val(txt_issueQnty.Text)) + ", bulkUnitName ='" + txt_purchaseUnit.Text.Trim() + "', \r\nbulkQnty =" + Conversions.ToString(Conversion.Val(txt_purchaseQnty.Text)) + ",userCode='" + mdl_public_variables.usercode + "' where companyCode = '" + mdl_public_variables.companycode + "' and unitCode = '" + mdl_itemmst.unitcode + "' ";
					ob.insert(text);
					((Form)this).Close();
					((Control)MyProject.Forms.frm_Form1).Enabled = true;
					try
					{
						Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
						return;
					}
					catch (Exception ex3)
					{
						ProjectData.SetProjectError(ex3);
						Exception ex4 = ex3;
						ProjectData.ClearProjectError();
						return;
					}
				}
				Interaction.MsgBox((object)"This unit already present", (MsgBoxStyle)16, (object)null);
			}
		}

		private bool duplicateUnitCheckAddEditTime()
		{
			string text = "";
			if (mdl_public_variables.flag == 1)
			{
				text = "SELECT basicUnitName, basicQnty, bulkUnitName, bulkQnty  \r\n FROM naiUnitMaster \r\n WHERE companyCode='" + mdl_public_variables.companycode + "' AND basicUnitName='" + txt_issueUnit.Text.Trim() + "' AND basicQnty='" + Conversions.ToString(Conversion.Val(txt_issueQnty.Text)) + "' AND bulkUnitName='" + txt_purchaseUnit.Text.Trim() + "' AND bulkQnty='" + Conversions.ToString(Conversion.Val(txt_purchaseQnty.Text)) + "' ";
				ds = ob.populate(text);
				if (ds.Tables[0].Rows.Count > 0)
				{
					return false;
				}
			}
			else if (mdl_public_variables.flag == 2)
			{
				text = "SELECT basicUnitName, basicQnty, bulkUnitName, bulkQnty  \r\n FROM naiUnitMaster \r\n WHERE companyCode='" + mdl_public_variables.companycode + "' AND basicUnitName='" + txt_issueUnit.Text.Trim() + "' AND basicQnty='" + Conversions.ToString(Conversion.Val(txt_issueQnty.Text)) + "' AND bulkUnitName='" + txt_purchaseUnit.Text.Trim() + "' AND bulkQnty='" + Conversions.ToString(Conversion.Val(txt_purchaseQnty.Text)) + "' AND unitCode <> '" + mdl_itemmst.unitcode + "'  ";
				ds = ob.populate(text);
				if (ds.Tables[0].Rows.Count > 0)
				{
					return false;
				}
			}
			return true;
		}

