		private void txt_issueQnty_KeyPress(object sender, KeyPressEventArgs e)
		{
			switch (e.KeyChar)
			{
			case '\b':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				e.Handled = false;
				break;
			default:
				e.Handled = true;
				break;
			}
		}

		private void frm_unit_FormClosing(object sender, FormClosingEventArgs e)
		{
			if (MyProject.Forms.frm_itemmstadd.addMainGroup | MyProject.Forms.frm_itemmstadd.addSubGroup | MyProject.Forms.frm_itemmstadd.addUnit)
			{
				mdl_public_variables.count = 503;
				try
				{
					Versioned.CallByName(RuntimeHelpers.GetObjectValue(myParentForm), "mainformload", (CallType)2, (object[])null);
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
				}
				MyProject.Forms.frm_itemmstadd.formload(mdl_public_variables.count, mdl_public_variables.flag);
				((Control)MyProject.Forms.frm_itemmstadd).Enabled = true;
				MyProject.Forms.frm_itemmstadd.addMainGroup = false;
				MyProject.Forms.frm_itemmstadd.addSubGroup = false;
				MyProject.Forms.frm_itemmstadd.addUnit = false;
			}
			else
			{
				((Control)MyProject.Forms.frm_Form1).Enabled = true;
			}
		}

