				((Control)ComboBox2).Visible = false;
				((Control)Label1).Visible = false;
				((Control)Label6).Visible = false;
				string s = "select * from users where usercode='" + mdl_public_variables.usercode + "'";
				ds = cls_conn2.populate(s);
