			if (dsuser.Tables[0].Rows.Count <= 0)
			{
				return;
			}
			checked
			{
				int num = dsuser.Tables[0].Rows.Count - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
