		private void userrights_Load(object sender, EventArgs e)
		{
			//IL_0060: Unknown result type (might be due to invalid IL or missing references)
			((Form)this).Icon = Icon.FromHandle(Resources.User_right.GetHicon());
			cls_conn cls_conn2 = new cls_conn();
			string s = "select usercode,username,accesslevel,password from users where users.accesslevel<>'Admin' and usercode <>'A00001' order by username";
			dsu = cls_conn2.populate(s);
			if (dsu.Tables[0].Rows.Count == 0)
			{
				Interaction.MsgBox((object)"No user exist, please add new user & set their rights.", (MsgBoxStyle)48, (object)"No User");
				mdl_public_variables.flag = 0;
				return;
			}
			checked
			{
				int num = dsu.Tables[0].Rows.Count - 1;
				int num2 = 0;
				while (true)
				{
					int num3 = num2;
					int num4 = num;
					if (num3 > num4)
					{
						break;
					}
					cmb_user.Items.Add((object)dsu.Tables[0].Rows[num2][1].ToString());
					num2++;
				}
				s = "select * from companymast order by companyname";
				dsc = cls_conn2.populate(s);
				int num5 = dsc.Tables[0].Rows.Count - 1;
				int num6 = 0;
				while (true)
				{
					int num7 = num6;
					int num4 = num5;
					if (num7 > num4)
					{
						break;
					}
					cmb_company.Items.Add((object)dsc.Tables[0].Rows[num6][1].ToString());
					num6++;
				}
				if (mdl_public_variables.flag == 1)
				{
					itemload();
					cmb_user.SelectedIndex = 0;
					cmb_company.SelectedIndex = 0;
				}
				else if (mdl_public_variables.flag == 2)
				{
					editload();
				}
				((Control)cmb_user).Select();
			}
		}

