							dgv_trans[3, num9].Value = dataSet.Tables[0].Rows[num2][8].ToString();
							dgv_trans[4, num9].Value = dataSet.Tables[0].Rows[num2][9].ToString();
						}
						num9++;
					}
					int num11 = dgv_reports.Rows.Count - 1;
