							break;
						}
						if (Operators.ConditionalCompareObjectEqual(dgv_reports[0, num12].Value, (object)dataSet.Tables[0].Rows[num2][5].ToString(), false))
						{
							dgv_reports[1, num12].Value = dataSet.Tables[0].Rows[num2][6].ToString();
