		private void yearcreation_Load(object sender, EventArgs e)
		{
			((Form)this).Icon = Icon.FromHandle(Resources.Ganesh.GetHicon());
			dt_st.Text = Conversions.ToString(Conversion.Val(Strings.Mid(Strings.Format((object)mdl_public_variables.comstdate, "dd/MM/yyyy"), 7, 4)) + 1.0);
			dt_end.Text = Conversions.ToString(Conversion.Val(dt_st.Text) + 1.0);
			present = 0;
		}

		private void get_yearcode()
		{
			s = "select top 1 yearcode from yearmst order by yearcode desc";
			s = ob.executereader(s);
			if (Operators.CompareString(s, (string)null, false) != 0)
			{
				ycode = Conversions.ToString(checked(Convert.ToInt32(s) + 1));
			}
			else
			{
				ycode = Conversions.ToString(1);
			}
		}

		private void check_present()
		{
			//IL_00c7: Unknown result type (might be due to invalid IL or missing references)
			s = "select count(*)as YRcount ,yearcode from yearmst  where companycode='" + mdl_public_variables.companycode + "'and yearrange='" + dt_st.Text + "-" + dt_end.Text + "' group by companycode,yearcode";
			DataSet dataSet = ob.populate(s);
			if (dataSet.Tables[0].Rows.Count > 0 && Operators.ConditionalCompareObjectGreater(dataSet.Tables[0].Rows[0][0], (object)0, false))
			{
				Interaction.MsgBox((object)"Year already created for this company.", (MsgBoxStyle)48, (object)"Year Exist");
				present = 1;
				ycode = Conversions.ToString(dataSet.Tables[0].Rows[0][1]);
			}
		}

		private void Button1_Click(object sender, EventArgs e)
		{
			//IL_0048: Unknown result type (might be due to invalid IL or missing references)
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Invalid comparison between Unknown and I4
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			//IL_0026: Invalid comparison between Unknown and I4
			//IL_0115: Unknown result type (might be due to invalid IL or missing references)
			//IL_011a: Unknown result type (might be due to invalid IL or missing references)
			//IL_011b: Unknown result type (might be due to invalid IL or missing references)
			//IL_011d: Invalid comparison between Unknown and I4
			check_present();
			if (present == 1)
			{
				MsgBoxResult val = Interaction.MsgBox((object)"Do you want to update the opening?", (MsgBoxStyle)4, (object)null);
				if ((int)val == 6)
				{
					update_opening();
				}
				return;
			}
			MsgBoxResult val2 = Interaction.MsgBox((object)"Do you want to create new year?", (MsgBoxStyle)3, (object)"New Year?");
			if ((int)val2 != 6)
			{
				return;
			}
			if ((Operators.CompareString(DateTime.Today.Day.ToString(), "31", false) != 0) & (Operators.CompareString(DateTime.Today.Day.ToString(), "01", false) != 0) & (Operators.CompareString(DateTime.Today.Month.ToString(), "03", false) != 0) & (Operators.CompareString(DateTime.Today.Day.ToString(), "04", false) != 0))
			{
				MsgBoxResult val3 = Interaction.MsgBox((object)"This is not the time of Financial year ending or starting, do you want to create a new year this time?", (MsgBoxStyle)3, (object)"New Year?");
				if ((int)val3 != 6)
				{
					return;
				}
			}
			get_yearcode();
			s = "insert into yearmst(yearcode,yearrange,stdate,enddate,companycode) values('" + ycode + "','" + dt_st.Text + "-" + dt_end.Text + "','" + dt_st.Text + "-04-01','" + dt_end.Text + "-03-31','" + mdl_public_variables.companycode + "')";
			ob.insert(s);
			update_opening();
			((ToolStripDropDownItem)MyProject.Forms.frm_main.tsddb_year).DropDownItems.Add(dt_st.Text + "-" + dt_end.Text);
			((Form)this).Close();
		}

		private void update_opening()
		{
			//IL_01fa: Unknown result type (might be due to invalid IL or missing references)
			s = "delete from openingstockdetail where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + ycode + "'";
			ob.insert(s);
			s = "delete from openingstockmst where companycode='" + mdl_public_variables.companycode + "' and yearcode='" + ycode + "'";
			s = Conversions.ToString(ob.insert(s));
			s = "insert into openingstockmst ( companycode, yearcode,shopcode, itemcode, purchaseRate,loose, box, qnty, trndate) \r\nselect openigStock.companycode,'" + ycode + "' as yearcode,storecode as shopcode,openigStock.itemcode,isnull(pdetail.RateWithOutFreeQnty,0)as purchaseRate   , stock as loose,0 as box,stock as qnty,'" + dt_st.Text + "-04-01'  as trndate   \r\n from opening_closing_stock('" + Conversions.ToString(mdl_public_variables.comstdate) + "','" + Conversions.ToString(mdl_public_variables.comenddate) + "','" + Conversions.ToString(mdl_public_variables.comenddate) + "') as openigStock \r\n left join  \r\n ( \r\n Select purchasedetail.companycode,purchasedetail.yearcode , purchasedetail.itemCode,(purchasedetail.itemamount/purchasedetail.itemquantity) as RateIncludeFreeQnty,(purchasedetail.itemamount/(purchasedetail.itemquantity-purchasedetail.itemfreeqnty)) as RateWithOutFreeQnty  \r\n from purchasedetail  \r\n Inner Join (  \r\n select X1.companycode,X1.yearcode,X1.trndate,Max(purchasedetail.trnno) as latestTrnNO,X1.itemcode  \r\n From purchasedetail  \r\n Inner Join (  \r\n SELECT purchasedetail.companycode,purchasedetail.yearcode,MAX(purchasedetail.trndate) AS trndate,purchasedetail.itemcode    \r\n FROM vw_itemCodebarCode as itemmst    \r\n Inner Join purchasedetail on itemmst.companycode = purchasedetail.companycode AND itemmst.itemcode = purchasedetail.itemcode     \r\n where purchasedetail.trndate<='" + Conversions.ToString(mdl_public_variables.comenddate) + "'  and purchasedetail.yearcode ='" + mdl_public_variables.yearcode + "'   --and purchasedetail.trndate>='6/23/2016'    \r\n GROUP BY purchasedetail.companycode,purchasedetail.yearcode,purchasedetail.itemcode   \r\n ) As X1 on X1.companycode = purchasedetail.companycode AND x1.yearcode = purchasedetail.yearcode AND x1.trndate = purchasedetail.trndate AND x1.itemcode = purchasedetail.itemcode    \r\n GROUP BY X1.companycode,X1.yearcode,X1.trndate,X1.itemcode    \r\n ) as X on X.companycode = purchasedetail.companycode AND x.yearcode = purchasedetail.yearcode AND x.trndate = purchasedetail.trndate AND x.latestTrnNo = purchasedetail.trnno AND x.itemcode = purchasedetail.itemcode   \r\n ) as pdetail on openigStock.companycode =pdetail.companycode  and openigStock.yearcode = pdetail.yearcode and openigStock.itemcode =pdetail.itemcode  \r\n where pdetail.companycode='" + mdl_public_variables.companycode + "'  ";
			ob.insert(s);
