			s = "Insert Into MasterAccountsOpening (companyCode,yearcode,restaurantCode,ledgerCode,TrnAmount ,TrnEffect,EffectDate ) Select x.companyCode , '" + openingYearCode + "' as yearCode ,restaurantCode , ledgerCode , Sum(ABS(forwordingAmount)) as forwordingAmount, case when sum(forwordingAmount) >= 0 then 1 else -1 end as trnEffect,yearmst.stDate  as effectDate  from(  select companyCode,yearCode,'NOTREQ' as restaurantCode,ledgerCode,(trnAmount*trnEffect) AS forwordingAmount from MasterAccountsOpening  where companyCode = '" + companycode + "' AND yearcode = '" + yearcode + "' Union All select companyCode,yearCode,'NOTREQ' as restaurantCode,trnAccount as ledgerCode,(trnAmount*trnEffect) as forwordingAmount from TransactionDetail  where companycode = '" + companycode + "' AND yearcode = '" + yearcode + "'  ) as x Inner join yearmst on yearmst.companyCode = x.companyCode AND yearmst.yearCode = '" + openingYearCode + "'   Group by x.companyCode ,x.yearcode,x.restaurantCode,x.ledgerCode,yearmst.stDate ";
			cls_DataAccess2.insert(s);
		}

